INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53002, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "源泉", "is_correct": true, "explanation": "人間関係をよくする力を生むもとを指し、文脈に合う。"}, {"text": "財布", "is_correct": false, "explanation": "『力の財布』は意味が通らず、力を生むもとを表せない。"}, {"text": "天井", "is_correct": false, "explanation": "『力の天井』は不自然で、文が成り立たない。"}, {"text": "紅葉", "is_correct": false, "explanation": "『力の紅葉』は意味が通らず、文脈に合わない。"}], "explanations": {"源泉": "人間関係をよくする力を生むもとを指し、文脈に合う。", "財布": "『力の財布』は意味が通らず、力を生むもとを表せない。", "天井": "『力の天井』は不自然で、文が成り立たない。", "紅葉": "『力の紅葉』は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "源泉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は昼ごはんに、源泉を注文した。", "explanation": "ここは〈定食〉の意味。〈源泉〉は物事の起こりを指し、食事の注文には使わないので合わない。"}, {"text": "この部屋の源泉を北側へ運んで、並べ替えた。", "explanation": "ここは〈家具〉の意味。〈源泉〉は物事のもとを指し、運んで並べる家具の名前には使わない。"}, {"text": "私は源泉を三番目の駅で降りた。", "explanation": "ここは〈駅〉の意味。〈源泉〉は物事のもとを指し、電車で降りる駅の名前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53002, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その経験が、作品の源泉をなった。", "corrected_sentence": "その経験が、作品の源泉になった。", "error_description": "『なる』は『に』を取る。『を』は誤りで、正しくは『に』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53002, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町の繁栄は、豊かな水の源泉が支えられている。", "corrected_sentence": "この町の繁栄は、豊かな水の源泉に支えられている。", "error_description": "『支える』は『に』で受け手を示す。『が』は誤りで、正しくは『に』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd44cc3-abfb-4de7-974d-f6c19a8e1420') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
