INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53005, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一週間のこと。月曜日から日曜日までの七日間。", "primary_collocate": null, "pronunciation": "ういーく", "ipa": "ɯiːkɯ", "syllable_count": 4, "sentences": [{"text": "英語の week を、日本語では「ウイーク」と書くことがあります。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "英語[えいご]の week を、日本語[にほんご]では「ウイーク」と書[か]くことがあります。", "sentence_source": "generated"}, {"text": "「ウイーク」は、月曜日から日曜日までの一週間を指す言葉です。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "「ウイーク」は、月曜日[げつようび]から日曜日[にちようび]までの一週間[いっしゅうかん]を指[さ]す言葉[ことば]です。", "sentence_source": "generated"}, {"text": "「ウイーク」と「週間」は、どちらも七日間の意味で使われます。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "「ウイーク」と「週間[しゅうかん]」は、どちらも七日間[なのかかん]の意味[いみ]で使[つか]われます。", "sentence_source": "generated"}, {"text": "外国の雑誌で、「ウイーク」という言葉を見かけました。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "外国[がいこく]の雑誌[ざっし]で、「ウイーク」という言葉[ことば]を見[み]かけました。", "sentence_source": "generated"}, {"text": "英語の「ウイーク」は、日本語の「週間」と同じ意味です。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "英語[えいご]の「ウイーク」は、日本語[にほんご]の「週間[しゅうかん]」と同[おな]じ意味[いみ]です。", "sentence_source": "generated"}, {"text": "翻訳の授業で、「ウイーク」の意味を辞書で調べました。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "翻訳[ほんやく]の授業[じゅぎょう]で、「ウイーク」の意味[いみ]を辞書[じしょ]で調[しら]べました。", "sentence_source": "generated"}, {"text": "「ウイーク」は七日間を表すので、二つ分を合わせると十四日間になります。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "「ウイーク」は七日間[なのかかん]を表[あらわ]すので、二[ふた]つ分[ぶん]を合[あ]わせると十四日間[じゅうよっかかん]になります。", "sentence_source": "generated"}, {"text": "辞書には、「ウイーク」は「週」と同じ意味だと書いてあります。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "辞書[じしょ]には、「ウイーク」は「週[しゅう]」と同[おな]じ意味[いみ]だと書[か]いてあります。", "sentence_source": "generated"}, {"text": "「ウイーク」という語は、英語の week から来ています。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "「ウイーク」という語[ご]は、英語[えいご]の week から来[き]ています。", "sentence_source": "generated"}, {"text": "外来語の辞書で、「ウイーク」の項目を確認しました。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "外来語[がいらいご]の辞書[じしょ]で、「ウイーク」の項目[こうもく]を確認[かくにん]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ウイーク", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "月曜から日曜までの七日間という時間の区切り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53005, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ウイーク", "is_correct": true, "explanation": "英語 week の表記として書く語で、文の意味に合う。"}, {"text": "ボール", "is_correct": false, "explanation": "球のことで、week の表記にはならない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物で、週を表す語の表記としては合わない。"}, {"text": "木曜", "is_correct": false, "explanation": "曜日の一つで、週全体を指す表記ではない。"}], "explanations": {"ウイーク": "英語 week の表記として書く語で、文の意味に合う。", "ボール": "球のことで、week の表記にはならない。", "電車": "乗り物で、週を表す語の表記としては合わない。", "木曜": "曜日の一つで、週全体を指す表記ではない。"}, "sentence_index": 0, "correct_answer": "ウイーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は毎週、ウイークの午後に開かれます。", "explanation": "ここは〈曜日〉の意味。ウイークは七日間の区切りなので、午後という時間帯の範囲には使えない。"}, {"text": "毎朝、ウイークを確かめて、傘を持つかを決める。", "explanation": "ここは〈天気〉の意味。ウイークは七日間の期間を指すので、その日の空模様には使わない。"}, {"text": "食後に、ウイークを一杯飲みます。", "explanation": "ここは〈ウイスキー〉（酒）の意味。ウイークは七日間の期間を指すので、飲み物の名前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53005, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ウイーク", "is_correct": true, "explanation": "七日間を表す語として、説明文の内容に合う。"}, {"text": "月", "is_correct": false, "explanation": "一か月を表す語で、七日間を表すことはできない。"}, {"text": "年", "is_correct": false, "explanation": "十二か月を表す語で、七日間を表さない。"}, {"text": "時間", "is_correct": false, "explanation": "長さを表す一般語で、七日間という特定の期間を表さない。"}], "explanations": {"ウイーク": "七日間を表す語として、説明文の内容に合う。", "月": "一か月を表す語で、七日間を表すことはできない。", "年": "十二か月を表す語で、七日間を表さない。", "時間": "長さを表す一般語で、七日間という特定の期間を表さない。"}, "sentence_index": 6, "correct_answer": "ウイーク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は友達にウイークを送って、挨拶をした。", "explanation": "ここは〈ウィンク〉（片目をつぶる仕草）の意味。ウイークは期間の名前で、仕草には使わない。"}, {"text": "毎月の月末に、ウイークに会費を払います。", "explanation": "ここは〈月〉の意味。ウイークは七日間の区切りで、月末の支払いの時期にはならない。"}, {"text": "毎朝、ウイークを量って、記録します。", "explanation": "ここは〈体重〉（重さ）の意味。ウイークは期間の名前で、重さを量る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53005, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このウイークを、毎日雨が降りました。", "corrected_sentence": "このウイークは、毎日雨が降りました。", "error_description": "「このウイーク」は話題（主題）なので「は」で示す。「を」は目的語の印で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53005, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ウイークを始まると、毎日忙しくなりました。", "corrected_sentence": "ウイークが始まると、毎日忙しくなりました。", "error_description": "「始まる」は自動詞なので、主語は「が」で示す。「ウイークを」は誤りで、正しくは「ウイークが始まると」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53006, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時期を表し、読書のウイークが貸し出しの時期として合う。"}, {"text": "を", "is_correct": false, "explanation": "「貸します」の目的語は「本」なので、「ウイークを」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、時期を表すことには合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示すが、時期を表すことはできない。"}], "correct_answer": "に", "explanations": {"に": "時期を表し、読書のウイークが貸し出しの時期として合う。", "を": "「貸します」の目的語は「本」なので、「ウイークを」は不自然。", "へ": "方向を示すが、時期を表すことには合わない。", "と": "相手や並列を示すが、時期を表すことはできない。"}, "error_tags": {"を": "対象の格", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53006, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ウイーク」と「最後の日」をつなぐ名詞修飾として合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、名詞を続ける位置には「の」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、名詞同士をつなぐ位置には合わない。"}, {"text": "に", "is_correct": false, "explanation": "時点を示すが、「日に」と二重になり不自然。"}], "correct_answer": "の", "explanations": {"の": "「ウイーク」と「最後の日」をつなぐ名詞修飾として合う。", "を": "目的語を示すが、名詞を続ける位置には「の」が必要。", "へ": "方向を示すが、名詞同士をつなぐ位置には合わない。", "に": "時点を示すが、「日に」と二重になり不自然。"}, "error_tags": {"を": "対象の格", "へ": "方向", "に": "時点の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53006, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "週間。特に、特定の行事や催しが行われる一週間を指すこともある。", "primary_collocate": null, "pronunciation": "ういーく", "ipa": "ɯiːkɯ", "syllable_count": 4, "sentences": [{"text": "この町では、毎年五月にお祭りのウイークがあります。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "この町[まち]では、毎年[まいとし]五月[ごがつ]にお祭[まつ]りのウイークがあります。", "sentence_source": "generated"}, {"text": "学校の読書のウイークに、図書室で本を貸します。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "学校[がっこう]の読書[どくしょ]のウイークに、図書室[としょしつ]で本[ほん]を貸[か]します。", "sentence_source": "generated"}, {"text": "春のウイークの間、駅の前で花の市が開かれます。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "春[はる]のウイークの間[あいだ]、駅[えき]の前[まえ]で花[はな]の市[いち]が開[ひら]かれます。", "sentence_source": "generated"}, {"text": "安全のウイークには、警察が学校で話をします。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "安全[あんぜん]のウイークには、警察[けいさつ]が学校[がっこう]で話[はなし]をします。", "sentence_source": "generated"}, {"text": "店はセールのウイークで、いつもより安く売っています。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "店[みせ]はセールのウイークで、いつもより安[やす]く売[う]っています。", "sentence_source": "generated"}, {"text": "町のウイークが始まると、道に旗が立ちます。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "町[まち]のウイークが始[はじ]まると、道[みち]に旗[はた]が立[た]ちます。", "sentence_source": "generated"}, {"text": "来月は健康のウイークなので、病院で無料の検査があります。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "来月[らいげつ]は健康[けんこう]のウイークなので、病院[びょういん]で無料[むりょう]の検査[けんさ]があります。", "sentence_source": "generated"}, {"text": "ウイークの最後の日に、みんなで歌を歌います。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "ウイークの最後[さいご]の日[ひ]に、みんなで歌[うた]を歌[うた]います。", "sentence_source": "generated"}, {"text": "本の町のウイークには、世界中から人が集まります。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "本[ほん]の町[まち]のウイークには、世界中[せかいじゅう]から人[ひと]が集[あつ]まります。", "sentence_source": "generated"}, {"text": "去年の読書のウイークは雨で、行事が少なくなりました。", "target_word": "ウイーク", "complexity_tier": "T3", "furigana": "去年[きょねん]の読書[どくしょ]のウイークは雨[あめ]で、行事[ぎょうじ]が少[すく]なくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ウイーク", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "行事や催しが行われる特別な一週間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53006, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ウイーク", "is_correct": true, "explanation": "行事が行われる一週間を指すので、お祭りの期間として合う。"}, {"text": "雲", "is_correct": false, "explanation": "空に浮かぶもので、お祭りの期間を表す語ではない。"}, {"text": "鍵", "is_correct": false, "explanation": "道具で、期間を表さない。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類で、お祭りの期間を表さない。"}], "explanations": {"ウイーク": "行事が行われる一週間を指すので、お祭りの期間として合う。", "雲": "空に浮かぶもので、お祭りの期間を表す語ではない。", "鍵": "道具で、期間を表さない。", "靴下": "衣類で、お祭りの期間を表さない。"}, "sentence_index": 0, "correct_answer": "ウイーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年は風邪のウイークが流行っています。", "explanation": "ここは〈ウイルス〉（病原体）の意味。ウイークは行事の期間を指すので、病気の原因には使わない。"}, {"text": "会場では、ウイークが案内をします。", "explanation": "ここは〈担当者〉（人）の意味。ウイークは期間の名前なので、案内する人にはならない。"}, {"text": "食後に、ウイークを一杯飲みます。", "explanation": "ここは〈ウイスキー〉（酒）の意味。ウイークは行事の期間を指すので、飲み物の名前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53006, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ウイーク", "is_correct": true, "explanation": "健康を意識する一週間を表すので、説明の期間として合う。"}, {"text": "雨", "is_correct": false, "explanation": "天気で、健康のための期間を表さない。"}, {"text": "旅行", "is_correct": false, "explanation": "行為で、健康の期間を表す語ではない。"}, {"text": "工事", "is_correct": false, "explanation": "作業で、健康の期間を表さない。"}], "explanations": {"ウイーク": "健康を意識する一週間を表すので、説明の期間として合う。", "雨": "天気で、健康のための期間を表さない。", "旅行": "行為で、健康の期間を表す語ではない。", "工事": "作業で、健康の期間を表さない。"}, "sentence_index": 6, "correct_answer": "ウイーク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は友達にウイークを送って、挨拶をした。", "explanation": "ここは〈ウィンク〉（片目をつぶる仕草）の意味。ウイークは期間の名前で、仕草には使わない。"}, {"text": "毎晩、ウイークに今日あったことを書きます。", "explanation": "ここは〈日記〉（書く帳面）の意味。ウイークは期間の名前なので、書く場所にはならない。"}, {"text": "頭にウイークをかぶって、出かけた。", "explanation": "ここは〈かつら〉（頭にかぶるもの）の意味。ウイークは期間の名前なので、かぶるものにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53006, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年のウイークを、お祭りがあります。", "corrected_sentence": "来年のウイークには、お祭りがあります。", "error_description": "「来年のウイーク」は時期を表すので「に（には）」で示す。「を」は目的語の印で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53006, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ウイークを終わると、町は静かになりました。", "corrected_sentence": "ウイークが終わると、町は静かになりました。", "error_description": "「終わる」は自動詞なので、主語は「が」で示す。「ウイークを」は誤りで、正しくは「ウイークが終わると」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
