INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53007, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ぜんぜん新しい、今までにない形や考え方のこと。", "primary_collocate": null, "pronunciation": "あばんぎゃるど", "ipa": "abaŋɡjaɾɯdo", "syllable_count": 6, "sentences": [{"text": "彼女の服は、今までにない形で、とてもアバンギャルドだ。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の服[ふく]は、今[いま]までにない形[かたち]で、とてもアバンギャルドだ。", "sentence_source": "generated"}, {"text": "この店のメニューはアバンギャルドで、初めて見る料理ばかりだ。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "この店[みせ]のメニューはアバンギャルドで、初[はじ]めて見[み]る料理[りょうり]ばかりだ。", "sentence_source": "generated"}, {"text": "社長のアバンギャルドな考えに、社員たちは最初おどろいた。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "社長[しゃちょう]のアバンギャルドな考[かんが]えに、社員[しゃいん]たちは最初[さいしょ]おどろいた。", "sentence_source": "generated"}, {"text": "アバンギャルドな建物は、遠くから見ても目立つ。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "アバンギャルドな建物[たてもの]は、遠[とお]くから見[み]ても目立[めだ]つ。", "sentence_source": "generated"}, {"text": "この新しいアイデアは、ふつうの人にはアバンギャルドに見えるかもしれない。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "この新[あたら]しいアイデアは、ふつうの人[ひと]にはアバンギャルドに見[み]えるかもしれない。", "sentence_source": "generated"}, {"text": "彼の髪型はアバンギャルドすぎて、友達もまねできなかった。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "彼[かれ]の髪型[かみがた]はアバンギャルドすぎて、友達[ともだち]もまねできなかった。", "sentence_source": "generated"}, {"text": "古い形をやめて、アバンギャルドなデザインのいすを作った。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "古[ふる]い形[かたち]をやめて、アバンギャルドなデザインのいすを作[つく]った。", "sentence_source": "generated"}, {"text": "アバンギャルドな発想のおかげで、この商品は人気になった。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "アバンギャルドな発想[はっそう]のおかげで、この商品[しょうひん]は人気[にんき]になった。", "sentence_source": "generated"}, {"text": "母は、私のアバンギャルドな部屋の飾りを見て笑った。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "母[はは]は、私[わたし]のアバンギャルドな部屋[へや]の飾[かざ]りを見[み]て笑[わら]った。", "sentence_source": "generated"}, {"text": "町の人は最初、アバンギャルドな橋の形に驚いた。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]は最初[さいしょ]、アバンギャルドな橋[はし]の形[かたち]に驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アバンギャルド", "label": "基本形"}, {"form": "アバンギャルドな", "label": "ナ形容詞的連体形"}, {"form": "アバンギャルドだ", "label": "断定形"}], "register": "neutral", "sense_fingerprint": "今までにない大胆で新しい形や考え方(前衛的であること)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53007, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アバンギャルド", "is_correct": true, "explanation": "今までにない新しい形を表し、服の形を説明するここに合う。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器で、服の形の説明には使えない。"}, {"text": "陽気", "is_correct": false, "explanation": "人の明るい性格を表す語で、服には使わない。"}, {"text": "不器用", "is_correct": false, "explanation": "人の手先の下手さを表す語で、服の形の説明にはならない。"}], "explanations": {"アバンギャルド": "今までにない新しい形を表し、服の形を説明するここに合う。", "ピアノ": "楽器で、服の形の説明には使えない。", "陽気": "人の明るい性格を表す語で、服には使わない。", "不器用": "人の手先の下手さを表す語で、服の形の説明にはならない。"}, "sentence_index": 0, "correct_answer": "アバンギャルド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い夜は、アバンギャルドをつけて部屋を暖めた。", "explanation": "ここは〈ヒーター〉の意味。ヒーターはつけて使う機器だが、形や考え方の新しさを表すアバンギャルドは機器ではないので合わない。"}, {"text": "玄関のアバンギャルドを閉めて、鍵をかけた。", "explanation": "ここは〈ドア〉の意味。ドアは閉めるものだが、形や考え方の新しさを表すアバンギャルドは閉めることができない。"}, {"text": "財布の中身を確かめて、アバンギャルドにしまった。", "explanation": "ここは〈財布〉の意味。財布はしまうものだが、形や考え方を表すアバンギャルドはしまえない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53007, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アバンギャルド", "is_correct": true, "explanation": "今までにない新しいデザインを表し、ここに合う。"}, {"text": "臆病", "is_correct": false, "explanation": "人の性格を表す語で、デザインには使わない。"}, {"text": "不機嫌", "is_correct": false, "explanation": "人の気分を表す語で、いすのデザインには合わない。"}, {"text": "嫉妬", "is_correct": false, "explanation": "感情を表す名詞で、「なデザイン」の形では修飾できない。"}], "explanations": {"アバンギャルド": "今までにない新しいデザインを表し、ここに合う。", "臆病": "人の性格を表す語で、デザインには使わない。", "不機嫌": "人の気分を表す語で、いすのデザインには合わない。", "嫉妬": "感情を表す名詞で、「なデザイン」の形では修飾できない。"}, "sentence_index": 6, "correct_answer": "アバンギャルド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水が止まらないので、アバンギャルドをひねって止めた。", "explanation": "ここは〈蛇口〉の意味。蛇口はひねって開け閉めするものだが、アバンギャルドは形や考え方の新しさを表すので合わない。"}, {"text": "誕生日に、アバンギャルドを切り分けて配った。", "explanation": "ここは〈ケーキ〉の意味。ケーキは切り分けて配るものだが、アバンギャルドは切り分けられない。"}, {"text": "雨で濡れたので、アバンギャルドをはいて帰った。", "explanation": "ここは〈靴〉の意味。靴ははくものだが、アバンギャルドは形や考え方を表すのではけない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53007, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このデザイナーは、アバンギャルドだ服を作ることで有名だ。", "corrected_sentence": "このデザイナーは、アバンギャルドな服を作ることで有名だ。", "error_description": "活用の誤り。名詞の前に置くときは「な」を使う。「だ」は文末の形なので、名詞の前には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53007, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父はその服を見て、アバンギャルドに言って笑った。", "corrected_sentence": "父はその服を見て、アバンギャルドだと言って笑った。", "error_description": "助詞の誤り。感想は「〜だと言う」で表す。「に」は「言う」と結びつかないので、「だと」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53008, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「アバンギャルドの音楽家」で、「の」が名詞を修飾するつなぎとして自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すので、「音楽家」を修飾する形にはならない。"}, {"text": "に", "is_correct": false, "explanation": "行き先や相手を表すので、ここでは名詞をつなげない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すので、「音楽家」を修飾する位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「アバンギャルドの音楽家」で、「の」が名詞を修飾するつなぎとして自然に続く。", "を": "目的語を示すので、「音楽家」を修飾する形にはならない。", "に": "行き先や相手を表すので、ここでは名詞をつなげない。", "が": "主語を示すので、「音楽家」を修飾する位置には入らない。"}, "error_tags": {"を": "目的語", "に": "相手・行き先", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
