INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53008, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "既存の枠組みにとらわれない、斬新で実験的な芸術様式や思想。", "primary_collocate": null, "pronunciation": "あばんぎゃるど", "ipa": "abaŋɡjaɾɯdo", "syllable_count": 6, "sentences": [{"text": "二十世紀の初めに、アバンギャルドの画家たちが新しい絵を描き始めた。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "二十世紀[にじっせいき]の初[はじ]めに、アバンギャルドの画家[がか]たちが新[あたら]しい絵[え]を描[えが]き始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼女はアバンギャルドの音楽家で、ふつうの楽器を使わない。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はアバンギャルドの音楽家[おんがくか]で、ふつうの楽器[がっき]を使[つか]わない。", "sentence_source": "generated"}, {"text": "美術館で、アバンギャルドの芸術展が開かれている。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で、アバンギャルドの芸術展[げいじゅつてん]が開[ひら]かれている。", "sentence_source": "generated"}, {"text": "その詩人は、伝統を破るアバンギャルドの運動に参加した。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "その詩人[しじん]は、伝統[でんとう]を破[やぶ]るアバンギャルドの運動[うんどう]に参加[さんか]した。", "sentence_source": "generated"}, {"text": "アバンギャルドな映画は、物語よりも映像の実験を大切にする。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "アバンギャルドな映画[えいが]は、物語[ものがたり]よりも映像[えいぞう]の実験[じっけん]を大切[たいせつ]にする。", "sentence_source": "generated"}, {"text": "この劇団は、アバンギャルドの演劇で知られている。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "この劇団[げきだん]は、アバンギャルドの演劇[えんげき]で知[し]られている。", "sentence_source": "generated"}, {"text": "批評家は、その作品を既存の形にとらわれないアバンギャルドだと評した。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "批評家[ひひょうか]は、その作品[さくひん]を既存[きそん]の形[かたち]にとらわれないアバンギャルドだと評[ひょう]した。", "sentence_source": "generated"}, {"text": "当時のアバンギャルドの作家は、文章の形をわざと壊した。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "当時[とうじ]のアバンギャルドの作家[さっか]は、文章[ぶんしょう]の形[かたち]をわざと壊[こわ]した。", "sentence_source": "generated"}, {"text": "アバンギャルドな舞台は、観客に新しい見方を求める。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "アバンギャルドな舞台[ぶたい]は、観客[かんきゃく]に新[あたら]しい見方[みかた]を求[もと]める。", "sentence_source": "generated"}, {"text": "大学で、ロシアのアバンギャルド芸術について発表した。", "target_word": "アバンギャルド", "complexity_tier": "T3", "furigana": "大学[だいがく]で、ロシアのアバンギャルド芸術[げいじゅつ]について発表[はっぴょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アバンギャルド", "label": "基本形"}, {"form": "アバンギャルドな", "label": "ナ形容詞的連体形"}, {"form": "アバンギャルドの", "label": "連体(の)"}], "register": "formal", "sense_fingerprint": "従来の枠を壊す実験的な芸術運動・様式・思想(前衛芸術)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53008, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アバンギャルド", "is_correct": true, "explanation": "前衛の芸術運動を指し、画家の流派として自然に合う。"}, {"text": "民主主義", "is_correct": false, "explanation": "政治の思想で、画家の流派にはならない。"}, {"text": "資本主義", "is_correct": false, "explanation": "経済の仕組みを表し、画家の流派としては合わない。"}, {"text": "合理主義", "is_correct": false, "explanation": "考え方の一つで、絵の流派を表す語としては合わない。"}], "explanations": {"アバンギャルド": "前衛の芸術運動を指し、画家の流派として自然に合う。", "民主主義": "政治の思想で、画家の流派にはならない。", "資本主義": "経済の仕組みを表し、画家の流派としては合わない。", "合理主義": "考え方の一つで、絵の流派を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "アバンギャルド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒くなったので、アバンギャルドを閉めて暖房をつけた。", "explanation": "ここは〈窓〉の意味。窓は閉めるものだが、芸術の運動を表すアバンギャルドは閉められない。"}, {"text": "雨が降ってきたので、アバンギャルドを広げて歩いた。", "explanation": "ここは〈傘〉の意味。傘は広げて使うものだが、芸術の運動を表すアバンギャルドは広げられない。"}, {"text": "そのアバンギャルドは、先生の教えを守って三百年続いている。", "explanation": "ここは〈流派〉の意味。昔からの教えを守る流れを指すので、従来の枠を壊すこの語義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53008, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アバンギャルド", "is_correct": true, "explanation": "既存の形にとらわれない芸術の流派を指し、作品への評価として合う。"}, {"text": "渋滞", "is_correct": false, "explanation": "道路の混雑を表し、作品の評価には合わない。"}, {"text": "倒産", "is_correct": false, "explanation": "会社がつぶれることで、作品の評価には使わない。"}, {"text": "地震", "is_correct": false, "explanation": "揺れる自然現象で、作品の評価には使えない。"}], "explanations": {"アバンギャルド": "既存の形にとらわれない芸術の流派を指し、作品への評価として合う。", "渋滞": "道路の混雑を表し、作品の評価には合わない。", "倒産": "会社がつぶれることで、作品の評価には使わない。", "地震": "揺れる自然現象で、作品の評価には使えない。"}, "sentence_index": 6, "correct_answer": "アバンギャルド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "サッカーで、アバンギャルドが二点目を決めた。", "explanation": "ここは〈前衛〉（攻撃の選手）の意味。アバンギャルドは芸術や思想の新しさを指し、選手の位置は表さないので合わない。"}, {"text": "出かけるとき、アバンギャルドをかけて外に出た。", "explanation": "ここは〈鍵〉の意味。鍵はかけるものだが、芸術や思想の運動を表すアバンギャルドはかけられない。"}, {"text": "誕生日に、アバンギャルドを切り分けた。", "explanation": "ここは〈ケーキ〉の意味。ケーキは切り分けるものだが、芸術や思想の運動を表すアバンギャルドは切り分けられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53008, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その画廊は、アバンギャルドを食べる展覧会を開いた。", "corrected_sentence": "その画廊は、アバンギャルドを紹介する展覧会を開いた。", "error_description": "動詞の誤り。「アバンギャルドを」に続く動詞は「紹介する」が正しい。「食べる」は運動や作品には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53008, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼らは、既存の枠を壊すアバンギャルドに目指した。", "corrected_sentence": "彼らは、既存の枠を壊すアバンギャルドを目指した。", "error_description": "助詞の誤り。「目指す」は目的を「を」で表す。「に」は誤りで、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53009, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「造形が特徴だ」の主語を示す「が」。特徴の主語になる。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の「に」。「造形に特徴だ」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。特徴の主語にはならず、文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「造形より特徴だ」は比べる相手がなく、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「造形が特徴だ」の主語を示す「が」。特徴の主語になる。", "に": "位置・相手の「に」。「造形に特徴だ」は文が成り立たない。", "へ": "方向の「へ」。特徴の主語にはならず、文に合わない。", "より": "比較の「より」。「造形より特徴だ」は比べる相手がなく、文が成り立たない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53009, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53009, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものの形やデザインのこと", "primary_collocate": null, "pronunciation": "ぞうけい", "ipa": "zoːkeː", "syllable_count": 4, "sentences": [{"text": "この車は、丸みのある造形が女性に人気だ。", "target_word": "造形", "complexity_tier": "T3", "furigana": "この車[くるま]は、丸[まる]みのある造形[ぞうけい]が女性[じょせい]に人気[にんき]だ。", "sentence_source": "generated"}, {"text": "新しい携帯電話は、薄くて滑らかな造形が特徴だ。", "target_word": "造形", "complexity_tier": "T3", "furigana": "新[あたら]しい携帯電話[けいたいでんわ]は、薄[うす]くて滑[なめ]らかな造形[ぞうけい]が特徴[とくちょう]だ。", "sentence_source": "generated"}, {"text": "机の上に置かれた花瓶の造形に、思わず見とれた。", "target_word": "造形", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に置[お]かれた花瓶[かびん]の造形[ぞうけい]に、思[おも]わず見[み]とれた。", "sentence_source": "generated"}, {"text": "古い仏像の造形から、当時の人々の願いが伝わってくる。", "target_word": "造形", "complexity_tier": "T3", "furigana": "古[ふる]い仏像[ぶつぞう]の造形[ぞうけい]から、当時[とうじ]の人々[ひとびと]の願[ねが]いが伝[つた]わってくる。", "sentence_source": "generated"}, {"text": "使いやすさだけでなく、造形の面白さも考えて商品を選ぶ。", "target_word": "造形", "complexity_tier": "T3", "furigana": "使[つか]いやすさだけでなく、造形[ぞうけい]の面白[おもしろ]さも考[かんが]えて商品[しょうひん]を選[えら]ぶ。", "sentence_source": "generated"}, {"text": "この菓子は、花の造形がとても細かい。", "target_word": "造形", "complexity_tier": "T3", "furigana": "この菓子[かし]は、花[はな]の造形[ぞうけい]がとても細[こま]かい。", "sentence_source": "generated"}, {"text": "ロボットの造形が子どもに受けて、おもちゃは大ヒットした。", "target_word": "造形", "complexity_tier": "T3", "furigana": "ロボットの造形[ぞうけい]が子[こ]どもに受[う]けて、おもちゃは大[だい]ヒットした。", "sentence_source": "generated"}, {"text": "船のような造形の建物が、町の目印になっている。", "target_word": "造形", "complexity_tier": "T3", "furigana": "船[ふね]のような造形[ぞうけい]の建物[たてもの]が、町[まち]の目印[めじるし]になっている。", "sentence_source": "generated"}, {"text": "彼女のデザインは、シンプルな造形なのに、とても印象的だ。", "target_word": "造形", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のデザインは、シンプルな造形[ぞうけい]なのに、とても印象的[いんしょうてき]だ。", "sentence_source": "generated"}, {"text": "展示された雪像は、どれも繊細な造形だった。", "target_word": "造形", "complexity_tier": "T3", "furigana": "展示[てんじ]された雪像[せつぞう]は、どれも繊細[せんさい]な造形[ぞうけい]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "造形的な", "label": "形容動詞形"}, {"form": "造形的に", "label": "副詞形"}], "register": "neutral", "sense_fingerprint": "物や作品の外見としての形やデザイン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53009, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "造形", "is_correct": true, "explanation": "ここは物の形やデザインを指す〈造形〉。丸みのある見た目の話として自然に入る。"}, {"text": "燃費", "is_correct": false, "explanation": "燃料あたりの走行距離。「丸みのある燃費」は見た目の形に結びつかず不自然。"}, {"text": "排気量", "is_correct": false, "explanation": "エンジンの容量。「丸みのある排気量」は形の話として成り立たない。"}, {"text": "整備", "is_correct": false, "explanation": "点検や修理のこと。「丸みのある整備」は形容として意味が通らない。"}], "explanations": {"造形": "ここは物の形やデザインを指す〈造形〉。丸みのある見た目の話として自然に入る。", "燃費": "燃料あたりの走行距離。「丸みのある燃費」は見た目の形に結びつかず不自然。", "排気量": "エンジンの容量。「丸みのある排気量」は形の話として成り立たない。", "整備": "点検や修理のこと。「丸みのある整備」は形容として意味が通らない。"}, "sentence_index": 0, "correct_answer": "造形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は中世の美術に深い造形を持っている。", "explanation": "ここは〈造詣〉（深い知識）の意味。造形は物の形やデザインを指すので、知識の深さには合わない。"}, {"text": "彼は新しい業界用語を造形して、社内に広めた。", "explanation": "ここは〈造語〉（新しい言葉を作ること）の意味。造形は形を作ることで、言葉を作る意味では使わない。"}, {"text": "この椅子は、硬い木の造形でできている。", "explanation": "ここは〈材質〉（何で作られているか）の意味。造形は形を指すので、材料の話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53009, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "造形", "is_correct": true, "explanation": "ここは〈造形〉（形やデザイン）の意味。ロボットの見た目が子どもに受けた、という文脈に合う。"}, {"text": "電池", "is_correct": false, "explanation": "動力源の部品。「ロボットの電池が子どもに受けて」は意味が通らない。"}, {"text": "故障", "is_correct": false, "explanation": "壊れて動かなくなること。「故障が子どもに受けて」は意味が通らない。"}, {"text": "保証", "is_correct": false, "explanation": "品質を保つ約束。「保証が子どもに受けて」は成り立たない。"}], "explanations": {"造形": "ここは〈造形〉（形やデザイン）の意味。ロボットの見た目が子どもに受けた、という文脈に合う。", "電池": "動力源の部品。「ロボットの電池が子どもに受けて」は意味が通らない。", "故障": "壊れて動かなくなること。「故障が子どもに受けて」は意味が通らない。", "保証": "品質を保つ約束。「保証が子どもに受けて」は成り立たない。"}, "sentence_index": 6, "correct_answer": "造形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この菓子は、栄養の造形が豊かだ。", "explanation": "ここは〈栄養〉（体を養う成分）の意味。造形は形やデザインを指すので、成分の豊かさには合わない。"}, {"text": "この車は、手ごろな造形で人気だ。", "explanation": "ここは〈価格〉（値段）の意味。造形は見た目の形を指すので、値段の話には合わない。"}, {"text": "この薬は、骨髄の造形を助ける。", "explanation": "ここは〈造血〉（血液を作ること）の意味。造形は形を作ることで、血液の生成には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53009, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この時計は、細い針の造形を美しい。", "corrected_sentence": "この時計は、細い針の造形が美しい。", "error_description": "「美しい」の主語は「が」で示す。「造形を美しい」の「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53009, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この家具は、造形的なに優れていて人気がある。", "corrected_sentence": "この家具は、造形的に優れていて人気がある。", "error_description": "副詞形は「造形的に」。「造形的なに」の「な」は不要で、「に」だけが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53010, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「造形に挑戦」の「に」。挑戦は「〜に挑む／挑戦する」の形で、対象を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「造形を挑戦した」は挑戦の対象の示し方として不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。ここでは挑戦の対象なので主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「造形より挑戦した」は比べる文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「造形に挑戦」の「に」。挑戦は「〜に挑む／挑戦する」の形で、対象を「に」で示す。", "を": "目的語の「を」。「造形を挑戦した」は挑戦の対象の示し方として不自然。", "が": "主語を示す「が」。ここでは挑戦の対象なので主語にはならない。", "より": "比較の「より」。「造形より挑戦した」は比べる文として成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53010, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「造形に取り組む」の「に」。取り組む対象を「に」で示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「造形の取り組んでいる」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「金属の造形より取り組んでいる」は比べる文になり、対象を示せない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「造形を取り組んでいる」は「取り組む」と結びつかず不自然。"}], "correct_answer": "に", "explanations": {"に": "「造形に取り組む」の「に」。取り組む対象を「に」で示す。", "の": "連体修飾の「の」。「造形の取り組んでいる」は文が成り立たない。", "より": "比較の「より」。「金属の造形より取り組んでいる」は比べる文になり、対象を示せない。", "を": "目的語の「を」。「造形を取り組んでいる」は「取り組む」と結びつかず不自然。"}, "error_tags": {"の": "連体修飾", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53010, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物の形を作り出すこと。また、その形。美術やデザインの分野でよく使われる。", "primary_collocate": null, "pronunciation": "ぞうけい", "ipa": "zoːkeː", "syllable_count": 4, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "造形", "complexity_tier": "T4", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "彼は粘土を使って動物の造形に挑戦した。", "target_word": "造形", "complexity_tier": "T3", "furigana": "彼[かれ]は粘土[ねんど]を使[つか]って動物[どうぶつ]の造形[ぞうけい]に挑戦[ちょうせん]した。", "sentence_source": "generated"}, {"text": "この椅子は、曲線の美しい造形が高く評価されている。", "target_word": "造形", "complexity_tier": "T3", "furigana": "この椅子[いす]は、曲線[きょくせん]の美[うつく]しい造形[ぞうけい]が高[たか]く評価[ひょうか]されている。", "sentence_source": "generated"}, {"text": "美術大学では、造形の基礎を一年生から学ぶ。", "target_word": "造形", "complexity_tier": "T3", "furigana": "美術大学[びじゅつだいがく]では、造形[ぞうけい]の基礎[きそ]を一年生[いちねんせい]から学[まな]ぶ。", "sentence_source": "generated"}, {"text": "子どもたちは紙や木の箱で自由に造形を楽しんだ。", "target_word": "造形", "complexity_tier": "T3", "furigana": "子[こ]どもたちは紙[かみ]や木[き]の箱[はこ]で自由[じゆう]に造形[ぞうけい]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "その建物は、鳥が羽を広げたような大胆な造形で知られる。", "target_word": "造形", "complexity_tier": "T3", "furigana": "その建物[たてもの]は、鳥[とり]が羽[はね]を広[ひろ]げたような大胆[だいたん]な造形[ぞうけい]で知[し]られる。", "sentence_source": "generated"}, {"text": "造形の授業で、石を削って小さな像を作った。", "target_word": "造形", "complexity_tier": "T3", "furigana": "造形[ぞうけい]の授業[じゅぎょう]で、石[いし]を削[けず]って小[ちい]さな像[ぞう]を作[つく]った。", "sentence_source": "generated"}, {"text": "彫刻家は、金属の造形に二十年取り組んでいる。", "target_word": "造形", "complexity_tier": "T3", "furigana": "彫刻家[ちょうこくか]は、金属[きんぞく]の造形[ぞうけい]に二十年[にじゅうねん]取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "展覧会では、若い作家の独創的な造形が注目を集めた。", "target_word": "造形", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]では、若[わか]い作家[さっか]の独創的[どくそうてき]な造形[ぞうけい]が注目[ちゅうもく]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "工場の職人は、熱いガラスを造形する技に優れている。", "target_word": "造形", "complexity_tier": "T3", "furigana": "工場[こうじょう]の職人[しょくにん]は、熱[あつ]いガラスを造形[ぞうけい]する技[わざ]に優[すぐ]れている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "造形する", "label": "動詞形"}, {"form": "造形的な", "label": "形容動詞形"}, {"form": "造形的に", "label": "副詞形"}], "register": "neutral", "sense_fingerprint": "美術やデザインで、物の形を作り出すこと、またその作られた形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): メゾン (Zipf 2.58), アヴァンギャルド (Zipf 2.38), 贅 (Zipf 2.41), 渇望 (Zipf 2.92)']::text[], '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53010, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "造形", "is_correct": true, "explanation": "ここは物の形を作り出す〈造形〉の意味。アヴァンギャルドな形の創作を指し、文脈に合う。"}, {"text": "採寸", "is_correct": false, "explanation": "体の寸法を測る意味。「アヴァンギャルドな採寸や」は形の話として成り立たない。"}, {"text": "試着", "is_correct": false, "explanation": "服を試しに着ること。「アヴァンギャルドな試着や」では、形の美学を述べる文に合わない。"}, {"text": "返品", "is_correct": false, "explanation": "購入した商品を返すこと。「アヴァンギャルドな返品や」は意味が通らず、形の話として合わない。"}], "explanations": {"造形": "ここは物の形を作り出す〈造形〉の意味。アヴァンギャルドな形の創作を指し、文脈に合う。", "採寸": "体の寸法を測る意味。「アヴァンギャルドな採寸や」は形の話として成り立たない。", "試着": "服を試しに着ること。「アヴァンギャルドな試着や」では、形の美学を述べる文に合わない。", "返品": "購入した商品を返すこと。「アヴァンギャルドな返品や」は意味が通らず、形の話として合わない。"}, "sentence_index": 0, "correct_answer": "造形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は古典文学に深い造形を持っている。", "explanation": "ここは〈造詣〉（学問や芸術への深い知識）の意味。造形は作品の形を作ることを指すので、「深い造形」とは言わない。"}, {"text": "この橋は、重い荷物に耐える造形で設計された。", "explanation": "ここは〈構造〉（組み立てのしくみ）の意味。造形は形を作り出すことなので、耐久性の話には合わない。"}, {"text": "彼は流行の言葉を造形して、仲間の間で広めた。", "explanation": "ここは〈造語〉（新しい言葉を作ること）の意味。造形は形を作ることなので、言葉を作る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53010, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "造形", "is_correct": true, "explanation": "ここは美術の授業名としての〈造形〉。形を作る学習を指し、石を削って像を作る内容と合う。"}, {"text": "体育", "is_correct": false, "explanation": "体を動かす教科。石を削って像を作る内容とは結びつかない。"}, {"text": "数学", "is_correct": false, "explanation": "計算や図形を学ぶ教科。石を削って像を作る授業とは合わない。"}, {"text": "書道", "is_correct": false, "explanation": "筆で文字を書く教科。石を削って像を作る授業としては合わない。"}], "explanations": {"造形": "ここは美術の授業名としての〈造形〉。形を作る学習を指し、石を削って像を作る内容と合う。", "体育": "体を動かす教科。石を削って像を作る内容とは結びつかない。", "数学": "計算や図形を学ぶ教科。石を削って像を作る授業とは合わない。", "書道": "筆で文字を書く教科。石を削って像を作る授業としては合わない。"}, "sentence_index": 6, "correct_answer": "造形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新型の機械を造形して、社内で組み立てた。", "explanation": "ここは〈組み立て〉の意味。造形は形を作ることで、部品をつなぎ合わせる作業には使わない。"}, {"text": "この山では、杉の苗木を造形している。", "explanation": "ここは〈造林〉（森林を育てること）の意味。造形は物の形を作ることで、植林には使わない。"}, {"text": "この工場では、大型の船を造形している。", "explanation": "ここは〈造船〉（船を造ること）の意味。造形は美術や物の形を作ることで、船の建造には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53010, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は陶芸の造形が大学で学んでいる。", "corrected_sentence": "彼女は陶芸の造形を大学で学んでいる。", "error_description": "「学ぶ」の目的語は「を」で示す。「造形が」の「が」は誤りで、正しくは「造形を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53010, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この美術館は造形的の展示で有名だ。", "corrected_sentence": "この美術館は造形的な展示で有名だ。", "error_description": "形容動詞の連体修飾は「造形的な」。「造形的の」の「の」は誤りで、「な」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53011, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「贅を尽くす」の目的語を示す「を」。「〜を尽くした食事」に入る。"}, {"text": "が", "is_correct": false, "explanation": "「贅が尽くす」とは言えず、主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「贅で尽くす」は手段の意味にならず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「贅と尽くす」は並列にも相手にもならず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「贅を尽くす」の目的語を示す「を」。「〜を尽くした食事」に入る。", "が": "「贅が尽くす」とは言えず、主語にはならない。", "で": "「贅で尽くす」は手段の意味にならず、不自然。", "と": "「贅と尽くす」は並列にも相手にもならず、意味が通らない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53011, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「贅を尽くす」の目的語を示す「を」。「〜を尽くした船旅」に入る。"}, {"text": "へ", "is_correct": false, "explanation": "「贅へ尽くす」は方向の意味にならず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "「贅から尽くす」は起点の意味にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「贅より尽くす」は比較の意味にならず、ここには入らない。"}], "correct_answer": "を", "explanations": {"を": "「贅を尽くす」の目的語を示す「を」。「〜を尽くした船旅」に入る。", "へ": "「贅へ尽くす」は方向の意味にならず、不自然。", "から": "「贅から尽くす」は起点の意味にならず、文が成り立たない。", "より": "「贅より尽くす」は比較の意味にならず、ここには入らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53011, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とてもお金や物をたくさん使って、すごくいいものを作ることです。", "primary_collocate": "尽くす", "pronunciation": "ぜい", "ipa": "d͡ze̞ː", "syllable_count": 2, "sentences": [{"text": "この宿の部屋は贅を尽くした造りで、風呂まで金色だ。", "target_word": "贅", "complexity_tier": "T3", "furigana": "この宿[やど]の部屋[へや]は贅[ぜい]を尽[つ]くした造[つく]りで、風呂[ふろ]まで金色[きんいろ]だ。", "sentence_source": "generated"}, {"text": "祖父は贅を尽くした食事より、母の味噌汁が好きだと言う。", "target_word": "贅", "complexity_tier": "T3", "furigana": "祖父[そふ]は贅[ぜい]を尽[つ]くした食事[しょくじ]より、母[はは]の味噌汁[みそしる]が好[す]きだと言[い]う。", "sentence_source": "generated"}, {"text": "王様は贅を尽くした城を建て、国のお金を使い果たした。", "target_word": "贅", "complexity_tier": "T3", "furigana": "王様[おうさま]は贅[ぜい]を尽[つ]くした城[しろ]を建[た]て、国[くに]のお金[かね]を使[つか]い果[は]たした。", "sentence_source": "generated"}, {"text": "誕生日には、贅を尽くしたケーキを自分のために買う。", "target_word": "贅", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]には、贅[ぜい]を尽[つ]くしたケーキを自分[じぶん]のために買[か]う。", "sentence_source": "generated"}, {"text": "贅を凝らした家具が並ぶ部屋に、客は言葉を失った。", "target_word": "贅", "complexity_tier": "T4", "furigana": "贅[ぜい]を凝[こ]らした家具[かぐ]が並[なら]ぶ部屋[へや]に、客[きゃく]は言葉[ことば]を失[うしな]った。", "sentence_source": "generated"}, {"text": "社長は贅の限りを尽くしたパーティーを開いた。", "target_word": "贅", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は贅[ぜい]の限[かぎ]りを尽[つ]くしたパーティーを開[ひら]いた。", "sentence_source": "generated"}, {"text": "この時計は贅を尽くして作られたため、値段も非常に高い。", "target_word": "贅", "complexity_tier": "T3", "furigana": "この時計[とけい]は贅[ぜい]を尽[つ]くして作[つく]られたため、値段[ねだん]も非常[ひじょう]に高[たか]い。", "sentence_source": "generated"}, {"text": "贅を尽くした船旅から戻ると、普段の暮らしが味気なく感じられた。", "target_word": "贅", "complexity_tier": "T4", "furigana": "贅[ぜい]を尽[つ]くした船旅[ふなたび]から戻[もど]ると、普段[ふだん]の暮[く]らしが味気[あじけ]なく感[かん]じられた。", "sentence_source": "generated"}, {"text": "貧しい村の人々は、贅とは無縁の生活を送っていた。", "target_word": "贅", "complexity_tier": "T3", "furigana": "貧[まず]しい村[むら]の人々[ひとびと]は、贅[ぜい]とは無縁[むえん]の生活[せいかつ]を送[おく]っていた。", "sentence_source": "generated"}, {"text": "劇場は贅を尽くした装飾で、天井には本物の金が使われている。", "target_word": "贅", "complexity_tier": "T3", "furigana": "劇場[げきじょう]は贅[ぜい]を尽[つ]くした装飾[そうしょく]で、天井[てんじょう]には本物[ほんもの]の金[きん]が使[つか]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "贅", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "贅:お金や物をたくさん使って作る豪華さ(贅を尽くす・贅を凝らす)", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53011, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贅", "is_correct": true, "explanation": "「贅を尽くす」は惜しまず金や物を使う意味で、「〜を尽くした造り」に入る語。"}, {"text": "憧れ", "is_correct": false, "explanation": "「憧れを尽くす」とは言わない。憧れは抱くもので、造りの説明には続かない。"}, {"text": "恐怖", "is_correct": false, "explanation": "「恐怖を尽くす」は不自然。恐怖は感じるもので、造りの説明には合わない。"}, {"text": "笑い", "is_correct": false, "explanation": "「笑いを尽くす」とは言わない。笑いは起こす・誘うもので、ここでは意味が通らない。"}], "explanations": {"贅": "「贅を尽くす」は惜しまず金や物を使う意味で、「〜を尽くした造り」に入る語。", "憧れ": "「憧れを尽くす」とは言わない。憧れは抱くもので、造りの説明には続かない。", "恐怖": "「恐怖を尽くす」は不自然。恐怖は感じるもので、造りの説明には合わない。", "笑い": "「笑いを尽くす」とは言わない。笑いは起こす・誘うもので、ここでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "贅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日練習して、贅を磨いた。", "explanation": "ここは〈技〉の意味。贅は金や物をかけるぜいたくで、磨くものではないので合わない。"}, {"text": "大勢の人が、大きな贅を上げて喜んだ。", "explanation": "ここは〈声〉の意味。贅は上げるものではなく、ぜいたくに使う語なので合わない。"}, {"text": "家族の贅を深めるため、週末は一緒に過ごした。", "explanation": "ここは〈絆〉の意味。贅は深めるものではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53011, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贅", "is_correct": true, "explanation": "「贅を尽くして作る」は、お金や物を惜しまず使う意味。「この時計は〜を尽くして」に入る語。"}, {"text": "夢", "is_correct": false, "explanation": "「夢を尽くす」とは言わない。夢は見る・叶えるもので、作る過程には続かない。"}, {"text": "怒り", "is_correct": false, "explanation": "「怒りを尽くす」は不自然。怒りは感じる・ぶつけるもので、作ることには合わない。"}, {"text": "悲しみ", "is_correct": false, "explanation": "「悲しみを尽くす」は不自然。悲しみは覚える・味わうもので、作る過程には合わない。"}], "explanations": {"贅": "「贅を尽くして作る」は、お金や物を惜しまず使う意味。「この時計は〜を尽くして」に入る語。", "夢": "「夢を尽くす」とは言わない。夢は見る・叶えるもので、作る過程には続かない。", "怒り": "「怒りを尽くす」は不自然。怒りは感じる・ぶつけるもので、作ることには合わない。", "悲しみ": "「悲しみを尽くす」は不自然。悲しみは覚える・味わうもので、作る過程には合わない。"}, "sentence_index": 6, "correct_answer": "贅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は仲間と大声で贅を歌い、夜遅くまで騒いだ。", "explanation": "ここは〈曲〉の意味。贅は演奏される曲ではなく、ぜいたくを表す語なので合わない。"}, {"text": "医者は薬を処方して、贅を治した。", "explanation": "ここは〈病気〉の意味。贅は治すものではないので、この文には合わない。"}, {"text": "彼女は遠くの友人に、長い贅を書いた。", "explanation": "ここは〈手紙〉の意味。贅は書くものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53011, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子爵は、贅が尽くした別荘を建てた。", "corrected_sentence": "子爵は、贅を尽くした別荘を建てた。", "error_description": "「贅を尽くす」の助詞は「を」。「が」は誤り（正しくは「贅を尽くした」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53011, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この器は贅を尽くすして作られた宮廷の品だ。", "corrected_sentence": "この器は贅を尽くして作られた宮廷の品だ。", "error_description": "「尽くす」に「して」を続ける形は「尽くして」。「尽くすして」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
