INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53012, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「贅」は、必要以上に金銭や物を費やして、ぜいたくをすることを意味する名詞です。特に「贅を尽くす」という形で、可能な限りの贅沢をすることを表します。", "primary_collocate": "尽くす", "pronunciation": "ぜい", "ipa": "d͡ze̞ː", "syllable_count": 2, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "贅", "complexity_tier": "T4", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "結婚三十周年の記念に、夫婦は贅を尽くした旅行を楽しんだ。", "target_word": "贅", "complexity_tier": "T3", "furigana": "結婚[けっこん]三十周年[さんじゅうしゅうねん]の記念[きねん]に、夫婦[ふうふ]は贅[ぜい]を尽[つ]くした旅行[りょこう]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "そのホテルは贅を尽くした内装で知られ、各国の王族も宿泊した。", "target_word": "贅", "complexity_tier": "T3", "furigana": "そのホテルは贅[ぜい]を尽[つ]くした内装[ないそう]で知[し]られ、各国[かっこく]の王族[おうぞく]も宿泊[しゅくはく]した。", "sentence_source": "generated"}, {"text": "彼は贅を尽くした暮らしをしていたが、事業に失敗してすべてを失った。", "target_word": "贅", "complexity_tier": "T3", "furigana": "彼[かれ]は贅[ぜい]を尽[つ]くした暮[く]らしをしていたが、事業[じぎょう]に失敗[しっぱい]してすべてを失[うしな]った。", "sentence_source": "generated"}, {"text": "今夜は特別な日なので、贅を尽くした料理を用意した。", "target_word": "贅", "complexity_tier": "T3", "furigana": "今夜[こんや]は特別[とくべつ]な日[ひ]なので、贅[ぜい]を尽[つ]くした料理[りょうり]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "貴族たちは贅を尽くして屋敷を飾り、毎晩のように宴を開いた。", "target_word": "贅", "complexity_tier": "T4", "furigana": "貴族[きぞく]たちは贅[ぜい]を尽[つ]くして屋敷[やしき]を飾[かざ]り、毎晩[まいばん]のように宴[うたげ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "不景気のため、今年の忘年会は贅を排して簡素に行うことにした。", "target_word": "贅", "complexity_tier": "T4", "furigana": "不景気[ふけいき]のため、今年[ことし]の忘年会[ぼうねんかい]は贅[ぜい]を排[はい]して簡素[かんそ]に行[おこな]うことにした。", "sentence_source": "generated"}, {"text": "贅を尽くした舞台装置が、観客の目を奪った。", "target_word": "贅", "complexity_tier": "T3", "furigana": "贅[ぜい]を尽[つ]くした舞台装置[ぶたいそうち]が、観客[かんきゃく]の目[め]を奪[うば]った。", "sentence_source": "generated"}, {"text": "贅を尽くした結婚式だったが、費用が重くのしかかり、二人は後で苦労した。", "target_word": "贅", "complexity_tier": "T4", "furigana": "贅[ぜい]を尽[つ]くした結婚式[けっこんしき]だったが、費用[ひよう]が重[おも]くのしかかり、二人[ふたり]は後[あと]で苦労[くろう]した。", "sentence_source": "generated"}, {"text": "彼は質素な家で育ったため、贅を尽くした生活にはなじめなかった。", "target_word": "贅", "complexity_tier": "T3", "furigana": "彼[かれ]は質素[しっそ]な家[いえ]で育[そだ]ったため、贅[ぜい]を尽[つ]くした生活[せいかつ]にはなじめなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "贅", "label": "基本形"}], "register": "formal", "sense_fingerprint": "贅:金や物を惜しまず使うぜいたく(贅を尽くす)", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53012, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贅", "is_correct": true, "explanation": "「贅を尽くす」は惜しまず金や物を使う意味で、「〜を尽くした素材使い」に入る語。"}, {"text": "夢", "is_correct": false, "explanation": "「夢を尽くす」とは言わない。夢は見る・叶えるもので、素材使いに続かない。"}, {"text": "誇り", "is_correct": false, "explanation": "「誇りを尽くす」は不自然。誇りは持つ・保つもので、ここでは意味が合わない。"}, {"text": "疑い", "is_correct": false, "explanation": "「疑いを尽くす」とは言えない。疑いは抱く・晴らすもので、素材使いには合わない。"}], "explanations": {"贅": "「贅を尽くす」は惜しまず金や物を使う意味で、「〜を尽くした素材使い」に入る語。", "夢": "「夢を尽くす」とは言わない。夢は見る・叶えるもので、素材使いに続かない。", "誇り": "「誇りを尽くす」は不自然。誇りは持つ・保つもので、ここでは意味が合わない。", "疑い": "「疑いを尽くす」とは言えない。疑いは抱く・晴らすもので、素材使いには合わない。"}, "sentence_index": 0, "correct_answer": "贅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は利益の一部を贅として国に納めた。", "explanation": "ここは〈税〉の意味（同じ読み「ぜい」）。贅は金や物をぜいたくに使うことで、国に納める語ではないので合わない。"}, {"text": "彼は一代で大きな贅を築き、子どもに残した。", "explanation": "ここは〈富〉（財産）の意味。贅は惜しまず使うぜいたくで、築いて残す財産の意味にはならない。"}, {"text": "彼女は新しい贅を三冊買って、棚に並べた。", "explanation": "贅は金や物を惜しまず使うぜいたくを表す語で、本を数えて買う意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53012, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贅", "is_correct": true, "explanation": "「贅を排す」は、ぜいたくな費やしを避ける意味。「贅を排して簡素に」に入る語。"}, {"text": "祈り", "is_correct": false, "explanation": "「祈りを排す」とは言わない。祈りは捧げるもので、簡素に行う文脈に合わない。"}, {"text": "熱意", "is_correct": false, "explanation": "「熱意を排す」は不自然。熱意は込めたり燃やしたりするもので、排する対象ではない。"}, {"text": "誠意", "is_correct": false, "explanation": "「誠意を排す」とは言わない。誠意は示すもので、ここでは意味が合わない。"}], "explanations": {"贅": "「贅を排す」は、ぜいたくな費やしを避ける意味。「贅を排して簡素に」に入る語。", "祈り": "「祈りを排す」とは言わない。祈りは捧げるもので、簡素に行う文脈に合わない。", "熱意": "「熱意を排す」は不自然。熱意は込めたり燃やしたりするもので、排する対象ではない。", "誠意": "「誠意を排す」とは言わない。誠意は示すもので、ここでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "贅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は時間の贅がなく、慌てて家を出た。", "explanation": "ここは〈余裕〉の意味。贅は惜しまず費やすぜいたくで、時間の余裕を表さないので合わない。"}, {"text": "彼は畑で贅を流して働き、家族を養った。", "explanation": "ここは〈汗〉の意味。贅は流すものではなく、費やして楽しむぜいたくなので合わない。"}, {"text": "彼は贅を償うため、二年間刑務所で過ごした。", "explanation": "ここは〈罪〉の意味。贅は償うものではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53012, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は孫の誕生日に、贅が尽くした料理を振る舞った。", "corrected_sentence": "祖母は孫の誕生日に、贅を尽くした料理を振る舞った。", "error_description": "「贅を尽くす」の助詞は「を」。「が」は誤り（正しくは「贅を尽くした」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53012, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王は贅を尽くすした宴を開いた。", "corrected_sentence": "王は贅を尽くした宴を開いた。", "error_description": "「尽くす」の過去連体形は「尽くした」。「尽くすした」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53013, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「一般の人」と名詞を修飾する連体修飾の助詞で、文の意味が通る。"}, {"text": "に", "is_correct": false, "explanation": "「一般に人も」では続かず、人を修飾する関係にならない。"}, {"text": "で", "is_correct": false, "explanation": "「一般で人も」は不自然で、名詞を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「一般を人」は目的語にならず、人を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「一般の人」と名詞を修飾する連体修飾の助詞で、文の意味が通る。", "に": "「一般に人も」では続かず、人を修飾する関係にならない。", "で": "「一般で人も」は不自然で、名詞を修飾できない。", "を": "「一般を人」は目的語にならず、人を修飾できない。"}, "error_tags": {"に": "格助詞：位置や相手を示すが、名詞を修飾しない", "で": "格助詞：場所や手段を示すが、名詞を修飾しない", "を": "格助詞：目的語を示すが、後の名詞を修飾しない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特殊", "is_correct": true, "explanation": "「一般」（特別でない、ふつうの）の対義語。一般の人と区別される特別なものを指す。"}, {"text": "個人", "is_correct": false, "explanation": "一人ひとりを指す語で、一般の反対語ではない。"}, {"text": "大衆", "is_correct": false, "explanation": "多くの人々を指す語で、一般と近い意味であり対義語ではない。"}, {"text": "平均", "is_correct": false, "explanation": "数値の中心値を指す語で、対義語ではない。"}], "correct_answer": "特殊", "explanations": {"特殊": "「一般」（特別でない、ふつうの）の対義語。一般の人と区別される特別なものを指す。", "個人": "一人ひとりを指す語で、一般の反対語ではない。", "大衆": "多くの人々を指す語で、一般と近い意味であり対義語ではない。", "平均": "数値の中心値を指す語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53013, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特別", "is_correct": true, "explanation": "「一般」（特別でない、ふつうの）の反対。ここでは「特別な場合」との対比になる。"}, {"text": "内部", "is_correct": false, "explanation": "内側を指す語で、一般と対になる語ではない。"}, {"text": "全体", "is_correct": false, "explanation": "全部の集まりを指す語で、対義語にはあたらない。"}, {"text": "機密", "is_correct": false, "explanation": "秘密にされたものを指す語で、対義語ではない。"}], "correct_answer": "特別", "explanations": {"特別": "「一般」（特別でない、ふつうの）の反対。ここでは「特別な場合」との対比になる。", "内部": "内側を指す語で、一般と対になる語ではない。", "全体": "全部の集まりを指す語で、対義語にはあたらない。", "機密": "秘密にされたものを指す語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53013, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人に共通していること。ふつうのこと。", "primary_collocate": null, "pronunciation": "いっぱん", "ipa": "ippaɴ", "syllable_count": 4, "sentences": [{"text": "一般に、日本の夏は湿度が高くて蒸し暑い。", "target_word": "一般", "complexity_tier": "T3", "furigana": "一般[いっぱん]に、日本[にほん]の夏[なつ]は湿度[しつど]が高[たか]くて蒸[む]し暑[あつ]い。", "sentence_source": "generated"}, {"text": "この博物館は、学生だけでなく一般の人も無料で見学できる。", "target_word": "一般", "complexity_tier": "T3", "furigana": "この博物館[はくぶつかん]は、学生[がくせい]だけでなく一般[いっぱん]の人[ひと]も無料[むりょう]で見学[けんがく]できる。", "sentence_source": "generated"}, {"text": "専門家には簡単な話でも、一般の人には難しく感じられる。", "target_word": "一般", "complexity_tier": "T3", "furigana": "専門家[せんもんか]には簡単[かんたん]な話[はなし]でも、一般[いっぱん]の人[ひと]には難[むずか]しく感[かん]じられる。", "sentence_source": "generated"}, {"text": "会議は社員だけで行い、一般の参加者は入れない。", "target_word": "一般", "complexity_tier": "T3", "furigana": "会議[かいぎ]は社員[しゃいん]だけで行[おこな]い、一般[いっぱん]の参加者[さんかしゃ]は入[い]れない。", "sentence_source": "generated"}, {"text": "彼の意見は特殊で、一般の考え方とはかなり違う。", "target_word": "一般", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は特殊[とくしゅ]で、一般[いっぱん]の考[かんが]え方[かた]とはかなり違[ちが]う。", "sentence_source": "generated"}, {"text": "来週から一般に販売が始まるので、早めに店へ行くつもりだ。", "target_word": "一般", "complexity_tier": "T3", "furigana": "来週[らいしゅう]から一般[いっぱん]に販売[はんばい]が始[はじ]まるので、早[はや]めに店[みせ]へ行[い]くつもりだ。", "sentence_source": "generated"}, {"text": "この規則は特別な場合を除いて、一般に適用される。", "target_word": "一般", "complexity_tier": "T3", "furigana": "この規則[きそく]は特別[とくべつ]な場合[ばあい]を除[のぞ]いて、一般[いっぱん]に適用[てきよう]される。", "sentence_source": "generated"}, {"text": "研究の成果を、一般の読者にもわかりやすく説明した本だ。", "target_word": "一般", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の成果[せいか]を、一般[いっぱん]の読者[どくしゃ]にもわかりやすく説明[せつめい]した本[ほん]だ。", "sentence_source": "generated"}, {"text": "一般の家庭では、電気代が冬に高くなることが多い。", "target_word": "一般", "complexity_tier": "T3", "furigana": "一般[いっぱん]の家庭[かてい]では、電気代[でんきだい]が冬[ふゆ]に高[たか]くなることが多[おお]い。", "sentence_source": "generated"}, {"text": "彼は有名な俳優だが、休みの日は一般の人と同じように買い物をする。", "target_word": "一般", "complexity_tier": "T3", "furigana": "彼[かれ]は有名[ゆうめい]な俳優[はいゆう]だが、休[やす]みの日[ひ]は一般[いっぱん]の人[ひと]と同[おな]じように買[か]い物[もの]をする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一般", "label": "基本形"}, {"form": "一般の", "label": "連体形(の)"}, {"form": "一般に", "label": "連用形(に)"}, {"form": "一般だ", "label": "断定形"}, {"form": "一般で", "label": "連用形(で)"}], "register": "書き言葉(文章語・常体)", "sense_fingerprint": "特別ではなく、多くの人や場合に当てはまるふつうの状態。専門家・特別な人と対比して使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '264dd313-b4bf-4db0-a29c-2a90cdc233fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53013, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一般", "is_correct": true, "explanation": "「一般に」は、ふつうには日本の夏は蒸し暑いという一般論として文が続く。"}, {"text": "特殊", "is_correct": false, "explanation": "「特殊に」は副詞として続かず、一般論の文脈に合わない。"}, {"text": "例外", "is_correct": false, "explanation": "「例外に」は副詞として続かず、夏の湿度の説明として意味が通らない。"}, {"text": "不利", "is_correct": false, "explanation": "「不利に」では夏の湿度の説明として意味が通らない。"}], "explanations": {"一般": "「一般に」は、ふつうには日本の夏は蒸し暑いという一般論として文が続く。", "特殊": "「特殊に」は副詞として続かず、一般論の文脈に合わない。", "例外": "「例外に」は副詞として続かず、夏の湿度の説明として意味が通らない。", "不利": "「不利に」では夏の湿度の説明として意味が通らない。"}, "sentence_index": 0, "correct_answer": "一般"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "実験は一般が担当し、二班は記録を取った。", "explanation": "ここは〈一班〉（第一の班）の意味。一般は特別でない多くの人を指す語なので、班の番号を表す場面では合わない。"}, {"text": "彼は一般の天才として知られている。", "explanation": "ここは〈特異〉（他と違って際立つ）の意味。一般は並でありふれたことを指すので、際立った天才とは矛盾して合わない。"}, {"text": "選手たちは一般に走り出した。", "explanation": "「一斉に」との取り違え。一般は多くの人に共通することを指すので、全員が同時に動き出す場面では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53013, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一般", "is_correct": true, "explanation": "「一般に適用される」は、特別な場合を除いて広く当てはまるという意味になる。"}, {"text": "禁止", "is_correct": false, "explanation": "「禁止に適用される」は名詞に「に」を続けた不自然な形で、除外の文脈にも合わない。"}, {"text": "例外", "is_correct": false, "explanation": "「例外に適用される」は意味が通らず、除外の文脈とも合わない。"}, {"text": "必要", "is_correct": false, "explanation": "「必要に適用される」は不自然で、除外の文脈と合わない。"}], "explanations": {"一般": "「一般に適用される」は、特別な場合を除いて広く当てはまるという意味になる。", "禁止": "「禁止に適用される」は名詞に「に」を続けた不自然な形で、除外の文脈にも合わない。", "例外": "「例外に適用される」は意味が通らず、除外の文脈とも合わない。", "必要": "「必要に適用される」は不自然で、除外の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "一般"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は一般の選手として世界大会で優勝した。", "explanation": "ここは〈一流〉（最高水準の）の意味。一般はふつうで並の水準を指すので、世界大会で優勝した選手とは矛盾して合わない。"}, {"text": "この部屋は一般の利用で、関係者しか入れない。", "explanation": "ここは〈専用〉（特定の人だけが使う）の意味。一般は誰でも使えることを指すので、関係者だけが入れるという後半とは矛盾して合わない。"}, {"text": "その判断は一般だった。前例のない決定だ。", "explanation": "ここは〈異例〉（前例がなく、めずらしい）の意味。一般はふつうのことを指すので、前例のない決定だという後半とは矛盾して合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53013, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬は一般で販売されている。", "corrected_sentence": "この薬は一般に販売されている。", "error_description": "「販売される」の相手を示す助詞は「に」を使う。「一般で販売」は助詞「で」が誤り。正しくは「一般に販売」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53013, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その作品は一般を人に人気がある。", "corrected_sentence": "その作品は一般の人に人気がある。", "error_description": "「一般」は後の名詞「人」を修飾するので、連体修飾の「の」が必要。「一般を人」は「を」が誤り。正しくは「一般の人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f984ddc3-240e-4edd-9c2b-1845a371ce98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53014, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一般に」は「ふつう」の意味の副詞。文頭で判断を示す「に」。"}, {"text": "が", "is_correct": false, "explanation": "「一般が」は主語にならず、副詞用法とも合わない。"}, {"text": "で", "is_correct": false, "explanation": "「一般で」は場所や手段の意味にならず、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「一般を、日本の夏は」は目的語にならず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「一般に」は「ふつう」の意味の副詞。文頭で判断を示す「に」。", "が": "「一般が」は主語にならず、副詞用法とも合わない。", "で": "「一般で」は場所や手段の意味にならず、不自然。", "を": "「一般を、日本の夏は」は目的語にならず、文が成り立たない。"}, "error_tags": {"に": "副詞", "が": "主語", "で": "手段", "を": "目的語"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特殊", "is_correct": true, "explanation": "「一般」の対義語（ほかと違う、限られた）。「特別でなく広く共通する」の反対側にある語。"}, {"text": "失敗", "is_correct": false, "explanation": "「一般」の対義語にはならない。"}, {"text": "名人", "is_correct": false, "explanation": "人を指す語で、「一般」と対になる語ではない。"}, {"text": "故郷", "is_correct": false, "explanation": "場所を指す語で、「一般」の対義語にならない。"}], "correct_answer": "特殊", "explanations": {"特殊": "「一般」の対義語（ほかと違う、限られた）。「特別でなく広く共通する」の反対側にある語。", "失敗": "「一般」の対義語にはならない。", "名人": "人を指す語で、「一般」と対になる語ではない。", "故郷": "場所を指す語で、「一般」の対義語にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
