INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53014, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特別でなく、広く一般的なさま。多くの人や物事に共通していること。", "primary_collocate": null, "pronunciation": "いっぱん", "ipa": "ippaɴ", "syllable_count": 4, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "一般", "complexity_tier": "T4", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "一般に、日本の夏は湿度が高くて蒸し暑い。", "target_word": "一般", "complexity_tier": "T3", "furigana": "一般[いっぱん]に、日本[にほん]の夏[なつ]は湿度[しつど]が高[たか]くて蒸[む]し暑[あつ]い。", "sentence_source": "generated"}, {"text": "この美術館は、月に一度だけ一般の人にも庭を公開している。", "target_word": "一般", "complexity_tier": "T3", "furigana": "この美術館[びじゅつかん]は、月[つき]に一度[いちど]だけ一般[いっぱん]の人[ひと]にも庭[にわ]を公開[こうかい]している。", "sentence_source": "generated"}, {"text": "専門家の意見は、一般の感覚とは違うことが多い。", "target_word": "一般", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の意見[いけん]は、一般[いっぱん]の感覚[かんかく]とは違[ちが]うことが多[おお]い。", "sentence_source": "generated"}, {"text": "工事の説明会は、住民だけでなく一般の参加者も自由に出席できる。", "target_word": "一般", "complexity_tier": "T4", "furigana": "工事[こうじ]の説明会[せつめいかい]は、住民[じゅうみん]だけでなく一般[いっぱん]の参加者[さんかしゃ]も自由[じゆう]に出席[しゅっせき]できる。", "sentence_source": "generated"}, {"text": "この病院の救急外来は、一般の患者でも夜間に受診できる。", "target_word": "一般", "complexity_tier": "T4", "furigana": "この病院[びょういん]の救急外来[きゅうきゅうがいらい]は、一般[いっぱん]の患者[かんじゃ]でも夜間[やかん]に受診[じゅしん]できる。", "sentence_source": "generated"}, {"text": "一般に、新しい製品は発売直後の値段が高い。", "target_word": "一般", "complexity_tier": "T3", "furigana": "一般[いっぱん]に、新[あたら]しい製品[せいひん]は発売直後[はつばいちょくご]の値段[ねだん]が高[たか]い。", "sentence_source": "generated"}, {"text": "社員用の入口とは別に、一般の入口が建物の東側にある。", "target_word": "一般", "complexity_tier": "T3", "furigana": "社員用[しゃいんよう]の入口[いりぐち]とは別[べつ]に、一般[いっぱん]の入口[いりぐち]が建物[たてもの]の東側[ひがしがわ]にある。", "sentence_source": "generated"}, {"text": "一般の家庭では、毎日これほど高い肉を買う余裕はない。", "target_word": "一般", "complexity_tier": "T3", "furigana": "一般[いっぱん]の家庭[かてい]では、毎日[まいにち]これほど高[たか]い肉[にく]を買[か]う余裕[よゆう]はない。", "sentence_source": "generated"}, {"text": "彼女は専門家ではなく一般の読者として、この本の感想を書いた。", "target_word": "一般", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は専門家[せんもんか]ではなく一般[いっぱん]の読者[どくしゃ]として、この本[ほん]の感想[かんそう]を書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一般", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "一般:特別でなく広く共通する、ふつうの(一般の人・一般に)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: アヴァンギャルド (Zipf 2.38), 贅 (Zipf 2.41)']::text[], '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53014, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一般", "is_correct": true, "explanation": "「一般消費者」の「一般」。「〜、___消費者の直接的なアクセス」の空所に入る語。"}, {"text": "歴史", "is_correct": false, "explanation": "「歴史消費者」は成り立たず、消費者の範囲を表さない。"}, {"text": "好奇心", "is_correct": false, "explanation": "「好奇心消費者」は意味が通らず、文脈に合わない。"}, {"text": "誇り", "is_correct": false, "explanation": "「誇り消費者」は不自然で、消費者の範囲を表す語にならない。"}], "explanations": {"一般": "「一般消費者」の「一般」。「〜、___消費者の直接的なアクセス」の空所に入る語。", "歴史": "「歴史消費者」は成り立たず、消費者の範囲を表さない。", "好奇心": "「好奇心消費者」は意味が通らず、文脈に合わない。", "誇り": "「誇り消費者」は不自然で、消費者の範囲を表す語にならない。"}, "sentence_index": 0, "correct_answer": "一般"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加者の一般が、新しい案に賛成した。", "explanation": "一般は数の多さ（大半）を表さず、「参加者の一般」は成り立たない。"}, {"text": "エンジンの一般が原因で、車が止まった。", "explanation": "一般は機械の故障を表さず、この文は成り立たない。"}, {"text": "工事の一般が、予定より一か月遅れた。", "explanation": "一般は完成の意味を持たず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53014, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一般", "is_correct": true, "explanation": "「一般に」は「ふつう」の意味の副詞。「___に、新しい製品は発売直後の値段が高い」に入る語。"}, {"text": "確信", "is_correct": false, "explanation": "「確信に」は判断の語として成り立たず、文の意味が通らない。"}, {"text": "祈り", "is_correct": false, "explanation": "「祈りに」は判断を表す副詞にならず、製品の値段の話と合わない。"}, {"text": "悲しみ", "is_correct": false, "explanation": "「悲しみに」は副詞として成り立たず、文脈に合わない。"}], "explanations": {"一般": "「一般に」は「ふつう」の意味の副詞。「___に、新しい製品は発売直後の値段が高い」に入る語。", "確信": "「確信に」は判断の語として成り立たず、文の意味が通らない。", "祈り": "「祈りに」は判断を表す副詞にならず、製品の値段の話と合わない。", "悲しみ": "「悲しみに」は副詞として成り立たず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "一般"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の一般が急に変更された。", "explanation": "一般は予定の時期を表さず、「会議の一般」は成り立たない。"}, {"text": "今年の一般が足りず、計画を縮小した。", "explanation": "一般は使える金額を表さず、この文は成り立たない。"}, {"text": "明日の一般は雨だと予報されている。", "explanation": "一般は空模様を表さず、「明日の一般は雨」は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53014, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一般を、古い建物は冬の寒さに弱いと言われる。", "corrected_sentence": "一般に、古い建物は冬の寒さに弱いと言われる。", "error_description": "「一般に」（ふつうは）と副詞で使うのが正しい。「一般を」は文の成分として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53014, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は一般的の料金で、学生にもありがたい。", "corrected_sentence": "この店は一般的な料金で、学生にもありがたい。", "error_description": "「一般的」は形容動詞なので、名詞を修飾するときは「一般的な」。「一般的の」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53015, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「最善を尽くす」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「最善が尽くした」は主語を取る形になり、「尽くす」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「最善で尽くした」は手段の意味として不自然で、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「最善と尽くした」は並列の形になり、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「最善を尽くす」の目的語を示す。", "が": "「最善が尽くした」は主語を取る形になり、「尽くす」の目的語にならない。", "で": "「最善で尽くした」は手段の意味として不自然で、成り立たない。", "と": "「最善と尽くした」は並列の形になり、文が通らない。"}, "error_tags": {"が": "主格", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53015, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「力を尽くす」の目的語を示す。"}, {"text": "から", "is_correct": false, "explanation": "「力から尽くす」は起点を表し、目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「力より尽くす」は比較の形になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「力へ尽くす」は方向を表す形になり、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「力を尽くす」の目的語を示す。", "から": "「力から尽くす」は起点を表し、目的語にならない。", "より": "「力より尽くす」は比較の形になり、文が成り立たない。", "へ": "「力へ尽くす」は方向を表す形になり、目的語にならない。"}, "error_tags": {"から": "起点", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53015, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ぜんぶの力を使って、何かを最後までする。", "primary_collocate": null, "pronunciation": "つくす", "ipa": "tsɯkɯsɯ", "syllable_count": 3, "sentences": [{"text": "試合に勝つために、選手たちは最後まで全力を尽くした。", "target_word": "尽くした", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]つために、選手[せんしゅ]たちは最後[さいご]まで全力[ぜんりょく]を尽[つ]くした。", "sentence_source": "generated"}, {"text": "私は最善を尽くしたので、結果がどうでも後悔はない。", "target_word": "尽くした", "complexity_tier": "T3", "furigana": "私[わたし]は最善[さいぜん]を尽[つ]くしたので、結果[けっか]がどうでも後悔[こうかい]はない。", "sentence_source": "generated"}, {"text": "母は子どもたちのために、力を尽くして働き続けた。", "target_word": "尽くして", "complexity_tier": "T3", "furigana": "母[はは]は子[こ]どもたちのために、力[ちから]を尽[つ]くして働[はたら]き続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼は町の復興に力を尽くし、十年かけて商店街を元に戻した。", "target_word": "尽くし", "complexity_tier": "T4", "furigana": "彼[かれ]は町[まち]の復興[ふっこう]に力[ちから]を尽[つ]くし、十年[じゅうねん]かけて商店街[しょうてんがい]を元[もと]に戻[もど]した。", "sentence_source": "generated"}, {"text": "委員長は誠意を尽くして住民に説明し、ようやく理解を得た。", "target_word": "尽くして", "complexity_tier": "T4", "furigana": "委員長[いいんちょう]は誠意[せいい]を尽[つ]くして住民[じゅうみん]に説明[せつめい]し、ようやく理解[りかい]を得[え]た。", "sentence_source": "generated"}, {"text": "全力を尽くして走ったのに、わずかな差で二位だった。", "target_word": "尽くして", "complexity_tier": "T3", "furigana": "全力[ぜんりょく]を尽[つ]くして走[はし]ったのに、わずかな差[さ]で二位[にい]だった。", "sentence_source": "generated"}, {"text": "先生は生徒が卒業するまで、できる限り力を尽くして指導した。", "target_word": "尽くして", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]が卒業[そつぎょう]するまで、できる限[かぎ]り力[ちから]を尽[つ]くして指導[しどう]した。", "sentence_source": "generated"}, {"text": "新人の彼女は、与えられた仕事に力を尽くすことで信頼を得た。", "target_word": "尽くす", "complexity_tier": "T4", "furigana": "新人[しんじん]の彼女[かのじょ]は、与[あた]えられた仕事[しごと]に力[ちから]を尽[つ]くすことで信頼[しんらい]を得[え]た。", "sentence_source": "generated"}, {"text": "大会の準備に力を尽くしてくれた皆さんに、心から感謝します。", "target_word": "尽くして", "complexity_tier": "T3", "furigana": "大会[たいかい]の準備[じゅんび]に力[ちから]を尽[つ]くしてくれた皆[みな]さんに、心[こころ]から感謝[かんしゃ]します。", "sentence_source": "generated"}, {"text": "彼は自分の役目を果たすため、最後の一日まで力を尽くした。", "target_word": "尽くした", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の役目[やくめ]を果[は]たすため、最後[さいご]の一日[いちにち]まで力[ちから]を尽[つ]くした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "尽くす", "label": "終止形"}, {"form": "尽くし", "label": "連用形"}, {"form": "尽くした", "label": "過去形"}, {"form": "尽くして", "label": "て形"}, {"form": "尽くさ", "label": "未然形"}, {"form": "尽くせば", "label": "仮定形"}, {"form": "尽くそう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "尽くす:持てる力を出し切って最後までやる(力を尽くす・最善を尽くす・全力を尽くす)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53015, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽くした", "is_correct": true, "explanation": "正解。過去形で、「最後まで全力を尽くした」と文を言い切る。"}, {"text": "尽くそう", "is_correct": false, "explanation": "意志形で「〜しよう」の意味になり、事実を述べる文に合わない。"}, {"text": "尽くせ", "is_correct": false, "explanation": "命令形になり、「選手たちは」と続く平叙文に合わない。"}, {"text": "尽くさ", "is_correct": false, "explanation": "未然形は単独で文を終えられず、ここでは文が途切れる。"}], "explanations": {"尽くした": "正解。過去形で、「最後まで全力を尽くした」と文を言い切る。", "尽くそう": "意志形で「〜しよう」の意味になり、事実を述べる文に合わない。", "尽くせ": "命令形になり、「選手たちは」と続く平叙文に合わない。", "尽くさ": "未然形は単独で文を終えられず、ここでは文が途切れる。"}, "sentence_index": 0, "correct_answer": "尽くした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来客が玄関のチャイムを尽くした。", "explanation": "尽くすはチャイムを鳴らす意味では使わず、この文は成り立たない。"}, {"text": "彼は杖で地面を尽くして歩いた。", "explanation": "尽くすは地面を突く意味では使わず、この文は成り立たない。"}, {"text": "母は朝、コーヒーを尽くした。", "explanation": "尽くすはコーヒーを淹れる意味では使わず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53015, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽くして", "is_correct": true, "explanation": "正解。「力を尽くして指導した」で、て形により後文へ続く。"}, {"text": "尽くせる", "is_correct": false, "explanation": "可能形で、「指導した」に直接つながらない。"}, {"text": "尽くしたい", "is_correct": false, "explanation": "希望の形で、「指導した」と続く文の形にならない。"}, {"text": "尽くせない", "is_correct": false, "explanation": "否定の可能形で、文の意味が成り立たない。"}], "explanations": {"尽くして": "正解。「力を尽くして指導した」で、て形により後文へ続く。", "尽くせる": "可能形で、「指導した」に直接つながらない。", "尽くしたい": "希望の形で、「指導した」と続く文の形にならない。", "尽くせない": "否定の可能形で、文の意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "尽くして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弓道部の彼は、一射ごとに的を尽くした。", "explanation": "尽くすは矢を的に当てる意味では使わず、この文は成り立たない。"}, {"text": "その汚れは一度服に尽くすと、なかなか落ちない。", "explanation": "尽くすは汚れが付く意味では使わず、この文は成り立たない。"}, {"text": "船は夜明けに目的地に尽くした。", "explanation": "尽くすは到着の意味では使わず、「港に尽くした」は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53015, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "委員たちは全力を尽くすして、文化祭を成功させた。", "corrected_sentence": "委員たちは全力を尽くして、文化祭を成功させた。", "error_description": "正しくは「尽くして」（て形）。「尽くすして」は活用の誤りで、て形は語幹に「して」を付けた形になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "尽くした", "is_correct": true, "explanation": "正解。過去形で、理由を述べる「ので」に続く。"}, {"text": "尽くさ", "is_correct": false, "explanation": "未然形は「ので」に続かず、文がつながらない。"}, {"text": "尽くせば", "is_correct": false, "explanation": "仮定形で条件を表すため、理由の文に合わない。"}, {"text": "尽くそう", "is_correct": false, "explanation": "意志形で、事実の理由にならない。"}], "correct_form": "尽くした", "base_form": "尽くす", "form_label": "過去形", "sentence_index": 1, "explanations": {"尽くした": "正解。過去形で、理由を述べる「ので」に続く。", "尽くさ": "未然形は「ので」に続かず、文がつながらない。", "尽くせば": "仮定形で条件を表すため、理由の文に合わない。", "尽くそう": "意志形で、事実の理由にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53015, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は力を尽くしたて、ようやく資格を取った。", "corrected_sentence": "彼女は力を尽くして、ようやく資格を取った。", "error_description": "正しくは「尽くして」（て形）。「尽くしたて」は「た」と「て」が重なった誤った形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "尽くす", "is_correct": true, "explanation": "正解。「力を尽くすこと」で、名詞「こと」を修飾する連体形。"}, {"text": "尽くし", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「こと」に続かない。"}, {"text": "尽くせ", "is_correct": false, "explanation": "命令形で、名詞「こと」には続かず文が成り立たない。"}, {"text": "尽くさ", "is_correct": false, "explanation": "未然形は「こと」の前に置けず、文が成り立たない。"}], "correct_form": "尽くす", "base_form": "尽くす", "form_label": "連体形", "sentence_index": 7, "explanations": {"尽くす": "正解。「力を尽くすこと」で、名詞「こと」を修飾する連体形。", "尽くし": "連用形は名詞を直接修飾できず、「こと」に続かない。", "尽くせ": "命令形で、名詞「こと」には続かず文が成り立たない。", "尽くさ": "未然形は「こと」の前に置けず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53016, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「尽くしたが」は逆接で、後文「救うことはできなかった」につながる。"}, {"text": "を", "is_correct": false, "explanation": "「尽くしたを」は文が続かない。目的語の「手を」はすでに示されているので二重になる。"}, {"text": "に", "is_correct": false, "explanation": "「尽くしたに」は逆接の接続として働かず、文が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「尽くしたで」は接続の役割を果たさず、文が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「尽くしたが」は逆接で、後文「救うことはできなかった」につながる。", "を": "「尽くしたを」は文が続かない。目的語の「手を」はすでに示されているので二重になる。", "に": "「尽くしたに」は逆接の接続として働かず、文が通らない。", "で": "「尽くしたで」は接続の役割を果たさず、文が通らない。"}, "error_tags": {"を": "目的語重複", "に": "接続不成立", "で": "接続不成立"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53016, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「手段を尽くす」の目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「手段と尽くして」は並列の相手を示す形で、目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「手段から尽くして」は起点を表し、目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「手段より尽くして」は比較の形になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「手段を尽くす」の目的語を示す。", "と": "「手段と尽くして」は並列の相手を示す形で、目的語にならない。", "から": "「手段から尽くして」は起点を表し、目的語にならない。", "より": "「手段より尽くして」は比較の形になり、文が成り立たない。"}, "error_tags": {"と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53016, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "持っているすべてのものを出して、ある状態や結果にまで到らせる。", "primary_collocate": "贅", "pronunciation": "つくす", "ipa": "tsɯkɯsɯ", "syllable_count": 3, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "尽くした", "complexity_tier": "T4", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "医者はあらゆる手を尽くしたが、患者を救うことはできなかった。", "target_word": "尽くした", "complexity_tier": "T3", "furigana": "医者[いしゃ]はあらゆる手[て]を尽[つ]くしたが、患者[かんじゃ]を救[すく]うことはできなかった。", "sentence_source": "generated"}, {"text": "彼女は言葉を尽くして謝ったが、友人の怒りは収まらなかった。", "target_word": "尽くして", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は言葉[ことば]を尽[つ]くして謝[あやま]ったが、友人[ゆうじん]の怒[いか]りは収[おさ]まらなかった。", "sentence_source": "generated"}, {"text": "王は贅を尽くした宮殿を建て、民に重い税を課した。", "target_word": "尽くした", "complexity_tier": "T4", "furigana": "王[おう]は贅[ぜい]を尽[つ]くした宮殿[きゅうでん]を建[た]て、民[たみ]に重[おも]い税[ぜい]を課[か]した。", "sentence_source": "generated"}, {"text": "贅を尽くした料理が次々に運ばれ、客たちは感嘆の声を上げた。", "target_word": "尽くした", "complexity_tier": "T3", "furigana": "贅[ぜい]を尽[つ]くした料理[りょうり]が次々[つぎつぎ]に運[はこ]ばれ、客[きゃく]たちは感嘆[かんたん]の声[こえ]を上[あ]げた。", "sentence_source": "generated"}, {"text": "村人は手を尽くして堤防を補強したが、洪水は防げなかった。", "target_word": "尽くして", "complexity_tier": "T4", "furigana": "村人[むらびと]は手[て]を尽[つ]くして堤防[ていぼう]を補強[ほきょう]したが、洪水[こうずい]は防[ふせ]げなかった。", "sentence_source": "generated"}, {"text": "説明に言葉を尽くしても、現場を見ていない人には伝わらない。", "target_word": "尽くしても", "complexity_tier": "T4", "furigana": "説明[せつめい]に言葉[ことば]を尽[つ]くしても、現場[げんば]を見[み]ていない人[ひと]には伝[つた]わらない。", "sentence_source": "generated"}, {"text": "警察は考えられる手段を尽くして、行方不明の子どもを捜した。", "target_word": "尽くして", "complexity_tier": "T4", "furigana": "警察[けいさつ]は考[かんが]えられる手段[しゅだん]を尽[つ]くして、行方不明[ゆくえふめい]の子[こ]どもを捜[さが]した。", "sentence_source": "generated"}, {"text": "悪事の限りを尽くした男は、ついに捕らえられた。", "target_word": "尽くした", "complexity_tier": "T4", "furigana": "悪事[あくじ]の限[かぎ]りを尽[つ]くした男[おとこ]は、ついに捕[とら]えられた。", "sentence_source": "generated"}, {"text": "彼らは贅沢の限りを尽くした末に、財産をすべて使い果たした。", "target_word": "尽くした", "complexity_tier": "T4", "furigana": "彼[かれ]らは贅沢[ぜいたく]の限[かぎ]りを尽[つ]くした末[すえ]に、財産[ざいさん]をすべて使[つか]い果[は]たした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "尽くす", "label": "終止形"}, {"form": "尽くし", "label": "連用形"}, {"form": "尽くした", "label": "過去形"}, {"form": "尽くして", "label": "て形"}, {"form": "尽くさ", "label": "未然形"}, {"form": "尽くせば", "label": "仮定形"}, {"form": "尽くそう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "尽くす:持てるものを出し切って極みまで至らせる(贅を尽くす・手を尽くす・言葉を尽くす)", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): メゾン (Zipf 2.58), アヴァンギャルド (Zipf 2.38), 贅 (Zipf 2.41), 渇望 (Zipf 2.92)']::text[], '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53016, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽くした", "is_correct": true, "explanation": "正解。「贅を尽くした」は名詞「素材使い」を修飾する連体形。"}, {"text": "尽くし", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、ここでは文が途切れてしまう。"}, {"text": "尽くさず", "is_correct": false, "explanation": "ず形は名詞を修飾できず、「素材使い」に続けられない。"}, {"text": "尽くせ", "is_correct": false, "explanation": "命令形なので、名詞を修飾する位置には入らない。"}], "explanations": {"尽くした": "正解。「贅を尽くした」は名詞「素材使い」を修飾する連体形。", "尽くし": "連用形は名詞を直接修飾できず、ここでは文が途切れてしまう。", "尽くさず": "ず形は名詞を修飾できず、「素材使い」に続けられない。", "尽くせ": "命令形なので、名詞を修飾する位置には入らない。"}, "sentence_index": 0, "correct_answer": "尽くした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上を尽くして、本を探した。", "explanation": "「机の上を尽くす」は成り立たず、尽くすは場所を目的語にしない。"}, {"text": "電気を尽くして、部屋を出た。", "explanation": "「電気を尽くす」は成り立たず、尽くすは消す動作の意味では使わない。"}, {"text": "庭の木を尽くして、花を植えた。", "explanation": "「庭の木を尽くす」は成り立たず、尽くすは木を目的語にしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53016, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽くしても", "is_correct": true, "explanation": "正解。「言葉を尽くしても」は逆接で、後文「伝わらない」につながる。"}, {"text": "尽くせる", "is_correct": false, "explanation": "可能形で、「、現場を〜」へ自然に続く形にならない。"}, {"text": "尽くしたい", "is_correct": false, "explanation": "希望の形で、事実を述べる文の中に入る形ではない。"}, {"text": "尽くせない", "is_correct": false, "explanation": "否定の可能形で、後文の意味と合わない。"}], "explanations": {"尽くしても": "正解。「言葉を尽くしても」は逆接で、後文「伝わらない」につながる。", "尽くせる": "可能形で、「、現場を〜」へ自然に続く形にならない。", "尽くしたい": "希望の形で、事実を述べる文の中に入る形ではない。", "尽くせない": "否定の可能形で、後文の意味と合わない。"}, "sentence_index": 6, "correct_answer": "尽くしても"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い航海を終えて、船はようやく港に尽くした。", "explanation": "尽くすは到着の意味では使わず、「港に尽くした」は成り立たない。"}, {"text": "老人は杖で床を尽くして、ゆっくり立ち上がった。", "explanation": "尽くすは突く動作の意味では使わず、この文は成り立たない。"}, {"text": "店員は朝早く、シャッターを尽くして客を迎えた。", "explanation": "尽くすはシャッターを開ける意味では使わず、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53016, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防隊は手に尽くして、取り残された人を救い出した。", "corrected_sentence": "消防隊は手を尽くして、取り残された人を救い出した。", "error_description": "正しくは「手を尽くして」。「手に尽くして」は助詞「を」を「に」にした誤りで、「人に尽くす（献身する）」の形になり、あらゆる方法を試すという意味が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "尽くした", "is_correct": true, "explanation": "正解。過去形で、逆接の「が」に続く。"}, {"text": "尽くせば", "is_correct": false, "explanation": "仮定形で「〜すれば」の条件を表すため、事実を述べる文に合わない。"}, {"text": "尽くそう", "is_correct": false, "explanation": "意志形で「〜しよう」の意味になり、過去の事実を述べる文に合わない。"}, {"text": "尽くさ", "is_correct": false, "explanation": "未然形は「ない」「せる」などの後にしか続かず、「が」の前では文がつながらない。"}], "correct_form": "尽くした", "base_form": "尽くす", "form_label": "過去形", "sentence_index": 1, "explanations": {"尽くした": "正解。過去形で、逆接の「が」に続く。", "尽くせば": "仮定形で「〜すれば」の条件を表すため、事実を述べる文に合わない。", "尽くそう": "意志形で「〜しよう」の意味になり、過去の事実を述べる文に合わない。", "尽くさ": "未然形は「ない」「せる」などの後にしか続かず、「が」の前では文がつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53016, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は贅が尽くして、客を歓迎した。", "corrected_sentence": "彼は贅を尽くして、客を歓迎した。", "error_description": "正しくは「贅を尽くして」。「尽くす」は目的語を「を」で取るので、「贅が」は助詞の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "尽くして", "is_correct": true, "explanation": "正解。「手段を尽くして」で、後の「捜した」に続く。"}, {"text": "尽くせる", "is_correct": false, "explanation": "可能形で、後の「捜した」へ続く文の形にならない。"}, {"text": "尽くしたい", "is_correct": false, "explanation": "希望の形で、事実を述べる文に合わない。"}, {"text": "尽くせない", "is_correct": false, "explanation": "否定の可能形で、「手段」を述べる文の意味と合わない。"}], "correct_form": "尽くして", "base_form": "尽くす", "form_label": "て形", "sentence_index": 7, "explanations": {"尽くして": "正解。「手段を尽くして」で、後の「捜した」に続く。", "尽くせる": "可能形で、後の「捜した」へ続く文の形にならない。", "尽くしたい": "希望の形で、事実を述べる文に合わない。", "尽くせない": "否定の可能形で、「手段」を述べる文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
