INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53017, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを使ったり、見たり、入ったりできること。", "primary_collocate": null, "pronunciation": "あくせす", "ipa": "akɯsesɯ", "syllable_count": 4, "sentences": [{"text": "管理者だけが、このファイルへのアクセスを許されている。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "管理者[かんりしゃ]だけが、このファイルへのアクセスを許[ゆる]されている。", "sentence_source": "generated"}, {"text": "パスワードを忘れて、自分のアカウントへのアクセスができなくなった。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "パスワードを忘[わす]れて、自分[じぶん]のアカウントへのアクセスができなくなった。", "sentence_source": "generated"}, {"text": "図書館のおかげで、誰でも貴重な資料へのアクセスが可能だ。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "図書館[としょかん]のおかげで、誰[だれ]でも貴重[きちょう]な資料[しりょう]へのアクセスが可能[かのう]だ。", "sentence_source": "generated"}, {"text": "親は子どもの有害なサイトへのアクセスを制限した。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "親[おや]は子[こ]どもの有害[ゆうがい]なサイトへのアクセスを制限[せいげん]した。", "sentence_source": "generated"}, {"text": "山荘の鍵がないので、建物の中へのアクセスはできない。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "山荘[さんそう]の鍵[かぎ]がないので、建物[たてもの]の中[なか]へのアクセスはできない。", "sentence_source": "generated"}, {"text": "この会員になれば、すべての記事へのアクセスが自由になる。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "この会員[かいいん]になれば、すべての記事[きじ]へのアクセスが自由[じゆう]になる。", "sentence_source": "generated"}, {"text": "地下の倉庫へのアクセスは、許可を持つ人に限られている。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "地下[ちか]の倉庫[そうこ]へのアクセスは、許可[きょか]を持[も]つ人[ひと]に限[かぎ]られている。", "sentence_source": "generated"}, {"text": "停電でネットワークが止まり、データへのアクセスが不可能になった。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "停電[ていでん]でネットワークが止[と]まり、データへのアクセスが不可能[ふかのう]になった。", "sentence_source": "generated"}, {"text": "研究者は、古い記録へのアクセスを求めて役所に申請した。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、古[ふる]い記録[きろく]へのアクセスを求[もと]めて役所[やくしょ]に申請[しんせい]した。", "sentence_source": "generated"}, {"text": "無料のWi-Fiがあるので、旅行中も情報へのアクセスに困らない。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "無料[むりょう]のWi-Fiがあるので、旅行中[りょこうちゅう]も情報[じょうほう]へのアクセスに困[こま]らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アクセス", "label": "基本形"}, {"form": "アクセスする", "label": "する動詞"}, {"form": "アクセスした", "label": "過去形"}, {"form": "アクセスの", "label": "連体修飾（の）"}], "register": "中立（常体）", "sense_fingerprint": "ファイル・情報・建物などを利用・閲覧・出入りできる権利や可能性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53017, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクセス", "is_correct": true, "explanation": "「ファイルへのアクセス」は閲覧や利用の権利を表し、「許されている」と合う。"}, {"text": "理解", "is_correct": false, "explanation": "「ファイルへの理解」は意味を成さず、許可の対象にならない。"}, {"text": "誕生", "is_correct": false, "explanation": "「ファイルへの誕生」は不自然で、許される対象として成り立たない。"}, {"text": "年齢", "is_correct": false, "explanation": "「ファイルへの年齢」は対象として成り立たず、許可の文脈に合わない。"}], "explanations": {"アクセス": "「ファイルへのアクセス」は閲覧や利用の権利を表し、「許されている」と合う。", "理解": "「ファイルへの理解」は意味を成さず、許可の対象にならない。", "誕生": "「ファイルへの誕生」は不自然で、許される対象として成り立たない。", "年齢": "「ファイルへの年齢」は対象として成り立たず、許可の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "アクセス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カーブで、車のアクセスをゆっくり踏んだ。", "explanation": "「アクセル」の意味。アクセスはファイルや建物を利用・閲覧できることで、車の踏み込む部品ではない。"}, {"text": "図書館で古い新聞をアクセスした。", "explanation": "閲覧寄りの使い方だが、紙の新聞には使わず不自然な文。"}, {"text": "先生は生徒に親身にアクセスした。", "explanation": "「接する」の意味。アクセスは利用や出入りの可否を表し、人への態度は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53017, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクセス", "is_correct": true, "explanation": "「地下の倉庫へのアクセス」は立ち入りや利用の可否を表し、「許可を持つ人に限られている」と合う。"}, {"text": "天気", "is_correct": false, "explanation": "「地下の倉庫への天気」は成り立たず、許可の条件を表す文にならない。"}, {"text": "音量", "is_correct": false, "explanation": "「地下の倉庫への音量」は不自然で、限定の文脈に合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "「地下の倉庫への色彩」は場所との関係として成り立たず、許可の話と結びつかない。"}], "explanations": {"アクセス": "「地下の倉庫へのアクセス」は立ち入りや利用の可否を表し、「許可を持つ人に限られている」と合う。", "天気": "「地下の倉庫への天気」は成り立たず、許可の条件を表す文にならない。", "音量": "「地下の倉庫への音量」は不自然で、限定の文脈に合わない。", "色彩": "「地下の倉庫への色彩」は場所との関係として成り立たず、許可の話と結びつかない。"}, "sentence_index": 6, "correct_answer": "アクセス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁の一角のアクセスに、青い布を掛けた。", "explanation": "「アクセント」（飾りの要素）の意味。アクセスは場所や情報に近づける意味で、飾りとしては使わない。"}, {"text": "私は去年の合唱大会にアクセスした。", "explanation": "「参加」の意味。アクセスは利用や出入りの可否を表し、大会に加わる意味は表さない。"}, {"text": "ベランダのアクセスを毎朝して、草を抜いた。", "explanation": "「手入れ」の意味。アクセスは近づいたり利用したりできることで、ベランダの世話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53017, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私だけが、この写真データへのアクセスで許されている。", "corrected_sentence": "私だけが、この写真データへのアクセスを許されている。", "error_description": "「許す」は目的語に「を」を取るので「アクセスを許されている」が正しい。「で」は助詞として誤りで、許可の対象を示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53017, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週の会議では、社外の人も資料へアクセスが認められる。", "corrected_sentence": "来週の会議では、社外の人も資料へのアクセスが認められる。", "error_description": "「資料へアクセス」は「の」が抜けた誤り。「へ」に「の」を続けて名詞「アクセス」につなぐ必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
