INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53018, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある場所や情報、機会などに近づいたり、利用したりできること。", "primary_collocate": null, "pronunciation": "あくせす", "ipa": "akɯsesɯ", "syllable_count": 4, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "アクセス", "complexity_tier": "T5", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "この島は橋がないので、本土へのアクセスが不便だ。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "この島[しま]は橋[はし]がないので、本土[ほんど]へのアクセスが不便[ふべん]だ。", "sentence_source": "generated"}, {"text": "山奥の村は雪のせいで、外からのアクセスが完全に絶たれた。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "山奥[やまおく]の村[むら]は雪[ゆき]のせいで、外[そと]からのアクセスが完全[かんぜん]に絶[た]たれた。", "sentence_source": "generated"}, {"text": "貧しい家庭の子どもは、良い教育へのアクセスが限られている。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "貧[まず]しい家庭[かてい]の子[こ]どもは、良[よ]い教育[きょういく]へのアクセスが限[かぎ]られている。", "sentence_source": "generated"}, {"text": "新しいバスが走り、駅へのアクセスがずっとよくなった。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "新[あたら]しいバスが走[はし]り、駅[えき]へのアクセスがずっとよくなった。", "sentence_source": "generated"}, {"text": "田舎では医療へのアクセスが悪いため、病院まで二時間かかる。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "田舎[いなか]では医療[いりょう]へのアクセスが悪[わる]いため、病院[びょういん]まで二時間[にじかん]かかる。", "sentence_source": "generated"}, {"text": "海に近いホテルは、ビーチへのアクセスが抜群だ。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "海[うみ]に近[ちか]いホテルは、ビーチへのアクセスが抜群[ばつぐん]だ。", "sentence_source": "generated"}, {"text": "難民は、水や食料へのアクセスさえ十分に得られない。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "難民[なんみん]は、水[みず]や食料[しょくりょう]へのアクセスさえ十分[じゅうぶん]に得[え]られない。", "sentence_source": "generated"}, {"text": "政府は、若者が仕事を探す機会へのアクセスを広げようとしている。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "政府[せいふ]は、若者[わかもの]が仕事[しごと]を探[さが]す機会[きかい]へのアクセスを広[ひろ]げようとしている。", "sentence_source": "generated"}, {"text": "工事中のため、公園へのアクセスは一時的に制限されている。", "target_word": "アクセス", "complexity_tier": "T3", "furigana": "工事中[こうじちゅう]のため、公園[こうえん]へのアクセスは一時的[いちじてき]に制限[せいげん]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アクセス", "label": "基本形"}, {"form": "アクセスする", "label": "する動詞"}, {"form": "アクセスした", "label": "過去形"}, {"form": "アクセスの", "label": "連体修飾（の）"}], "register": "中立（常体）", "sense_fingerprint": "場所・サービス・機会などに近づけること、またはそこへの行きやすさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アヴァンギャルド (Zipf 2.38), 贅 (Zipf 2.41)']::text[], '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53018, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクセス", "is_correct": true, "explanation": "「直接的なアクセス」は消費者が商品や店に近づくことを指し、それを拒絶するという文脈に合う。"}, {"text": "距離", "is_correct": false, "explanation": "「直接的な距離」は拒絶の対象にならず、「拒絶することで渇望を生む」という文の流れに合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「直接的な季節」は言い方として成り立たず、拒絶の対象にもならない。"}, {"text": "色合い", "is_correct": false, "explanation": "「直接的な色合い」は拒絶の対象として不自然で、消費者の行動を表せない。"}], "explanations": {"アクセス": "「直接的なアクセス」は消費者が商品や店に近づくことを指し、それを拒絶するという文脈に合う。", "距離": "「直接的な距離」は拒絶の対象にならず、「拒絶することで渇望を生む」という文の流れに合わない。", "季節": "「直接的な季節」は言い方として成り立たず、拒絶の対象にもならない。", "色合い": "「直接的な色合い」は拒絶の対象として不自然で、消費者の行動を表せない。"}, "sentence_index": 0, "correct_answer": "アクセス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この曲のアクセスを強めて、踊りを変えた。", "explanation": "「アクセント（強調）」の意味。アクセスは近づく・利用する意味で、強調の位置は表さない。"}, {"text": "坂道で、車のアクセスを強く踏み込んだ。", "explanation": "「アクセル」の意味。アクセスは近づくことや利用できることで、車の踏み込む部品ではない。"}, {"text": "子どもは動物に優しくアクセスした。", "explanation": "「接する」の意味。アクセスは場所・情報・機会を利用できることで、人や動物への態度は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53018, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクセス", "is_correct": true, "explanation": "「ビーチへのアクセス」は場所への行きやすさを表し、「抜群だ」という評価と合う。"}, {"text": "天気", "is_correct": false, "explanation": "「ビーチへの天気」は場所との関係として成り立たず、「抜群だ」とは評価できない。"}, {"text": "値段", "is_correct": false, "explanation": "「ビーチへの値段」は不自然で、場所の便利さを表す文にならない。"}, {"text": "音量", "is_correct": false, "explanation": "「ビーチへの音量」は場所に対する言い方として成り立たず、「抜群だ」とも結びつかない。"}], "explanations": {"アクセス": "「ビーチへのアクセス」は場所への行きやすさを表し、「抜群だ」という評価と合う。", "天気": "「ビーチへの天気」は場所との関係として成り立たず、「抜群だ」とは評価できない。", "値段": "「ビーチへの値段」は不自然で、場所の便利さを表す文にならない。", "音量": "「ビーチへの音量」は場所に対する言い方として成り立たず、「抜群だ」とも結びつかない。"}, "sentence_index": 6, "correct_answer": "アクセス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関のアクセスに、赤い花を一つ添えた。", "explanation": "「アクセント」（飾りの要素）の意味。アクセスは場所や情報に近づける意味で、飾りとしては使わない。"}, {"text": "私は去年の大会にアクセスした。", "explanation": "「参加」の意味。アクセスは場所や情報を利用できることで、大会に加わる意味は表さない。"}, {"text": "庭のアクセスを毎朝して、花を植え直した。", "explanation": "「手入れ」の意味。アクセスは近づいたり利用したりできることで、庭の世話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53018, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地下鉄の延伸で、大学の正門へアクセスが大きく改善した。", "corrected_sentence": "地下鉄の延伸で、大学の正門へのアクセスが大きく改善した。", "error_description": "「正門へアクセス」は助詞「の」が抜けた誤り。「正門へのアクセス」が正しく、「へ」に「の」を続けて名詞「アクセス」につなぐ必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53018, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの安全のため、遊び場へのアクセスをできない。", "corrected_sentence": "子どもの安全のため、遊び場へのアクセスができない。", "error_description": "「できない」の主語は「が」で示す。「アクセスをできない」は「を」が誤りで、可能の「できる」には「が」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
