INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53019, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても強いこと。", "primary_collocate": null, "pronunciation": "きょうれつ", "ipa": "kʲoːɾetsɯ", "syllable_count": 4, "sentences": [{"text": "真夏の強烈な日差しの中を、一時間も歩き続けた。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "真夏[まなつ]の強烈[きょうれつ]な日差[ひざ]しの中[なか]を、一時間[いちじかん]も歩[ある]き続[つづ]けた。", "sentence_source": "generated"}, {"text": "強烈なにおいが部屋に広がり、私は思わず窓を開けた。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "強烈[きょうれつ]なにおいが部屋[へや]に広[ひろ]がり、私[わたし]は思[おも]わず窓[まど]を開[あ]けた。", "sentence_source": "generated"}, {"text": "彼は相手の顔に強烈なパンチを入れた。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "彼[かれ]は相手[あいて]の顔[かお]に強烈[きょうれつ]なパンチを入[い]れた。", "sentence_source": "generated"}, {"text": "強烈な風が吹いて、庭の木が何本も倒れた。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "強烈[きょうれつ]な風[かぜ]が吹[ふ]いて、庭[にわ]の木[き]が何本[なんぼん]も倒[たお]れた。", "sentence_source": "generated"}, {"text": "このカレーは強烈に辛くて、水を何杯も飲んだ。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "このカレーは強烈[きょうれつ]に辛[から]くて、水[みず]を何杯[なんばい]も飲[の]んだ。", "sentence_source": "generated"}, {"text": "暗い部屋で強烈な光を見て、目がくらんだ。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "暗[くら]い部屋[へや]で強烈[きょうれつ]な光[ひかり]を見[み]て、目[め]がくらんだ。", "sentence_source": "generated"}, {"text": "台風の強烈な雨で、道が川のようになった。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "台風[たいふう]の強烈[きょうれつ]な雨[あめ]で、道[みち]が川[かわ]のようになった。", "sentence_source": "generated"}, {"text": "強烈な酸味のレモンを、そのままかじってしまった。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "強烈[きょうれつ]な酸味[さんみ]のレモンを、そのままかじってしまった。", "sentence_source": "generated"}, {"text": "ライブ会場は強烈な音で、耳がしばらく痛かった。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "ライブ会場[かいじょう]は強烈[きょうれつ]な音[おと]で、耳[みみ]がしばらく痛[いた]かった。", "sentence_source": "generated"}, {"text": "強烈な寒さの朝、水道管が凍ってしまった。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "強烈[きょうれつ]な寒[さむ]さの朝[あさ]、水道管[すいどうかん]が凍[こお]ってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強烈", "label": "語幹"}, {"form": "強烈な", "label": "連体形"}, {"form": "強烈に", "label": "連用形"}, {"form": "強烈だ", "label": "終止形"}, {"form": "強烈で", "label": "中止形"}], "register": "中立（常体）", "sense_fingerprint": "光・におい・味・打撃・風雨など物理的な刺激や力がとても強いさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53019, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強烈", "is_correct": true, "explanation": "「強烈な日差し」は光や熱がとても強いことを表し、「一時間も歩き続けた」という文脈と合う。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔な日差し」は言い方として成り立たず、強さを表さない。"}, {"text": "勤勉", "is_correct": false, "explanation": "「勤勉な日差し」は意味が合わず、日差しの性質を表さない。"}, {"text": "雑然", "is_correct": false, "explanation": "「雑然な日差し」は不自然で、日差しの強さを表す文脈に合わない。"}], "explanations": {"強烈": "「強烈な日差し」は光や熱がとても強いことを表し、「一時間も歩き続けた」という文脈と合う。", "清潔": "「清潔な日差し」は言い方として成り立たず、強さを表さない。", "勤勉": "「勤勉な日差し」は意味が合わず、日差しの性質を表さない。", "雑然": "「雑然な日差し」は不自然で、日差しの強さを表す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "強烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強烈な刃物で、指先を切ってしまった。", "explanation": "「鋭利」の意味。強烈は刺激や力の強さを表し、刃物の切れ味には使わない。"}, {"text": "父は強烈な荷物を三つ運んだ。", "explanation": "「重い」の意味。強烈は力や刺激の強さを表し、物の重さを言う語ではない。"}, {"text": "山の湧き水は強烈に澄んでいて、冷たかった。", "explanation": "「透明」の意味。強烈は強さを表す語で、水の透み具合は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53019, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強烈", "is_correct": true, "explanation": "「台風の強烈な雨」は激しく強い雨を表し、「道が川のようになった」と合う。"}, {"text": "不潔", "is_correct": false, "explanation": "「台風の不潔な雨」は意味が合わず、川のようになる状況を表さない。"}, {"text": "簡素", "is_correct": false, "explanation": "「台風の簡素な雨」は言い方として成り立たず、雨の強さを表さない。"}, {"text": "厳格", "is_correct": false, "explanation": "「台風の厳格な雨」は不自然で、雨の激しさを表す文脈に合わない。"}], "explanations": {"強烈": "「台風の強烈な雨」は激しく強い雨を表し、「道が川のようになった」と合う。", "不潔": "「台風の不潔な雨」は意味が合わず、川のようになる状況を表さない。", "簡素": "「台風の簡素な雨」は言い方として成り立たず、雨の強さを表さない。", "厳格": "「台風の厳格な雨」は不自然で、雨の激しさを表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "強烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その机は強烈な作りで、すぐにがたついた。", "explanation": "「粗雑」の意味。強烈は力や刺激の強さを表し、作りの雑さは表さない。"}, {"text": "彼女は強烈な小声で、そっと話しかけた。", "explanation": "「静か」の意味。強烈は強さを表し、音の静けさとは合わない。"}, {"text": "このパンは強烈に柔らかい。", "explanation": "強烈は強さの激しさを表すので、柔らかさの程度強調には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53019, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の強烈に陽射しを避けて、木陰で休んだ。", "corrected_sentence": "夏の強烈な陽射しを避けて、木陰で休んだ。", "error_description": "名詞「陽射し」を修飾するには連体形「強烈な」が必要。連用形「強烈に」は名詞の前には置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強烈な", "is_correct": true, "explanation": "連体形で名詞「におい」を修飾する形。「強烈なにおい」となる。"}, {"text": "強烈に", "is_correct": false, "explanation": "連用形で、動詞や形容詞を修飾する形。名詞「におい」の前には入らない。"}, {"text": "強烈だ", "is_correct": false, "explanation": "終止形で、文を終える形。名詞を修飾できない。"}, {"text": "強烈で", "is_correct": false, "explanation": "中止形で、文を続けるときの形。名詞の前には使わない。"}], "correct_form": "強烈な", "base_form": "強烈だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"強烈な": "連体形で名詞「におい」を修飾する形。「強烈なにおい」となる。", "強烈に": "連用形で、動詞や形容詞を修飾する形。名詞「におい」の前には入らない。", "強烈だ": "終止形で、文を終える形。名詞を修飾できない。", "強烈で": "中止形で、文を続けるときの形。名詞の前には使わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53019, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕立の雨は強烈な、傘も役に立たなかった。", "corrected_sentence": "夕立の雨は強烈で、傘も役に立たなかった。", "error_description": "文を続けるには中止形「強烈で」が必要。連体形「強烈な」は名詞の前に置く形で、読点の前では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強烈な", "is_correct": true, "explanation": "連体形で名詞「酸味」を修飾する形。「強烈な酸味」となる。"}, {"text": "強烈だった", "is_correct": false, "explanation": "過去形で、名詞「酸味」を修飾する位置には入らない。"}, {"text": "強烈である", "is_correct": false, "explanation": "「である」は名詞の前に直接つかず、「酸味」を修飾できない。"}, {"text": "強烈の", "is_correct": false, "explanation": "形容動詞の語幹に格助詞「の」は続かず、名詞を修飾する形ではない。"}], "correct_form": "強烈な", "base_form": "強烈だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"強烈な": "連体形で名詞「酸味」を修飾する形。「強烈な酸味」となる。", "強烈だった": "過去形で、名詞「酸味」を修飾する位置には入らない。", "強烈である": "「である」は名詞の前に直接つかず、「酸味」を修飾できない。", "強烈の": "形容動詞の語幹に格助詞「の」は続かず、名詞を修飾する形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
