INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53020, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "感情や印象などが非常に強いこと。また、そのさま。", "primary_collocate": null, "pronunciation": "きょうれつ", "ipa": "kʲoːɾetsɯ", "syllable_count": 4, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "強烈", "complexity_tier": "T5", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "初めて見たオーロラの美しさは、強烈な印象として心に残っている。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "初[はじ]めて見[み]たオーロラの美[うつく]しさは、強烈[きょうれつ]な印象[いんしょう]として心[こころ]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "彼の言葉は強烈で、会場にいた全員が静まり返った。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]は強烈[きょうれつ]で、会場[かいじょう]にいた全員[ぜんいん]が静[しず]まり返[かえ]った。", "sentence_source": "generated"}, {"text": "彼女に会いたいという強烈な思いが、私を遠い町へ向かわせた。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "彼女[かのじょ]に会[あ]いたいという強烈[きょうれつ]な思[おも]いが、私[わたし]を遠[とお]い町[まち]へ向[む]かわせた。", "sentence_source": "generated"}, {"text": "その映画の最後の場面はあまりに強烈で、夜になっても忘れられなかった。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "その映画[えいが]の最後[さいご]の場面[ばめん]はあまりに強烈[きょうれつ]で、夜[よる]になっても忘[わす]れられなかった。", "sentence_source": "generated"}, {"text": "試合に負けた悔しさは強烈で、しばらく食事ものどを通らなかった。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けた悔[くや]しさは強烈[きょうれつ]で、しばらく食事[しょくじ]ものどを通[とお]らなかった。", "sentence_source": "generated"}, {"text": "強烈な個性を持つ画家の作品は、見る人の心をとらえて離さない。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "強烈[きょうれつ]な個性を持つ画家の作品は、見る人の心をとらえて離さない。", "sentence_source": "generated"}, {"text": "別れの悲しみは強烈で、涙が止まらなかった。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "別[わか]れの悲[かな]しみは強烈[きょうれつ]で、涙[なみだ]が止[と]まらなかった。", "sentence_source": "generated"}, {"text": "子どものころに受けた強烈な体験が、彼の生き方を変えた。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "子[こ]どものころに受[う]けた強烈[きょうれつ]な体験[たいけん]が、彼[かれ]の生[い]き方[かた]を変[か]えた。", "sentence_source": "generated"}, {"text": "強烈な嫉妬を感じて、自分でも驚いた。", "target_word": "強烈", "complexity_tier": "T3", "furigana": "強烈[きょうれつ]な嫉妬[しっと]を感[かん]じて、自分[じぶん]でも驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強烈", "label": "語幹"}, {"form": "強烈な", "label": "連体形"}, {"form": "強烈に", "label": "連用形"}, {"form": "強烈だ", "label": "終止形"}, {"form": "強烈で", "label": "中止形"}], "register": "中立（常体）", "sense_fingerprint": "感情・印象・体験などが心に強く迫るほど激しいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): メゾン (Zipf 2.58), アヴァンギャルド (Zipf 2.38), 贅 (Zipf 2.41), 渇望 (Zipf 2.92)']::text[], '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53020, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強烈", "is_correct": true, "explanation": "「強烈な渇望」は強い欲求を表し、「かえって」の対比と合う。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やかな渇望」は文の対比と矛盾し、感情を喚起する強さに合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔な渇望」は意味が成り立たず、感情の強さを表さない。"}, {"text": "簡素", "is_correct": false, "explanation": "「簡素な渇望」は意味が合わず、強い欲求を表す文脈に当てはまらない。"}], "explanations": {"強烈": "「強烈な渇望」は強い欲求を表し、「かえって」の対比と合う。", "穏やか": "「穏やかな渇望」は文の対比と矛盾し、感情を喚起する強さに合わない。", "清潔": "「清潔な渇望」は意味が成り立たず、感情の強さを表さない。", "簡素": "「簡素な渇望」は意味が合わず、強い欲求を表す文脈に当てはまらない。"}, "sentence_index": 0, "correct_answer": "強烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は強烈な腕前で、難しい手術を成功させた。", "explanation": "「優れた」の意味。強烈は感情や印象の激しさを表し、技量の高さには使わない。"}, {"text": "彼は強烈に勉強して、試験に合格した。", "explanation": "「熱心」の意味。強烈は感情や印象の激しさを表し、努力の度合いには使わない。"}, {"text": "私は強烈に検討してから、結論を出した。", "explanation": "「慎重」の意味。強烈は感情や印象が激しいことを表し、検討の丁寧さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53020, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強烈", "is_correct": true, "explanation": "「強烈な個性」は作品の印象が非常に強いことを表し、「心をとらえて離さない」と合う。"}, {"text": "不潔", "is_correct": false, "explanation": "「不潔な個性」は意味が合わず、作品の魅力を表さない。"}, {"text": "勤勉", "is_correct": false, "explanation": "「勤勉な個性」は人の性格としては成り立つが、作品が心をとらえる強さには合わない。"}, {"text": "雑然", "is_correct": false, "explanation": "「雑然な個性」は不自然で、「心をとらえて離さない」という評価と合わない。"}], "explanations": {"強烈": "「強烈な個性」は作品の印象が非常に強いことを表し、「心をとらえて離さない」と合う。", "不潔": "「不潔な個性」は意味が合わず、作品の魅力を表さない。", "勤勉": "「勤勉な個性」は人の性格としては成り立つが、作品が心をとらえる強さには合わない。", "雑然": "「雑然な個性」は不自然で、「心をとらえて離さない」という評価と合わない。"}, "sentence_index": 6, "correct_answer": "強烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は強烈に準備を整えて、試合に臨んだ。", "explanation": "「入念」の意味。強烈は感情や印象の激しさを表し、準備の丁寧さは表さない。"}, {"text": "その計算は、強烈に正確だった。", "explanation": "「精密」の意味。強烈は感情や印象の激しさを表し、計算の精密さは表さない。"}, {"text": "彼女は強烈に冷静な態度で話し合いを進めた。", "explanation": "「穏やか」の意味。強烈は激しい感情や印象を表し、穏やかな態度とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53020, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その夜の出来事は、強烈が記憶として今も残っている。", "corrected_sentence": "その夜の出来事は、強烈な記憶として今も残っている。", "error_description": "形容動詞「強烈」が名詞「記憶」を修飾するには連体形「強烈な」が必要。「強烈が」は語幹のまま名詞に続けた誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強烈な", "is_correct": true, "explanation": "連体形で名詞「印象」を修飾する形。「強烈な印象」となる。"}, {"text": "強烈", "is_correct": false, "explanation": "語幹だけでは名詞「印象」を修飾できない。"}, {"text": "強烈だ", "is_correct": false, "explanation": "終止形で、文を終える形。名詞を修飾できない。"}, {"text": "強烈で", "is_correct": false, "explanation": "中止形で、文を続けるときの形。名詞の前には使わない。"}], "correct_form": "強烈な", "base_form": "強烈だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"強烈な": "連体形で名詞「印象」を修飾する形。「強烈な印象」となる。", "強烈": "語幹だけでは名詞「印象」を修飾できない。", "強烈だ": "終止形で、文を終える形。名詞を修飾できない。", "強烈で": "中止形で、文を続けるときの形。名詞の前には使わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53020, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その大雨の夜は、強烈の恐怖として今も忘れられない。", "corrected_sentence": "その大雨の夜は、強烈な恐怖として今も忘れられない。", "error_description": "形容動詞の語幹「強烈」が名詞を修飾するときは「な」が必要。「の」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強烈で", "is_correct": true, "explanation": "中止形で、「悲しみは強烈で、」と文を続ける形。"}, {"text": "強烈に", "is_correct": false, "explanation": "連用形で、「悲しみは」に続けて文を終える述語にはならない。"}, {"text": "強烈の", "is_correct": false, "explanation": "形容動詞の語幹に格助詞「の」は続かず、述語として成り立たない。"}, {"text": "強烈さに", "is_correct": false, "explanation": "名詞「強烈さ」に助詞「に」が付いた形で、「悲しみは」の述語にはならない。"}], "correct_form": "強烈で", "base_form": "強烈だ", "form_label": "中止形", "sentence_index": 7, "explanations": {"強烈で": "中止形で、「悲しみは強烈で、」と文を続ける形。", "強烈に": "連用形で、「悲しみは」に続けて文を終える述語にはならない。", "強烈の": "形容動詞の語幹に格助詞「の」は続かず、述語として成り立たない。", "強烈さに": "名詞「強烈さ」に助詞「に」が付いた形で、「悲しみは」の述語にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
