INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53021, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっとほしいと強く思うこと。", "primary_collocate": null, "pronunciation": "あこがれ", "ipa": "akoɡaɾe", "syllable_count": 4, "sentences": [{"text": "小さな家を持つことは、長い間の憧れだった。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "小[ちい]さな家[いえ]を持[も]つことは、長[なが]い間[あいだ]の憧[あこが]れだった。", "sentence_source": "generated"}, {"text": "彼にとって、あの青い車は子どものころからの憧れだ。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "彼[かれ]にとって、あの青[あお]い車[くるま]は子[こ]どものころからの憧[あこが]れだ。", "sentence_source": "generated"}, {"text": "ブランドのバッグは、多くの若い女性の憧れである。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "ブランドのバッグは、多[おお]くの若[わか]い女性[じょせい]の憧[あこが]れである。", "sentence_source": "generated"}, {"text": "海の見える部屋に住むのが、私の憧れだ。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "海[うみ]の見[み]える部屋[へや]に住[す]むのが、私[わたし]の憧[あこが]れだ。", "sentence_source": "generated"}, {"text": "貯金をして、やっと憧れのピアノを買うことができた。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "貯金[ちょきん]をして、やっと憧[あこが]れのピアノを買[か]うことができた。", "sentence_source": "generated"}, {"text": "憧れの楽器を手に入れて、毎日うれしくてたまらない。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "憧[あこが]れの楽器[がっき]を手[て]に入[い]れて、毎日[まいにち]うれしくてたまらない。", "sentence_source": "generated"}, {"text": "世界一周の旅は、定年後の父の憧れだった。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "世界一周[せかいいっしゅう]の旅[たび]は、定年後[ていねんご]の父[ちち]の憧[あこが]れだった。", "sentence_source": "generated"}, {"text": "憧れだった制服を着て、入学式に出かけた。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "憧[あこが]れだった制服[せいふく]を着[き]て、入学式[にゅうがくしき]に出[で]かけた。", "sentence_source": "generated"}, {"text": "彼は憧れの腕時計を、店の窓越しにずっと見つめていた。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "彼[かれ]は憧[あこが]れの腕時計[うでどけい]を、店[みせ]の窓越[まどご]しにずっと見[み]つめていた。", "sentence_source": "generated"}, {"text": "北海道の広い牧場で暮らすのは、妻の憧れだ。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "北海道[ほっかいどう]の広[ひろ]い牧場[ぼくじょう]で暮[く]らすのは、妻[つま]の憧[あこが]れだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "憧れ", "label": "基本形（名詞）"}, {"form": "憧れの", "label": "連体修飾（名詞＋の）"}, {"form": "憧れる", "label": "動詞の終止形"}, {"form": "憧れた", "label": "動詞の過去形"}], "register": "中立（常体）", "sense_fingerprint": "物や暮らしなどを長い間ほしいと強く思い続ける気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53021, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "憧れ", "is_correct": true, "explanation": "「長い間の憧れだった」で、長く強くほしいと思い続けた気持ちを表す。"}, {"text": "請求", "is_correct": false, "explanation": "〈請求〉は金銭などを求める手続きで、「家を持つことは長い間の請求だった」は意味が成り立たない。"}, {"text": "検査", "is_correct": false, "explanation": "〈検査〉は調べることで、家を持つことの説明としては成り立たない。"}, {"text": "実習", "is_correct": false, "explanation": "〈実習〉は練習の期間を指し、「家を持つことは長い間の実習だった」は意味が通らない。"}], "explanations": {"憧れ": "「長い間の憧れだった」で、長く強くほしいと思い続けた気持ちを表す。", "請求": "〈請求〉は金銭などを求める手続きで、「家を持つことは長い間の請求だった」は意味が成り立たない。", "検査": "〈検査〉は調べることで、家を持つことの説明としては成り立たない。", "実習": "〈実習〉は練習の期間を指し、「家を持つことは長い間の実習だった」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "憧れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の試験の結果発表は、私の長年の憧れだ。", "explanation": "ここは〈不安〉の意味。〈憧れ〉は欲しいと願う気持ちで、結果を待つ不安とは合わない。"}, {"text": "隣の家の騒音は、毎晩の大きな憧れだ。", "explanation": "ここは〈迷惑〉の意味。〈憧れ〉は強く欲しいと願う気持ちなので、迷惑な騒音には使えない。"}, {"text": "毎日の通勤は、体にとって大きな憧れになっている。", "explanation": "ここは〈負担〉の意味。〈憧れ〉は欲しいと願う気持ちで、体への重荷を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53021, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "憧れ", "is_correct": true, "explanation": "「定年後の父の憧れだった」で、長く強く願っていた気持ちを表す。"}, {"text": "伝票", "is_correct": false, "explanation": "〈伝票〉は取引の書類で、旅への気持ちを表せない。"}, {"text": "寝坊", "is_correct": false, "explanation": "〈寝坊〉は朝起きられないことで、「世界一周の旅は父の寝坊だった」は意味が通らない。"}, {"text": "名簿", "is_correct": false, "explanation": "〈名簿〉は名前の一覧で、旅の性質を表す語として成り立たない。"}], "explanations": {"憧れ": "「定年後の父の憧れだった」で、長く強く願っていた気持ちを表す。", "伝票": "〈伝票〉は取引の書類で、旅への気持ちを表せない。", "寝坊": "〈寝坊〉は朝起きられないことで、「世界一周の旅は父の寝坊だった」は意味が通らない。", "名簿": "〈名簿〉は名前の一覧で、旅の性質を表す語として成り立たない。"}, "sentence_index": 6, "correct_answer": "憧れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの失敗は、今も私の憧れとして残っている。", "explanation": "ここは〈後悔〉の意味。〈憧れ〉は欲しいと願う気持ちで、過去の失敗を悔いる気持ちとは違う。"}, {"text": "雨の降る日曜は、私にとって大きな憧れだ。", "explanation": "ここは〈嫌悪〉の意味。〈憧れ〉は強く欲しいと願う気持ちで、雨を嫌う気持ちとは合わない。"}, {"text": "夜道の暗さは、私にとって大きな憧れだ。", "explanation": "ここは〈恐怖〉の意味。〈憧れ〉は引かれる気持ちで、暗さへの怖さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53021, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私はずっと海の見える家を憧れてきた。", "corrected_sentence": "私はずっと海の見える家に憧れてきた。", "error_description": "「憧れる」は「〜に憧れる」と続ける。「を」は誤り。正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53021, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私の憧れを、北海道の牧場だ。", "corrected_sentence": "私の憧れは、北海道の牧場だ。", "error_description": "「憧れ」は主題として「は」で示す。「を」は誤り。正しくは「は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53022, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「憧れを持ち続けている」で、持つ対象を示す。文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「憧れが持ち続けている」では憧れが主語になるが、持ち続けるのは人なので文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「憧れに持ち続けている」は「持つ」の対象を示せず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「憧れで持ち続けている」は手段の意味にならず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「憧れを持ち続けている」で、持つ対象を示す。文が成り立つ。", "が": "「憧れが持ち続けている」では憧れが主語になるが、持ち続けるのは人なので文が成り立たない。", "に": "「憧れに持ち続けている」は「持つ」の対象を示せず、不自然。", "で": "「憧れで持ち続けている」は手段の意味にならず、文が成り立たない。"}, "error_tags": {"が": "主語", "に": "対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53022, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「少年の憧れの的」で、憧れの対象を修飾する「の」。文が成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "「少年の憧れへ的は」は方向の意味になり、名詞同士の続きとして不自然。"}, {"text": "から", "is_correct": false, "explanation": "「少年の憧れから的は」は起点の意味になり、文の構造が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「少年の憧れより的は」は比較の意味になり、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「少年の憧れの的」で、憧れの対象を修飾する「の」。文が成り立つ。", "へ": "「少年の憧れへ的は」は方向の意味になり、名詞同士の続きとして不自然。", "から": "「少年の憧れから的は」は起点の意味になり、文の構造が成り立たない。", "より": "「少年の憧れより的は」は比較の意味になり、文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53022, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "理想や目標とする対象に対して、強く心を引かれ、そうなりたい、手に入れたいと願う気持ち。", "primary_collocate": null, "pronunciation": "あこがれ", "ipa": "akoɡaɾe", "syllable_count": 4, "sentences": [{"text": "この憧れの感情は、やがてグローバルな大衆向けブランドによって巧妙に咀嚼され、誰もが手が届く価格帯へと昇華されるのだ。", "target_word": "憧れ", "complexity_tier": "T5", "furigana": "この憧[あこが]れの感情[かんじょう]は、やがてグローバルな大衆向[たいしゅうむ]けブランドによって巧妙[こうみょう]に咀嚼[そしゃく]され、誰[だれ]もが手[て]が届[とど]く価格帯[かかくたい]へと昇華[しょうか]されるのだ。", "sentence_source": "mined"}, {"text": "子どものころから、宇宙飛行士への憧れを持ち続けている。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "子[こ]どものころから、宇宙飛行士[うちゅうひこうし]への憧[あこが]れを持[も]ち続[つづ]けている。", "sentence_source": "generated"}, {"text": "姉は私にとって憧れの存在で、いつも背中を追いかけている。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "姉[あね]は私[わたし]にとって憧[あこが]れの存在[そんざい]で、いつも背中[せなか]を追[お]いかけている。", "sentence_source": "generated"}, {"text": "彼女は都会での生活に憧れを抱いて、田舎の町を出た。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は都会[とかい]での生活[せいかつ]に憧[あこが]れを抱[いだ]いて、田舎[いなか]の町[まち]を出[で]た。", "sentence_source": "generated"}, {"text": "憧れだけでは、プロの料理人にはなれないと先生に言われた。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "憧[あこが]れだけでは、プロの料理人[りょうりにん]にはなれないと先生[せんせい]に言[い]われた。", "sentence_source": "generated"}, {"text": "先輩の演奏を聞いて、ピアニストへの憧れが強くなった。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "先輩[せんぱい]の演奏[えんそう]を聞[き]いて、ピアニストへの憧[あこが]れが強[つよ]くなった。", "sentence_source": "generated"}, {"text": "外国で働きたいという憧れは、年を重ねても消えなかった。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "外国[がいこく]で働[はたら]きたいという憧[あこが]れは、年[とし]を重[かさ]ねても消[き]えなかった。", "sentence_source": "generated"}, {"text": "少年の憧れの的は、いつも試合で活躍するエースだった。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "少年[しょうねん]の憧[あこが]れの的[まと]は、いつも試合[しあい]で活躍[かつやく]するエースだった。", "sentence_source": "generated"}, {"text": "憧れが現実になる日を夢見て、毎日練習している。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "憧[あこが]れが現実[げんじつ]になる日[ひ]を夢見[ゆめみ]て、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "実際に働いてみると、憧れと現実の違いに気づいた。", "target_word": "憧れ", "complexity_tier": "T3", "furigana": "実際[じっさい]に働[はたら]いてみると、憧[あこが]れと現実[げんじつ]の違[ちが]いに気[き]づいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "憧れ", "label": "基本形（名詞）"}, {"form": "憧れの", "label": "連体修飾（名詞＋の）"}, {"form": "憧れる", "label": "動詞の終止形"}, {"form": "憧れた", "label": "動詞の過去形"}], "register": "中立（常体）", "sense_fingerprint": "理想の人物・職業・生き方に心を引かれ、自分もそうなりたいと願う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53022, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "憧れ", "is_correct": true, "explanation": "理想とする対象へ心を引かれる気持ちを表し、「この〜の感情」の空所に入る。後半の大衆向けブランドへの流れとも合う。"}, {"text": "反感", "is_correct": false, "explanation": "〈反感〉は反発する気持ちで、「咀嚼され、価格帯へと昇華される」という前向きな流れに合わない。"}, {"text": "恐怖", "is_correct": false, "explanation": "〈恐怖〉は恐れの感情で、ブランドによって手が届く価格帯へ変えられるという文脈と合わない。"}, {"text": "無関心", "is_correct": false, "explanation": "〈無関心〉は心が動かないことで、「感情」が咀嚼され昇華されるという流れと矛盾する。"}], "explanations": {"憧れ": "理想とする対象へ心を引かれる気持ちを表し、「この〜の感情」の空所に入る。後半の大衆向けブランドへの流れとも合う。", "反感": "〈反感〉は反発する気持ちで、「咀嚼され、価格帯へと昇華される」という前向きな流れに合わない。", "恐怖": "〈恐怖〉は恐れの感情で、ブランドによって手が届く価格帯へ変えられるという文脈と合わない。", "無関心": "〈無関心〉は心が動かないことで、「感情」が咀嚼され昇華されるという流れと矛盾する。"}, "sentence_index": 0, "correct_answer": "憧れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の試合に、監督は大きな憧れを寄せている。", "explanation": "ここは〈期待〉の意味。〈期待を寄せる〉は見込みを向ける言い方で、理想の人物への心の引かれを表す〈憧れ〉とは合わない。"}, {"text": "毎朝の満員電車は、私にとって大きな憧れだ。", "explanation": "ここは〈苦痛〉の意味。〈憧れ〉は理想へ心が引かれる気持ちで、混雑の苦しさとは合わない。"}, {"text": "あの横柄な上司に、私は強い憧れを覚えた。", "explanation": "ここは〈反感〉の意味。〈憧れ〉は好ましく引かれる気持ちなので、横柄さへの不快感には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53022, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "憧れ", "is_correct": true, "explanation": "働きたいという願いを表し、年を重ねても消えなかった気持ちに合う。"}, {"text": "拒絶", "is_correct": false, "explanation": "〈拒絶〉は断ることで、働きたい願いと逆の意味になり、「消えなかった」にも合わない。"}, {"text": "嫌悪", "is_correct": false, "explanation": "〈嫌悪〉は嫌う気持ちで、働きたいという願いとは合わない。"}, {"text": "軽蔑", "is_correct": false, "explanation": "〈軽蔑〉は見下す気持ちで、働きたいという前向きな願いの文脈と合わない。"}], "explanations": {"憧れ": "働きたいという願いを表し、年を重ねても消えなかった気持ちに合う。", "拒絶": "〈拒絶〉は断ることで、働きたい願いと逆の意味になり、「消えなかった」にも合わない。", "嫌悪": "〈嫌悪〉は嫌う気持ちで、働きたいという願いとは合わない。", "軽蔑": "〈軽蔑〉は見下す気持ちで、働きたいという前向きな願いの文脈と合わない。"}, "sentence_index": 6, "correct_answer": "憧れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みの宿題は、子どもたちにとって大きな憧れだ。", "explanation": "ここは〈負担〉の意味。〈憧れ〉は理想へ心が引かれる気持ちで、宿題の重さは表せない。"}, {"text": "その腐った匂いに、強い憧れを覚えた。", "explanation": "ここは〈嫌悪〉の意味。〈憧れ〉は好ましく引かれる気持ちで、不快な匂いには使わない。"}, {"text": "彼の差別的な発言に、憧れを感じた。", "explanation": "ここは〈侮蔑〉の意味。〈憧れ〉は尊敬や好意の気持ちで、相手を見下す発言には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53022, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私はずっとピアニストへの憧れに持ち続けている。", "corrected_sentence": "私はずっとピアニストへの憧れを持ち続けている。", "error_description": "「憧れを持つ」の目的語は「を」で示す。「憧れに持ち続けている」は助詞「に」が誤り。正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53022, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は田舎暮らしへの憧れで、町を出た。", "corrected_sentence": "彼は田舎暮らしへの憧れから、町を出た。", "error_description": "「憧れ」に続けて理由を示すときは「から」を使う。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53023, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "承諾", "is_correct": true, "explanation": "頼みや誘いを受け入れるという意味で、〈拒絶〉の対義語。"}, {"text": "完成", "is_correct": false, "explanation": "〈完成〉は仕上がることで、〈拒絶〉の対義語ではない。"}, {"text": "点検", "is_correct": false, "explanation": "〈点検〉は状態を調べることで、頼みへの応答とは関係がない。"}, {"text": "訓練", "is_correct": false, "explanation": "〈訓練〉は技術を身につけることで、〈拒絶〉の対義語ではない。"}], "correct_answer": "承諾", "explanations": {"承諾": "頼みや誘いを受け入れるという意味で、〈拒絶〉の対義語。", "完成": "〈完成〉は仕上がることで、〈拒絶〉の対義語ではない。", "点検": "〈点検〉は状態を調べることで、頼みへの応答とは関係がない。", "訓練": "〈訓練〉は技術を身につけることで、〈拒絶〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53023, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「彼の拒絶の言葉」で、拒絶を修飾する「の」。文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「彼の拒絶が言葉は」は主語の並びとして不自然で、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「彼の拒絶を言葉は」は目的語の並びとして成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「彼の拒絶に言葉は」は対象の示し方として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「彼の拒絶の言葉」で、拒絶を修飾する「の」。文が成り立つ。", "が": "「彼の拒絶が言葉は」は主語の並びとして不自然で、文が成り立たない。", "を": "「彼の拒絶を言葉は」は目的語の並びとして成り立たない。", "に": "「彼の拒絶に言葉は」は対象の示し方として成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "対象"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "承諾", "is_correct": true, "explanation": "頼みや誘いを受け入れるという意味で、〈拒絶〉の対義語。"}, {"text": "生産", "is_correct": false, "explanation": "〈生産〉は物を作ることで、〈拒絶〉の対義語ではない。"}, {"text": "教育", "is_correct": false, "explanation": "〈教育〉は人に教えることで、頼みへの応答とは関係がない。"}, {"text": "観察", "is_correct": false, "explanation": "〈観察〉は注意して見ることで、〈拒絶〉の対義語ではない。"}], "correct_answer": "承諾", "explanations": {"承諾": "頼みや誘いを受け入れるという意味で、〈拒絶〉の対義語。", "生産": "〈生産〉は物を作ることで、〈拒絶〉の対義語ではない。", "教育": "〈教育〉は人に教えることで、頼みへの応答とは関係がない。", "観察": "〈観察〉は注意して見ることで、〈拒絶〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53023, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "いやだと言うこと。こたえをことわること。", "primary_collocate": null, "pronunciation": "きょぜつ", "ipa": "kʲozetsɯ", "syllable_count": 3, "sentences": [{"text": "子どもは薬を飲むのを拒絶して、口を固く閉じた。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "子[こ]どもは薬[くすり]を飲[の]むのを拒絶[きょぜつ]して、口[くち]を固[かた]く閉[と]じた。", "sentence_source": "generated"}, {"text": "彼女に告白したが、すぐに拒絶された。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "彼女[かのじょ]に告白[こくはく]したが、すぐに拒絶[きょぜつ]された。", "sentence_source": "generated"}, {"text": "先生に理由を聞かれても、彼は答えるのを拒絶した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "先生[せんせい]に理由[りゆう]を聞[き]かれても、彼[かれ]は答[こた]えるのを拒絶[きょぜつ]した。", "sentence_source": "generated"}, {"text": "犬は散歩に行くのを拒絶して、玄関で動かなかった。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "犬[いぬ]は散歩[さんぽ]に行[い]くのを拒絶[きょぜつ]して、玄関[げんかん]で動[うご]かなかった。", "sentence_source": "generated"}, {"text": "兄は手伝ってほしいという私の頼みを拒絶した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "兄[あに]は手伝[てつだ]ってほしいという私[わたし]の頼[たの]みを拒絶[きょぜつ]した。", "sentence_source": "generated"}, {"text": "拒絶されるのが怖くて、彼女に話しかけられなかった。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "拒絶[きょぜつ]されるのが怖[こわ]くて、彼女[かのじょ]に話[はな]しかけられなかった。", "sentence_source": "generated"}, {"text": "弟はピーマンを食べろと言われて、強く拒絶した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "弟[おとうと]はピーマンを食[た]べろと言[い]われて、強[つよ]く拒絶[きょぜつ]した。", "sentence_source": "generated"}, {"text": "彼の拒絶の言葉は短く、冷たかった。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "彼[かれ]の拒絶[きょぜつ]の言葉[ことば]は短[みじか]く、冷[つめ]たかった。", "sentence_source": "generated"}, {"text": "席をゆずってほしいと頼んだが、男は拒絶した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "席[せき]をゆずってほしいと頼[たの]んだが、男[おとこ]は拒絶[きょぜつ]した。", "sentence_source": "generated"}, {"text": "友達にお金を貸してと言われたが、私は拒絶した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "友達[ともだち]にお金[かね]を貸[か]してと言[い]われたが、私[わたし]は拒絶[きょぜつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拒絶する", "label": "終止形"}, {"form": "拒絶した", "label": "過去形"}, {"form": "拒絶される", "label": "受身形"}, {"form": "拒絶して", "label": "て形"}], "register": "標準", "sense_fingerprint": "頼みや誘いに対して、いやだと言ってことわる行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53023, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒絶", "is_correct": true, "explanation": "「薬を飲むのを拒絶して」で、飲むことをいやだと言って断る意味になり、文が成り立つ。"}, {"text": "歓迎", "is_correct": false, "explanation": "〈歓迎〉は喜んで迎えることで、「薬を飲むのを歓迎して」は意味が通らない。"}, {"text": "完了", "is_correct": false, "explanation": "〈完了〉は終わることで、「薬を飲むのを完了して」は文が成り立たない。"}, {"text": "保存", "is_correct": false, "explanation": "〈保存〉は残すことで、「薬を飲むのを保存して」は意味が通らない。"}], "explanations": {"拒絶": "「薬を飲むのを拒絶して」で、飲むことをいやだと言って断る意味になり、文が成り立つ。", "歓迎": "〈歓迎〉は喜んで迎えることで、「薬を飲むのを歓迎して」は意味が通らない。", "完了": "〈完了〉は終わることで、「薬を飲むのを完了して」は文が成り立たない。", "保存": "〈保存〉は残すことで、「薬を飲むのを保存して」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "拒絶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "移植した腎臓が、体の拒絶反応で数日後に機能を失った。", "explanation": "ここは〈拒絶反応〉（免疫）の意味。異物を退ける体の反応で、人の頼みを断る〈拒絶〉とは別。"}, {"text": "彼は部下の遅刻を拒絶した。", "explanation": "ここは〈注意〉の意味。〈拒絶〉は頼みや誘いを断る意味で、相手の行いを正すことにはならない。"}, {"text": "その薬を飲んだあと、彼の体は拒絶反応で発疹に覆われた。", "explanation": "ここは〈拒絶反応〉（免疫）の意味。人の頼みを断る〈拒絶〉の意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53023, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拒絶", "is_correct": true, "explanation": "「弟はピーマンを食べろと言われて、強く拒絶した」で、いやだと言って断る意味になる。"}, {"text": "遂行", "is_correct": false, "explanation": "〈遂行〉は実行することで、「強く遂行した」は指示を断る文脈と合わない。"}, {"text": "解消", "is_correct": false, "explanation": "〈解消〉は問題を取り除くことで、「強く解消した」は意味が通らない。"}, {"text": "点検", "is_correct": false, "explanation": "〈点検〉は調べることで、「強く点検した」は文が成り立たない。"}], "explanations": {"拒絶": "「弟はピーマンを食べろと言われて、強く拒絶した」で、いやだと言って断る意味になる。", "遂行": "〈遂行〉は実行することで、「強く遂行した」は指示を断る文脈と合わない。", "解消": "〈解消〉は問題を取り除くことで、「強く解消した」は意味が通らない。", "点検": "〈点検〉は調べることで、「強く点検した」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "拒絶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新薬を使ったあと、彼の体は拒絶反応で高い熱を出した。", "explanation": "ここは〈拒絶反応〉（免疫）の意味。人の申し出を断る〈拒絶〉とは別の意味。"}, {"text": "蜂に刺されたあと、彼の体は拒絶反応で大きく腫れ上がった。", "explanation": "ここは〈拒絶反応〉（免疫）の意味。人の頼みを断る〈拒絶〉とは違う。"}, {"text": "移植された心臓が、体の拒絶反応で弱っていった。", "explanation": "ここは〈拒絶反応〉（免疫）の意味。異物を退ける体の反応で、〈拒絶〉の義項とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53023, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達の頼みを拒絶て、私は笑顔で断った。", "corrected_sentence": "友達の頼みを拒絶して、私は笑顔で断った。", "error_description": "動詞「拒絶する」のて形は「拒絶して」。「拒絶て」は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53023, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は友達のお金の頼みに拒絶した。", "corrected_sentence": "私は友達のお金の頼みを拒絶した。", "error_description": "「拒絶する」の対象は「を」で示す。「に」は誤り。正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53024, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「要求を拒絶した」で、拒絶の対象を示す。文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「要求が拒絶した」では要求が拒絶する主体になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「要求に拒絶した」は拒絶の対象を示せず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「要求と拒絶した」は並列の意味になり、拒絶の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「要求を拒絶した」で、拒絶の対象を示す。文が成り立つ。", "が": "「要求が拒絶した」では要求が拒絶する主体になり、文が成り立たない。", "に": "「要求に拒絶した」は拒絶の対象を示せず、不自然。", "と": "「要求と拒絶した」は並列の意味になり、拒絶の対象にならない。"}, "error_tags": {"が": "主語", "に": "対象", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "承諾", "is_correct": true, "explanation": "申し出を受け入れるという意味で、〈拒絶〉の対義語。"}, {"text": "完成", "is_correct": false, "explanation": "〈完成〉は仕上がることで、〈拒絶〉の対義語ではない。"}, {"text": "整備", "is_correct": false, "explanation": "〈整備〉は整えることで、申し出への応答とは関係がない。"}, {"text": "訓練", "is_correct": false, "explanation": "〈訓練〉は技術を身につけることで、〈拒絶〉の対義語ではない。"}], "correct_answer": "承諾", "explanations": {"承諾": "申し出を受け入れるという意味で、〈拒絶〉の対義語。", "完成": "〈完成〉は仕上がることで、〈拒絶〉の対義語ではない。", "整備": "〈整備〉は整えることで、申し出への応答とは関係がない。", "訓練": "〈訓練〉は技術を身につけることで、〈拒絶〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53024, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受諾", "is_correct": true, "explanation": "申し出を引き受けるという意味で、〈拒絶〉の対義語。"}, {"text": "生産", "is_correct": false, "explanation": "〈生産〉は物を作ることで、〈拒絶〉の対義語ではない。"}, {"text": "教育", "is_correct": false, "explanation": "〈教育〉は人に教えることで、申し出への応答とは関係がない。"}, {"text": "観察", "is_correct": false, "explanation": "〈観察〉は注意して見ることで、〈拒絶〉の対義語ではない。"}], "correct_answer": "受諾", "explanations": {"受諾": "申し出を引き受けるという意味で、〈拒絶〉の対義語。", "生産": "〈生産〉は物を作ることで、〈拒絶〉の対義語ではない。", "教育": "〈教育〉は人に教えることで、申し出への応答とは関係がない。", "観察": "〈観察〉は注意して見ることで、〈拒絶〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53024, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "申し出や要求などを断ること。受け入れないこと。", "primary_collocate": null, "pronunciation": "きょぜつ", "ipa": "kʲozetsɯ", "syllable_count": 3, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的な購入の申し出を拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "拒絶", "complexity_tier": "T5", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]な購入[こうにゅう]の申[もう]し出[で]を拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "generated"}, {"text": "会社は相手の無理な要求をはっきり拒絶した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は相手[あいて]の無理[むり]な要求[ようきゅう]をはっきり拒絶[きょぜつ]した。", "sentence_source": "generated"}, {"text": "彼女は何度も頼まれたが、その申し出を拒絶した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何度[なんど]も頼[たの]まれたが、その申[もう]し出[で]を拒絶[きょぜつ]した。", "sentence_source": "generated"}, {"text": "提案が拒絶されたので、計画を最初から考え直した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "提案[ていあん]が拒絶[きょぜつ]されたので、計画[けいかく]を最初[さいしょ]から考[かんが]え直[なお]した。", "sentence_source": "generated"}, {"text": "新しい制度を拒絶する人も少なくない。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]を拒絶[きょぜつ]する人[ひと]も少[すく]なくない。", "sentence_source": "generated"}, {"text": "彼は援助の申し出を丁寧に拒絶した。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "彼[かれ]は援助[えんじょ]の申[もう]し出[で]を丁寧[ていねい]に拒絶[きょぜつ]した。", "sentence_source": "generated"}, {"text": "面会を拒絶されても、彼は毎日病院に通い続けた。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "面会[めんかい]を拒絶[きょぜつ]されても、彼[かれ]は毎日[まいにち]病院[びょういん]に通[かよ]い続[つづ]けた。", "sentence_source": "generated"}, {"text": "銀行に融資を拒絶され、店の開業をあきらめた。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]に融資[ゆうし]を拒絶[きょぜつ]され、店[みせ]の開業[かいぎょう]をあきらめた。", "sentence_source": "generated"}, {"text": "政府は交渉の条件をすべて拒絶し、話し合いは終わった。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "政府[せいふ]は交渉[こうしょう]の条件[じょうけん]をすべて拒絶[きょぜつ]し、話[はな]し合[あ]いは終[お]わった。", "sentence_source": "generated"}, {"text": "母の誘いを拒絶したことを、今でも少し後悔している。", "target_word": "拒絶", "complexity_tier": "T3", "furigana": "母[はは]の誘[さそ]いを拒絶[きょぜつ]したことを、今[いま]でも少[すこ]し後悔[こうかい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拒絶する", "label": "終止形"}, {"form": "拒絶した", "label": "過去形"}, {"form": "拒絶される", "label": "受身形"}, {"form": "拒絶して", "label": "て形"}], "register": "やや硬い", "sense_fingerprint": "申し出・要求・提案などを受け入れずに断る行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): メゾン (Zipf 2.58), アヴァンギャルド (Zipf 2.38), 贅 (Zipf 2.41), 渇望 (Zipf 2.92)']::text[], '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53024, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒絶", "is_correct": true, "explanation": "「直接的なアクセスを拒絶することで」の空所に入り、一般消費者を退ける意味で文が成り立つ。"}, {"text": "完了", "is_correct": false, "explanation": "〈完了〉は終わることで、「アクセスを完了することで」は意味が通らない。"}, {"text": "保管", "is_correct": false, "explanation": "〈保管〉は預かって守ることで、「アクセスを保管することで」は文が成り立たない。"}, {"text": "採点", "is_correct": false, "explanation": "〈採点〉は点数をつけることで、アクセスとは結びつかない。"}], "explanations": {"拒絶": "「直接的なアクセスを拒絶することで」の空所に入り、一般消費者を退ける意味で文が成り立つ。", "完了": "〈完了〉は終わることで、「アクセスを完了することで」は意味が通らない。", "保管": "〈保管〉は預かって守ることで、「アクセスを保管することで」は文が成り立たない。", "採点": "〈採点〉は点数をつけることで、アクセスとは結びつかない。"}, "sentence_index": 0, "correct_answer": "拒絶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は長年の友情を拒絶して、今も毎週一緒に遊んでいる。", "explanation": "ここは〈絶縁〉の意味。〈拒絶〉は申し出や要求を断ることで、関係そのものを断つ意味にはならない。"}, {"text": "移植した肝臓が体の拒絶反応で弱り、彼は入院が長引いた。", "explanation": "ここは〈拒絶反応〉（免疫）の意味。人の申し出を断る〈拒絶〉とは別の意味。"}, {"text": "会社の方針に疲れ、彼は会社を拒絶した。", "explanation": "ここは〈辞職〉の意味。自分から職を退くことで、相手の申し出を断る意味とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53024, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拒絶", "is_correct": true, "explanation": "「面会を拒絶されても」で、面会を断られた意味になり、文が成り立つ。"}, {"text": "遂行", "is_correct": false, "explanation": "〈遂行〉は実行することで、「面会を遂行されても」は意味が通らない。"}, {"text": "清掃", "is_correct": false, "explanation": "〈清掃〉は掃除することで、「面会を清掃されても」は文が成り立たない。"}, {"text": "翻訳", "is_correct": false, "explanation": "〈翻訳〉は言葉を訳すことで、面会とは結びつかない。"}], "explanations": {"拒絶": "「面会を拒絶されても」で、面会を断られた意味になり、文が成り立つ。", "遂行": "〈遂行〉は実行することで、「面会を遂行されても」は意味が通らない。", "清掃": "〈清掃〉は掃除することで、「面会を清掃されても」は文が成り立たない。", "翻訳": "〈翻訳〉は言葉を訳すことで、面会とは結びつかない。"}, "sentence_index": 6, "correct_answer": "拒絶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、ずっと続いていた誤解を拒絶して、ようやく解いた。", "explanation": "ここは〈否定〉の意味。〈拒絶〉は申し出や要求を断ることで、事実として誤解を打ち消す〈否定〉とは違う。"}, {"text": "長年の問題を、彼はついに拒絶した。", "explanation": "ここは〈解決〉の意味。問題は解決するものなので、〈拒絶〉では解決の流れに合わない。"}, {"text": "被災した人々を、私たちは拒絶した。", "explanation": "ここは〈同情〉の意味。同情は相手を思いやる気持ちで、退けるという〈拒絶〉とは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53024, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "田中さんは友人の誘いに拒絶して、はっきり断った。", "corrected_sentence": "田中さんは友人の誘いを拒絶して、はっきり断った。", "error_description": "「拒絶する」の対象は「を」で示す。「に」は誤り。正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53024, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その申し出は、彼女に拒絶れた。", "corrected_sentence": "その申し出は、彼女に拒絶された。", "error_description": "「拒絶される」の受身形が正しい。「拒絶れた」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53026, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「大衆の声」の「の」は、大衆が声を修飾することを示し、自然な名詞句になる。"}, {"text": "を", "is_correct": false, "explanation": "「大衆を声を」と「を」が二つ並び、文の構造が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「大衆で声を」は場所や手段の意味になり、この文脈では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「大衆へ声を政治に届けたい」は方向が二重になり、文意が通らない。"}], "correct_answer": "の", "explanations": {"の": "「大衆の声」の「の」は、大衆が声を修飾することを示し、自然な名詞句になる。", "を": "「大衆を声を」と「を」が二つ並び、文の構造が崩れる。", "で": "「大衆で声を」は場所や手段の意味になり、この文脈では成り立たない。", "へ": "「大衆へ声を政治に届けたい」は方向が二重になり、文意が通らない。"}, "error_tags": {"の": "連体修飾", "を": "目的語の重複", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53026, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「大衆には受け入れられなかった」の「に」は、受け入れる相手を示す。受身文で相手を表す自然な形。"}, {"text": "が", "is_correct": false, "explanation": "「大衆がは」と「は」が重なり、文の形が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「大衆とは受け入れられなかった」は相手を示す形にならず、文意が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「大衆よりは」は比較の意味になり、受け入れられなかった相手として文意に合わない。"}], "correct_answer": "に", "explanations": {"に": "「大衆には受け入れられなかった」の「に」は、受け入れる相手を示す。受身文で相手を表す自然な形。", "が": "「大衆がは」と「は」が重なり、文の形が崩れる。", "と": "「大衆とは受け入れられなかった」は相手を示す形にならず、文意が通らない。", "より": "「大衆よりは」は比較の意味になり、受け入れられなかった相手として文意に合わない。"}, "error_tags": {"に": "相手（受身）", "が": "主語", "と": "並列・共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53026, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会の多くの一般の人々。", "primary_collocate": null, "pronunciation": "たいしゅう", "ipa": "taiɕɯː", "syllable_count": 4, "sentences": [{"text": "大衆向けブランドは、安くて手に入りやすい商品を多く売っている。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "大衆向[たいしゅうむ]けブランドは、安[やす]くて手[て]に入[はい]りやすい商品[しょうひん]を多[おお]く売[う]っている。", "sentence_source": "generated"}, {"text": "この雑誌は大衆の声を政治に届けたいと考えている。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]は大衆[たいしゅう]の声[こえ]を政治[せいじ]に届[とど]けたいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "大衆向けの映画は、わかりやすい物語が好まれる。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "大衆向[たいしゅうむ]けの映画[えいが]は、わかりやすい物語[ものがたり]が好[この]まれる。", "sentence_source": "generated"}, {"text": "江戸時代には、歌舞伎は大衆の娯楽として親しまれた。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "江戸時代[えどじだい]には、歌舞伎[かぶき]は大衆[たいしゅう]の娯楽[ごらく]として親[した]しまれた。", "sentence_source": "generated"}, {"text": "大衆の支持を失った政党は、選挙で大きく負けた。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "大衆[たいしゅう]の支持[しじ]を失[うしな]った政党[せいとう]は、選挙[せんきょ]で大[おお]きく負[ま]けた。", "sentence_source": "generated"}, {"text": "高級店とちがい、この食堂は大衆が気軽に入れる店だ。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "高級店[こうきゅうてん]とちがい、この食堂[しょくどう]は大衆[たいしゅう]が気軽[きがる]に入[はい]れる店[みせ]だ。", "sentence_source": "generated"}, {"text": "新聞は大衆に情報を伝える大切な役割を持つ。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "新聞[しんぶん]は大衆[たいしゅう]に情報[じょうほう]を伝[つた]える大切[たいせつ]な役割[やくわり]を持[も]つ。", "sentence_source": "generated"}, {"text": "彼の小説は難しすぎて、大衆には受け入れられなかった。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "彼[かれ]の小説[しょうせつ]は難[むずか]しすぎて、大衆[たいしゅう]には受[う]け入[い]れられなかった。", "sentence_source": "generated"}, {"text": "大衆文化の研究は、時代の空気を知る手がかりになる。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "大衆文化[たいしゅうぶんか]の研究[けんきゅう]は、時代[じだい]の空気[くうき]を知[し]る手[て]がかりになる。", "sentence_source": "generated"}, {"text": "大衆の怒りが高まり、町ではデモが起きた。", "target_word": "大衆", "complexity_tier": "T3", "furigana": "大衆[たいしゅう]の怒[いか]りが高[たか]まり、町[まち]ではデモが起[お]きた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大衆の", "label": "名詞＋の"}, {"form": "大衆に", "label": "名詞＋に"}, {"form": "大衆が", "label": "名詞＋が"}, {"form": "大衆向け", "label": "接尾の語形"}], "register": "標準", "sense_fingerprint": "特別な地位を持たない、社会の多くの一般の人々", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53026, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大衆", "is_correct": true, "explanation": "「大衆向けブランド」の空所には「大衆」が入り、社会の一般の人々向けの商品という意味になる。"}, {"text": "感情", "is_correct": false, "explanation": "「感情向けブランド」は成り立たず、商品の対象として意味が通らない。"}, {"text": "憧れ", "is_correct": false, "explanation": "「憧れ向けブランド」は対象を表せず、この文脈では不自然。"}, {"text": "咀嚼", "is_correct": false, "explanation": "「咀嚼向け」は商品の対象にならず、この位置では成り立たない。"}], "explanations": {"大衆": "「大衆向けブランド」の空所には「大衆」が入り、社会の一般の人々向けの商品という意味になる。", "感情": "「感情向けブランド」は成り立たず、商品の対象として意味が通らない。", "憧れ": "「憧れ向けブランド」は対象を表せず、この文脈では不自然。", "咀嚼": "「咀嚼向け」は商品の対象にならず、この位置では成り立たない。"}, "sentence_index": 0, "correct_answer": "大衆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事件の目撃者は大衆だった。", "explanation": "ここは〈一般人〉の意味。大衆は社会の多くの一般の人々を指す語で、一人の目撃者には使わない。"}, {"text": "彼は経済学の大衆で、大学で教えている。", "explanation": "ここは〈専門家〉の意味。大衆は一般の人々を指し、専門的な知識を持つ人の意味では使わない。"}, {"text": "その会議には大衆が三人だけ参加した。", "explanation": "ここは〈少数の参加者〉の意味。大衆は社会の多くの一般の人々を指す語で、少人数の集まりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53026, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大衆", "is_correct": true, "explanation": "「新聞は大衆に情報を伝える」の空所には、社会一般の人々を指す「大衆」が入る。"}, {"text": "役割", "is_correct": false, "explanation": "「役割に情報を伝える」は意味をなさず、伝える相手にならない。"}, {"text": "情報", "is_correct": false, "explanation": "「情報に情報を伝える」は同じ語が重なり、伝える相手として成り立たない。"}, {"text": "空気", "is_correct": false, "explanation": "「空気に情報を伝える」は現実にはあり得ず、伝える相手として不自然。"}], "explanations": {"大衆": "「新聞は大衆に情報を伝える」の空所には、社会一般の人々を指す「大衆」が入る。", "役割": "「役割に情報を伝える」は意味をなさず、伝える相手にならない。", "情報": "「情報に情報を伝える」は同じ語が重なり、伝える相手として成り立たない。", "空気": "「空気に情報を伝える」は現実にはあり得ず、伝える相手として不自然。"}, "sentence_index": 6, "correct_answer": "大衆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放課後、大衆と一緒に野球を練習した。", "explanation": "ここは〈仲間〉の意味。大衆は社会全体の人々の総称で、親しい仲間の集まりの意味では使わない。"}, {"text": "彼女の大衆は、週末の登山だ。", "explanation": "ここは〈趣味〉の意味。大衆は社会全体を指す語で、個人の好みには使わない。"}, {"text": "妹は、大衆の帽子をかぶって学校へ行く。", "explanation": "ここは〈帽子〉の意味。大衆は人々の総称で、かぶり物の名前ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53026, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昔は、大衆を娯楽が少なかった。", "corrected_sentence": "昔は、大衆の娯楽が少なかった。", "error_description": "「大衆の娯楽」では「の」が大衆と娯楽を結ぶ。「大衆を」とすると、形容詞「少なかった」は目的語を取らないので文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53026, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大衆で求めるものを、企業は丁寧に調べている。", "corrected_sentence": "大衆が求めるものを、企業は丁寧に調べている。", "error_description": "「大衆が求める」の「が」は求める主体を示す。「で」は場所や手段を表すので、「求める」の主語にはできない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
