INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53028, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の企業や組織が、自らの商品やサービスを他社のものと区別するために使用する名称、標章、デザインなどの総称。", "primary_collocate": null, "pronunciation": "ぶらんど", "ipa": "buɾando", "syllable_count": 4, "sentences": [{"text": "大衆向けブランドは、安くて手に入りやすい商品を多く売っている。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "大衆向[たいしゅうむ]けブランドは、安[やす]くて手[て]に入[はい]りやすい商品[しょうひん]を多[おお]く売[う]っている。", "sentence_source": "generated"}, {"text": "このブランドは、品質のよさで世界的に知られている。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "このブランドは、品質[ひんしつ]のよさで世界的[せかいてき]に知[し]られている。", "sentence_source": "generated"}, {"text": "姉は好きなブランドの新作バッグを予約した。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "姉[あね]は好[す]きなブランドの新作[しんさく]バッグを予約[よやく]した。", "sentence_source": "generated"}, {"text": "新しいブランドを立ち上げるため、彼は会社をやめた。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "新[あたら]しいブランドを立[た]ち上[あ]げるため、彼[かれ]は会社[かいしゃ]をやめた。", "sentence_source": "generated"}, {"text": "有名なブランドの名前だけで、商品を選ぶ人もいる。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "有名[ゆうめい]なブランドの名前[なまえ]だけで、商品[しょうひん]を選[えら]ぶ人[ひと]もいる。", "sentence_source": "generated"}, {"text": "日本の食品ブランドが、海外で人気を集めている。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "日本[にほん]の食品[しょくひん]ブランドが、海外[かいがい]で人気[にんき]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "若者向けのブランドは、価格を低く抑えている。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "若者向[わかものむ]けのブランドは、価格[かかく]を低[ひく]く抑[おさ]えている。", "sentence_source": "generated"}, {"text": "長い歴史を持つブランドでも、信頼を失えば客は離れる。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "長[なが]い歴史[れきし]を持[も]つブランドでも、信頼[しんらい]を失[うしな]えば客[きゃく]は離[はな]れる。", "sentence_source": "generated"}, {"text": "このブランドのロゴは、一目でわかる独特なデザインだ。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "このブランドのロゴは、一目[ひとめ]でわかる独特[どくとく]なデザインだ。", "sentence_source": "generated"}, {"text": "地元の農家が協力して、米のブランドを作った。", "target_word": "ブランド", "complexity_tier": "T3", "furigana": "地元[じもと]の農家[のうか]が協力[きょうりょく]して、米[こめ]のブランドを作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブランドの", "label": "名詞＋の"}, {"form": "ブランドが", "label": "名詞＋が"}, {"form": "ブランドを", "label": "名詞＋を"}, {"form": "ブランドに", "label": "名詞＋に"}], "register": "標準", "sense_fingerprint": "商品やサービスを他社と区別する名称・標章・デザインの総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 失え (Zipf 2.22)']::text[], '2470728c-17dd-49c3-bc13-e1f303e86446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53028, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブランド", "is_correct": true, "explanation": "「大衆向けブランド」の空所には、商品に付けられる名称・標章を表す「ブランド」が入る。"}, {"text": "感情", "is_correct": false, "explanation": "「大衆向け感情は」は成り立たず、商品として扱えない。"}, {"text": "憧れ", "is_correct": false, "explanation": "「大衆向け憧れは」は意味が通らず、商品を表せない。"}, {"text": "咀嚼", "is_correct": false, "explanation": "「大衆向け咀嚼は」は商品の対象にならず、文脈では成り立たない。"}], "explanations": {"ブランド": "「大衆向けブランド」の空所には、商品に付けられる名称・標章を表す「ブランド」が入る。", "感情": "「大衆向け感情は」は成り立たず、商品として扱えない。", "憧れ": "「大衆向け憧れは」は意味が通らず、商品を表せない。", "咀嚼": "「大衆向け咀嚼は」は商品の対象にならず、文脈では成り立たない。"}, "sentence_index": 0, "correct_answer": "ブランド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は小さなブランドで一生暮らした。", "explanation": "ここは〈町〉の意味。ブランドは商品を区別する名称・標章で、人が暮らす場所ではない。"}, {"text": "祖母は朝、ブランドを三つ焼いた。", "explanation": "ここは〈パン〉の意味。ブランドは名称・標章の総称で、焼いて作る食べ物ではない。"}, {"text": "今日はブランドが降るので、傘を持って行く。", "explanation": "ここは〈雨〉の意味。ブランドは降るものではなく、名称・標章の総称である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53028, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブランド", "is_correct": true, "explanation": "「若者向けのブランドは、価格を低く抑えている」の空所には、商品の名称・標章を表す「ブランド」が入る。"}, {"text": "季節", "is_correct": false, "explanation": "「若者向けの季節は」は主語として意味をなさず、価格を抑える主体にならない。"}, {"text": "空気", "is_correct": false, "explanation": "「若者向けの空気は」は価格を抑える主体にならず、不自然。"}, {"text": "風景", "is_correct": false, "explanation": "「若者向けの風景は」は価格を抑える主体にならず、文意が通らない。"}], "explanations": {"ブランド": "「若者向けのブランドは、価格を低く抑えている」の空所には、商品の名称・標章を表す「ブランド」が入る。", "季節": "「若者向けの季節は」は主語として意味をなさず、価格を抑える主体にならない。", "空気": "「若者向けの空気は」は価格を抑える主体にならず、不自然。", "風景": "「若者向けの風景は」は価格を抑える主体にならず、文意が通らない。"}, "sentence_index": 6, "correct_answer": "ブランド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地元の農家が協力して、ブランドを耕した。", "explanation": "ここは〈畑〉の意味。ブランドは土地ではなく名称なので、耕すことはできない。"}, {"text": "農家の人たちは、炊きたてのブランドを食べた。", "explanation": "ここは〈ご飯〉の意味。ブランドは食べ物ではなく、名称や標章の総称である。"}, {"text": "農家の人たちは、田植えのブランドを歌った。", "explanation": "ここは〈歌〉の意味。ブランドは歌うことのできるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53028, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このブランドを名前は、祖母の名字から取られた。", "corrected_sentence": "このブランドの名前は、祖母の名字から取られた。", "error_description": "「このブランドの名前」では「の」がブランドと名前を結ぶ。「ブランドを」とすると「名前」を修飾できず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53028, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このブランドに製品は、どれも丁寧に作られている。", "corrected_sentence": "このブランドの製品は、どれも丁寧に作られている。", "error_description": "「このブランドの製品」では「の」がブランドと製品を結ぶ。「ブランドに」とすると、製品を修飾できず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a4d254-3578-4f4f-92de-50858fc37d31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
