INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53029, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53029, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "あることをすると、反対の結果になること。", "primary_collocate": null, "pronunciation": "かえって", "ipa": "kaetːe", "syllable_count": 4, "sentences": [{"text": "無理に勉強を続けたら、却って成績が下がった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "無理[むり]に勉強[べんきょう]を続[つづ]けたら、却[かえ]って成績[せいせき]が下[さ]がった。", "sentence_source": "generated"}, {"text": "地図を見すぎて、却って道に迷ってしまった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]すぎて、却[かえ]って道[みち]に迷[まよ]ってしまった。", "sentence_source": "generated"}, {"text": "心配して何度も電話したら、却って母を怒らせた。", "target_word": "却って", "complexity_tier": "T3", "furigana": "心配[しんぱい]して何度[なんど]も電話[でんわ]したら、却[かえ]って母[はは]を怒[おこ]らせた。", "sentence_source": "generated"}, {"text": "薄い味付けにしたつもりが、却って塩辛くなった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "薄[うす]い味付[あじづ]けにしたつもりが、却[かえ]って塩辛[しおから]くなった。", "sentence_source": "generated"}, {"text": "練習を休んだほうが、却って体が軽くなることもある。", "target_word": "却って", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を休[やす]んだほうが、却[かえ]って体[からだ]が軽[かる]くなることもある。", "sentence_source": "generated"}, {"text": "親が口を出しすぎると、子どもは却って反発する。", "target_word": "却って", "complexity_tier": "T3", "furigana": "親[おや]が口[くち]を出[だ]しすぎると、子[こ]どもは却[かえ]って反発[はんぱつ]する。", "sentence_source": "generated"}, {"text": "安い靴を買ったせいで、却って高くついた。", "target_word": "却って", "complexity_tier": "T3", "furigana": "安[やす]い靴[くつ]を買[か]ったせいで、却[かえ]って高[たか]くついた。", "sentence_source": "generated"}, {"text": "彼にお礼を言ったら、却って恐縮されてしまった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "彼[かれ]にお礼[れい]を言[い]ったら、却[かえ]って恐縮[きょうしゅく]されてしまった。", "sentence_source": "generated"}, {"text": "暖房をつけすぎて、却って頭が痛くなった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "暖房[だんぼう]をつけすぎて、却[かえ]って頭[あたま]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "広い部屋に引っ越したが、却って落ち着かない。", "target_word": "却って", "complexity_tier": "T3", "furigana": "広[ひろ]い部屋[へや]に引[ひ]っ越[こ]したが、却[かえ]って落[お]ち着[つ]かない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "却って", "label": "漢字表記"}, {"form": "かえって", "label": "かな表記"}], "register": "中立（書き言葉・話し言葉の両方で使う）", "sense_fingerprint": "ある行為をしたせいで、望んだ結果と逆になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53029, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "却って", "is_correct": true, "explanation": "勉強を続けた結果、望んだ成果と逆に成績が下がったという反対の結果を表すので、文意に合う。"}, {"text": "決して", "is_correct": false, "explanation": "「決して〜ない」と打ち消しと呼応する副詞なので、肯定の「下がった」には続かない。"}, {"text": "まるで", "is_correct": false, "explanation": "「まるで〜ようだ」と比喩の形で使う副詞で、この事実の説明にはつながらない。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも〜ない」と否定と呼応する副詞なので、肯定の「下がった」とは合わない。"}], "explanations": {"却って": "勉強を続けた結果、望んだ成果と逆に成績が下がったという反対の結果を表すので、文意に合う。", "決して": "「決して〜ない」と打ち消しと呼応する副詞なので、肯定の「下がった」には続かない。", "まるで": "「まるで〜ようだ」と比喩の形で使う副詞で、この事実の説明にはつながらない。", "少しも": "「少しも〜ない」と否定と呼応する副詞なので、肯定の「下がった」とは合わない。"}, "sentence_index": 0, "correct_answer": "却って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "予報どおり、却って大雪になった。", "explanation": "ここは〈案の定〉（予想どおり）の意味。却っては予想と逆の結果を表すので、予想どおりの出来事には合わない。"}, {"text": "長い会議の末、却って結論が出た。", "explanation": "ここは〈ようやく〉（長い過程の末に）の意味。却っては「逆に」の副詞なので、長引いた末の到達には合わない。"}, {"text": "却っての難しい道を選んだ。", "explanation": "却っては副詞なので「却っての＋名詞」の形は取れず、非文になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53029, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "却って", "is_correct": true, "explanation": "安い靴を買った結果、かえって費用がかさんだという反対の結果を表すので、文意に合う。"}, {"text": "一向に", "is_correct": false, "explanation": "「一向に〜ない」と否定と呼応する副詞なので、肯定の「高くついた」には続かない。"}, {"text": "必ずしも", "is_correct": false, "explanation": "「必ずしも〜ない」と部分否定で使うので、肯定の事実を述べるこの文には合わない。"}, {"text": "どうしても", "is_correct": false, "explanation": "「どうしても〜ない」と不可能を表す否定と結びつくので、ここでは続かない。"}], "explanations": {"却って": "安い靴を買った結果、かえって費用がかさんだという反対の結果を表すので、文意に合う。", "一向に": "「一向に〜ない」と否定と呼応する副詞なので、肯定の「高くついた」には続かない。", "必ずしも": "「必ずしも〜ない」と部分否定で使うので、肯定の事実を述べるこの文には合わない。", "どうしても": "「どうしても〜ない」と不可能を表す否定と結びつくので、ここでは続かない。"}, "sentence_index": 6, "correct_answer": "却って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仕事を終えて、ほどなく却って寝た。", "explanation": "ここは〈すぐに〉（間をおかず）の意味。却っては予想と反対の結果を表すので、時間の早さを表す文には使えない。"}, {"text": "湿った木の板は、却っての形を保った。", "explanation": "却っては副詞なので「却っての＋名詞」の形は取れず、非文になる。"}, {"text": "急いで階段を却って上がった。", "explanation": "ここは〈駆け上がって〉（勢いよく上る）の意味。却っては予想と反対の結果を表すので、勢いよく動く行為の説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53029, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゆっくり作ると、却って味が深める。", "corrected_sentence": "ゆっくり作ると、却って味が深まる。", "error_description": "「味が」を主語にする自動詞「深まる」が正しい。他動詞「深める」は目的語を取るので、「味が」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53029, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもを急かすと、却って言うことを聞かなくなり。", "corrected_sentence": "子どもを急かすと、却って言うことを聞かなくなる。", "error_description": "「なり」で文が終わっており、連用形のままになっている。述語は終止形「なる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
