INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53030, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "予想や期待とは反対の結果になることを表す副詞。むしろ、逆に。", "primary_collocate": null, "pronunciation": "かえって", "ipa": "kaetːe", "syllable_count": 4, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "かえって", "complexity_tier": "T5", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "薬を飲みすぎたせいで、却って体調が悪くなってしまった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]みすぎたせいで、却[かえ]って体調[たいちょう]が悪[わる]くなってしまった。", "sentence_source": "generated"}, {"text": "親切のつもりで手伝ったのに、却って迷惑をかけてしまった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "親切[しんせつ]のつもりで手伝[てつだ]ったのに、却[かえ]って迷惑[めいわく]をかけてしまった。", "sentence_source": "generated"}, {"text": "急いで近道を通ったら、却って時間がかかった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "急[いそ]いで近道[ちかみち]を通[とお]ったら、却[かえ]って時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "説明を増やしすぎると、却って分かりにくくなる。", "target_word": "却って", "complexity_tier": "T3", "furigana": "説明[せつめい]を増[ふ]やしすぎると、却[かえ]って分[わ]かりにくくなる。", "sentence_source": "generated"}, {"text": "値段を下げたのに、却って客が減ってしまった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "値段[ねだん]を下[さ]げたのに、却[かえ]って客[きゃく]が減[へ]ってしまった。", "sentence_source": "generated"}, {"text": "先生に注意されて、彼は却ってやる気を失った。", "target_word": "却って", "complexity_tier": "T3", "furigana": "先生[せんせい]に注意[ちゅうい]されて、彼[かれ]は却[かえ]ってやる気[き]を失[うしな]った。", "sentence_source": "generated"}, {"text": "雨の日は道が空いていて、却って移動しやすかった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は道[みち]が空[す]いていて、却[かえ]って移動[いどう]しやすかった。", "sentence_source": "generated"}, {"text": "励まされるほど、却って苦しくなると彼女は言った。", "target_word": "却って", "complexity_tier": "T3", "furigana": "励[はげ]まされるほど、却[かえ]って苦[くる]しくなると彼女[かのじょ]は言[い]った。", "sentence_source": "generated"}, {"text": "掃除をしたつもりが、却って部屋が散らかった。", "target_word": "却って", "complexity_tier": "T3", "furigana": "掃除[そうじ]をしたつもりが、却[かえ]って部屋[へや]が散[ち]らかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "却って", "label": "漢字表記"}, {"form": "かえって", "label": "かな表記"}], "register": "中立（書き言葉・話し言葉の両方で使う）", "sense_fingerprint": "予想や期待に反して逆の結果になる、むしろの意味の副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53030, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "かえって", "is_correct": true, "explanation": "「拒絶することで」の結果として、予想と逆に渇望が喚起されるという反対の結果を表すので、文意に合う。"}, {"text": "まるで", "is_correct": false, "explanation": "「まるで〜ようだ」と比喩の形で使う副詞で、この結果を述べる文にはつながらない。"}, {"text": "あいにく", "is_correct": false, "explanation": "残念な事情を伝える副詞で、中立的に効果を説明するこの文の述語とは合わない。"}, {"text": "決して", "is_correct": false, "explanation": "「決して〜ない」と打ち消しと呼応する副詞なので、肯定の「喚起する」には続かない。"}], "explanations": {"かえって": "「拒絶することで」の結果として、予想と逆に渇望が喚起されるという反対の結果を表すので、文意に合う。", "まるで": "「まるで〜ようだ」と比喩の形で使う副詞で、この結果を述べる文にはつながらない。", "あいにく": "残念な事情を伝える副詞で、中立的に効果を説明するこの文の述語とは合わない。", "決して": "「決して〜ない」と打ち消しと呼応する副詞なので、肯定の「喚起する」には続かない。"}, "sentence_index": 0, "correct_answer": "かえって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降りだしたので、傘を買わずに、却って新聞を頭にのせた。", "explanation": "ここは〈代わりに〉（ほかのもので代える）の意味。却っては予想と反対の結果を表すので、代用の行為には合わない。"}, {"text": "毎日練習していたので、却って上達するのは当然だった。", "explanation": "ここは〈やっぱり〉（予想どおり）の意味。却っては予想と反対の結果を表すので、予想どおりの上達には合わない。"}, {"text": "寝坊して、却って遅刻した。", "explanation": "ここは〈つい〉（うっかり）の意味。却っては予想と逆の結果を表すので、うっかりした行為の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53030, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "却って", "is_correct": true, "explanation": "注意された結果、予想に反してやる気が失われたという反対の結果を表すので、文意に合う。"}, {"text": "一向に", "is_correct": false, "explanation": "「一向に〜ない」と否定と呼応する副詞なので、肯定形の「失った」には続かない。"}, {"text": "必ずしも", "is_correct": false, "explanation": "「必ずしも〜ない」と部分否定で使う副詞なので、肯定の出来事を述べるこの文には合わない。"}, {"text": "どうしても", "is_correct": false, "explanation": "「どうしても〜ない」と不可能を表す否定と結びつくので、ここでは続かない。"}], "explanations": {"却って": "注意された結果、予想に反してやる気が失われたという反対の結果を表すので、文意に合う。", "一向に": "「一向に〜ない」と否定と呼応する副詞なので、肯定形の「失った」には続かない。", "必ずしも": "「必ずしも〜ない」と部分否定で使う副詞なので、肯定の出来事を述べるこの文には合わない。", "どうしても": "「どうしても〜ない」と不可能を表す否定と結びつくので、ここでは続かない。"}, "sentence_index": 6, "correct_answer": "却って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天気予報どおり、却って雨が降った。", "explanation": "ここは〈案の定〉（予想どおり）の意味。却っては予想と逆の結果を表すので、予想どおりの出来事には合わない。"}, {"text": "雨の日の散歩を、却っての中止だった。", "explanation": "却っては副詞なので「却っての＋名詞」の形は取れず、非文になる。"}, {"text": "兄は、弟の服を却っての借り物にした。", "explanation": "却っては副詞なので「却っての＋名詞」の形は取れず、非文になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53030, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薬を飲みすぎると、却って体を壊し。", "corrected_sentence": "薬を飲みすぎると、却って体を壊す。", "error_description": "「壊し」では文が終わらず連用形のままになっている。「却って」が修飾する述語は終止形「壊す」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53030, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "褒めすぎると、却って相手が冷ます。", "corrected_sentence": "褒めすぎると、却って相手が冷める。", "error_description": "「相手が」を主語にする自動詞「冷める」が正しい。他動詞「冷ます」は目的語を取るので、主語「相手が」とは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
