INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53031, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「咀嚼が」の「が」で、「不十分だ」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格助詞。ここは主語の位置なので、「咀嚼を不十分だ」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格助詞。「咀嚼へ不十分だ」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格助詞。「咀嚼から不十分だ」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「咀嚼が」の「が」で、「不十分だ」の主語を示す。", "を": "目的語を示す格助詞。ここは主語の位置なので、「咀嚼を不十分だ」では成り立たない。", "へ": "方向を示す格助詞。「咀嚼へ不十分だ」では意味が通らない。", "から": "起点を示す格助詞。「咀嚼から不十分だ」では意味が通らない。"}, "error_tags": {"を": "目的語の格（ここは主語の位置）", "へ": "方向の格（意味が通らない）", "から": "起点の格（意味が通らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53031, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食べ物をよくかんで、のどを通るようにすること。", "primary_collocate": null, "pronunciation": "そしゃく", "ipa": "soɕaku", "syllable_count": 3, "sentences": [{"text": "歯が痛くて、ご飯を咀嚼するのがつらい。", "target_word": "咀嚼", "complexity_tier": "T2", "furigana": "歯[は]が痛[いた]くて、ご飯[はん]を咀嚼[そしゃく]するのがつらい。", "sentence_source": "generated"}, {"text": "赤ちゃんには、柔らかい離乳食をゆっくり咀嚼させる。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんには、柔[やわ]らかい離乳食[りにゅうしょく]をゆっくり咀嚼[そしゃく]させる。", "sentence_source": "generated"}, {"text": "咀嚼の回数を増やすと、満腹感を得やすくなる。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "咀嚼[そしゃく]の回数[かいすう]を増[ふ]やすと、満腹感[まんぷくかん]を得[え]やすくなる。", "sentence_source": "generated"}, {"text": "祖父は入れ歯が合わず、固い食べ物を咀嚼できない。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "祖父[そふ]は入[い]れ歯[ば]が合[あ]わず、固[かた]い食[た]べ物[もの]を咀嚼[そしゃく]できない。", "sentence_source": "generated"}, {"text": "医者に、一口三十回は咀嚼するよう言われた。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "医者[いしゃ]に、一口[ひとくち]三十回[さんじゅっかい]は咀嚼[そしゃく]するよう言[い]われた。", "sentence_source": "generated"}, {"text": "早食いをやめて、よく咀嚼して食べるようにした。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "早食[はやぐ]いをやめて、よく咀嚼[そしゃく]して食[た]べるようにした。", "sentence_source": "generated"}, {"text": "ガムを咀嚼すると、あごの筋肉が鍛えられる。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "ガムを咀嚼[そしゃく]すると、あごの筋肉[きんにく]が鍛[きた]えられる。", "sentence_source": "generated"}, {"text": "咀嚼が不十分だと、胃に負担がかかる。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "咀嚼[そしゃく]が不十分[ふじゅうぶん]だと、胃[い]に負担[ふたん]がかかる。", "sentence_source": "generated"}, {"text": "牛が草を咀嚼する音が、静かな牧場に響いていた。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "牛[うし]が草[くさ]を咀嚼[そしゃく]する音[おと]が、静[しず]かな牧場[ぼくじょう]に響[ひび]いていた。", "sentence_source": "generated"}, {"text": "咀嚼しやすいように、野菜を小さく切った。", "target_word": "咀嚼", "complexity_tier": "T2", "furigana": "咀嚼[そしゃく]しやすいように、野菜[やさい]を小[ちい]さく切[き]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "咀嚼する", "label": "サ変動詞・基本形"}, {"form": "咀嚼した", "label": "過去形"}, {"form": "咀嚼して", "label": "て形"}, {"form": "咀嚼させる", "label": "使役形"}], "register": "やや硬い（書き言葉・改まった場面）", "sense_fingerprint": "食べ物を口の中でよくかむという、実際の食事の動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53031, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咀嚼", "is_correct": true, "explanation": "食べ物を口の中でかみくだく動作を表し、ご飯を対象にする文に合う。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える意味で、ご飯を対象にすると意味が通らない。"}, {"text": "採点", "is_correct": false, "explanation": "答案に点数をつける意味で、食事の動作には合わない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける意味で、食べ物を対象にすると文が成り立たない。"}], "explanations": {"咀嚼": "食べ物を口の中でかみくだく動作を表し、ご飯を対象にする文に合う。", "換気": "空気を入れ替える意味で、ご飯を対象にすると意味が通らない。", "採点": "答案に点数をつける意味で、食事の動作には合わない。", "施錠": "鍵をかける意味で、食べ物を対象にすると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "咀嚼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ペットボトルを咀嚼して、ごみ箱に捨てた。", "explanation": "ここは〈押しつぶす〉（力を加えて潰す）の意味。咀嚼は食べ物を口でかみくだくことなので、物を潰す動作には使えない。"}, {"text": "蛇はネズミを咀嚼する。", "explanation": "ここは〈丸飲み〉（かまずにそのまま飲む）の意味。咀嚼は口の中でかみくだく動作なので、かまずに飲む蛇には使えない。"}, {"text": "ストローでジュースを咀嚼する。", "explanation": "ここは〈吸う〉（口で液体を吸い込む）の意味。咀嚼は食べ物をかみくだく動作なので、液体を吸う動作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53031, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咀嚼", "is_correct": true, "explanation": "ガムを口の中でかむ動作を表し、あごの筋肉が鍛えられるという文に合う。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、ガムを対象にすると文が成り立たない。"}, {"text": "撹拌", "is_correct": false, "explanation": "かき混ぜる意味で、ガムに対して使うと筋肉の話とつながらない。"}, {"text": "脱水", "is_correct": false, "explanation": "水分を抜く意味で、ガムを対象にする動作としては続かない。"}], "explanations": {"咀嚼": "ガムを口の中でかむ動作を表し、あごの筋肉が鍛えられるという文に合う。", "点火": "火をつける意味で、ガムを対象にすると文が成り立たない。", "撹拌": "かき混ぜる意味で、ガムに対して使うと筋肉の話とつながらない。", "脱水": "水分を抜く意味で、ガムを対象にする動作としては続かない。"}, "sentence_index": 6, "correct_answer": "咀嚼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その国の領土を一定期間、咀嚼した。", "explanation": "ここは〈租借〉（他国の領土を一定期間借りる）の意味。咀嚼は食べ物をかむ意味なので、土地を借りる意味では使えない。"}, {"text": "ごまを乳鉢で咀嚼する。", "explanation": "ここは〈すりつぶす〉（力を加えて細かくする）の意味。咀嚼は口の中でかむ動作なので、道具で砕く場面には使わない。"}, {"text": "ガラスのコップを咀嚼した。", "explanation": "ここは〈割る〉（砕いて壊す）の意味。咀嚼は食べ物を口でかみくだくことなので、ガラスを砕く行為には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53031, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "よく咀嚼ると、胃の負担が減る。", "corrected_sentence": "よく咀嚼すると、胃の負担が減る。", "error_description": "「咀嚼ると」は誤り。サ変動詞「咀嚼する」の仮定形は「咀嚼すると」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53031, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咀嚼に助けるため、野菜はよく煮る。", "corrected_sentence": "咀嚼を助けるため、野菜はよく煮る。", "error_description": "「助ける」の対象は「を」で示すので「咀嚼を助ける」が正しい。「咀嚼に助ける」は格助詞の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
