INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53032, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食べ物を口の中でかみくだいて味わうこと。また、比喩的に、情報や感情を十分に理解したり、うまく利用したりすること。", "primary_collocate": null, "pronunciation": "そしゃく", "ipa": "soɕaku", "syllable_count": 3, "sentences": [{"text": "この憧れの感情は、やがてグローバルな大衆向けブランドによって巧妙に咀嚼され、誰もが手が届く価格帯へと昇華されるのだ。", "target_word": "咀嚼", "complexity_tier": "T5", "furigana": "この憧[あこが]れの感情[かんじょう]は、やがてグローバルな大衆向[たいしゅうむ]けブランドによって巧妙[こうみょう]に咀嚼[そしゃく]され、誰[だれ]もが手[て]が届[とど]く価格帯[かかくたい]へと昇華[しょうか]されるのだ。", "sentence_source": "mined"}, {"text": "難しい本は、内容を咀嚼しながらゆっくり読むようにしている。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "難[むずか]しい本[ほん]は、内容[ないよう]を咀嚼[そしゃく]しながらゆっくり読[よ]むようにしている。", "sentence_source": "generated"}, {"text": "先生の話を咀嚼して、自分の言葉でまとめ直した。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]を咀嚼[そしゃく]して、自分[じぶん]の言葉[ことば]でまとめ直[なお]した。", "sentence_source": "generated"}, {"text": "新しい制度の意味を咀嚼するのに、時間がかかった。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]の意味[いみ]を咀嚼[そしゃく]するのに、時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "彼は外国の文化をよく咀嚼したうえで、自分の作品に取り入れた。", "target_word": "咀嚼", "complexity_tier": "T4", "furigana": "彼[かれ]は外国[がいこく]の文化[ぶんか]をよく咀嚼[そしゃく]したうえで、自分[じぶん]の作品[さくひん]に取[と]り入[い]れた。", "sentence_source": "generated"}, {"text": "硬い肉は、十分に咀嚼してから飲み込むほうがよい。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "硬[かた]い肉[にく]は、十分[じゅうぶん]に咀嚼[そしゃく]してから飲[の]み込[こ]むほうがよい。", "sentence_source": "generated"}, {"text": "資料を咀嚼しきれないまま発表したため、質問に答えられなかった。", "target_word": "咀嚼", "complexity_tier": "T4", "furigana": "資料[しりょう]を咀嚼[そしゃく]しきれないまま発表[はっぴょう]したため、質問[しつもん]に答[こた]えられなかった。", "sentence_source": "generated"}, {"text": "悲しい知らせを咀嚼するまでに、数日かかった。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "悲[かな]しい知[し]らせを咀嚼[そしゃく]するまでに、数日[すうじつ]かかった。", "sentence_source": "generated"}, {"text": "一口ごとに咀嚼すると、料理の甘みがよく分かる。", "target_word": "咀嚼", "complexity_tier": "T3", "furigana": "一口[ひとくち]ごとに咀嚼[そしゃく]すると、料理[りょうり]の甘[あま]みがよく分[わ]かる。", "sentence_source": "generated"}, {"text": "読んだ内容を咀嚼せずに引用しても、説得力は生まれない。", "target_word": "咀嚼", "complexity_tier": "T4", "furigana": "読[よ]んだ内容[ないよう]を咀嚼[そしゃく]せずに引用[いんよう]しても、説得力[せっとくりょく]は生[う]まれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "咀嚼する", "label": "サ変動詞・基本形"}, {"form": "咀嚼した", "label": "過去形"}, {"form": "咀嚼して", "label": "て形"}, {"form": "咀嚼される", "label": "受身形"}], "register": "やや硬い（書き言葉・改まった場面）", "sense_fingerprint": "食べ物をかむことに加え、内容や感情を理解して自分のものにする比喩的な意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53032, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咀嚼", "is_correct": true, "explanation": "感情を巧妙に取り込み、理解して加工するという比喩的な意味で、文の流れに合う。"}, {"text": "隆起", "is_correct": false, "explanation": "地面などが盛り上がる意味で、ブランドが感情を扱う文脈には合わない。"}, {"text": "発芽", "is_correct": false, "explanation": "種から芽が出る意味で、感情を取り込んで加工する働きとは合わない。"}, {"text": "沈殿", "is_correct": false, "explanation": "液体の底に溜まる意味で、「巧妙に」と続いて加工を述べる文には合わない。"}], "explanations": {"咀嚼": "感情を巧妙に取り込み、理解して加工するという比喩的な意味で、文の流れに合う。", "隆起": "地面などが盛り上がる意味で、ブランドが感情を扱う文脈には合わない。", "発芽": "種から芽が出る意味で、感情を取り込んで加工する働きとは合わない。", "沈殿": "液体の底に溜まる意味で、「巧妙に」と続いて加工を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "咀嚼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その港を十年間、咀嚼した。", "explanation": "ここは〈租借〉（他国の土地を一定期間借りる）の意味。咀嚼は内容を消化して理解することなので、土地を借りる意味では使えない。"}, {"text": "消しゴムを咀嚼するのに、時間がかかった。", "explanation": "ここは〈いじる〉（手で触る）の意味。咀嚼は口でかみくだく動作なので、物を手でいじる行為には使えない。"}, {"text": "報告書を咀嚼して、紙飛行機にした。", "explanation": "ここは〈折る〉（紙を形に折り畳む）の意味。咀嚼は口でかみくだく動作なので、紙を折る作業には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53032, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咀嚼", "is_correct": true, "explanation": "資料を十分に理解しきれないという意味で、比喩的な用法として文に合う。"}, {"text": "点滅", "is_correct": false, "explanation": "明かりが点いたり消えたりする意味で、資料を対象にすると文が成り立たない。"}, {"text": "結露", "is_correct": false, "explanation": "水滴がつく現象を表し、資料を対象にする動作とは合わない。"}, {"text": "降雨", "is_correct": false, "explanation": "雨が降る現象の名詞で、資料に対する動作の述語としては続かない。"}], "explanations": {"咀嚼": "資料を十分に理解しきれないという意味で、比喩的な用法として文に合う。", "点滅": "明かりが点いたり消えたりする意味で、資料を対象にすると文が成り立たない。", "結露": "水滴がつく現象を表し、資料を対象にする動作とは合わない。", "降雨": "雨が降る現象の名詞で、資料に対する動作の述語としては続かない。"}, "sentence_index": 6, "correct_answer": "咀嚼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "細かい誤りを咀嚼した。", "explanation": "ここは〈見落とす〉（気づかず通り過ぎる）の意味。咀嚼は内容を理解して味わうことなので、誤りを見逃す意味には合わない。"}, {"text": "先生の小言を咀嚼して、冷蔵庫に入れた。", "explanation": "ここは〈しまう〉（片付けて置く）の意味。咀嚼は内容を理解することなので、物を片付ける行為には使えない。"}, {"text": "数字を咀嚼して、窓辺に並べた。", "explanation": "ここは〈陳列〉（商品などを並べて見せる）の意味。咀嚼は内容を理解することなので、物を並べて見せる行為には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53032, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "話の要点を咀嚼で、自分の言葉で説明する。", "corrected_sentence": "話の要点を咀嚼して、自分の言葉で説明する。", "error_description": "「咀嚼で」は誤り。動作を順に連ねる「咀嚼して」（て形）が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53032, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "情報は、一度咀嚼てから受け入れたほうがいい。", "corrected_sentence": "情報は、一度咀嚼してから受け入れたほうがいい。", "error_description": "「咀嚼てから」は誤り。サ変名詞「咀嚼」には「して」を続けるので「咀嚼してから」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53033, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53033, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「奉仕を続けている」で、続ける対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「奉仕に続けている」は、続ける対象を示す形としては不自然で、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「奉仕と続けている」は名詞を並べる形で、続ける対象として文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「奉仕の続けている」は名詞を修飾する形になり、文の述語が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「奉仕を続けている」で、続ける対象を表す。", "に": "「奉仕に続けている」は、続ける対象を示す形としては不自然で、文が成り立たない。", "と": "「奉仕と続けている」は名詞を並べる形で、続ける対象として文が成り立たない。", "の": "「奉仕の続けている」は名詞を修飾する形になり、文の述語が成り立たない。"}, "error_tags": {"に": "方向・相手（〜に）", "と": "並列（〜と）", "の": "修飾（〜の）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53033, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "だれかのために、はたらくこと。", "primary_collocate": null, "pronunciation": "ほうし", "ipa": "hoːɕi", "syllable_count": 3, "sentences": [{"text": "休みの日に、近所の公園で奉仕の作業をした。", "target_word": "奉仕", "complexity_tier": "T2", "furigana": "休[やす]みの日[ひ]に、近所[きんじょ]の公園[こうえん]で奉仕[ほうし]の作業[さぎょう]をした。", "sentence_source": "generated"}, {"text": "彼は人の役に立つ奉仕の仕事がしたいと言っている。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]の役[やく]に立[た]つ奉仕[ほうし]の仕事[しごと]がしたいと言[い]っている。", "sentence_source": "generated"}, {"text": "無料で子どもたちに勉強を教える奉仕を始めた。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "無料[むりょう]で子[こ]どもたちに勉強[べんきょう]を教[おし]える奉仕[ほうし]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "奉仕は、お金のためではなく人のためにする仕事だ。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "奉仕[ほうし]は、お金[かね]のためではなく人[ひと]のためにする仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "私の母は老人ホームで奉仕している。", "target_word": "奉仕", "complexity_tier": "T2", "furigana": "私[わたし]の母[はは]は老人[ろうじん]ホームで奉仕[ほうし]している。", "sentence_source": "generated"}, {"text": "奉仕の気持ちがあれば、小さなことでも人を助けられる。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "奉仕[ほうし]の気持[きも]ちがあれば、小[ちい]さなことでも人[ひと]を助[たす]けられる。", "sentence_source": "generated"}, {"text": "学校の行事で、町の川をきれいにする奉仕に参加した。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "学校[がっこう]の行事[ぎょうじ]で、町[まち]の川[かわ]をきれいにする奉仕[ほうし]に参加[さんか]した。", "sentence_source": "generated"}, {"text": "彼女は頼まれなくても、毎朝道を掃除する奉仕を続けている。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は頼[たの]まれなくても、毎朝[まいあさ]道[みち]を掃除[そうじ]する奉仕[ほうし]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "災害の現場では、多くの人が奉仕のために集まった。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "災害[さいがい]の現場[げんば]では、多[おお]くの人[ひと]が奉仕[ほうし]のために集[あつ]まった。", "sentence_source": "generated"}, {"text": "奉仕を通して、人に感謝される喜びを知った。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "奉仕[ほうし]を通[つう]して、人[ひと]に感謝[かんしゃ]される喜[よろこ]びを知[し]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奉仕する", "label": "サ変動詞・基本形"}, {"form": "奉仕した", "label": "過去形"}, {"form": "奉仕して", "label": "て形"}, {"form": "奉仕させる", "label": "使役形"}], "register": "やや硬い（書き言葉・改まった場面）", "sense_fingerprint": "お金のためではなく、人の役に立つために働く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53033, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出産", "is_correct": false, "explanation": "出産は子を産むこと。近所の公園で出産の作業をしたという文は意味を成さない。"}, {"text": "結婚", "is_correct": false, "explanation": "結婚は夫婦になること。「結婚の作業をした」という表現は文脈に合わない。"}, {"text": "奉仕", "is_correct": true, "explanation": "お金のためでなく人のために働く作業という文意に合い、「奉仕の作業」として自然に成立する。"}, {"text": "離婚", "is_correct": false, "explanation": "離婚は夫婦が別れること。近所の公園で離婚の作業をするという文は成り立たない。"}], "explanations": {"出産": "出産は子を産むこと。近所の公園で出産の作業をしたという文は意味を成さない。", "結婚": "結婚は夫婦になること。「結婚の作業をした」という表現は文脈に合わない。", "奉仕": "お金のためでなく人のために働く作業という文意に合い、「奉仕の作業」として自然に成立する。", "離婚": "離婚は夫婦が別れること。近所の公園で離婚の作業をするという文は成り立たない。"}, "sentence_index": 0, "correct_answer": "奉仕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は契約書に奉仕を署名した。", "explanation": "ここは〈署名〉（名前を書き入れること）の意味。〈奉仕〉は人のために働くことなので、書類に名前を書く行為には使わない。"}, {"text": "彼は工場で毎日十時間、給料をもらって奉仕している。", "explanation": "ここは〈労働〉（報酬を得て働くこと）の意味。〈奉仕〉は無償で人のために働くことなので、賃金を得る仕事には合わない。"}, {"text": "父は地元の寺に多額の奉仕をした。", "explanation": "ここは〈寄付〉（金品を差し出すこと）の意味。〈奉仕〉は労力を人のために使うことなので、金額には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53033, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暗記", "is_correct": false, "explanation": "暗記は内容を覚えること。学校の行事で川をきれいにする暗記に参加したという文は成り立たない。"}, {"text": "解雇", "is_correct": false, "explanation": "解雇は職を辞めさせること。川をきれいにする行事に解雇が参加するという文は意味が通らない。"}, {"text": "奉仕", "is_correct": true, "explanation": "町の川をきれいにする無償の活動に参加したという文意に合い、奉仕の行事として自然。"}, {"text": "出版", "is_correct": false, "explanation": "出版は書籍などを世に出すこと。川をきれいにする行事の内容としては合わない。"}], "explanations": {"暗記": "暗記は内容を覚えること。学校の行事で川をきれいにする暗記に参加したという文は成り立たない。", "解雇": "解雇は職を辞めさせること。川をきれいにする行事に解雇が参加するという文は意味が通らない。", "奉仕": "町の川をきれいにする無償の活動に参加したという文意に合い、奉仕の行事として自然。", "出版": "出版は書籍などを世に出すこと。川をきれいにする行事の内容としては合わない。"}, "sentence_index": 6, "correct_answer": "奉仕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コーチは選手に技術を奉仕した。", "explanation": "ここは〈指導〉（教えて身につけさせること）の意味。〈奉仕〉は相手のために働くことで、技術を教える場面には合わない。"}, {"text": "学生は宿題を先生に奉仕した。", "explanation": "ここは〈提出〉（書類や物を相手に渡すこと）の意味。〈奉仕〉は身を尽くす働きなので、物を渡す行為には使わない。"}, {"text": "警察は犯人を奉仕した。", "explanation": "ここは〈逮捕〉（身柄を拘束すること）の意味。〈奉仕〉は仕えることで、人を捕らえる行為とは意味が正反対になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53033, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は週末、無償で地域の清掃に奉仕を払った。", "corrected_sentence": "彼は週末、無償で地域の清掃に奉仕した。", "error_description": "〈奉仕〉は「する」で行う行為なので、「払った」とは組み合わない。正しくは「奉仕した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53033, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校の行事で、町の川をきれいにする奉仕な活動に参加した。", "corrected_sentence": "学校の行事で、町の川をきれいにする奉仕的な活動に参加した。", "error_description": "〈奉仕〉は名詞なので、形容動詞の「な」で直接修飾すると誤り。「奉仕的な」と「的」を付けて形容動詞にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53034, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「奉仕に力を尽くす」で、力を向ける先を表す。"}, {"text": "と", "is_correct": false, "explanation": "「奉仕と力を尽くした」は名詞を並べる形で、力を尽くす対象として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すため、「奉仕から力を尽くした」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、比べる文脈がないので「奉仕より力を尽くした」は合わない。"}], "correct_answer": "に", "explanations": {"に": "「奉仕に力を尽くす」で、力を向ける先を表す。", "と": "「奉仕と力を尽くした」は名詞を並べる形で、力を尽くす対象として成り立たない。", "から": "「から」は起点を表すため、「奉仕から力を尽くした」は意味が通らない。", "より": "「より」は比較を表すが、比べる文脈がないので「奉仕より力を尽くした」は合わない。"}, "error_tags": {"と": "並列（〜と）", "から": "起点（〜から）", "より": "比較（〜より）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53034, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「奉仕に生涯を捧げた」で、捧げる対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「奉仕が生涯を捧げた」では奉仕が主語になり、捧げる主体が成り立たないので文として合わない。"}, {"text": "は", "is_correct": false, "explanation": "「奉仕は生涯を捧げた」では奉仕が捧げる主体になり、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「生涯を」に既に「を」があり、「奉仕を」と目的語が重なるため不自然。"}], "correct_answer": "に", "explanations": {"に": "「奉仕に生涯を捧げた」で、捧げる対象を表す。", "が": "「奉仕が生涯を捧げた」では奉仕が主語になり、捧げる主体が成り立たないので文として合わない。", "は": "「奉仕は生涯を捧げた」では奉仕が捧げる主体になり、文として成り立たない。", "を": "「生涯を」に既に「を」があり、「奉仕を」と目的語が重なるため不自然。"}, "error_tags": {"が": "主語（〜が）", "は": "主題（〜は）", "を": "目的語（〜を）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53034, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他人や特定の集団のために尽力すること。特に、目上の人や社会に仕えること。", "primary_collocate": null, "pronunciation": "ほうし", "ipa": "hoːɕi", "syllable_count": 3, "sentences": [{"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "奉仕", "complexity_tier": "T5", "furigana": "すなわち、限[かぎ]られた特権階級[とっけんかいきゅう]のみに奉仕[ほうし]することを潔[いさぎよ]しとしない独占的[どくせんてき]な美学[びがく]こそが、地上[ちじょう]に降[お]り立[た]つトレンドの羅針盤[らしんばん]としての役割[やくわり]を担[にな]い、現代[げんだい]のファッション産業[さんぎょう]における生態系[せいたいけい]を永続的[えいぞくてき]に循環[じゅんかん]させているのである。", "sentence_source": "mined"}, {"text": "彼は一生、社会への奉仕に力を尽くした。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "彼[かれ]は一生[いっしょう]、社会[しゃかい]への奉仕[ほうし]に力[ちから]を尽[つ]くした。", "sentence_source": "generated"}, {"text": "休日には地域の清掃活動で奉仕している。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]には地域[ちいき]の清掃活動[せいそうかつどう]で奉仕[ほうし]している。", "sentence_source": "generated"}, {"text": "騎士は主君に奉仕することを誇りにしていた。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "騎士[きし]は主君[しゅくん]に奉仕[ほうし]することを誇[ほこ]りにしていた。", "sentence_source": "generated"}, {"text": "彼女は病院で週に二度、患者のために奉仕を続けている。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "彼女は病院[びょういん]で週[しゅう]に二度[にど]、患者[かんじゃ]のために奉仕[ほうし]を続けている。", "sentence_source": "generated"}, {"text": "国民に奉仕するのが、公務員の本来の務めだ。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "国民[こくみん]に奉仕[ほうし]するのが、公務員[こうむいん]の本来[ほんらい]の務[つと]めだ。", "sentence_source": "generated"}, {"text": "私利私欲を捨てて、人々のために奉仕する決意をした。", "target_word": "奉仕", "complexity_tier": "T4", "furigana": "私利私欲[しりしよく]を捨[す]てて、人々[ひとびと]のために奉仕[ほうし]する決意[けつい]をした。", "sentence_source": "generated"}, {"text": "修道女たちは貧しい人々への奉仕に生涯を捧げた。", "target_word": "奉仕", "complexity_tier": "T4", "furigana": "修道女[しゅうどうじょ]たちは貧[まず]しい人々[ひとびと]への奉仕[ほうし]に生涯[しょうがい]を捧[ささ]げた。", "sentence_source": "generated"}, {"text": "長年の奉仕に対して、市から表彰を受けた。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "長年[ながねん]の奉仕[ほうし]に対[たい]して、市[し]から表彰[ひょうしょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "奉仕の精神を学ぶため、学生たちが施設を訪れた。", "target_word": "奉仕", "complexity_tier": "T3", "furigana": "奉仕[ほうし]の精神[せいしん]を学[まな]ぶため、学生[がくせい]たちが施設[しせつ]を訪[おとず]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奉仕する", "label": "サ変動詞・基本形"}, {"form": "奉仕した", "label": "過去形"}, {"form": "奉仕して", "label": "て形"}, {"form": "奉仕させる", "label": "使役形"}], "register": "やや硬い（書き言葉・改まった場面）", "sense_fingerprint": "目上の人や社会、特定の集団のために身を尽くして仕える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 潔し (Zipf 1.9)']::text[], '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53034, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作曲", "is_correct": false, "explanation": "作曲は曲を創ること。特権階級のみに曲を作ることを潔しとしないという文意では、仕える行為の意味にならない。"}, {"text": "奉仕", "is_correct": true, "explanation": "特権階級のみに仕えることを潔しとしないという文意に合い、目上や社会に仕える意味で使われている。"}, {"text": "撮影", "is_correct": false, "explanation": "撮影は写真や映像を撮ること。特権階級のみに撮影するという行為は、この文の意味と合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言葉を別の言語に置き換えること。身分の高い人に仕える文脈では意味が通らない。"}], "explanations": {"作曲": "作曲は曲を創ること。特権階級のみに曲を作ることを潔しとしないという文意では、仕える行為の意味にならない。", "奉仕": "特権階級のみに仕えることを潔しとしないという文意に合い、目上や社会に仕える意味で使われている。", "撮影": "撮影は写真や映像を撮ること。特権階級のみに撮影するという行為は、この文の意味と合わない。", "翻訳": "翻訳は言葉を別の言語に置き換えること。身分の高い人に仕える文脈では意味が通らない。"}, "sentence_index": 0, "correct_answer": "奉仕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は答案の余白に奉仕を書いた。", "explanation": "ここは〈解答〉（問題に答えを書くこと）の意味。〈奉仕〉は人のために働くことなので、答案に答えを書く行為には使わない。"}, {"text": "彼は夜中に大声で騒いで、隣人に奉仕した。", "explanation": "ここは〈迷惑〉（相手を困らせること）の意味。〈奉仕〉は相手のために尽くすことなので、相手を困らせる行為には使えない。"}, {"text": "信者が神社に絵馬を奉仕した。", "explanation": "ここは〈奉納〉（神仏に物を捧げる）の意味。〈奉仕〉は人に仕える行為で、物を捧げる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53034, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "離婚", "is_correct": false, "explanation": "離婚は夫婦が法的に別れること。人々のために離婚するという文は意味を成さない。"}, {"text": "暗記", "is_correct": false, "explanation": "暗記は内容を覚えること。人々のために暗記する決意という文脈では意味が通らない。"}, {"text": "奉仕", "is_correct": true, "explanation": "人々のために仕える決意という文意に合い、私利私欲を捨てる流れとも一致する。"}, {"text": "解雇", "is_correct": false, "explanation": "解雇は職を辞めさせること。人々のために解雇する決意という文は、文脈と合わない。"}], "explanations": {"離婚": "離婚は夫婦が法的に別れること。人々のために離婚するという文は意味を成さない。", "暗記": "暗記は内容を覚えること。人々のために暗記する決意という文脈では意味が通らない。", "奉仕": "人々のために仕える決意という文意に合い、私利私欲を捨てる流れとも一致する。", "解雇": "解雇は職を辞めさせること。人々のために解雇する決意という文は、文脈と合わない。"}, "sentence_index": 6, "correct_answer": "奉仕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は被災地に多額の奉仕をした。", "explanation": "ここは〈寄付〉（金品を差し出すこと）の意味。〈奉仕〉は身を尽くして働くことなので、金額には使えない。"}, {"text": "部下は社長に売上を奉仕した。", "explanation": "ここは〈報告〉（事実や結果を伝えること）の意味。〈奉仕〉は仕える働きなので、数字の情報を伝える行為には使わない。"}, {"text": "監督は選手に作戦を奉仕した。", "explanation": "ここは〈指示〉（指図して行わせること）の意味。〈奉仕〉は相手に仕えることで、作戦を伝えて動かす意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53034, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は社会を奉仕する決意を固めた。", "corrected_sentence": "彼は社会に奉仕する決意を固めた。", "error_description": "〈奉仕〉は「〜に奉仕する」と、仕える相手を「に」で表す。「を」は誤り。正しくは「社会に奉仕する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53034, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は若い頃から社会を奉仕し続けた。", "corrected_sentence": "彼女は若い頃から社会に奉仕し続けた。", "error_description": "〈奉仕〉は仕える相手を「に」で表す。「を」は誤り。正しくは「社会に奉仕し続けた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53035, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地上に足をつける」で、足を置く場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "「地上が足をつける」は主語と動作が合わず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「地上を足をつける」は目的語が二つになり、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「地上の足をつける」は名詞を修飾する形になり、文の動作が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「地上に足をつける」で、足を置く場所を表す。", "が": "「地上が足をつける」は主語と動作が合わず、文が成り立たない。", "を": "「地上を足をつける」は目的語が二つになり、不自然。", "の": "「地上の足をつける」は名詞を修飾する形になり、文の動作が成り立たない。"}, "error_tags": {"が": "主語（〜が）", "を": "目的語（〜を）", "の": "修飾（〜の）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53035, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地上に落ちた」で、落ちた先の場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "「地上が落ちた葉を」は主語と動作が合わず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「地上より落ちた葉」は比較の形になり、落ちた場所を表す文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「地上を落ちた葉を」は場所を通る形になり、落ちた先を示す文とは合わない。"}], "correct_answer": "に", "explanations": {"に": "「地上に落ちた」で、落ちた先の場所を表す。", "が": "「地上が落ちた葉を」は主語と動作が合わず、文が成り立たない。", "より": "「地上より落ちた葉」は比較の形になり、落ちた場所を表す文として成り立たない。", "を": "「地上を落ちた葉を」は場所を通る形になり、落ちた先を示す文とは合わない。"}, "error_tags": {"が": "主語（〜が）", "より": "比較（〜より）", "を": "目的語（〜を）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53035, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面のこと。足の下にあるところ。", "primary_collocate": null, "pronunciation": "ちじょう", "ipa": "tɕidʑoː", "syllable_count": 3, "sentences": [{"text": "木から落ちた実が、地上でころころ転がっている。", "target_word": "地上", "complexity_tier": "T2", "furigana": "木[き]から落[お]ちた実[み]が、地上[ちじょう]でころころ転[ころ]がっている。", "sentence_source": "generated"}, {"text": "はしごから降りて地上に足をつけると、ほっとした。", "target_word": "地上", "complexity_tier": "T3", "furigana": "はしごから降[お]りて地上[ちじょう]に足[あし]をつけると、ほっとした。", "sentence_source": "generated"}, {"text": "モグラは地下にすみ、めったに地上には出てこない。", "target_word": "地上", "complexity_tier": "T3", "furigana": "モグラは地下[ちか]にすみ、めったに地上[ちじょう]には出[で]てこない。", "sentence_source": "generated"}, {"text": "井戸の水を汲み上げて、地上まで運んだ。", "target_word": "地上", "complexity_tier": "T3", "furigana": "井戸[いど]の水[みず]を汲[く]み上[あ]げて、地上[ちじょう]まで運[はこ]んだ。", "sentence_source": "generated"}, {"text": "工事中の穴から、はしごで地上へ上がった。", "target_word": "地上", "complexity_tier": "T3", "furigana": "工事中[こうじちゅう]の穴[あな]から、はしごで地上[ちじょう]へ上[あ]がった。", "sentence_source": "generated"}, {"text": "巣から落ちたひなが、地上でじっとしていた。", "target_word": "地上", "complexity_tier": "T2", "furigana": "巣[す]から落[お]ちたひなが、地上[ちじょう]でじっとしていた。", "sentence_source": "generated"}, {"text": "雪が降って、地上が真っ白になった。", "target_word": "地上", "complexity_tier": "T2", "furigana": "雪[ゆき]が降[ふ]って、地上[ちじょう]が真[ま]っ白[しろ]になった。", "sentence_source": "generated"}, {"text": "地上に落ちた葉を、子どもたちが集めて袋に入れた。", "target_word": "地上", "complexity_tier": "T3", "furigana": "地上[ちじょう]に落[お]ちた葉[は]を、子[こ]どもたちが集[あつ]めて袋[ふくろ]に入[い]れた。", "sentence_source": "generated"}, {"text": "洞窟の外に出ると、地上はまぶしいほど明るかった。", "target_word": "地上", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の外[そと]に出[で]ると、地上[ちじょう]はまぶしいほど明[あか]るかった。", "sentence_source": "generated"}, {"text": "ミミズは雨が降ると、地上に出てくることがある。", "target_word": "地上", "complexity_tier": "T3", "furigana": "ミミズは雨[あめ]が降[ふ]ると、地上[ちじょう]に出[で]てくることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地上", "label": "基本形"}], "register": "一般", "sense_fingerprint": "地下や高い所に対して、足で立つ地面の面。落ちた物や降りた先の場所。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53035, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鏡", "is_correct": false, "explanation": "鏡は物を映す道具。木から落ちた実が鏡でころころ転がるという文は意味が通らない。"}, {"text": "地上", "is_correct": true, "explanation": "木から落ちた実が足元の地面で転がっているという文意に合い、地面の上を指している。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文章を送る物。実が手紙でころころ転がっているという文は成り立たない。"}, {"text": "紙袋", "is_correct": false, "explanation": "紙袋は物を入れる袋。実が紙袋でころころ転がっているという文は合わない。"}], "explanations": {"鏡": "鏡は物を映す道具。木から落ちた実が鏡でころころ転がるという文は意味が通らない。", "地上": "木から落ちた実が足元の地面で転がっているという文意に合い、地面の上を指している。", "手紙": "手紙は文章を送る物。実が手紙でころころ転がっているという文は成り立たない。", "紙袋": "紙袋は物を入れる袋。実が紙袋でころころ転がっているという文は合わない。"}, "sentence_index": 0, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "池の地上に白鳥が浮かんでいる。", "explanation": "ここは〈水面〉（水の表面）の意味。〈地上〉は足の下の地面なので、池に浮かぶ白鳥の位置には合わない。"}, {"text": "漁船が地上を静かに進んでいく。", "explanation": "ここは〈水上〉（水の上）の意味。〈地上〉は足の下の地面なので、水の上を進む船には合わない。"}, {"text": "玄関の地上に写真がかけてある。", "explanation": "ここは〈壁〉の意味。〈地上〉は足の下の地面なので、写真をかける壁面の位置には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53035, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地下", "is_correct": false, "explanation": "地下は地面の下。雪が降って地下が真っ白になったという文は、地面の上を覆う様子として合わない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は部屋の名前。雪が降って教室が真っ白になったという文は意味が通らない。"}, {"text": "地上", "is_correct": true, "explanation": "雪が降って地面が真っ白になったという文意に合い、地面の表面を指している。"}, {"text": "屏風", "is_correct": false, "explanation": "屏風は部屋に置く仕切りの道具。雪が降って屏風が真っ白になったという文は成り立たない。"}], "explanations": {"地下": "地下は地面の下。雪が降って地下が真っ白になったという文は、地面の上を覆う様子として合わない。", "教室": "教室は部屋の名前。雪が降って教室が真っ白になったという文は意味が通らない。", "地上": "雪が降って地面が真っ白になったという文意に合い、地面の表面を指している。", "屏風": "屏風は部屋に置く仕切りの道具。雪が降って屏風が真っ白になったという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リスは地上の枝から枝へ飛び回っている。", "explanation": "ここは〈樹上〉（木の上）の意味。〈地上〉は足の下の地面なので、木の枝の位置には合わない。"}, {"text": "猫は屋根に登るように、地上に登って昼寝をする。", "explanation": "ここは〈屋上〉（建物の上の平らな所）の意味。〈地上〉は地面なので、猫が昼寝をする建物の上の場所には合わない。"}, {"text": "屋内の高いところ、地上にクモの巣が張っている。", "explanation": "ここは〈天井〉（部屋の上の面）の意味。〈地上〉は地面なので、部屋の上の面に張るクモの巣の位置には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53035, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "カエルは雨の夜になると、地上の出てくることがある。", "corrected_sentence": "カエルは雨の夜になると、地上に出てくることがある。", "error_description": "「出てくる」の前に「の」を置くと名詞句が切れ、文が成り立たない。「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53035, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜のあいだに雪が降り、地上な一面が真っ白になった。", "corrected_sentence": "夜のあいだに雪が降り、地上の一面が真っ白になった。", "error_description": "「地上」は名詞なので、名詞を修飾するときは「の」を使う。「な」は誤り。正しくは「地上の一面」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53036, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「地上の建物」で、建物がある場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "「地上が建物が」は主語が二つになり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「地上を建物が」は目的語の位置が合わず、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「地上へ建物」は方向を示すが、建物の位置を表す形にはならない。"}], "correct_answer": "の", "explanations": {"の": "「地上の建物」で、建物がある場所を表す。", "が": "「地上が建物が」は主語が二つになり、文が成り立たない。", "を": "「地上を建物が」は目的語の位置が合わず、意味が通らない。", "へ": "「地上へ建物」は方向を示すが、建物の位置を表す形にはならない。"}, "error_tags": {"が": "主語（〜が）", "を": "目的語（〜を）", "へ": "方向（〜へ）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53036, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53036, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面。大地。地球の表面。", "primary_collocate": null, "pronunciation": "ちじょう", "ipa": "tɕidʑoː", "syllable_count": 3, "sentences": [{"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "地上", "complexity_tier": "T4", "furigana": "すなわち、限[かぎ]られた特権[とっけん]階級[かいきゅう]のみに奉仕[ほうし]することを潔[いさぎよ]しとしない独占的[どくせんてき]な美学[びがく]こそが、地上[ちじょう]に降[お]り立[た]つトレンドの羅針盤[らしんばん]としての役割[やくわり]を担[にな]い、現代[げんだい]のファッション産業[さんぎょう]における生態系[せいたいけい]を永続的[えいぞくてき]に循環[じゅんかん]させているのである。", "sentence_source": "mined"}, {"text": "飛行機が高度を下げると、地上の建物が少しずつ大きく見えてきた。", "target_word": "地上", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が高度[こうど]を下[さ]げると、地上[ちじょう]の建物[たてもの]が少[すこ]しずつ大[おお]きく見[み]えてきた。", "sentence_source": "generated"}, {"text": "宇宙飛行士は半年ぶりに地上へ戻り、重力の重さに驚いた。", "target_word": "地上", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]飛行士[ひこうし]は半年[はんとし]ぶりに地上[ちじょう]へ戻[もど]り、重力[じゅうりょく]の重[おも]さに驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "地下は涼しいが、地上は真夏の太陽で焼けるように暑かった。", "target_word": "地上", "complexity_tier": "T3", "furigana": "地下[ちか]は涼[すず]しいが、地上[ちじょう]は真夏[まなつ]の太陽[たいよう]で焼[や]けるように暑[あつ]かった。", "sentence_source": "generated"}, {"text": "この鉄道は途中で地下から地上に出て、そのまま海沿いを走る。", "target_word": "地上", "complexity_tier": "T3", "furigana": "この鉄道[てつどう]は途中[とちゅう]で地下[ちか]から地上[ちじょう]に出[で]て、そのまま海沿[うみぞ]いを走[はし]る。", "sentence_source": "generated"}, {"text": "地上で生きる動物の中で、ゾウは最も体が大きい。", "target_word": "地上", "complexity_tier": "T3", "furigana": "地上[ちじょう]で生[い]きる動物[どうぶつ]の中[なか]で、ゾウは最[もっと]も体[からだ]が大[おお]きい。", "sentence_source": "generated"}, {"text": "ビルの屋上から見下ろすと、地上の人々が豆粒のように小さかった。", "target_word": "地上", "complexity_tier": "T3", "furigana": "ビルの屋上[おくじょう]から見下[みお]ろすと、地上[ちじょう]の人々[ひとびと]が豆粒[まめつぶ]のように小[ちい]さかった。", "sentence_source": "generated"}, {"text": "ロケットは炎を上げて地上を離れ、ゆっくり空へ昇っていった。", "target_word": "地上", "complexity_tier": "T3", "furigana": "ロケットは炎[ほのお]を上[あ]げて地上[ちじょう]を離[はな]れ、ゆっくり空[そら]へ昇[のぼ]っていった。", "sentence_source": "generated"}, {"text": "地上の水は太陽に温められて蒸発し、やがて雲になる。", "target_word": "地上", "complexity_tier": "T3", "furigana": "地上[ちじょう]の水[みず]は太陽[たいよう]に温[あたた]められて蒸発[じょうはつ]し、やがて雲[くも]になる。", "sentence_source": "generated"}, {"text": "山頂は霧に包まれていたが、地上は晴れていた。", "target_word": "地上", "complexity_tier": "T3", "furigana": "山頂[さんちょう]は霧[きり]に包[つつ]まれていたが、地上[ちじょう]は晴[は]れていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地上", "label": "基本形"}], "register": "一般", "sense_fingerprint": "地下・空・宇宙に対して、地球の表面の側。人や建物や動物がいる場所。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 潔し (Zipf 1.9)','sentence 6 above tier T2: contains vocabulary far above tier T2: 豆粒 (Zipf 2.17)']::text[], '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53036, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書類", "is_correct": false, "explanation": "書類は文書。トレンドが書類に降り立つという文は、降り立つ先として意味が通らない。"}, {"text": "海底", "is_correct": false, "explanation": "海底は海の底。トレンドが海底に降り立つという文は、降り立つ先として意味が通らない。"}, {"text": "水中", "is_correct": false, "explanation": "水中は水の中。トレンドが水中に降り立つという文は、降り立つ場所として合わない。"}, {"text": "地上", "is_correct": true, "explanation": "地面の上に降り立つという文意に合い、地球の表面を指す意味で使われている。"}], "explanations": {"書類": "書類は文書。トレンドが書類に降り立つという文は、降り立つ先として意味が通らない。", "海底": "海底は海の底。トレンドが海底に降り立つという文は、降り立つ先として意味が通らない。", "水中": "水中は水の中。トレンドが水中に降り立つという文は、降り立つ場所として合わない。", "地上": "地面の上に降り立つという文意に合い、地球の表面を指す意味で使われている。"}, "sentence_index": 0, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小舟が地上を静かに進んでいく。", "explanation": "ここは〈水上〉（水の上）の意味。〈地上〉は陸の地面を指すので、水の上を進む舟には合わない。"}, {"text": "真夜中の海で、潜水士は地上の珊瑚を観察した。", "explanation": "ここは〈海底〉（海の底）の意味。〈地上〉は陸の地面なので、海の底にある珊瑚の位置には使えない。"}, {"text": "旅客機が地上の雲の間を飛んでいる。", "explanation": "ここは〈上空〉（空の高い所）の意味。〈地上〉は地面なので、雲のある空の位置には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53036, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面。見下ろすと天井の人々が豆粒のように小さかったという文は意味を成さない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "押し入れは収納のための空間。見下ろすと押し入れの人々が小さかったという文は成り立たない。"}, {"text": "地上", "is_correct": true, "explanation": "屋上から見下ろしたときの地面にいる人々という文意に合い、地球の表面を指している。"}, {"text": "食器棚", "is_correct": false, "explanation": "食器棚は食器を収める家具。見下ろすと食器棚の人々が小さかったという文は意味が通らない。"}], "explanations": {"天井": "天井は部屋の上の面。見下ろすと天井の人々が豆粒のように小さかったという文は意味を成さない。", "押し入れ": "押し入れは収納のための空間。見下ろすと押し入れの人々が小さかったという文は成り立たない。", "地上": "屋上から見下ろしたときの地面にいる人々という文意に合い、地球の表面を指している。", "食器棚": "食器棚は食器を収める家具。見下ろすと食器棚の人々が小さかったという文は意味が通らない。"}, "sentence_index": 6, "correct_answer": "地上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猫は地上の瓦の上で昼寝をした。", "explanation": "ここは〈屋根〉の意味。〈地上〉は地面なので、猫が昼寝をする屋根の位置には合わない。"}, {"text": "居間の地上に絵がかけてある。", "explanation": "ここは〈壁〉の意味。〈地上〉は地面の表面なので、絵をかける壁面の位置には使えない。"}, {"text": "部屋の上の方、地上にクモの巣が張っている。", "explanation": "ここは〈天井〉（部屋の上の面）の意味。〈地上〉は地面なので、部屋の上の面に張るクモの巣の位置には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53036, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "探査機は三年の旅を終え、ついに地上を戻ってきた。", "corrected_sentence": "探査機は三年の旅を終え、ついに地上へ戻ってきた。", "error_description": "「戻る」は到着する先に「へ」を使う。「地上を戻る」は「を」で誤り。正しくは「地上へ戻ってきた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53036, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ヘリコプターは高度を下げ、ゆっくり地上に登った。", "corrected_sentence": "ヘリコプターは高度を下げ、ゆっくり地上に降りた。", "error_description": "高度を下げて地面に近づくときは「降りる」を使う。「登る」は上へ向かう動きで、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53037, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「庭に」は下り立つ着地点を示す到着の「に」で、文の意味に合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作が行われる場所を示すが、移動の着地点には使えないので不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は通過する対象を示すので、「庭を下り立った」は着地点として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すので、移動の着地点を表すことはできない。"}], "correct_answer": "に", "explanations": {"に": "「庭に」は下り立つ着地点を示す到着の「に」で、文の意味に合う。", "で": "「で」は動作が行われる場所を示すが、移動の着地点には使えないので不自然。", "を": "「を」は通過する対象を示すので、「庭を下り立った」は着地点として成り立たない。", "と": "「と」は相手や共同を示すので、移動の着地点を表すことはできない。"}, "error_tags": {"で": "動作の場所", "を": "移動の経路", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53037, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「岩場に」は降り立つ着地点を示す「に」で、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「岩場が下り立ち」では岩場が動作主になり意味が変わる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、動詞の前には置けない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すので、着地点を表すことはできない。"}], "correct_answer": "に", "explanations": {"に": "「岩場に」は降り立つ着地点を示す「に」で、文の意味に合う。", "が": "「が」は主語を示すので、「岩場が下り立ち」では岩場が動作主になり意味が変わる。", "の": "「の」は名詞どうしをつなぐもので、動詞の前には置けない。", "と": "「と」は相手や共同を示すので、着地点を表すことはできない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53037, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "高いところからおりて、たつこと。", "primary_collocate": null, "pronunciation": "おりたつ", "ipa": "oɾitat͡sɯ", "syllable_count": 4, "sentences": [{"text": "鳥が木の枝から地面に下り立った。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "鳥(とり)が木(き)の枝(えだ)から地面(じめん)に下(お)り立(た)った。", "sentence_source": "generated"}, {"text": "猫は塀の上から庭に下り立った。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "猫(ねこ)は塀(へい)の上(うえ)から庭(にわ)に下(お)り立(た)った。", "sentence_source": "generated"}, {"text": "隊員はロープで崖の上から谷底に下り立った。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "隊員(たいいん)はロープで崖(がけ)の上(うえ)から谷底(たにぞこ)に下(お)り立(た)った。", "sentence_source": "generated"}, {"text": "彼は高い塔の上から広場へ下り立ち、人々に手をふった。", "target_word": "下り立ち", "complexity_tier": "T3", "furigana": "彼(かれ)は高(たか)い塔(とう)の上(うえ)から広場(ひろば)へ下(お)り立(た)ち、人々(ひとびと)に手(て)をふった。", "sentence_source": "generated"}, {"text": "白い鳥が池のそばの岩に下り立つ。", "target_word": "下り立つ", "complexity_tier": "T3", "furigana": "白(しろ)い鳥(とり)が池(いけ)のそばの岩(いわ)に下(お)り立(た)つ。", "sentence_source": "generated"}, {"text": "空から舞い降りた天使が、野原に下り立ちました。", "target_word": "下り立ち", "complexity_tier": "T3", "furigana": "空(そら)から舞(ま)い降(お)りた天使(てんし)が、野原(のはら)に下(お)り立(た)ちました。", "sentence_source": "generated"}, {"text": "彼は馬から下り立って、水を飲ませた。", "target_word": "下り立って", "complexity_tier": "T3", "furigana": "彼(かれ)は馬(うま)から下(お)り立(た)って、水(みず)を飲(の)ませた。", "sentence_source": "generated"}, {"text": "鷹が岩場に下り立ち、じっと獲物を見ていた。", "target_word": "下り立ち", "complexity_tier": "T3", "furigana": "鷹(たか)が岩場(いわば)に下(お)り立(た)ち、じっと獲物(えもの)を見(み)ていた。", "sentence_source": "generated"}, {"text": "はしごを使って屋根から庭に下り立った。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "はしごを使(つか)って屋根(やね)から庭(にわ)に下(お)り立(た)った。", "sentence_source": "generated"}, {"text": "木のぼりが好きな弟は、高い枝から軽く下り立った。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "木(き)のぼりが好(す)きな弟(おとうと)は、高(たか)い枝(えだ)から軽(かる)く下(お)り立(た)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下り立つ", "label": "辞書形"}, {"form": "下り立たない", "label": "否定形"}, {"form": "下り立ち", "label": "連用形"}, {"form": "下り立った", "label": "過去形"}, {"form": "下り立って", "label": "て形"}, {"form": "下り立てば", "label": "仮定形"}], "register": "文章語", "sense_fingerprint": "高い所から降りて地面などに立つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53037, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下り立った", "is_correct": true, "explanation": "過去の完了を表す形で、鳥が地面に降りた動作を述べるので文末に合う。"}, {"text": "下り立ち", "is_correct": false, "explanation": "連用形は文を終える形ではなく、ここでは文が途切れて成り立たない。"}, {"text": "下り立て", "is_correct": false, "explanation": "命令形は三人称の鳥を主語にした平叙文には使えない。"}, {"text": "下り立てば", "is_correct": false, "explanation": "仮定形は「〜ば」で後ろに続ける形なので、文末の述語には置けない。"}], "explanations": {"下り立った": "過去の完了を表す形で、鳥が地面に降りた動作を述べるので文末に合う。", "下り立ち": "連用形は文を終える形ではなく、ここでは文が途切れて成り立たない。", "下り立て": "命令形は三人称の鳥を主語にした平叙文には使えない。", "下り立てば": "仮定形は「〜ば」で後ろに続ける形なので、文末の述語には置けない。"}, "sentence_index": 0, "correct_answer": "下り立った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨粒が屋根の端から下り立ち、地面をぬらした。", "explanation": "ここは〈落ちる〉の意味。下り立つは人や動物が自分で降りて立つ動作なので、雨粒には使えない。"}, {"text": "登山の末に、彼はついに山頂へ下り立った。", "explanation": "ここは〈登る〉の意味。下り立つは高い所から降りて地面に立つ動作なので、上にある山頂には使えない。"}, {"text": "先月から、牛乳の値段が下り立った。", "explanation": "ここは〈下がる〉の意味。下り立つは人や動物が自分で降りて立つ動作なので、値段には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53037, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下り立って", "is_correct": true, "explanation": "て形で、後ろの「水を飲ませた」へ続けられるので、ここに入る。"}, {"text": "下り立つ", "is_correct": false, "explanation": "辞書形は文を終える形で、読点の前には置けないので文が成り立たない。"}, {"text": "下り立たない", "is_correct": false, "explanation": "否定形は降りなかったという意味になり、馬から降りて水を飲ませた文脈と矛盾する。"}, {"text": "下り立った", "is_correct": false, "explanation": "過去形は文末で完結するので、読点で続けると文として成立しない。"}], "explanations": {"下り立って": "て形で、後ろの「水を飲ませた」へ続けられるので、ここに入る。", "下り立つ": "辞書形は文を終える形で、読点の前には置けないので文が成り立たない。", "下り立たない": "否定形は降りなかったという意味になり、馬から降りて水を飲ませた文脈と矛盾する。", "下り立った": "過去形は文末で完結するので、読点で続けると文として成立しない。"}, "sentence_index": 6, "correct_answer": "下り立って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "池の水面が静かに下り立ち、魚がおどろいた。", "explanation": "ここは〈沈む〉の意味。下り立つは人や動物が自分で降りて立つ動作なので、池の水面には使えない。"}, {"text": "かばんを下り立たせて、机の上に置いた。", "explanation": "「下り立つ」は自動詞で、物を地面に降ろすことはできない。物を降ろすには「下ろす」を使う。"}, {"text": "潜水艦が海面に下り立った。", "explanation": "ここは〈浮上する〉の意味。下り立つは高い所から地面に降りて立つ動作なので、海面へ浮かび上がる潜水艦には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53037, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猫が屋根から庭に下り立ちた。", "corrected_sentence": "猫が屋根から庭に下り立った。", "error_description": "「下り立つ」の過去形は「下り立った」で、「下り立ちた」は誤り。「下り立ち」は連用形なので、過去の「た」の前には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下り立った", "is_correct": true, "explanation": "過去形で、猫が庭に降り立った完了した動作を表すので文に合う。"}, {"text": "下り立ち", "is_correct": false, "explanation": "連用形は文末で過去の意味を表せず、文を完結させられない。"}, {"text": "下り立って", "is_correct": false, "explanation": "て形は後ろに続く文が必要で、ここでは述語として成り立たない。"}, {"text": "下り立てば", "is_correct": false, "explanation": "仮定形は条件を表すので、過去に起きた出来事を述べられない。"}], "correct_form": "下り立った", "base_form": "下り立つ", "form_label": "過去形", "sentence_index": 1, "explanations": {"下り立った": "過去形で、猫が庭に降り立った完了した動作を表すので文に合う。", "下り立ち": "連用形は文末で過去の意味を表せず、文を完結させられない。", "下り立って": "て形は後ろに続く文が必要で、ここでは述語として成り立たない。", "下り立てば": "仮定形は条件を表すので、過去に起きた出来事を述べられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53037, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は馬から下り立ったて、水を飲ませた。", "corrected_sentence": "父は馬から下り立って、水を飲ませた。", "error_description": "て形は「下り立って」で、「下り立ったて」は誤り。「った」は過去形で、て形の「って」とは区別する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下り立ち", "is_correct": true, "explanation": "連用形で、後ろの「じっと獲物を見ていた」へ続けられるので、ここに合う。"}, {"text": "下り立った", "is_correct": false, "explanation": "過去形は文を完結させるので、後ろに続けて「見ていた」とつなぐ位置には合わない。"}, {"text": "下り立つ", "is_correct": false, "explanation": "辞書形は文末の現在形で、後ろに続く文がある位置には入らない。"}, {"text": "下り立たない", "is_correct": false, "explanation": "否定形は降りないという意味になり、鷹が岩場に降り立った場面と合わない。"}], "correct_form": "下り立ち", "base_form": "下り立つ", "form_label": "連用形", "sentence_index": 7, "explanations": {"下り立ち": "連用形で、後ろの「じっと獲物を見ていた」へ続けられるので、ここに合う。", "下り立った": "過去形は文を完結させるので、後ろに続けて「見ていた」とつなぐ位置には合わない。", "下り立つ": "辞書形は文末の現在形で、後ろに続く文がある位置には入らない。", "下り立たない": "否定形は降りないという意味になり、鷹が岩場に降り立った場面と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53038, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「月面に」は下り立つ着地点を示す「に」で、文の意味に合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作が行われる場所を示すが、着地の到達点を表す「に」の代わりにはならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は通過する対象を示すので、「月面を下り立った」は着地点として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すので、着地点を表すことはできない。"}], "correct_answer": "に", "explanations": {"に": "「月面に」は下り立つ着地点を示す「に」で、文の意味に合う。", "で": "「で」は動作が行われる場所を示すが、着地の到達点を表す「に」の代わりにはならない。", "を": "「を」は通過する対象を示すので、「月面を下り立った」は着地点として成り立たない。", "と": "「と」は相手や共同を示すので、着地点を表すことはできない。"}, "error_tags": {"で": "動作の場所", "を": "対象", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53038, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「空港に」は降り立つ着地点を示す「に」で、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「空港が下り立ち」では空港が動作主になり意味が変わる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、動詞の前には置けない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示すので、着地点を表すことはできない。"}], "correct_answer": "に", "explanations": {"に": "「空港に」は降り立つ着地点を示す「に」で、文の意味に合う。", "が": "「が」は主語を示すので、「空港が下り立ち」では空港が動作主になり意味が変わる。", "の": "「の」は名詞どうしをつなぐもので、動詞の前には置けない。", "と": "「と」は相手や共同を示すので、着地点を表すことはできない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53038, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "乗り物や高い場所から降りて、地面に立つこと。また、比喩的に、新しい場所に現れること。", "primary_collocate": null, "pronunciation": "おりたつ", "ipa": "oɾitat͡sɯ", "syllable_count": 4, "sentences": [{"text": "飛行機から空港に下り立つと、暑い空気が体を包んだ。", "target_word": "下り立つ", "complexity_tier": "T3", "furigana": "飛行機(ひこうき)から空港(くうこう)に下(お)り立(た)つと、暑(あつ)い空気(くうき)が体(からだ)を包(つつ)んだ。", "sentence_source": "generated"}, {"text": "宇宙飛行士が月面に下り立った。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "宇宙飛行士(うちゅうひこうし)が月面(げつめん)に下(お)り立(た)った。", "sentence_source": "generated"}, {"text": "船から港に下り立った旅人は、道に迷った。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "船(ふね)から港(みなと)に下(お)り立(た)った旅人(たびびと)は、道(みち)に迷(まよ)った。", "sentence_source": "generated"}, {"text": "電車から駅のホームに下り立つと、雪が降っていた。", "target_word": "下り立つ", "complexity_tier": "T3", "furigana": "電車(でんしゃ)から駅(えき)のホームに下(お)り立(た)つと、雪(ゆき)が降(ふ)っていた。", "sentence_source": "generated"}, {"text": "初めてパリの地に下り立った日を忘れない。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "初(はじ)めてパリの地(ち)に下(お)り立(た)った日(ひ)を忘(わす)れない。", "sentence_source": "generated"}, {"text": "この町に初めて下り立った時、海の匂いがした。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "この町(まち)に初(はじ)めて下(お)り立(た)った時(とき)、海(うみ)の匂(にお)いがした。", "sentence_source": "generated"}, {"text": "バスから下り立った子どもたちが、元気に走り出した。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "バスから下(お)り立(た)った子(こ)どもたちが、元気(げんき)に走(はし)り出(だ)した。", "sentence_source": "generated"}, {"text": "大統領専用機が空港に下り立ち、出迎えの人々が集まった。", "target_word": "下り立ち", "complexity_tier": "T3", "furigana": "大統領専用機(だいとうりょうせんようき)が空港(くうこう)に下(お)り立(た)ち、出迎(でむか)えの人々(ひとびと)が集(あつ)まった。", "sentence_source": "generated"}, {"text": "雨の中、タクシーから下り立つと、傘がなかった。", "target_word": "下り立つ", "complexity_tier": "T3", "furigana": "雨(あめ)の中(なか)、タクシーから下(お)り立(た)つと、傘(かさ)がなかった。", "sentence_source": "generated"}, {"text": "長い旅の末に、ついに目的地の駅へ下り立った。", "target_word": "下り立った", "complexity_tier": "T3", "furigana": "長(なが)い旅(たび)の末(すえ)に、ついに目的地(もくてきち)の駅(えき)へ下(お)り立(た)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下り立つ", "label": "辞書形"}, {"form": "下り立たない", "label": "否定形"}, {"form": "下り立ち", "label": "連用形"}, {"form": "下り立った", "label": "過去形"}, {"form": "下り立って", "label": "て形"}, {"form": "下り立てば", "label": "仮定形"}], "register": "文章語", "sense_fingerprint": "乗り物から降りて新しい土地に立つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53038, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下り立つ", "is_correct": true, "explanation": "辞書形に「と」を続けると「〜すると」の意味になり、飛行機から降りた時の場面に合う。"}, {"text": "下り立ち", "is_correct": false, "explanation": "連用形は「と」に続けられず、文が成り立たない。"}, {"text": "下り立って", "is_correct": false, "explanation": "て形は「と」に続かないので、この位置では不自然になる。"}, {"text": "下り立て", "is_correct": false, "explanation": "命令形は「と」に続けられず、平叙文の中にも入らない。"}], "explanations": {"下り立つ": "辞書形に「と」を続けると「〜すると」の意味になり、飛行機から降りた時の場面に合う。", "下り立ち": "連用形は「と」に続けられず、文が成り立たない。", "下り立って": "て形は「と」に続かないので、この位置では不自然になる。", "下り立て": "命令形は「と」に続けられず、平叙文の中にも入らない。"}, "sentence_index": 0, "correct_answer": "下り立つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋の蓋を開けると、湯気が下り立った。", "explanation": "ここは〈立ちのぼる〉の意味。下り立つは降りて地面に立つ動作なので、下から上へ昇る湯気には使えない。"}, {"text": "夜明けに、霧が港へ下り立った。", "explanation": "ここは〈立ちこめる〉の意味。下り立つは降りて地面に立つ人や乗り物の動作なので、霧が広がる場面には使えない。"}, {"text": "電車は駅に下り立ち、ドアが開いた。", "explanation": "ここは〈到着する〉の意味。下り立つは降りて地面に立つ人の動作なので、乗り物が着く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53038, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下り立った", "is_correct": true, "explanation": "過去の連体形で、後ろの「子どもたち」を修飾するので、バスから降りた子どもたちという意味に合う。"}, {"text": "下り立とう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「子どもたち」の前には置けない。"}, {"text": "下り立ちます", "is_correct": false, "explanation": "丁寧形は名詞を直接修飾できず、「子どもたち」へつながらない。"}, {"text": "下り立てば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「子どもたち」とつながらない。"}], "explanations": {"下り立った": "過去の連体形で、後ろの「子どもたち」を修飾するので、バスから降りた子どもたちという意味に合う。", "下り立とう": "意志形は名詞を修飾できず、「子どもたち」の前には置けない。", "下り立ちます": "丁寧形は名詞を直接修飾できず、「子どもたち」へつながらない。", "下り立てば": "仮定形は名詞を修飾できず、「子どもたち」とつながらない。"}, "sentence_index": 6, "correct_answer": "下り立った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は長い旅のあと、ついに地図の上に下り立った。", "explanation": "ここは〈たどり着く〉の意味。下り立つは乗り物や高所から地面に降りて立つ動作なので、地図の上には使えない。"}, {"text": "彼はかぜで熱が出て、ふとんに下り立った。", "explanation": "ここは「もぐり込む」の意味。下り立つは降りて地面に立つ動作なので、布団に潜る動作には使えない。"}, {"text": "彼は椅子から飛び上がって、天井に下り立った。", "explanation": "ここは〈登る〉の意味。下り立つは上から下へ降りる動作なので、上にある天井へ向かう文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53038, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父が縁側から庭に下り立つた。", "corrected_sentence": "祖父が縁側から庭に下り立った。", "error_description": "過去の「た」の前は促音の「っ」が必要で、「下り立つた」は誤り。正しくは「下り立った」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下り立った", "is_correct": true, "explanation": "過去形で、宇宙飛行士が月面に降り立った完了した動作を表すので文に合う。"}, {"text": "下り立ち", "is_correct": false, "explanation": "連用形は文末で過去の意味を表せず、文を完結させられない。"}, {"text": "下り立って", "is_correct": false, "explanation": "て形は後ろに続く文が必要で、ここでは述語として成り立たない。"}, {"text": "下り立てば", "is_correct": false, "explanation": "仮定形は条件を表すので、過去の出来事を述べることはできない。"}], "correct_form": "下り立った", "base_form": "下り立つ", "form_label": "過去形", "sentence_index": 1, "explanations": {"下り立った": "過去形で、宇宙飛行士が月面に降り立った完了した動作を表すので文に合う。", "下り立ち": "連用形は文末で過去の意味を表せず、文を完結させられない。", "下り立って": "て形は後ろに続く文が必要で、ここでは述語として成り立たない。", "下り立てば": "仮定形は条件を表すので、過去の出来事を述べることはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53038, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄はバスから下り立ったて、道に迷った。", "corrected_sentence": "兄はバスから下り立って、道に迷った。", "error_description": "て形は「下り立って」で、「下り立ったて」は誤り。過去形の「った」とは区別する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下り立ち", "is_correct": true, "explanation": "連用形で、後ろの「出迎えの人々が集まった」へ続けられるので、ここに合う。"}, {"text": "下り立った", "is_correct": false, "explanation": "過去形は文を完結させるので、後ろに続けて文をつなぐ位置には合わない。"}, {"text": "下り立つ", "is_correct": false, "explanation": "辞書形は文末の現在形で、後ろに続く文がある位置には入らない。"}, {"text": "下り立たない", "is_correct": false, "explanation": "否定形は降りないという意味になり、専用機が空港に降り立った場面と矛盾する。"}], "correct_form": "下り立ち", "base_form": "下り立つ", "form_label": "連用形", "sentence_index": 7, "explanations": {"下り立ち": "連用形で、後ろの「出迎えの人々が集まった」へ続けられるので、ここに合う。", "下り立った": "過去形は文を完結させるので、後ろに続けて文をつなぐ位置には合わない。", "下り立つ": "辞書形は文末の現在形で、後ろに続く文がある位置には入らない。", "下り立たない": "否定形は降りないという意味になり、専用機が空港に降り立った場面と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
