INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53039, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをしようとする理由や目的を表す言葉です。", "primary_collocate": null, "pronunciation": "ため", "ipa": "tame", "syllable_count": 2, "sentences": [{"text": "体力をつけるため、毎朝三十分ほど歩くことにしている。", "target_word": "ため", "complexity_tier": "T3", "furigana": "体力[たいりょく]をつけるため、毎朝[まいあさ]三十分[さんじゅっぷん]ほど歩[ある]くことにしている。", "sentence_source": "generated"}, {"text": "雨が降ったため、運動会は来週に延期された。", "target_word": "ため", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったため、運動会[うんどうかい]は来週[らいしゅう]に延期[えんき]された。", "sentence_source": "generated"}, {"text": "友達に会うため、私は朝早い電車に乗った。", "target_word": "ため", "complexity_tier": "T3", "furigana": "友達[ともだち]に会[あ]うため、私[わたし]は朝早[あさはや]い電車[でんしゃ]に乗[の]った。", "sentence_source": "generated"}, {"text": "大雪のため、新幹線は二時間も遅れて駅に着いた。", "target_word": "ため", "complexity_tier": "T3", "furigana": "大雪[おおゆき]のため、新幹線[しんかんせん]は二時間[にじかん]も遅[おく]れて駅[えき]に着[つ]いた。", "sentence_source": "generated"}, {"text": "試験に合格するため、彼は毎晩遅くまで勉強している。", "target_word": "ため", "complexity_tier": "T3", "furigana": "試験[しけん]に合格[ごうかく]するため、彼[かれ]は毎晩[まいばん]遅[おそ]くまで勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "風邪をひいたため、今日は学校を休んだ。", "target_word": "ため", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいたため、今日[きょう]は学校[がっこう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "家族を養うため、父は毎日遠くの工場まで働きに行く。", "target_word": "ため", "complexity_tier": "T3", "furigana": "家族[かぞく]を養[やしな]うため、父[ちち]は毎日[まいにち]遠[とお]くの工場[こうじょう]まで働[はたら]きに行[い]く。", "sentence_source": "generated"}, {"text": "事故があったため、この道路は朝から通れなくなっている。", "target_word": "ため", "complexity_tier": "T3", "furigana": "事故[じこ]があったため、この道路[どうろ]は朝[あさ]から通[とお]れなくなっている。", "sentence_source": "generated"}, {"text": "新しい自転車を買うため、姉はアルバイトを始めた。", "target_word": "ため", "complexity_tier": "T3", "furigana": "新[あたら]しい自転車[じてんしゃ]を買[か]うため、姉[あね]はアルバイトを始[はじ]めた。", "sentence_source": "generated"}, {"text": "工事のため、図書館は今月いっぱい閉まっている。", "target_word": "ため", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、図書館[としょかん]は今月[こんげつ]いっぱい閉[し]まっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ため", "label": "基本形"}, {"form": "ために", "label": "に格（目的）"}, {"form": "のため", "label": "名詞＋のため（理由）"}], "register": "中立", "sense_fingerprint": "目的（〜するために）や原因・理由（〜したため）を表す形式名詞。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53039, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ため", "is_correct": true, "explanation": "動詞の辞書形に続いて目的を表し、「体力をつけるために歩く」という文脈に合う。"}, {"text": "のため", "is_correct": false, "explanation": "「のため」は名詞に続く形なので、動詞「つける」の直後には置けない。"}, {"text": "ゆえに", "is_correct": false, "explanation": "「ゆえに」は名詞に続く語で、動詞の辞書形の後には続かない。"}, {"text": "ばかりに", "is_correct": false, "explanation": "「ばかりに」は『〜したせいで悪い結果になった』の意味になり、目的を述べる文に合わない。"}], "explanations": {"ため": "動詞の辞書形に続いて目的を表し、「体力をつけるために歩く」という文脈に合う。", "のため": "「のため」は名詞に続く形なので、動詞「つける」の直後には置けない。", "ゆえに": "「ゆえに」は名詞に続く語で、動詞の辞書形の後には続かない。", "ばかりに": "「ばかりに」は『〜したせいで悪い結果になった』の意味になり、目的を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "ため"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もし雨が降ったため、運動会は中止になる。", "explanation": "ここは〈もし〜たら〉（仮定）の意味。「ため」は実際に起きた事実の理由を述べる語なので、仮定の条件には使えない。"}, {"text": "学校ため、今日は休んだ。", "explanation": "名詞に続く「のため」は「の」が必要で、「学校ため」とは言えない。"}, {"text": "寒いため、窓を閉めてください。", "explanation": "ここは〈ので〉のように依頼の理由を述べる用法。「ため」は客観的な原因・目的を述べる語なので、依頼の根拠には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53039, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ため", "is_correct": true, "explanation": "動詞の辞書形に続いて目的を表し、「家族を養うために働く」という文脈に合う。"}, {"text": "ことに", "is_correct": false, "explanation": "「ことに」は後ろに「〜することになる」などの述語が必要で、ここでは目的を表す文にならない。"}, {"text": "ところを", "is_correct": false, "explanation": "「ところを」は『〜している最中に』という時間の意味になり、目的の文脈に合わない。"}, {"text": "ずに", "is_correct": false, "explanation": "「ずに」は動詞の未然形に続くので、辞書形「養う」に直接続くことはできない。"}], "explanations": {"ため": "動詞の辞書形に続いて目的を表し、「家族を養うために働く」という文脈に合う。", "ことに": "「ことに」は後ろに「〜することになる」などの述語が必要で、ここでは目的を表す文にならない。", "ところを": "「ところを」は『〜している最中に』という時間の意味になり、目的の文脈に合わない。", "ずに": "「ずに」は動詞の未然形に続くので、辞書形「養う」に直接続くことはできない。"}, "sentence_index": 6, "correct_answer": "ため"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "頑張ったため、合格できなかった。", "explanation": "ここは〈のに〉（逆接）の意味。「ため」は原因と結果を順接でつなぐ語なので、予想に反する結果には合わない。"}, {"text": "毎朝ジョギングするため、体力がついた。", "explanation": "ここは〈ことで〉（手段・結果）の意味。「ため」は目的を表すので、結果として生じた「体力がついた」とは合わない。"}, {"text": "嬉しいため、思わず涙が出た。", "explanation": "ここは〈て〉（感情の原因）の意味。「ため」は客観的な事情の理由を表す語なので、感情の原因には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53039, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試験に受かるのため、毎日二時間勉強している。", "corrected_sentence": "試験に受かるため、毎日二時間勉強している。", "error_description": "誤り：動詞の辞書形「受かる」の直後に「の」を入れている。正しくは「受かるため」と、辞書形に直接「ため」を続ける（「のため」は名詞に続く形）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53039, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもが熱を出したのため、今日は休んだ。", "corrected_sentence": "子どもが熱を出したため、今日は休んだ。", "error_description": "誤り：動詞「出した」の後に「の」を入れている。正しくは「出したため」と、過去形に直接「ため」を続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
