INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53040, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "動作や行為の目的・理由を示す名詞。", "primary_collocate": null, "pronunciation": "ため", "ipa": "tame", "syllable_count": 2, "sentences": [{"text": "子どもの成長を見守るため、母は仕事を減らした。", "target_word": "ため", "complexity_tier": "T3", "furigana": "子[こ]どもの成長[せいちょう]を見守[みまも]るため、母[はは]は仕事[しごと]を減[へ]らした。", "sentence_source": "generated"}, {"text": "強い風のため、沖の船はすべて港に戻った。", "target_word": "ため", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]のため、沖[おき]の船[ふね]はすべて港[みなと]に戻[もど]った。", "sentence_source": "generated"}, {"text": "日本語を話せるようになるため、彼女は毎日ラジオを聞く。", "target_word": "ため", "complexity_tier": "T3", "furigana": "日本語[にほんご]を話[はな]せるようになるため、彼女[かのじょ]は毎日[まいにち]ラジオを聞[き]く。", "sentence_source": "generated"}, {"text": "停電のため、店の中は昼なのに暗かった。", "target_word": "ため", "complexity_tier": "T3", "furigana": "停電[ていでん]のため、店[みせ]の中[なか]は昼[ひる]なのに暗[くら]かった。", "sentence_source": "generated"}, {"text": "町の人々を喜ばせるため、市長は新しい公園を作った。", "target_word": "ため", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]を喜[よろこ]ばせるため、市長[しちょう]は新[あたら]しい公園[こうえん]を作[つく]った。", "sentence_source": "generated"}, {"text": "寝不足のため、午後の会議で何度もあくびが出た。", "target_word": "ため", "complexity_tier": "T3", "furigana": "寝不足[ねぶそく]のため、午後[ごご]の会議[かいぎ]で何度[なんど]もあくびが出[で]た。", "sentence_source": "generated"}, {"text": "夢をかなえるため、兄は故郷を出て東京へ向かった。", "target_word": "ため", "complexity_tier": "T3", "furigana": "夢[ゆめ]をかなえるため、兄[あに]は故郷[こきょう]を出[で]て東京[とうきょう]へ向[む]かった。", "sentence_source": "generated"}, {"text": "病気の祖母を見舞うため、私は毎週お粥を作って届けている。", "target_word": "ため", "complexity_tier": "T3", "furigana": "病気[びょうき]の祖母[そぼ]を見舞[みま]うため、私[わたし]は毎週[まいしゅう]お粥[かゆ]を作[つく]って届[とど]けている。", "sentence_source": "generated"}, {"text": "足をけがしたため、走る練習はしばらく休むことにした。", "target_word": "ため", "complexity_tier": "T3", "furigana": "足[あし]をけがしたため、走[はし]る練習[れんしゅう]はしばらく休[やす]むことにした。", "sentence_source": "generated"}, {"text": "虫を防ぐため、台所の窓に網戸を付けた。", "target_word": "ため", "complexity_tier": "T3", "furigana": "虫[むし]を防[ふせ]ぐため、台所[だいどころ]の窓[まど]に網戸[あみど]を付[つ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ため", "label": "基本形"}, {"form": "ために", "label": "に格（目的）"}, {"form": "のため", "label": "名詞＋のため（理由）"}], "register": "中立", "sense_fingerprint": "動作や行為の目的、またはその原因・理由を示す形式名詞。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: 見舞う (Zipf 2.28)','sentence 8 above tier T1: contains vocabulary far above tier T1: けがし (Zipf 2.18)']::text[], '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53040, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ため", "is_correct": true, "explanation": "動詞の辞書形に続いて目的を表し、「成長を見守るために仕事を減らす」という文脈に合う。"}, {"text": "のため", "is_correct": false, "explanation": "「のため」は名詞に続く形なので、動詞「見守る」の直後には置けない。"}, {"text": "ゆえに", "is_correct": false, "explanation": "「ゆえに」は名詞に続く語で、動詞の辞書形の後には続かない。"}, {"text": "ばかりに", "is_correct": false, "explanation": "「ばかりに」は『〜せいで悪い結果になった』の意味になり、目的を述べる文に合わない。"}], "explanations": {"ため": "動詞の辞書形に続いて目的を表し、「成長を見守るために仕事を減らす」という文脈に合う。", "のため": "「のため」は名詞に続く形なので、動詞「見守る」の直後には置けない。", "ゆえに": "「ゆえに」は名詞に続く語で、動詞の辞書形の後には続かない。", "ばかりに": "「ばかりに」は『〜せいで悪い結果になった』の意味になり、目的を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "ため"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もし大雪が降ったため、学校は休みになる。", "explanation": "ここは〈もし〜たら〉（仮定）の意味。「ため」は実際に起きた事実の理由を述べる語なので、仮定の条件には使えない。"}, {"text": "電車ため、今日は遅れた。", "explanation": "名詞に続く「のため」は「の」が必要で、「電車ため」とは言えない。"}, {"text": "暑いため、エアコンをつけてください。", "explanation": "ここは〈ので〉のように依頼の理由を述べる用法。「ため」は客観的な原因・目的を述べる語なので、依頼の根拠には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53040, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ため", "is_correct": true, "explanation": "動詞の辞書形に続いて目的を表し、「夢をかなえるために故郷を出る」という文脈に合う。"}, {"text": "ことに", "is_correct": false, "explanation": "「ことに」は後ろに述語が必要で、ここでは目的を表す文にならない。"}, {"text": "ところを", "is_correct": false, "explanation": "「ところを」は『〜している最中に』という時間の意味になり、目的の文脈に合わない。"}, {"text": "ずに", "is_correct": false, "explanation": "「ずに」は動詞の未然形に続くので、辞書形「かなえる」に直接続くことはできない。"}], "explanations": {"ため": "動詞の辞書形に続いて目的を表し、「夢をかなえるために故郷を出る」という文脈に合う。", "ことに": "「ことに」は後ろに述語が必要で、ここでは目的を表す文にならない。", "ところを": "「ところを」は『〜している最中に』という時間の意味になり、目的の文脈に合わない。", "ずに": "「ずに」は動詞の未然形に続くので、辞書形「かなえる」に直接続くことはできない。"}, "sentence_index": 6, "correct_answer": "ため"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "頑張ったため、合格できなかった。", "explanation": "ここは〈のに〉（逆接）の意味。「ため」は原因と結果を順接でつなぐ語なので、予想に反する結果には合わない。"}, {"text": "ゆっくり話すため、相手の理解が深まった。", "explanation": "ここは〈ことで〉（手段・結果）の意味。「ため」は目的を表すので、結果として生じた「理解が深まった」とは合わない。"}, {"text": "悲しいため、涙が出た。", "explanation": "ここは〈て〉（感情の原因）の意味。「ため」は客観的な事情の理由を表す語なので、感情の原因には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53040, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降ったのため、傘を持った。", "corrected_sentence": "雨が降ったため、傘を持った。", "error_description": "誤り：動詞「降った」の後に「の」を入れている。正しくは「降ったため」と、過去形に直接「ため」を続ける（「のため」は名詞に続く形）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53040, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お腹が痛いのため、病院へ行った。", "corrected_sentence": "お腹が痛いため、病院へ行った。", "error_description": "誤り：形容詞「痛い」の後に「の」を入れている。正しくは「痛いため」と、形容詞に直接「ため」を続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53049, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「治す」の対象である「けが」に続き、「けがを治す」となる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すので、他動詞「治す」の目的語には合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を示すので、「治す」の対象を表す位置には使えない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を示すので、「けがと治す」では対象関係が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「治す」の対象である「けが」に続き、「けがを治す」となる。", "が": "主語を示すので、他動詞「治す」の目的語には合わない。", "に": "相手や方向を示すので、「治す」の対象を表す位置には使えない。", "と": "並列や引用を示すので、「けがと治す」では対象関係が成り立たない。"}, "error_tags": {"が": "主語", "に": "相手", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53049, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「大きなけがを治す」と「けが」が治す対象になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すので、「治す」の目的語を表す位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すので、「けがで治す」では対象が示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を示すので、「けがと治す」では対象関係が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「大きなけがを治す」と「けが」が治す対象になる。", "が": "主語を示すので、「治す」の目的語を表す位置には合わない。", "で": "手段や場所を示すので、「けがで治す」では対象が示せない。", "と": "並列や引用を示すので、「けがと治す」では対象関係が成り立たない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53049, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "けがや病いをなおして、元気にすることです。", "primary_collocate": null, "pronunciation": "なおす", "ipa": "naosɯ", "syllable_count": 3, "sentences": [{"text": "医者は、ひどい熱を治すために薬を出した。", "target_word": "治す", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、ひどい熱[ねつ]を治[なお]すために薬[くすり]を出[だ]した。", "sentence_source": "generated"}, {"text": "足のけがを治して、またサッカーがしたい。", "target_word": "治して", "complexity_tier": "T3", "furigana": "足[あし]のけがを治[なお]して、またサッカーがしたい。", "sentence_source": "generated"}, {"text": "早く風邪を治すために、今日はもう寝る。", "target_word": "治す", "complexity_tier": "T3", "furigana": "早[はや]く風邪[かぜ]を治[なお]すために、今日[きょう]はもう寝[ね]る。", "sentence_source": "generated"}, {"text": "祖父は長い入院で病気を治して、家に帰ってきた。", "target_word": "治して", "complexity_tier": "T3", "furigana": "祖父[そふ]は長[なが]い入院[にゅういん]で病気[びょうき]を治[なお]して、家[いえ]に帰[かえ]ってきた。", "sentence_source": "generated"}, {"text": "虫歯を治しに、週末に歯医者へ行く。", "target_word": "治し", "complexity_tier": "T3", "furigana": "虫歯[むしば]を治[なお]しに、週末[しゅうまつ]に歯医者[はいしゃ]へ行[い]く。", "sentence_source": "generated"}, {"text": "この薬はおなかの痛みを治す効果がある。", "target_word": "治す", "complexity_tier": "T3", "furigana": "この薬[くすり]はおなかの痛[いた]みを治[なお]す効果[こうか]がある。", "sentence_source": "generated"}, {"text": "手のやけどを治すまで、水仕事はできない。", "target_word": "治す", "complexity_tier": "T3", "furigana": "手[て]のやけどを治[なお]すまで、水仕事[みずしごと]はできない。", "sentence_source": "generated"}, {"text": "彼女は大きなけがを治して、試合に戻った。", "target_word": "治して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大[おお]きなけがを治[なお]して、試合[しあい]に戻[もど]った。", "sentence_source": "generated"}, {"text": "けがを治したいなら、まず無理をしないことだ。", "target_word": "治したい", "complexity_tier": "T3", "furigana": "けがを治[なお]したいなら、まず無理[むり]をしないことだ。", "sentence_source": "generated"}, {"text": "母は私の熱を治すために、一晩中そばにいた。", "target_word": "治す", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の熱[ねつ]を治[なお]すために、一晩中[ひとばんじゅう]そばにいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "治した", "label": "過去形"}, {"form": "治して", "label": "て形"}, {"form": "治さない", "label": "否定形"}, {"form": "治せる", "label": "可能形"}, {"form": "治せば", "label": "仮定形"}], "register": "標準・常体", "sense_fingerprint": "けがや病気を手当てして元気な体にもどす（やさしい説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 水仕事 (Zipf 1.51)']::text[], '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53049, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治す", "is_correct": true, "explanation": "「ために」の前には辞書形が入るので、「熱を治すために」と自然につながる。"}, {"text": "治し", "is_correct": false, "explanation": "連用形のままでは「ために」に続かず、文が成り立たない。"}, {"text": "治る", "is_correct": false, "explanation": "自動詞なので「熱が治る」となり、「熱を」の形は取れない。"}, {"text": "治せ", "is_correct": false, "explanation": "命令形は「ために」の前に続かず、文が成り立たない。"}], "explanations": {"治す": "「ために」の前には辞書形が入るので、「熱を治すために」と自然につながる。", "治し": "連用形のままでは「ために」に続かず、文が成り立たない。", "治る": "自動詞なので「熱が治る」となり、「熱を」の形は取れない。", "治せ": "命令形は「ために」の前に続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "治す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "畑の土を治して、野菜の種をまいた。", "explanation": "ここは〈耕す〉の意味。治すは病気やけがをなおす意味で使い、土を耕す意味では使わない。"}, {"text": "パンの生地を治して、丁寧に焼いた。", "explanation": "ここは〈練る〉の意味。治すは病気やけがをなおす意味で使い、生地をこねる意味では使わない。"}, {"text": "破れた靴下を治して、そのまままた履いた。", "explanation": "ここは〈繕う〉の意味。治すは病気やけがに使うので、衣類の補修には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53049, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治す", "is_correct": true, "explanation": "「まで」の前には辞書形が入るので、「治すまで」と自然につながる。"}, {"text": "治した", "is_correct": false, "explanation": "過去形は「まで」の前に続かず、「治したまで」は不自然。"}, {"text": "治せ", "is_correct": false, "explanation": "命令形は「まで」の前に続かず、文が成り立たない。"}, {"text": "治そう", "is_correct": false, "explanation": "意向形は「まで」の前に続かず、「治そうまで」は成立しない。"}], "explanations": {"治す": "「まで」の前には辞書形が入るので、「治すまで」と自然につながる。", "治した": "過去形は「まで」の前に続かず、「治したまで」は不自然。", "治せ": "命令形は「まで」の前に続かず、文が成り立たない。", "治そう": "意向形は「まで」の前に続かず、「治そうまで」は成立しない。"}, "sentence_index": 6, "correct_answer": "治す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "曲がったネクタイを治して、出かけた。", "explanation": "ここは〈整える〉の意味。治すは病気やけがをなおす意味で使い、身なりを整える意味では使わない。"}, {"text": "国をよく治して、人々が安心して暮らせるようにした。", "explanation": "ここは〈治める〉の意味。治すは病気やけがに使い、国の統治には使わない。"}, {"text": "二人の仲を治して、また一緒に暮らし始めた。", "explanation": "ここは〈仲直りする〉の意味。治すは病気やけがに使い、人間関係には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53049, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "けがに治すために、しばらく練習を休むことにした。", "corrected_sentence": "けがを治すために、しばらく練習を休むことにした。", "error_description": "「治す」は目的語に「を」を取る他動詞。「けがに」の「に」は誤りで、正しくは「けがを」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "治して", "is_correct": true, "explanation": "「て形」で、「けがを治して、またサッカーがしたい」と文をつなぐ形。"}, {"text": "治せ", "is_correct": false, "explanation": "命令形は「治せ」と言い切る指示になり、「またサッカーがしたい」と続かない。"}, {"text": "治さない", "is_correct": false, "explanation": "否定形なので、「治せない」の意味になり文脈と逆になる。"}, {"text": "治せる", "is_correct": false, "explanation": "可能形で「治すことができる」の意味になり、文の内容とずれる。"}], "correct_form": "治して", "base_form": "治す", "form_label": "て形", "sentence_index": 1, "explanations": {"治して": "「て形」で、「けがを治して、またサッカーがしたい」と文をつなぐ形。", "治せ": "命令形は「治せ」と言い切る指示になり、「またサッカーがしたい」と続かない。", "治さない": "否定形なので、「治せない」の意味になり文脈と逆になる。", "治せる": "可能形で「治すことができる」の意味になり、文の内容とずれる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53049, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傷を治せまで、練習を休むことにした。", "corrected_sentence": "傷を治すまで、練習を休むことにした。", "error_description": "「まで」の前には辞書形「治す」が必要。「治せ」は命令形なので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "治して", "is_correct": true, "explanation": "「て形」で、「大きなけがを治して、試合に戻った」と前後をつなぐ形。"}, {"text": "治そう", "is_correct": false, "explanation": "意向形は「〜しよう」の意味になり、過去の出来事を述べる文に合わない。"}, {"text": "治せ", "is_correct": false, "explanation": "命令形は文末の強い指示になり、文の流れに合わない。"}, {"text": "治される", "is_correct": false, "explanation": "受身形は「治された」の意味になり、主語の行為と合わない。"}], "correct_form": "治して", "base_form": "治す", "form_label": "て形", "sentence_index": 7, "explanations": {"治して": "「て形」で、「大きなけがを治して、試合に戻った」と前後をつなぐ形。", "治そう": "意向形は「〜しよう」の意味になり、過去の出来事を述べる文に合わない。", "治せ": "命令形は文末の強い指示になり、文の流れに合わない。", "治される": "受身形は「治された」の意味になり、主語の行為と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53050, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53050, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「ひざのけがを治す」と「けが」が治す対象になる。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を示すので、「けがに治す」では対象関係が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すので、「けがで治す」は対象を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、「けがへ治す」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「ひざのけがを治す」と「けが」が治す対象になる。", "に": "相手や方向を示すので、「けがに治す」では対象関係が成り立たない。", "で": "手段を示すので、「けがで治す」は対象を示せず不自然。", "へ": "方向を示すので、「けがへ治す」は成り立たない。"}, "error_tags": {"に": "相手", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53050, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "病気やけがなどを治療して、健康な状態にすること。", "primary_collocate": null, "pronunciation": "なおす", "ipa": "naosɯ", "syllable_count": 3, "sentences": [{"text": "医師は点滴で患者の肺炎を治した。", "target_word": "治した", "complexity_tier": "T3", "furigana": "医師[いし]は点滴[てんてき]で患者[かんじゃ]の肺炎[はいえん]を治[なお]した。", "sentence_source": "generated"}, {"text": "長く続く慢性の病気は、簡単には治せない。", "target_word": "治せない", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]く慢性[まんせい]の病気[びょうき]は、簡単[かんたん]には治[なお]せない。", "sentence_source": "generated"}, {"text": "新しい治療法のおかげで、多くの患者が病気を治している。", "target_word": "治している", "complexity_tier": "T3", "furigana": "新[あたら]しい治療法[ちりょうほう]のおかげで、多[おお]くの患者[かんじゃ]が病気[びょうき]を治[なお]している。", "sentence_source": "generated"}, {"text": "歯科医は一週間で虫歯を治してくれた。", "target_word": "治して", "complexity_tier": "T3", "furigana": "歯科医[しかい]は一週間[いっしゅうかん]で虫歯[むしば]を治[なお]してくれた。", "sentence_source": "generated"}, {"text": "彼は病院に通って、腰の病気をしっかり治した。", "target_word": "治した", "complexity_tier": "T3", "furigana": "彼[かれ]は病院[びょういん]に通[かよ]って、腰[こし]の病気[びょうき]をしっかり治[なお]した。", "sentence_source": "generated"}, {"text": "この病院では、心の病気も治すために、長期の治療を行っている。", "target_word": "治す", "complexity_tier": "T3", "furigana": "この病院では、心の病気も治(なお)すために、長期の治療(ちりょう)を行(おこな)っている。", "sentence_source": "generated"}, {"text": "薬だけで病気を治そうとせず、生活も見直すべきだ。", "target_word": "治そう", "complexity_tier": "T3", "furigana": "薬[くすり]だけで病気[びょうき]を治[なお]そうとせず、生活[せいかつ]も見直[みなお]すべきだ。", "sentence_source": "generated"}, {"text": "ひざのけがを治すため、専門の医者に診てもらった。", "target_word": "治す", "complexity_tier": "T3", "furigana": "ひざのけがを治[なお]すため、専門[せんもん]の医者[いしゃ]に診[み]てもらった。", "sentence_source": "generated"}, {"text": "病気を治した後も、定期的な検査が必要だ。", "target_word": "治した", "complexity_tier": "T3", "furigana": "病気[びょうき]を治[なお]した後[あと]も、定期的[ていきてき]な検査[けんさ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "治療を続ければ、アレルギーを治せる可能性がある。", "target_word": "治せる", "complexity_tier": "T3", "furigana": "治療[ちりょう]を続[つづ]ければ、アレルギーを治[なお]せる可能性[かのうせい]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "治した", "label": "過去形"}, {"form": "治して", "label": "て形"}, {"form": "治さない", "label": "否定形"}, {"form": "治せる", "label": "可能形"}, {"form": "治せば", "label": "仮定形"}], "register": "標準・常体", "sense_fingerprint": "医療や治療によって病気やけがを健康な状態にもどす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53050, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治した", "is_correct": true, "explanation": "過去形で、点滴による治療の結果を表す文に自然に収まる。"}, {"text": "治し", "is_correct": false, "explanation": "連用形のままでは文末が成り立たず、文として完結しない。"}, {"text": "治さ", "is_correct": false, "explanation": "未然形のままでは文として成り立たない。"}, {"text": "治れ", "is_correct": false, "explanation": "自動詞「治る」は「肺炎を」の形を取れず、命令形にしても文が成り立たない。"}], "explanations": {"治した": "過去形で、点滴による治療の結果を表す文に自然に収まる。", "治し": "連用形のままでは文末が成り立たず、文として完結しない。", "治さ": "未然形のままでは文として成り立たない。", "治れ": "自動詞「治る」は「肺炎を」の形を取れず、命令形にしても文が成り立たない。"}, "sentence_index": 0, "correct_answer": "治した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "散らばった書類を治して、クリップで留めた。", "explanation": "ここは〈まとめる〉の意味。治すは病気やけがを治療する意味で使い、書類をまとめる意味では使わない。"}, {"text": "ケンカした仲を治して、ようやく話せた。", "explanation": "ここは〈仲直りする〉の意味。治すは病気やけがの治療に使い、人間関係には使わない。"}, {"text": "乱れた髪を治して、出かけた。", "explanation": "ここは〈整える〉の意味。治すは病気やけがの治療に使うので、身だしなみを整える意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53050, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治そう", "is_correct": true, "explanation": "意向形で「病気を治そうとせず」と、目的を持つ行動を表す形に続く。"}, {"text": "治し", "is_correct": false, "explanation": "連用形のままでは「〜とせず」に続かず、文が成り立たない。"}, {"text": "治せ", "is_correct": false, "explanation": "命令形は「〜とせず」に続かず、文の流れに合わない。"}, {"text": "治る", "is_correct": false, "explanation": "自動詞なので「病気が治る」となり、「病気を」の形は取れない。"}], "explanations": {"治そう": "意向形で「病気を治そうとせず」と、目的を持つ行動を表す形に続く。", "治し": "連用形のままでは「〜とせず」に続かず、文が成り立たない。", "治せ": "命令形は「〜とせず」に続かず、文の流れに合わない。", "治る": "自動詞なので「病気が治る」となり、「病気を」の形は取れない。"}, "sentence_index": 6, "correct_answer": "治そう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学で医学を治して、卒業した。", "explanation": "ここは〈修める〉の意味。治すは病気やけがを治療する意味で使い、学問を習得する意味では使わない。"}, {"text": "騒ぎを治して、みんなを落ち着かせた。", "explanation": "ここは〈鎮める〉の意味。治すは病気やけがの治療に使い、騒ぎを静める意味では使わない。"}, {"text": "昔の王は国を治して、人々に慕われた。", "explanation": "ここは〈治める〉の意味。治すは病気やけがの治療に使い、国の統治には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53050, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "点滴で肺炎に治して、退院した。", "corrected_sentence": "点滴で肺炎を治して、退院した。", "error_description": "「治す」の目的語には「を」が必要。「肺炎に」の「に」は誤りで、正しくは「肺炎を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "治せない", "is_correct": true, "explanation": "可能形の否定形で「簡単には治すことができない」の意味になり、文の内容に合う。"}, {"text": "治せる", "is_correct": false, "explanation": "可能形の肯定形は「治すことができる」となり、文の内容と逆になる。"}, {"text": "治して", "is_correct": false, "explanation": "「て形」は文末の否定や可能を表せず、「簡単には」の文に合わない。"}, {"text": "治した", "is_correct": false, "explanation": "過去形は完了を表すので、一般的な事実を述べる文に合わない。"}], "correct_form": "治せない", "base_form": "治す", "form_label": "可能形の否定形", "sentence_index": 1, "explanations": {"治せない": "可能形の否定形で「簡単には治すことができない」の意味になり、文の内容に合う。", "治せる": "可能形の肯定形は「治すことができる」となり、文の内容と逆になる。", "治して": "「て形」は文末の否定や可能を表せず、「簡単には」の文に合わない。", "治した": "過去形は完了を表すので、一般的な事実を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53050, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "点滴だけで病気を治そうせず、生活も見直すべきだ。", "corrected_sentence": "点滴だけで病気を治そうとせず、生活も見直すべきだ。", "error_description": "「治そうとせず」の形には「と」が必要。「治そうせず」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "治す", "is_correct": true, "explanation": "辞書形で「治すため」と目的を表す形に続き、文の流れに合う。"}, {"text": "治して", "is_correct": false, "explanation": "「て形」は「治して」と前後をつなぐ形で、「ため」の前には続かない。"}, {"text": "治せ", "is_correct": false, "explanation": "命令形は「ため」の前に続かず、文の流れに合わない。"}, {"text": "治そう", "is_correct": false, "explanation": "意向形は「治そうため」となり、「ため」の前に続かない。"}], "correct_form": "治す", "base_form": "治す", "form_label": "辞書形", "sentence_index": 7, "explanations": {"治す": "辞書形で「治すため」と目的を表す形に続き、文の流れに合う。", "治して": "「て形」は「治して」と前後をつなぐ形で、「ため」の前には続かない。", "治せ": "命令形は「ため」の前に続かず、文の流れに合わない。", "治そう": "意向形は「治そうため」となり、「ため」の前に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53051, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「母の手を」で引く対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、手が引く主体になると文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すが、ここでは引く対象の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、引く動作の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「母の手を」で引く対象を示す。正解。", "が": "「が」は主語を示すが、手が引く主体になると文が成り立たない。", "に": "「に」は相手や場所を示すが、ここでは引く対象の位置に合わない。", "へ": "「へ」は方向を示すが、引く動作の対象にはならない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "押す", "is_correct": true, "explanation": "人や物を向こうへ動かすという意味で、手前へ引くの対義語。"}, {"text": "切る", "is_correct": false, "explanation": "切る動作は、引く動作と対になる関係ではない。"}, {"text": "上げる", "is_correct": false, "explanation": "上げるは高い方向への動きで、手前へ引くの対義語ではない。"}, {"text": "結ぶ", "is_correct": false, "explanation": "結ぶ動作は、引く動作と対になる関係ではない。"}], "correct_answer": "押す", "explanations": {"押す": "人や物を向こうへ動かすという意味で、手前へ引くの対義語。", "切る": "切る動作は、引く動作と対になる関係ではない。", "上げる": "上げるは高い方向への動きで、手前へ引くの対義語ではない。", "結ぶ": "結ぶ動作は、引く動作と対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53051, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「手で」で手段を示し、手を使って引く意味になる。正解。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「手と引く」では何と何を並べるのか成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる基準を示すが、ここには比べる内容がなく文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「手から引く」は手を起点にする意味になり、手段を表す「手で」とは違う。"}], "correct_answer": "で", "explanations": {"で": "「手で」で手段を示し、手を使って引く意味になる。正解。", "と": "「と」は並列や相手を示すが、「手と引く」では何と何を並べるのか成り立たない。", "より": "「より」は比べる基準を示すが、ここには比べる内容がなく文が成り立たない。", "から": "「から」は起点を示すので、「手から引く」は手を起点にする意味になり、手段を表す「手で」とは違う。"}, "error_tags": {"と": "並列", "より": "比較", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "押す", "is_correct": true, "explanation": "物を向こうへ動かすという意味で、手前へ引くの対義語。"}, {"text": "結ぶ", "is_correct": false, "explanation": "結ぶ動作は、引く動作と対になる関係ではない。"}, {"text": "掴む", "is_correct": false, "explanation": "掴む動作は、引く動作と対になる関係ではない。"}, {"text": "下げる", "is_correct": false, "explanation": "下げるは低い方向への動きで、手前へ引くの対義語ではない。"}], "correct_answer": "押す", "explanations": {"押す": "物を向こうへ動かすという意味で、手前へ引くの対義語。", "結ぶ": "結ぶ動作は、引く動作と対になる関係ではない。", "掴む": "掴む動作は、引く動作と対になる関係ではない。", "下げる": "下げるは低い方向への動きで、手前へ引くの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53051, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手や腕を使って、ものをおしやるのではなく手前へ動かすことです。", "primary_collocate": null, "pronunciation": "ひく", "ipa": "çikɯ", "syllable_count": 2, "sentences": [{"text": "友達の腕を引くと、友達は笑ってこちらを向きました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "友達[ともだち]の腕[うで]を引[ひ]くと、友達[ともだち]は笑[わら]ってこちらを向[む]きました。", "sentence_source": "generated"}, {"text": "子供が母の手を引く姿を、店の前で見ました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "子供[こども]が母[はは]の手[て]を引[ひ]く姿[すがた]を、店[みせ]の前[まえ]で見[み]ました。", "sentence_source": "generated"}, {"text": "重い戸は、両腕で引くとやっと開きました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "重[おも]い戸[と]は、両腕[りょうて]で引[ひ]くとやっと開[あ]きました。", "sentence_source": "generated"}, {"text": "弟が私の袖を引くので、話を止めました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "弟[おとうと]が私[わたし]の袖[そで]を引[ひ]くので、話[はなし]を止[と]めました。", "sentence_source": "generated"}, {"text": "倒れそうな人の手を引く前に、足元を確かめました。", "target_word": "引く", "complexity_tier": "T4", "furigana": "倒[たお]れそうな人[ひと]の手[て]を引[ひ]く前[まえ]に、足元[あしもと]を確[たし]かめました。", "sentence_source": "generated"}, {"text": "手をぐっと引くと、体がこちらに近づいてきます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "手[て]をぐっと引[ひ]くと、体[からだ]がこちらに近[ちか]づいてきます。", "sentence_source": "generated"}, {"text": "泣いている子の腕を引く時は、強すぎないようにします。", "target_word": "引く", "complexity_tier": "T4", "furigana": "泣[な]いている子[こ]の腕[うで]を引[ひ]く時[とき]は、強[つよ]すぎないようにします。", "sentence_source": "generated"}, {"text": "座る前に、いすを少し手で引く習慣があります。", "target_word": "引く", "complexity_tier": "T3", "furigana": "座[すわ]る前[まえ]に、いすを少[すこ]し手[て]で引[ひ]く習慣[しゅうかん]があります。", "sentence_source": "generated"}, {"text": "ふとんの端を引くと、中の猫が出てきました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "ふとんの端[はし]を引[ひ]くと、中[なか]の猫[ねこ]が出[で]てきました。", "sentence_source": "generated"}, {"text": "ロープを両手で引くと、船が岸に寄ってきます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "ロープを両手[りょうて]で引[ひ]くと、船[ふね]が岸[きし]に寄[よ]ってきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引く", "label": "終止形"}, {"form": "引かない", "label": "否定形"}, {"form": "引きます", "label": "丁寧形"}, {"form": "引いた", "label": "過去形"}, {"form": "引いて", "label": "て形"}, {"form": "引けば", "label": "仮定形"}, {"form": "引こう", "label": "意向形"}, {"form": "引かれる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "手や腕の力で、物や人を押さずに自分の手前へ動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53051, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "友達の腕を手前へ引くという意味で、空欄に入る唯一の語。"}, {"text": "切る", "is_correct": false, "explanation": "友達の腕を切ると、笑ってこちらを向く文脈にならない。"}, {"text": "割る", "is_correct": false, "explanation": "腕を割るという動作は成り立たない。"}, {"text": "焼く", "is_correct": false, "explanation": "腕を焼くという動作は文脈に合わない。"}], "explanations": {"引く": "友達の腕を手前へ引くという意味で、空欄に入る唯一の語。", "切る": "友達の腕を切ると、笑ってこちらを向く文脈にならない。", "割る": "腕を割るという動作は成り立たない。", "焼く": "腕を焼くという動作は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子犬の頭を引いて、やさしく撫でました。", "explanation": "ここは〈撫でる〉の文。頭は撫でるもので、手前へ引く動作ではない。"}, {"text": "スーツの袖の埃を、手で引いて落としました。", "explanation": "ここは〈払う〉の文。埃は払うもので、引く動作では取れない。"}, {"text": "子供の背中を引いて、ブランコをこがせました。", "explanation": "ここは〈押す〉の文。背中を押してブランコを動かすので、引くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53051, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "泣いている子の腕を手前へ引くという意味で、空欄に入る唯一の語。"}, {"text": "干す", "is_correct": false, "explanation": "「干す」は洗濯物などを日にさらす動作で、子の腕には使えない。"}, {"text": "煮る", "is_correct": false, "explanation": "「煮る」は食材を湯で加熱する動作で、人の腕には合わない。"}, {"text": "砕く", "is_correct": false, "explanation": "「砕く」は硬い物を細かくする動作で、人の腕には使えない。"}], "explanations": {"引く": "泣いている子の腕を手前へ引くという意味で、空欄に入る唯一の語。", "干す": "「干す」は洗濯物などを日にさらす動作で、子の腕には使えない。", "煮る": "「煮る」は食材を湯で加熱する動作で、人の腕には合わない。", "砕く": "「砕く」は硬い物を細かくする動作で、人の腕には使えない。"}, "sentence_index": 6, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黒板の字を、黒板消しで引きました。", "explanation": "ここは〈消す〉の文。字は消すもので、引く動作ではない。"}, {"text": "友達が大きくボールを引いて、ゴールを決めました。", "explanation": "ここは〈蹴る〉の文。ボールを飛ばすのは蹴るで、引くとは言わない。"}, {"text": "会が終わると、先生はみんなに丁寧にお礼を引きました。", "explanation": "ここは〈述べる〉の文。お礼は述べるもので、引くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
