INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53052, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「引くと」で条件を示す。手前へ引けばドアが開くという意味になる。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「引くを」と続けると条件の文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「引くで」と続けると条件の文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、動詞の後に付けて条件を表すことはできない。"}], "correct_answer": "と", "explanations": {"と": "「引くと」で条件を示す。手前へ引けばドアが開くという意味になる。正解。", "を": "「を」は目的語を示すが、「引くを」と続けると条件の文が成り立たない。", "で": "「で」は手段や場所を示すが、「引くで」と続けると条件の文にならない。", "へ": "「へ」は方向を示すが、動詞の後に付けて条件を表すことはできない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "押す", "is_correct": true, "explanation": "物を向こうへ動かすという意味で、手前へ引くの対義語。"}, {"text": "結ぶ", "is_correct": false, "explanation": "物を結ぶ動作で、手前へ動かす動作の対義語ではない。"}, {"text": "切る", "is_correct": false, "explanation": "切る動作は、引く動作と対になる関係ではない。"}, {"text": "上げる", "is_correct": false, "explanation": "上げるは高い方向への動きで、手前へ引くの対義語ではない。"}], "correct_answer": "押す", "explanations": {"押す": "物を向こうへ動かすという意味で、手前へ引くの対義語。", "結ぶ": "物を結ぶ動作で、手前へ動かす動作の対義語ではない。", "切る": "切る動作は、引く動作と対になる関係ではない。", "上げる": "上げるは高い方向への動きで、手前へ引くの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53052, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「網を」で引く対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、網が引く主体になると文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や場所を示すが、ここでは網の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、引く動作の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「網を」で引く対象を示す。正解。", "が": "「が」は主語を示すが、網が引く主体になると文が成り立たない。", "に": "「に」は方向や場所を示すが、ここでは網の位置に合わない。", "へ": "「へ」は方向を示すが、引く動作の対象にはならない。"}, "error_tags": {"が": "主語", "に": "場所", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "押す", "is_correct": true, "explanation": "物を向こうへ動かすという意味で、手前へ引くの対義語。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「運ぶ」は物を別の場所へ移すことで、向こうへ動かす押すの反対語ではない。"}, {"text": "掴む", "is_correct": false, "explanation": "「掴む」は手でしっかり握ることで、手前へ動かす引くの対義語ではない。"}, {"text": "乗せる", "is_correct": false, "explanation": "「乗せる」は物を上に置くことで、押す・引くと対になる関係ではない。"}], "correct_answer": "押す", "explanations": {"押す": "物を向こうへ動かすという意味で、手前へ引くの対義語。", "運ぶ": "「運ぶ」は物を別の場所へ移すことで、向こうへ動かす押すの反対語ではない。", "掴む": "「掴む」は手でしっかり握ることで、手前へ動かす引くの対義語ではない。", "乗せる": "「乗せる」は物を上に置くことで、押す・引くと対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53052, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手や道具などを使って、物体をおしやるのではなく手前へ動かすこと。", "primary_collocate": null, "pronunciation": "ひく", "ipa": "çikɯ", "syllable_count": 2, "sentences": [{"text": "長い紐を引くと、馬は元気に走ります。", "target_word": "引く", "complexity_tier": "T3", "furigana": "長[なが]い紐[ひも]を引[ひ]くと、馬[うま]は元気[げんき]に走[はし]ります。", "sentence_source": "mined"}, {"text": "このドアは押さずに、手前に引くと開きます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "このドアは押[お]さずに、手前[てまえ]に引[ひ]くと開[あ]きます。", "sentence_source": "generated"}, {"text": "この引き出しは、取っ手を引くと静かに開きます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "この引[ひ]き出[だ]しは、取[と]っ手[て]を引[ひ]くと静[しず]かに開[あ]きます。", "sentence_source": "generated"}, {"text": "釣りざおを引くと、大きな魚が水から上がってきました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "釣[つ]りざおを引[ひ]くと、大[おお]きな魚[さかな]が水[みず]から上[あ]がってきました。", "sentence_source": "generated"}, {"text": "長い棒のフックで枝を引くと、高い所の実が手元に来ます。", "target_word": "引く", "complexity_tier": "T4", "furigana": "長[なが]い棒[ぼう]のフックで枝[えだ]を引[ひ]くと、高[たか]い所[ところ]の実[み]が手元[てもと]に来[き]ます。", "sentence_source": "generated"}, {"text": "机の下の箱は、重いので両手で引く必要があります。", "target_word": "引く", "complexity_tier": "T3", "furigana": "机[つくえ]の下[した]の箱[はこ]は、重[おも]いので両手[りょうて]で引[ひ]く必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "ばねの端を手で引くと、ゆっくり伸びていきます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "ばねの端[はし]を手[て]で引[ひ]くと、ゆっくり伸[の]びていきます。", "sentence_source": "generated"}, {"text": "網を引くと、中に小さな魚がたくさん入っていました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "網[あみ]を引[ひ]くと、中[なか]に小[ちい]さな魚[さかな]がたくさん入[はい]っていました。", "sentence_source": "generated"}, {"text": "スーツケースの持ち手を引く音が、朝の駅に響いています。", "target_word": "引く", "complexity_tier": "T4", "furigana": "スーツケースの持[も]ち手[て]を引[ひ]く音[おと]が、朝[あさ]の駅[えき]に響[ひび]いています。", "sentence_source": "generated"}, {"text": "そりを引くと、雪の上でもゆっくり進みます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "そりを引[ひ]くと、雪[ゆき]の上[うえ]でもゆっくり進[すす]みます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引く", "label": "終止形"}, {"form": "引かない", "label": "否定形"}, {"form": "引きます", "label": "丁寧形"}, {"form": "引いた", "label": "過去形"}, {"form": "引いて", "label": "て形"}, {"form": "引けば", "label": "仮定形"}, {"form": "引こう", "label": "意向形"}, {"form": "引かれる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "手や道具を使って、物を押さずに手前へ動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ざお (Zipf 2.14)']::text[], '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53052, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "長い紐を手前へ引くという動作に合う唯一の語。"}, {"text": "割る", "is_correct": false, "explanation": "紐を割るという動作は成り立たず、文が意味をなさない。"}, {"text": "焼く", "is_correct": false, "explanation": "紐を焼くという動作は文脈に合わない。"}, {"text": "砕く", "is_correct": false, "explanation": "紐を砕くという動作は成り立たない。"}], "explanations": {"引く": "長い紐を手前へ引くという動作に合う唯一の語。", "割る": "紐を割るという動作は成り立たず、文が意味をなさない。", "焼く": "紐を焼くという動作は文脈に合わない。", "砕く": "紐を砕くという動作は成り立たない。"}, "sentence_index": 0, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園の景色を、鉛筆で絵を引きました。", "explanation": "ここは〈描く〉の文。絵は描くもので、引くとは言わない。"}, {"text": "ケーキを引いて、みんなに配りました。", "explanation": "ここは〈切る〉の文。ケーキは切るもので、引く動作では分けられない。"}, {"text": "エレベーターのボタンを引いて、呼びました。", "explanation": "ここは〈押す〉の文。ボタンは押すもので、引くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53052, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "ばねの端を手で手前に引くという意味で、空欄に入る唯一の語。"}, {"text": "磨く", "is_correct": false, "explanation": "ばねを磨く動作は、伸びていく文脈に合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "洗う動作で、ばねの端が伸びていく流れに合わない。"}, {"text": "注ぐ", "is_correct": false, "explanation": "液体を流し入れる動作で、ばねの端には使えない。"}], "explanations": {"引く": "ばねの端を手で手前に引くという意味で、空欄に入る唯一の語。", "磨く": "ばねを磨く動作は、伸びていく文脈に合わない。", "洗う": "洗う動作で、ばねの端が伸びていく流れに合わない。", "注ぐ": "液体を流し入れる動作で、ばねの端には使えない。"}, "sentence_index": 6, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓を引いて、きれいにしました。", "explanation": "ここは〈拭く〉の文。窓は拭くもので、引く動作ではない。"}, {"text": "朝、お皿を引いて、洗いました。", "explanation": "ここは〈洗う〉の文。皿は洗うもので、引く動作ではない。"}, {"text": "ボールを引いて、遠くまで飛ばしました。", "explanation": "ここは〈蹴る〉の文。ボールを飛ばすのは蹴るで、引くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
