INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53052, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い木箱の蓋を手前に引かて、中身を確かめました。", "corrected_sentence": "古い木箱の蓋を手前に引いて、中身を確かめました。", "error_description": "誤りは「引かて」。「引く」のて形は「引いて」で、「引かて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引く", "is_correct": true, "explanation": "「引くと」の前は終止形。条件を表す文脈に合う正しい形。"}, {"text": "引き", "is_correct": false, "explanation": "連用形で、条件の「と」の前には続かない。"}, {"text": "引け", "is_correct": false, "explanation": "命令形で、条件の「と」の前には続かない。"}, {"text": "引いたり", "is_correct": false, "explanation": "並列の形で、条件の「と」に続けると文が成り立たない。"}], "correct_form": "引く", "base_form": "引く", "form_label": "終止形", "sentence_index": 7, "explanations": {"引く": "「引くと」の前は終止形。条件を表す文脈に合う正しい形。", "引き": "連用形で、条件の「と」の前には続かない。", "引け": "命令形で、条件の「と」の前には続かない。", "引いたり": "並列の形で、条件の「と」に続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
