INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53053, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "はやく動きます。じかんをあまりかけません。", "primary_collocate": null, "pronunciation": "はやい", "ipa": "hajai", "syllable_count": 3, "sentences": [{"text": "兄は自転車に乗るのが速いです。", "target_word": "速い", "complexity_tier": "T2", "furigana": "兄[あに]は自転車[じてんしゃ]に乗[の]るのが速[はや]いです。", "sentence_source": "generated"}, {"text": "この電車は速いので、三十分で着きます。", "target_word": "速い", "complexity_tier": "T2", "furigana": "この電車[でんしゃ]は速[はや]いので、三十分[さんじっぷん]で着[つ]きます。", "sentence_source": "generated"}, {"text": "速く歩かないと、バスに間に合いません。", "target_word": "速く", "complexity_tier": "T2", "furigana": "速[はや]く歩[ある]かないと、バスに間[ま]に合[あ]いません。", "sentence_source": "generated"}, {"text": "犬は人間より走るのが速いです。", "target_word": "速い", "complexity_tier": "T2", "furigana": "犬[いぬ]は人間[にんげん]より走[はし]るのが速[はや]いです。", "sentence_source": "generated"}, {"text": "ゆっくり話す人も、速く話す人もいます。", "target_word": "速く", "complexity_tier": "T2", "furigana": "ゆっくり話[はな]す人[ひと]も、速[はや]く話[はな]す人[ひと]もいます。", "sentence_source": "generated"}, {"text": "あの車は速くて、すぐ見えなくなりました。", "target_word": "速く", "complexity_tier": "T2", "furigana": "あの車[くるま]は速[はや]くて、すぐ見[み]えなくなりました。", "sentence_source": "generated"}, {"text": "私は泳ぐのが速くないので、毎日練習しています。", "target_word": "速く", "complexity_tier": "T3", "furigana": "私[わたし]は泳[およ]ぐのが速[はや]くないので、毎日[まいにち]練習[れんしゅう]しています。", "sentence_source": "generated"}, {"text": "鳥は飛ぶのが速いので、写真を撮るのが難しいです。", "target_word": "速い", "complexity_tier": "T3", "furigana": "鳥[とり]は飛[と]ぶのが速[はや]いので、写真[しゃしん]を撮[と]るのが難[むずか]しいです。", "sentence_source": "generated"}, {"text": "速い電車に乗ったから、約束の時間に間に合いました。", "target_word": "速い", "complexity_tier": "T3", "furigana": "速[はや]い電車[でんしゃ]に乗[の]ったから、約束[やくそく]の時間[じかん]に間[ま]に合[あ]いました。", "sentence_source": "generated"}, {"text": "水の流れが速いところには、近づかないでください。", "target_word": "速い", "complexity_tier": "T3", "furigana": "水[みず]の流[なが]れが速[はや]いところには、近[ちか]づかないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "速い", "label": "終止形"}, {"form": "速く", "label": "連用形"}, {"form": "速かった", "label": "過去形"}, {"form": "速くない", "label": "否定形"}, {"form": "速ければ", "label": "仮定形"}, {"form": "速くて", "label": "て形"}], "register": "neutral", "sense_fingerprint": "ゆっくりでなく、短い時間で動く（初級向けの「速い」）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53053, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速い", "is_correct": true, "explanation": "乗る速さを表し、「乗るのが速い」と続く形で、ここに合う"}, {"text": "深い", "is_correct": false, "explanation": "奥行きが大きい意味。乗る速さの説明には合わない"}, {"text": "広い", "is_correct": false, "explanation": "面積が大きい意味。乗る動作の様子には当てはまらない"}, {"text": "黒い", "is_correct": false, "explanation": "色の意味で、動作の様子とは合わない"}], "explanations": {"速い": "乗る速さを表し、「乗るのが速い」と続く形で、ここに合う", "深い": "奥行きが大きい意味。乗る速さの説明には合わない", "広い": "面積が大きい意味。乗る動作の様子には当てはまらない", "黒い": "色の意味で、動作の様子とは合わない"}, "sentence_index": 0, "correct_answer": "速い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今朝は速いので、コートを着て出かけました。", "explanation": "気温の話に「速い」は使わないので合わない。"}, {"text": "部屋が速いので、家族みんなで使えます。", "explanation": "部屋の広さに「速い」は使わないので合わない。"}, {"text": "このパンは速いので、スープに浸して食べます。", "explanation": "パンの固さに「速い」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53053, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。「泳ぐのが速くない」の「速く」の部分で、否定の「ない」に続く形"}, {"text": "厚く", "is_correct": false, "explanation": "厚さを表す意味。泳ぐ様子とは合わない"}, {"text": "固く", "is_correct": false, "explanation": "固さを表す意味で、泳ぐ速さの話にならない"}, {"text": "軽く", "is_correct": false, "explanation": "重さの反対の意味。泳ぐ様子の説明にならない"}], "explanations": {"速く": "連用形。「泳ぐのが速くない」の「速く」の部分で、否定の「ない」に続く形", "厚く": "厚さを表す意味。泳ぐ様子とは合わない", "固く": "固さを表す意味で、泳ぐ速さの話にならない", "軽く": "重さの反対の意味。泳ぐ様子の説明にならない"}, "sentence_index": 6, "correct_answer": "速く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スープが速いので、水で薄めました。", "explanation": "スープの濃さに「速い」は使わないので合わない。"}, {"text": "この本は速いので、持ち歩くのが大変です。", "explanation": "本の厚みに「速い」は使わないので合わない。"}, {"text": "池は速いので、子どもだけで入ってはいけません。", "explanation": "池の深さに「速い」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53053, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は足が速くので、リレーの選手に選ばれました。", "corrected_sentence": "彼は足が速いので、リレーの選手に選ばれました。", "error_description": "活用の誤り。形容詞「速い」は「ので」の前で「速いので」と続けるので、「速くので」は誤り", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "速い", "is_correct": true, "explanation": "終止形。「速いので」と理由を続ける形で、ここに合う"}, {"text": "速く", "is_correct": false, "explanation": "連用形。言い切れず「速くので」と続かないので、文が成り立たない"}, {"text": "速そう", "is_correct": false, "explanation": "様子の推量の形で、「速そうので」と理由の文に続かない。"}, {"text": "速ければ", "is_correct": false, "explanation": "仮定形。条件を表すので、理由を述べる「速いので」の文と合わない"}], "correct_form": "速い", "base_form": "速い", "form_label": "終止形", "sentence_index": 1, "explanations": {"速い": "終止形。「速いので」と理由を続ける形で、ここに合う", "速く": "連用形。言い切れず「速くので」と続かないので、文が成り立たない", "速そう": "様子の推量の形で、「速そうので」と理由の文に続かない。", "速ければ": "仮定形。条件を表すので、理由を述べる「速いので」の文と合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53053, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の上は風を速いので、登山は午前中に終えましょう。", "corrected_sentence": "山の上は風が速いので、登山は午前中に終えましょう。", "error_description": "助詞の誤り。「速い」の主語は「が」で示すので、「を」は誤り", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "速い", "is_correct": true, "explanation": "終止形。「速いので」と理由を続ける形で、飛ぶ速さの説明に合う"}, {"text": "速くて", "is_correct": false, "explanation": "て形で、理由を述べる「ので」の前には続かない。"}, {"text": "速いだろう", "is_correct": false, "explanation": "推量の形で、「ので」の前には続かず理由の文が成り立たない。"}, {"text": "速かろう", "is_correct": false, "explanation": "文語の推量形で、「ので」の前には続かない。"}], "correct_form": "速い", "base_form": "速い", "form_label": "終止形", "sentence_index": 7, "explanations": {"速い": "終止形。「速いので」と理由を続ける形で、飛ぶ速さの説明に合う", "速くて": "て形で、理由を述べる「ので」の前には続かない。", "速いだろう": "推量の形で、「ので」の前には続かず理由の文が成り立たない。", "速かろう": "文語の推量形で、「ので」の前には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53054, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "速さが反対の意味で、辞書でも対義語として並ぶ"}, {"text": "軽い", "is_correct": false, "explanation": "重さの反対の意味で、速さの対義語ではない"}, {"text": "高い", "is_correct": false, "explanation": "値段や位置の高さの反対で、速さの対義語ではない"}, {"text": "浅い", "is_correct": false, "explanation": "深さの反対の意味で、速さとは関係ない"}], "correct_answer": "遅い", "explanations": {"遅い": "速さが反対の意味で、辞書でも対義語として並ぶ", "軽い": "重さの反対の意味で、速さの対義語ではない", "高い": "値段や位置の高さの反対で、速さの対義語ではない", "浅い": "深さの反対の意味で、速さとは関係ない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
