INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53054, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "時間のかかることなく、すぐに終わること。また、移動や作業のスピードが高いこと。", "primary_collocate": null, "pronunciation": "はやい", "ipa": "hajai", "syllable_count": 3, "sentences": [{"text": "新幹線は車よりずっと速いので、東京まで二時間で着きます。", "target_word": "速い", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]は車[くるま]よりずっと速[はや]いので、東京[とうきょう]まで二時間[にじかん]で着[つ]きます。", "sentence_source": "generated"}, {"text": "弟は走るのが速くて、いつも運動会で一番になる。", "target_word": "速く", "complexity_tier": "T3", "furigana": "弟[おとうと]は走[はし]るのが速[はや]くて、いつも運動会[うんどうかい]で一番[いちばん]になる。", "sentence_source": "generated"}, {"text": "この店は料理が出てくるのが速いので、昼休みでも安心です。", "target_word": "速い", "complexity_tier": "T3", "furigana": "この店[みせ]は料理[りょうり]が出[で]てくるのが速[はや]いので、昼休[ひるやす]みでも安心[あんしん]です。", "sentence_source": "generated"}, {"text": "川の流れが速いから、子どもだけで泳いではいけません。", "target_word": "速い", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れが速[はや]いから、子[こ]どもだけで泳[およ]いではいけません。", "sentence_source": "generated"}, {"text": "田中さんは仕事が速く、頼んだ資料もその日のうちにできた。", "target_word": "速く", "complexity_tier": "T3", "furigana": "田中[たなか]さんは仕事[しごと]が速[はや]く、頼[たの]んだ資料[しりょう]もその日[ひ]のうちにできた。", "sentence_source": "generated"}, {"text": "彼は計算が速いが、よく間違える。", "target_word": "速い", "complexity_tier": "T3", "furigana": "彼[かれ]は計算[けいさん]が速[はや]いが、よく間違[まちが]える。", "sentence_source": "generated"}, {"text": "雨雲は思ったより速く動いて、すぐに青空が見えた。", "target_word": "速く", "complexity_tier": "T3", "furigana": "雨雲[あまぐも]は思[おも]ったより速[はや]く動[うご]いて、すぐに青空[あおぞら]が見[み]えた。", "sentence_source": "generated"}, {"text": "この光回線は通信が速くて、大きなファイルもすぐ送れる。", "target_word": "速く", "complexity_tier": "T3", "furigana": "この光回線[ひかりかいせん]は通信[つうしん]が速[はや]くて、大[おお]きなファイルもすぐ送[おく]れる。", "sentence_source": "generated"}, {"text": "速いバスよりも、のんびり走る電車のほうが私は好きだ。", "target_word": "速い", "complexity_tier": "T3", "furigana": "速[はや]いバスよりも、のんびり走[はし]る電車[でんしゃ]のほうが私[わたし]は好[す]きだ。", "sentence_source": "generated"}, {"text": "彼女は歩くのが速いので、私はついていくのが大変だった。", "target_word": "速い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は歩[ある]くのが速[はや]いので、私[わたし]はついていくのが大変[たいへん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "速い", "label": "終止形"}, {"form": "速く", "label": "連用形"}, {"form": "速かった", "label": "過去形"}, {"form": "速くない", "label": "否定形"}, {"form": "速ければ", "label": "仮定形"}, {"form": "速くて", "label": "て形"}], "register": "neutral", "sense_fingerprint": "動きや作業のスピードが高い（速度・手際）の意味の「速い」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53054, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速い", "is_correct": true, "explanation": "移動のスピードが高いという意味で、二時間で着く理由になる"}, {"text": "広い", "is_correct": false, "explanation": "面積が大きい意味。広いことは二時間で着く理由にならないので合わない"}, {"text": "重い", "is_correct": false, "explanation": "目方が大きい意味。重さは到着時間の理由にならないので合わない"}, {"text": "深い", "is_correct": false, "explanation": "奥行きが大きい意味で、移動の速さの説明にならない"}], "explanations": {"速い": "移動のスピードが高いという意味で、二時間で着く理由になる", "広い": "面積が大きい意味。広いことは二時間で着く理由にならないので合わない", "重い": "目方が大きい意味。重さは到着時間の理由にならないので合わない", "深い": "奥行きが大きい意味で、移動の速さの説明にならない"}, "sentence_index": 0, "correct_answer": "速い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は朝が速いから、もう寝ます。", "explanation": "時刻の早さは「早い」で表すので、「速い」は合わない。"}, {"text": "この店は値段が速いので、学生には少し厳しいです。", "explanation": "値段の高さに「速い」は使わないので合わない。"}, {"text": "この荷物は速いので、一人では運べません。", "explanation": "重さの話に「速い」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53054, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。動く様子を表す「速く」で、「動いて」を修飾する形として自然"}, {"text": "寒く", "is_correct": false, "explanation": "温度が低い意味。雨雲が寒く動くのは意味が通らない"}, {"text": "甘く", "is_correct": false, "explanation": "味の甘さを表す意味で、動く様子には合わない"}, {"text": "熱く", "is_correct": false, "explanation": "温度が高い意味で、雨雲の動きとは合わない"}], "explanations": {"速く": "連用形。動く様子を表す「速く」で、「動いて」を修飾する形として自然", "寒く": "温度が低い意味。雨雲が寒く動くのは意味が通らない", "甘く": "味の甘さを表す意味で、動く様子には合わない", "熱く": "温度が高い意味で、雨雲の動きとは合わない"}, "sentence_index": 6, "correct_answer": "速く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鍋は速いので、一度に三人分作れます。", "explanation": "大きさに「速い」は使わないので合わない。"}, {"text": "このロープは速いので、重い荷物も運べます。", "explanation": "太さに「速い」は使わないので合わない。"}, {"text": "この糸は速いので、切れやすいです。", "explanation": "細さに「速い」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53054, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この新しいパソコンは処理を速いので、動画の編集も楽にできます。", "corrected_sentence": "この新しいパソコンは処理が速いので、動画の編集も楽にできます。", "error_description": "助詞の誤り。「速い」の主語は「が」で示すので、「を」は誤り", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。「速くて」の「速く」にあたり、「て」に続く形で、ここに合う"}, {"text": "速い", "is_correct": false, "explanation": "終止形。言い切りの形で、「走るのが速くて」と続く形には合わない"}, {"text": "速かった", "is_correct": false, "explanation": "過去形。いつも一番になるという現在の習慣と合わない"}, {"text": "速ければ", "is_correct": false, "explanation": "仮定形。条件の形で、「速くて」と並ぶ文の流れに合わない"}], "correct_form": "速く", "base_form": "速い", "form_label": "連用形", "sentence_index": 1, "explanations": {"速く": "連用形。「速くて」の「速く」にあたり、「て」に続く形で、ここに合う", "速い": "終止形。言い切りの形で、「走るのが速くて」と続く形には合わない", "速かった": "過去形。いつも一番になるという現在の習慣と合わない", "速ければ": "仮定形。条件の形で、「速くて」と並ぶ文の流れに合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53054, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい電車は思ったより速くて走るので、驚きました。", "corrected_sentence": "新しい電車は思ったより速く走るので、驚きました。", "error_description": "活用形の誤り。動詞「走る」を修飾するには連用形「速く」を使い、「速くて」は動詞に続かない", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。「通信が速くて」の「速く」にあたり、「て」に続く形で、ここに合う"}, {"text": "速くない", "is_correct": false, "explanation": "否定形。通信が速くないという意味になり、文の内容と反対になる"}, {"text": "速すぎる", "is_correct": false, "explanation": "程度が過ぎる形。程度を強める文脈ではなく、ここに合わない"}, {"text": "速そう", "is_correct": false, "explanation": "様子の推量の形。通信が速いと断定している文と合わない"}], "correct_form": "速く", "base_form": "速い", "form_label": "連用形", "sentence_index": 7, "explanations": {"速く": "連用形。「通信が速くて」の「速く」にあたり、「て」に続く形で、ここに合う", "速くない": "否定形。通信が速くないという意味になり、文の内容と反対になる", "速すぎる": "程度が過ぎる形。程度を強める文脈ではなく、ここに合わない", "速そう": "様子の推量の形。通信が速いと断定している文と合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
