INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53055, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "ぐらつかないで、じょうぶです。きちんとしていて、あやまりません。", "primary_collocate": null, "pronunciation": "しっかり", "ipa": "ɕikkaɾi", "syllable_count": 4, "sentences": [{"text": "転ばないように、手すりをしっかり持ってください。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "転[ころ]ばないように、手[て]すりをしっかり持[も]ってください。", "sentence_source": "generated"}, {"text": "ひもをしっかり結んだので、荷物は落ちませんでした。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "ひもをしっかり結[むす]んだので、荷物[にもつ]は落[お]ちませんでした。", "sentence_source": "generated"}, {"text": "風が強いので、ドアをしっかり閉めておきましょう。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]いので、ドアをしっかり閉[し]めておきましょう。", "sentence_source": "generated"}, {"text": "試験の前に、名前と番号をしっかり確かめました。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、名前[なまえ]と番号[ばんごう]をしっかり確[たし]かめました。", "sentence_source": "generated"}, {"text": "彼女は自分の考えをしっかり持っているので、意見が変わりません。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の考[かんが]えをしっかり持[も]っているので、意見[いけん]が変[か]わりません。", "sentence_source": "generated"}, {"text": "倒れないように、机の足をしっかり支えてください。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "倒[たお]れないように、机[つくえ]の足[あし]をしっかり支[ささ]えてください。", "sentence_source": "generated"}, {"text": "朝ごはんをしっかり食べると、午前中も元気に動けます。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんをしっかり食[た]べると、午前中[ごぜんちゅう]も元気[げんき]に動[うご]けます。", "sentence_source": "generated"}, {"text": "先生の話をしっかり聞いて、大事なことをノートに書きました。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]をしっかり聞[き]いて、大事[だいじ]なことをノートに書[か]きました。", "sentence_source": "generated"}, {"text": "地震でも倒れないように、棚を壁にしっかり固定しました。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "地震[じしん]でも倒[たお]れないように、棚[たな]を壁[かべ]にしっかり固定[こてい]しました。", "sentence_source": "generated"}, {"text": "弟は小さいのに、留守番をしっかりして、母を助けてくれました。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "弟[おとうと]は小[ちい]さいのに、留守番[るすばん]をしっかりして、母[はは]を助[たす]けてくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "しっかり", "label": "基本形"}, {"form": "確り", "label": "漢字表記"}], "register": "丁寧（です・ます体）", "sense_fingerprint": "確り|しっかり|ぐらつかず確か・きちんと|副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241fa7e4-e5ef-46f7-8ead-7bb2111dc929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53055, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "しっかり", "is_correct": true, "explanation": "ぐらつかず確かな様子を表し、「手すりをしっかり持つ」として転ばないための意味に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "熟睡の様子を表す語で、「手すりをぐっすり持つ」は意味をなさない。"}, {"text": "ぺこぺこ", "is_correct": false, "explanation": "空腹の様子を表す語で、手すりを持つ動作の様子には合わない。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "光って輝く様子を表す語で、「手すりをぴかぴか持つ」は不自然で空欄に入らない。"}], "explanations": {"しっかり": "ぐらつかず確かな様子を表し、「手すりをしっかり持つ」として転ばないための意味に合う。", "ぐっすり": "熟睡の様子を表す語で、「手すりをぐっすり持つ」は意味をなさない。", "ぺこぺこ": "空腹の様子を表す語で、手すりを持つ動作の様子には合わない。", "ぴかぴか": "光って輝く様子を表す語で、「手すりをぴかぴか持つ」は不自然で空欄に入らない。"}, "sentence_index": 0, "correct_answer": "しっかり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍵をしっかり忘れて、家に入れませんでした。", "explanation": "ここは〈すっかり（完全に）〉の意味。しっかりは確かさ・きちんとを表すので、「すっかり忘れる」の代わりにはならない。"}, {"text": "用事を思い出して、しっかり帰りました。", "explanation": "ここは〈さっさと〉の意味。しっかりは確かさ・きちんとを表し、速く帰る意味では使わない。"}, {"text": "大事な話を、しっかり聞き流しました。", "explanation": "ここは〈ちゃんと聞く〉の意味で「しっかり」を当てているが、しっかりは確かさを表す語で、〈気にとめずに通す〉と両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53055, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "しっかり", "is_correct": true, "explanation": "しっかり食べることを表し、「朝ごはんをしっかり食べると」に合う。"}, {"text": "くるくる", "is_correct": false, "explanation": "回る様子を表す語で、「朝ごはんをくるくる食べる」は意味をなさない。"}, {"text": "ひらひら", "is_correct": false, "explanation": "舞い揺れる様子を表す語で、食べる動作には合わない。"}, {"text": "ちらちら", "is_correct": false, "explanation": "ちらりと見る様子を表す語で、食べる動作には合わず空欄に入らない。"}], "explanations": {"しっかり": "しっかり食べることを表し、「朝ごはんをしっかり食べると」に合う。", "くるくる": "回る様子を表す語で、「朝ごはんをくるくる食べる」は意味をなさない。", "ひらひら": "舞い揺れる様子を表す語で、食べる動作には合わない。", "ちらちら": "ちらりと見る様子を表す語で、食べる動作には合わず空欄に入らない。"}, "sentence_index": 6, "correct_answer": "しっかり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "話し合いが、しっかり長引きました。", "explanation": "ここは〈だらだらと少しずつ〉の意味（ずるずる）。しっかりは確かさ・きちんとの意味で、長引く様子には合わない。"}, {"text": "たまたま町で、しっかり友達に会いました。", "explanation": "ここは〈偶然〉の意味。しっかりは確かさを表し、たまたま出会う意味には合わない。"}, {"text": "わざと、しっかり遅刻しました。", "explanation": "ここは〈意図的に〉の意味（わざと）。しっかりは確かさ・きちんとの意味で、遅刻の意図には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53055, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "転ばないように、手すりをしっかりを握ってください。", "corrected_sentence": "転ばないように、手すりをしっかりと握ってください。", "error_description": "「しっかり」は副詞で、後ろに「を」は付かない。「手すりをしっかりを握る」の「を」が余分な誤り。副詞は動詞に直接続く（しっかり握る／しっかりと握る）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53055, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ひもを、しっかり結ばました。", "corrected_sentence": "ひもを、しっかり結びました。", "error_description": "「結ぶ」の活用が誤り。過去形は「結びました」で、「結ばました」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
