INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53056, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不安定", "is_correct": true, "explanation": "〈安定しないさま〉の意味で、「経営がしっかりしている」の対義語として辞書に並ぶ。"}, {"text": "豪快", "is_correct": false, "explanation": "〈ものごとが大きく勢いのよいさま〉の意味で、経営の確かさとは対にならない。"}, {"text": "大胆", "is_correct": false, "explanation": "〈思い切りのよいさま〉の意味で、この文の対義語には当たらない。"}, {"text": "地味", "is_correct": false, "explanation": "〈目立たないさま〉の意味で、経営の状態の対義語ではない。"}], "correct_answer": "不安定", "explanations": {"不安定": "〈安定しないさま〉の意味で、「経営がしっかりしている」の対義語として辞書に並ぶ。", "豪快": "〈ものごとが大きく勢いのよいさま〉の意味で、経営の確かさとは対にならない。", "大胆": "〈思い切りのよいさま〉の意味で、この文の対義語には当たらない。", "地味": "〈目立たないさま〉の意味で、経営の状態の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53056, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "ぐらつかず、じょうぶであるさま。また、きちんとしていて、あやまったりおろそかになったりしないさま。", "primary_collocate": null, "pronunciation": "しっかり", "ipa": "ɕikkaɾi", "syllable_count": 4, "sentences": [{"text": "この家は柱がしっかりしているので、台風でも倒れない。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "この家[いえ]は柱[はしら]がしっかりしているので、台風[たいふう]でも倒[たお]れない。", "sentence_source": "generated"}, {"text": "彼はまだ若いが、考え方がしっかりしている。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "彼[かれ]はまだ若[わか]いが、考[かんが]え方[かた]がしっかりしている。", "sentence_source": "generated"}, {"text": "しっかりした土台の上に、高い建物を建てる。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "しっかりした土台[どだい]の上[うえ]に、高[たか]い建物[たてもの]を建[た]てる。", "sentence_source": "generated"}, {"text": "母は金銭感覚がしっかりしていて、無駄づかいをしない。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "母[はは]は金銭[きんせん]感覚[かんかく]がしっかりしていて、無駄[むだ]づかいをしない。", "sentence_source": "generated"}, {"text": "このいすは作りがしっかりしていて、座ってもきしまない。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "このいすは作[つく]りがしっかりしていて、座[すわ]ってもきしまない。", "sentence_source": "generated"}, {"text": "受け答えがしっかりしていて、面接官にも好印象だった。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "受[う]け答[こた]えがしっかりしていて、面接官[めんせつかん]にも好印象[こういんしょう]だった。", "sentence_source": "generated"}, {"text": "基礎がしっかりしていれば、応用問題も解けるようになる。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "基礎[きそ]がしっかりしていれば、応用[おうよう]問題[もんだい]も解[と]けるようになる。", "sentence_source": "generated"}, {"text": "しっかりした根拠がなければ、その意見は受け入れられない。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "しっかりした根拠[こんきょ]がなければ、その意見[いけん]は受[う]け入[い]れられない。", "sentence_source": "generated"}, {"text": "足腰がしっかりしているので、祖母は毎日散歩に行ける。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "足腰[あしこし]がしっかりしているので、祖母[そぼ]は毎日[まいにち]散歩[さんぽ]に行[い]ける。", "sentence_source": "generated"}, {"text": "この会社は経営がしっかりしているから、安心して働ける。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は経営[けいえい]がしっかりしているから、安心[あんしん]して働[はたら]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "しっかり", "label": "基本形"}, {"form": "しっかりした", "label": "連体形"}, {"form": "しっかりしている", "label": "状態形"}, {"form": "しっかりして", "label": "テ形"}], "register": "中立・口語（常体）", "sense_fingerprint": "ぐらつかず丈夫なさま、また土台や考えがしっかりして誤りがないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53056, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "しっかり", "is_correct": true, "explanation": "「柱がしっかりしている」で、ぐらつかず丈夫な様子を表す。文に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "〈深く眠るさま〉の意味で、柱の状態には使えない。"}, {"text": "はっきり", "is_correct": false, "explanation": "〈明瞭なさま〉の意味で、建物の丈夫さは表せない。"}, {"text": "てきぱき", "is_correct": false, "explanation": "〈素早く手際よいさま〉の意味で、柱の状態には合わない。"}], "explanations": {"しっかり": "「柱がしっかりしている」で、ぐらつかず丈夫な様子を表す。文に合う。", "ぐっすり": "〈深く眠るさま〉の意味で、柱の状態には使えない。", "はっきり": "〈明瞭なさま〉の意味で、建物の丈夫さは表せない。", "てきぱき": "〈素早く手際よいさま〉の意味で、柱の状態には合わない。"}, "sentence_index": 0, "correct_answer": "しっかり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この川は流れの速さがしっかりしていて、夏は泳ぎやすい。", "explanation": "ここは〈丈夫で安定した〉の意味。流れの速さを表すのは「速い」などで、しっかりは速さや勢いには使えないので合わない。"}, {"text": "この靴は底がしっかり薄く、少し歩くだけで穴が開く。", "explanation": "ここは〈丈夫である〉の意味。底の薄さを表すのは「薄い」で、しっかりは丈夫さや確かさを表すので合わない。"}, {"text": "彼は言い訳ばかりで、約束をしっかり破ってばかりいる。", "explanation": "ここは〈きちんと確実に〉の意味。約束を破る行為を強める用法には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53056, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "しっかり", "is_correct": true, "explanation": "「基礎がしっかりしていれば」で、土台が確かで揺るがない様子を表す。文に合う。"}, {"text": "のんびり", "is_correct": false, "explanation": "〈ゆったり落ち着いたさま〉の意味で、基礎の状態には合わない。"}, {"text": "ぼんやり", "is_correct": false, "explanation": "〈はっきりしないさま〉の意味で、基礎の確かさは表せない。"}, {"text": "きっぱり", "is_correct": false, "explanation": "〈はっきり断るさま〉の意味で、基礎の状態には使えない。"}], "explanations": {"しっかり": "「基礎がしっかりしていれば」で、土台が確かで揺るがない様子を表す。文に合う。", "のんびり": "〈ゆったり落ち着いたさま〉の意味で、基礎の状態には合わない。", "ぼんやり": "〈はっきりしないさま〉の意味で、基礎の確かさは表せない。", "きっぱり": "〈はっきり断るさま〉の意味で、基礎の状態には使えない。"}, "sentence_index": 6, "correct_answer": "しっかり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は会議で話をしっかり切って、毎回すぐ終わらせてしまう。", "explanation": "ここは〈きちんとして誤りがない〉の意味。話を切るという行為は「しっかり」では表せず、ここでは合わない。"}, {"text": "その計画は見通しをしっかり崩して、途中で必ず行き詰まる。", "explanation": "ここは〈確かで土台が堅い〉の意味。見通しを崩すという行為を「しっかり」で強めることはできず、矛盾する。"}, {"text": "足元をしっかり踏み外して、雨の日は何度も転んでいる。", "explanation": "ここは〈ぐらつかず丈夫〉の意味。踏み外すという動きを「しっかり」で強める用法はなく、転ぶ状況とも矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53056, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この家は柱がしっかりしいて、台風でも倒れにくい。", "corrected_sentence": "この家は柱がしっかりしていて、台風でも倒れにくい。", "error_description": "て形「しっかりしていて」が正しい。「しっかりしいて」は活用が誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53056, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "経営がしっかりする企業は、景気の悪い時期も乗り切れる。", "corrected_sentence": "経営がしっかりした企業は、景気の悪い時期も乗り切れる。", "error_description": "名詞を修飾する連体形「しっかりした」が正しい。「しっかりする」は連体修飾に使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53065, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「スポークンで自分の詩を声に出して演じる」で、演じる手段を表す。スポークンに直接続く。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は方向や相手を表すので、演じる手段を示す文脈には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すので、演じる手段としては合わない。"}, {"text": "の", "is_correct": false, "explanation": "「スポークンの自分の詩」となり、〈の〉では修飾が成り立たず不自然。"}], "correct_answer": "で", "explanations": {"で": "「スポークンで自分の詩を声に出して演じる」で、演じる手段を表す。スポークンに直接続く。", "に": "〈に〉は方向や相手を表すので、演じる手段を示す文脈には合わない。", "へ": "〈へ〉は方向を表すので、演じる手段としては合わない。", "の": "「スポークンの自分の詩」となり、〈の〉では修飾が成り立たず不自然。"}, "error_tags": {"に": "方向・相手", "へ": "方向", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53065, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「スポークンを演じ」で、演じる対象を表す。スポークンに直接続く。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は相手や引用を表すので、演じる対象を示す文脈には合わない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すので、「スポークンが演じ」では演じる主体が逆転して合わない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表すので、演じる対象の文脈には合わない。"}], "correct_answer": "を", "explanations": {"を": "「スポークンを演じ」で、演じる対象を表す。スポークンに直接続く。", "と": "〈と〉は相手や引用を表すので、演じる対象を示す文脈には合わない。", "が": "〈が〉は主語を示すので、「スポークンが演じ」では演じる主体が逆転して合わない。", "から": "〈から〉は起点を表すので、演じる対象の文脈には合わない。"}, "error_tags": {"と": "相手", "が": "主語", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53065, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "声に出した言葉を舞台で演じる芸術。", "primary_collocate": null, "pronunciation": "すぽーくん", "ipa": "supoːkɯɴ", "syllable_count": 5, "sentences": [{"text": "昨夜、小さな劇場でスポークンの舞台を見ました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "昨夜[さくや]、小[ちい]さな劇場[げきじょう]でスポークンの舞台[ぶたい]を見[み]ました。", "sentence_source": "generated"}, {"text": "詩人は、スポークンで自分の詩を声に出して演じました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "詩人[しじん]は、スポークンで自分[じぶん]の詩[し]を声[こえ]に出[だ]して演[えん]じました。", "sentence_source": "generated"}, {"text": "スポークンは、声の強さや間で気持ちを伝える芸術です。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "スポークンは、声[こえ]の強[つよ]さや間[ま]で気持[きも]ちを伝[つた]える芸術[げいじゅつ]です。", "sentence_source": "generated"}, {"text": "兄はスポークンに興味があって、週末に朗読会へ通っています。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "兄[あに]はスポークンに興味[きょうみ]があって、週末[しゅうまつ]に朗読会[ろうどくかい]へ通[かよ]っています。", "sentence_source": "generated"}, {"text": "観客は、スポークンの力強い声に引きこまれました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "観客[かんきゃく]は、スポークンの力強[ちからづよ]い声[こえ]に引[ひ]きこまれました。", "sentence_source": "generated"}, {"text": "学校の文化祭で、生徒たちがスポークンを披露しました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "学校[がっこう]の文化祭[ぶんかさい]で、生徒[せいと]たちがスポークンを披露[ひろう]しました。", "sentence_source": "generated"}, {"text": "歌とちがって、スポークンはメロディーがなく、言葉だけで聞かせます。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "歌[うた]とちがって、スポークンはメロディーがなく、言葉[ことば]だけで聞[き]かせます。", "sentence_source": "generated"}, {"text": "彼女は大会でスポークンを演じ、会場から大きな拍手をもらいました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大会[たいかい]でスポークンを演[えん]じ、会場[かいじょう]から大[おお]きな拍手[はくしゅ]をもらいました。", "sentence_source": "generated"}, {"text": "スポークンの練習では、まず声を出して言葉を何度も読みます。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "スポークンの練習[れんしゅう]では、まず声[こえ]を出[だ]して言葉[ことば]を何度[なんど]も読[よ]みます。", "sentence_source": "generated"}, {"text": "外国の街で見たスポークンは、言葉が分からなくても迫力がありました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "外国[がいこく]の街[まち]で見[み]たスポークンは、言葉[ことば]が分[わ]からなくても迫力[はくりょく]がありました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スポークン", "label": "基本形"}], "register": "polite", "sense_fingerprint": "声に出した言葉を舞台で演じる芸術・パフォーマンス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53065, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スポークン", "is_correct": true, "explanation": "「スポークンの舞台」と続き、声で言葉を演じる芸術を指すので、空所にはこの語が入る。"}, {"text": "照明", "is_correct": false, "explanation": "舞台を照らす装置で、「照明の舞台」という演目の名称にはならないので合わない。"}, {"text": "衣装", "is_correct": false, "explanation": "俳優が着る服で、舞台の種類を表す語にはならないので合わない。"}, {"text": "小道具", "is_correct": false, "explanation": "舞台で使う道具で、芸術の種類を示す語にはならないので合わない。"}], "explanations": {"スポークン": "「スポークンの舞台」と続き、声で言葉を演じる芸術を指すので、空所にはこの語が入る。", "照明": "舞台を照らす装置で、「照明の舞台」という演目の名称にはならないので合わない。", "衣装": "俳優が着る服で、舞台の種類を表す語にはならないので合わない。", "小道具": "舞台で使う道具で、芸術の種類を示す語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "スポークン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は舞台で、メロディー付きのスポークンを大きな声で披露しました。", "explanation": "ここは〈歌〉の意味。メロディーに乗せるのは歌で、メロディーを伴わないスポークンの説明としては合わない。"}, {"text": "祖父は孫の前で、スポークンを上映しました。", "explanation": "ここは〈映画〉の意味。上映するのは映画で、声で言葉を届けるスポークンは上映の対象にならないので合わない。"}, {"text": "スポークンは、長い距離を走って速さを競います。", "explanation": "ここは〈競走〉の意味。走って速さを競うのは競技で、声で言葉を伝える芸術のスポークンとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53065, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スポークン", "is_correct": true, "explanation": "歌とちがい、メロディーがなく言葉だけで聞かせる芸術なので、空所にはこの語が入る。"}, {"text": "客席", "is_correct": false, "explanation": "観客が座る場所で、メロディーの有無を論じる主語にはならないので合わない。"}, {"text": "舞台装置", "is_correct": false, "explanation": "舞台の設備で、音楽の有無とは関係がなく合わない。"}, {"text": "幕", "is_correct": false, "explanation": "舞台の仕切りで、メロディーの有無を表す主語にはならないので合わない。"}], "explanations": {"スポークン": "歌とちがい、メロディーがなく言葉だけで聞かせる芸術なので、空所にはこの語が入る。", "客席": "観客が座る場所で、メロディーの有無を論じる主語にはならないので合わない。", "舞台装置": "舞台の設備で、音楽の有無とは関係がなく合わない。", "幕": "舞台の仕切りで、メロディーの有無を表す主語にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "スポークン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スポークンは、歌とダンスで物語を伝えます。", "explanation": "ここはミュージカルの意味。歌もダンスも伴わない声の芸術であるスポークンには合わない。"}, {"text": "彼は包丁で野菜を切り、スポークンを鍋で煮込みました。", "explanation": "ここは〈料理〉の意味。包丁と鍋で調理するのは料理で、声で言葉を届けるスポークンとは合わない。"}, {"text": "彼は絵の具を重ねて、キャンバスにスポークンの風景を描きました。", "explanation": "ここは〈絵画〉の意味。絵の具で描くのは絵画で、声で言葉を届けるスポークンとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53065, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その詩人は、スポークンに舞台で新作を披露しました。", "corrected_sentence": "その詩人は、スポークンの舞台で新作を披露しました。", "error_description": "誤: スポークンに舞台。正: スポークンの舞台。舞台を修飾する〈の〉が必要で、〈に〉は方向を表すので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53065, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は毎週、スポークンを演じるています。", "corrected_sentence": "彼は毎週、スポークンを演じています。", "error_description": "誤: 演じるています。正: 演じています。『演じる』の活用が誤り、『演じて』に『いる』を続けた形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53066, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「スポークンは音楽を〜」で、スポークンを主題として示す。スポークンに直接続く。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は対象を表すが、「スポークンを、ギターの伴奏が〜」では主題の文脈にならず合わない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すので、ここでは文の流れに合わない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は相手や方向を表すので、主題を示す文脈には合わない。"}], "correct_answer": "は", "explanations": {"は": "「スポークンは音楽を〜」で、スポークンを主題として示す。スポークンに直接続く。", "を": "〈を〉は対象を表すが、「スポークンを、ギターの伴奏が〜」では主題の文脈にならず合わない。", "へ": "〈へ〉は方向を表すので、ここでは文の流れに合わない。", "に": "〈に〉は相手や方向を表すので、主題を示す文脈には合わない。"}, "error_tags": {"を": "対象", "へ": "方向", "に": "相手・方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53066, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「スポークンは声の高さと間で〜」で、スポークンを主題として示す。スポークンに直接続く。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すので、「声の高さと間へ雰囲気を作る」では成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「スポークンを…雰囲気を作ります」となり、〈を〉が二つ並んで不自然。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表すので、主題を示す文脈には合わない。"}], "correct_answer": "は", "explanations": {"は": "「スポークンは声の高さと間で〜」で、スポークンを主題として示す。スポークンに直接続く。", "へ": "〈へ〉は方向を表すので、「声の高さと間へ雰囲気を作る」では成り立たない。", "を": "「スポークンを…雰囲気を作ります」となり、〈を〉が二つ並んで不自然。", "から": "〈から〉は起点を表すので、主題を示す文脈には合わない。"}, "error_tags": {"へ": "方向", "を": "対象", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53066, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "口頭で直接言葉を発すること。特に音楽を伴わずに言葉を朗読するパフォーマンスを指す。", "primary_collocate": null, "pronunciation": "すぽーくん", "ipa": "supoːkɯɴ", "syllable_count": 5, "sentences": [{"text": "スポークンは音楽を使わず、声だけで詩を朗読します。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "スポークンは音楽[おんがく]を使[つか]わず、声[こえ]だけで詩[し]を朗読[ろうどく]します。", "sentence_source": "generated"}, {"text": "彼のスポークンは、ギターの伴奏がなくても、心に強く残りました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "彼[かれ]のスポークンは、ギターの伴奏[ばんそう]がなくても、心[こころ]に強[つよ]く残[のこ]りました。", "sentence_source": "generated"}, {"text": "カフェで開かれた夜のスポークンに、十人ほどの詩人が出ました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "カフェで開[ひら]かれた夜[よる]のスポークンに、十人[じゅうにん]ほどの詩人[しじん]が出[で]ました。", "sentence_source": "generated"}, {"text": "ラップはビートに乗せますが、スポークンは音楽なしで言葉を届けます。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "ラップはビートに乗[の]せますが、スポークンは音楽[おんがく]なしで言葉[ことば]を届[とど]けます。", "sentence_source": "generated"}, {"text": "友人が書いた詩を、スポークンで朗読しました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "友人[ゆうじん]が書[か]いた詩[し]を、スポークンで朗読[ろうどく]しました。", "sentence_source": "generated"}, {"text": "スポークンの途中で、会場が静まり返りました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "スポークンの途中[とちゅう]で、会場[かいじょう]が静[しず]まり返[かえ]りました。", "sentence_source": "generated"}, {"text": "彼女はマイク一本でスポークンを行い、観客を笑わせたり泣かせたりしました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はマイク一本[いっぽん]でスポークンを行[おこな]い、観客[かんきゃく]を笑[わら]わせたり泣[な]かせたりしました。", "sentence_source": "generated"}, {"text": "音楽がなくても、スポークンは声の高さと間で雰囲気を作ります。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "音楽[おんがく]がなくても、スポークンは声[こえ]の高[たか]さと間[ま]で雰囲気[ふんいき]を作[つく]ります。", "sentence_source": "generated"}, {"text": "図書館のイベントで、地元の作家がスポークンを披露しました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "図書館[としょかん]のイベントで、地元[じもと]の作家[さっか]がスポークンを披露[ひろう]しました。", "sentence_source": "generated"}, {"text": "今夜のスポークンのテーマは「家族」で、八人が順番に朗読します。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "今夜[こんや]のスポークンのテーマは「家族[かぞく]」で、八人[はちにん]が順番[じゅんばん]に朗読[ろうどく]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スポークン", "label": "基本形"}], "register": "中立", "sense_fingerprint": "音楽なしで言葉だけを朗読するパフォーマンス", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: 静まり返り (Zipf 1.28)']::text[], 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53066, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スポークン", "is_correct": true, "explanation": "音楽を使わず声だけで詩を朗読する芸術なので、文頭の主語にはこの語が入る。"}, {"text": "絵画", "is_correct": false, "explanation": "絵を描く芸術で、音楽を使わず詩を朗読するという説明とは合わないので入らない。"}, {"text": "彫刻", "is_correct": false, "explanation": "立体造形の芸術で、詩を朗読するという説明とは合わないので入らない。"}, {"text": "陶芸", "is_correct": false, "explanation": "土で器を作る芸術で、詩を朗読するという説明とは合わないので入らない。"}], "explanations": {"スポークン": "音楽を使わず声だけで詩を朗読する芸術なので、文頭の主語にはこの語が入る。", "絵画": "絵を描く芸術で、音楽を使わず詩を朗読するという説明とは合わないので入らない。", "彫刻": "立体造形の芸術で、詩を朗読するという説明とは合わないので入らない。", "陶芸": "土で器を作る芸術で、詩を朗読するという説明とは合わないので入らない。"}, "sentence_index": 0, "correct_answer": "スポークン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は声を出さずに、指の動きでスポークンを届けました。", "explanation": "ここは〈手話〉の意味。指の動きで伝えるのは手話で、声を出して言葉を発するスポークンとは合わない。"}, {"text": "スポークンは、ボールを投げて点を競う競技です。", "explanation": "ここは〈スポーツ〉の意味。ボールで点を競うのは競技で、声で言葉を届けるスポークンとは合わない。"}, {"text": "彼は楽譜を見ながら、スポークンの旋律を奏でました。", "explanation": "ここは〈演奏〉の意味。旋律を奏でるのは演奏で、音楽を伴わない朗読のスポークンとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53066, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スポークン", "is_correct": true, "explanation": "マイク一本で行う、音楽を伴わない言葉のパフォーマンスなので、空所にはこの語が入る。"}, {"text": "笑顔", "is_correct": false, "explanation": "表情を指す語で、「笑顔を行う」とは言わないので合わない。"}, {"text": "足音", "is_correct": false, "explanation": "歩く音を指す語で、「足音を行う」とは言わないので合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の呼吸を指す語で、「寝息を行う」とは言わないので合わない。"}], "explanations": {"スポークン": "マイク一本で行う、音楽を伴わない言葉のパフォーマンスなので、空所にはこの語が入る。", "笑顔": "表情を指す語で、「笑顔を行う」とは言わないので合わない。", "足音": "歩く音を指す語で、「足音を行う」とは言わないので合わない。", "寝息": "眠っている人の呼吸を指す語で、「寝息を行う」とは言わないので合わない。"}, "sentence_index": 6, "correct_answer": "スポークン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スポークンは、絵の具で色を重ねて表現します。", "explanation": "ここは〈絵画〉の意味。絵の具で色を重ねて表現するのは絵画で、声で言葉を届けるスポークンとは合わない。"}, {"text": "スポークンは、機械に言葉を閉じ込めて残します。", "explanation": "ここは〈録音〉の意味。機械に残す記録は録音で、声で言葉を届けるスポークンは記録の媒体にはならないので合わない。"}, {"text": "スポークンは、大勢で声をそろえて歌います。", "explanation": "ここは〈合唱〉の意味。大勢で声をそろえて歌うのは合唱で、ひとりが音楽を伴わずに朗読するスポークンとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53066, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "詩の会では、スポークンに朗読する人が多いです。", "corrected_sentence": "詩の会では、スポークンで朗読する人が多いです。", "error_description": "誤: スポークンに朗読。正: スポークンで朗読。朗読の手段・様式を表すには〈で〉が必要で、〈に〉は方向を表すので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53066, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜のカフェでは、詩人たちがスポークンを会を開きます。", "corrected_sentence": "夜のカフェでは、詩人たちがスポークンの会を開きます。", "error_description": "誤: スポークンを会。正: スポークンの会。種類を示す〈の〉が必要で、〈を〉を続けると目的語が二つ並び不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53069, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「パフォーマンスに」で、拍手が起こったきっかけや対象を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「起こる」は目的語を取らないので、「を」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」だが、「パフォーマンスから拍手が起こった」は原因を表さず不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の相手を示す「と」で、拍手の原因にはならない。"}], "correct_answer": "に", "explanations": {"に": "「パフォーマンスに」で、拍手が起こったきっかけや対象を示す正しい助詞。", "を": "「起こる」は目的語を取らないので、「を」では文が成り立たない。", "から": "起点を示す「から」だが、「パフォーマンスから拍手が起こった」は原因を表さず不自然。", "と": "並列の相手を示す「と」で、拍手の原因にはならない。"}, "error_tags": {"を": "目的語", "から": "起点", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53069, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「入れたパフォーマンスで」の手段を示す正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「パフォーマンスに観客を楽しませる」は後ろの「観客を」と重なり、対象の関係が不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語が二つになり、「楽しませる」の文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、「パフォーマンスから楽しませる」は手段の関係が合わない。"}], "correct_answer": "で", "explanations": {"で": "「入れたパフォーマンスで」の手段を示す正しい助詞。", "に": "「パフォーマンスに観客を楽しませる」は後ろの「観客を」と重なり、対象の関係が不自然。", "を": "目的語が二つになり、「楽しませる」の文として成り立たない。", "から": "起点を示す「から」で、「パフォーマンスから楽しませる」は手段の関係が合わない。"}, "error_tags": {"に": "方向・対象", "を": "目的語", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53069, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ステージで歌うことや踊ることです。", "primary_collocate": null, "pronunciation": "ぱふぉーまんす", "ipa": "paɸoːmaɴsɯ", "syllable_count": 6, "sentences": [{"text": "文化祭で、クラスの友だちと歌のパフォーマンスをしました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "文化祭[ぶんかさい]で、クラスの友[とも]だちと歌[うた]のパフォーマンスをしました。", "sentence_source": "generated"}, {"text": "彼女のダンスのパフォーマンスに、客席から大きな拍手が起こりました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のダンスのパフォーマンスに、客席[きゃくせき]から大[おお]きな拍手[はくしゅ]が起[お]こりました。", "sentence_source": "generated"}, {"text": "駅前で若い男の子たちがパフォーマンスをしていて、人が集まっていました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "駅前[えきまえ]で若[わか]い男[おとこ]の子[こ]たちがパフォーマンスをしていて、人[ひと]が集[あつ]まっていました。", "sentence_source": "generated"}, {"text": "アイドルのパフォーマンスが始まると、会場はいっせいに静かになりました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "アイドルのパフォーマンスが始[はじ]まると、会場[かいじょう]はいっせいに静[しず]かになりました。", "sentence_source": "generated"}, {"text": "毎日練習したので、本番のパフォーマンスは完璧でした。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]したので、本番[ほんばん]のパフォーマンスは完璧[かんぺき]でした。", "sentence_source": "generated"}, {"text": "兄はバンドでパフォーマンスをするために、毎週ギターを練習しています。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "兄[あに]はバンドでパフォーマンスをするために、毎週[まいしゅう]ギターを練習[れんしゅう]しています。", "sentence_source": "generated"}, {"text": "最後のパフォーマンスで、みんなが立ち上がって一緒に歌いました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "最後[さいご]のパフォーマンスで、みんなが立[た]ち上[あ]がって一緒[いっしょ]に歌[うた]いました。", "sentence_source": "generated"}, {"text": "歌手は、ダンスを入れたパフォーマンスで観客を楽しませました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "歌手[かしゅ]は、ダンスを入[い]れたパフォーマンスで観客[かんきゃく]を楽[たの]しませました。", "sentence_source": "generated"}, {"text": "動画でこのグループのパフォーマンスを見て、ファンになりました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "動画[どうが]でこのグループのパフォーマンスを見[み]て、ファンになりました。", "sentence_source": "generated"}, {"text": "学園祭のパフォーマンスに出るために、私たちは毎晩踊りの練習をしました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "学園祭[がくえんさい]のパフォーマンスに出[で]るために、私[わたし]たちは毎晩[まいばん]踊[おど]りの練習[れんしゅう]をしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パフォーマンス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人前で歌ったり踊ったりする披露", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53069, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パフォーマンス", "is_correct": true, "explanation": "「をする」と続き、人前で歌や踊りを見せる行為を表す。空所に入るのはこの語だけ。"}, {"text": "机", "is_correct": false, "explanation": "物の名前で、「をする」で行為を表さない。「歌の机をしました」は意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "物の名前で、「をする」の対象にならない。「歌の窓をしました」は不自然。"}, {"text": "寿命", "is_correct": false, "explanation": "物の使える期間を表す語で、「寿命をする」とは言わない。"}], "explanations": {"パフォーマンス": "「をする」と続き、人前で歌や踊りを見せる行為を表す。空所に入るのはこの語だけ。", "机": "物の名前で、「をする」で行為を表さない。「歌の机をしました」は意味が通らない。", "窓": "物の名前で、「をする」の対象にならない。「歌の窓をしました」は不自然。", "寿命": "物の使える期間を表す語で、「寿命をする」とは言わない。"}, "sentence_index": 0, "correct_answer": "パフォーマンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バイト代で、パフォーマンスを貯めて新しい自転車を買った。", "explanation": "ここは〈貯金〉の意味との混同。貯金は貯めるものだが、この語は演じることを指すので「貯める」とは合わない。"}, {"text": "公演の前に、駅でパフォーマンスを配った。", "explanation": "ここは〈チラシ〉の意味との混同。チラシは配るものだが、この語は演じることを指すので「配る」とは合わない。"}, {"text": "彼は夜中までパフォーマンスを書いていた。", "explanation": "ここは〈歌詞〉の意味との混同。歌詞は書くものだが、この語は演じることを指すので「書く」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53069, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パフォーマンス", "is_correct": true, "explanation": "「最後の〜で」で、ステージで歌う場面を指す。空所に入るのはこの語だけ。"}, {"text": "天気", "is_correct": false, "explanation": "空模様の語で、立ち上がって歌う場面にはならない。「最後の天気で」は不自然。"}, {"text": "財布", "is_correct": false, "explanation": "持ち物の名前で、歌う場面を指さない。「最後の財布で」は意味が通らない。"}, {"text": "寿命", "is_correct": false, "explanation": "物の使える期間を表す語で、歌う場面を示さない。「最後の寿命で」は不自然。"}], "explanations": {"パフォーマンス": "「最後の〜で」で、ステージで歌う場面を指す。空所に入るのはこの語だけ。", "天気": "空模様の語で、立ち上がって歌う場面にはならない。「最後の天気で」は不自然。", "財布": "持ち物の名前で、歌う場面を指さない。「最後の財布で」は意味が通らない。", "寿命": "物の使える期間を表す語で、歌う場面を示さない。「最後の寿命で」は不自然。"}, "sentence_index": 6, "correct_answer": "パフォーマンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本番前に、パフォーマンスを着て舞台に立った。", "explanation": "ここは〈衣装〉の意味との混同。衣装は身につけるものだが、この語は演じること自体を指すので「着る」とは合わない。"}, {"text": "開演前に、客席にパフォーマンスが集まった。", "explanation": "ここは〈観客〉の意味との混同。観客は集まる人々だが、演技は人のように集まらないので合わない。"}, {"text": "舞台を明るくするため、パフォーマンスを当てた。", "explanation": "ここは〈照明〉の意味との混同。照明は当てるものだが、この語は演技を指すので「当てる」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53069, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "文化祭では、みんなで歌のパフォーマンスが披露しました。", "corrected_sentence": "文化祭では、みんなで歌のパフォーマンスを披露しました。", "error_description": "「披露する」は目的語を「を」で示す。「が」を付けると主語になり、「披露しました」と続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53069, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学園祭で、クラスのみんなが歌のパフォーマンスが成功させた。", "corrected_sentence": "学園祭で、クラスのみんなが歌のパフォーマンスを成功させた。", "error_description": "「成功させる」は目的語を「を」で示す。「パフォーマンスが」と「が」を付けると主語になり、「成功させた」の目的語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53070, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「パフォーマンスで観客を引きつけた」の手段を示す正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「パフォーマンスに観客を引きつけた」は、引きつける手段の関係が合わず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、引きつける手段の意味にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列の相手を示す「と」で、手段の意味にはならない。"}], "correct_answer": "で", "explanations": {"で": "「パフォーマンスで観客を引きつけた」の手段を示す正しい助詞。", "に": "「パフォーマンスに観客を引きつけた」は、引きつける手段の関係が合わず不自然。", "から": "起点を示す「から」で、引きつける手段の意味にはならない。", "と": "並列の相手を示す「と」で、手段の意味にはならない。"}, "error_tags": {"に": "方向・対象", "から": "起点", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
