INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53070, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "舞台などで音楽や演劇を見客に披露すること。また、その演技そのものを指します。", "primary_collocate": null, "pronunciation": "ぱふぉーまんす", "ipa": "paɸoːmaɴsɯ", "syllable_count": 6, "sentences": [{"text": "劇場で、有名な劇団の素晴らしいパフォーマンスを見ました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "劇場[げきじょう]で、有名[ゆうめい]な劇団[げきだん]の素晴[すば]らしいパフォーマンスを見[み]ました。", "sentence_source": "generated"}, {"text": "ピアニストは、静かな曲のパフォーマンスで観客を引きつけました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "ピアニストは、静[しず]かな曲[きょく]のパフォーマンスで観客[かんきゃく]を引[ひ]きつけました。", "sentence_source": "generated"}, {"text": "公演の後、役者のパフォーマンスについて友だちと話しました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "公演[こうえん]の後[あと]、役者[やくしゃ]のパフォーマンスについて友[とも]だちと話[はな]しました。", "sentence_source": "generated"}, {"text": "市民ホールでオーケストラのパフォーマンスを楽しみました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "市民[しみん]ホールでオーケストラのパフォーマンスを楽[たの]しみました。", "sentence_source": "generated"}, {"text": "彼女は舞台で落ち着いたパフォーマンスを披露しました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は舞台[ぶたい]で落[お]ち着[つ]いたパフォーマンスを披露[ひろう]しました。", "sentence_source": "generated"}, {"text": "新人の俳優は、初めての舞台でも堂々としたパフォーマンスをしました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "新人[しんじん]の俳優[はいゆう]は、初[はじ]めての舞台[ぶたい]でも堂々[どうどう]としたパフォーマンスをしました。", "sentence_source": "generated"}, {"text": "路上のパフォーマンスは、道を通る人に楽しい音楽を届けました。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "路上[ろじょう]のパフォーマンスは、道[みち]を通[とお]る人[ひと]に楽[たの]しい音楽[おんがく]を届[とど]けました。", "sentence_source": "generated"}, {"text": "劇団のパフォーマンスは三時間も続きましたが、少しも退屈しませんでした。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "劇団[げきだん]のパフォーマンスは三時間[さんじかん]も続[つづ]きましたが、少[すこ]しも退屈[たいくつ]しませんでした。", "sentence_source": "generated"}, {"text": "観客は、この夜のパフォーマンスを長い間忘れないでしょう。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "観客[かんきゃく]は、この夜[よる]のパフォーマンスを長[なが]い間[あいだ]忘[わす]れないでしょう。", "sentence_source": "generated"}, {"text": "祭りでは、地元の人たちが太鼓のパフォーマンスを見せてくれます。", "target_word": "パフォーマンス", "complexity_tier": "T3", "furigana": "祭[まつ]りでは、地元[じもと]の人[ひと]たちが太鼓[たいこ]のパフォーマンスを見[み]せてくれます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パフォーマンス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "舞台で音楽や演劇を観客に披露する演技", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53070, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パフォーマンス", "is_correct": true, "explanation": "「素晴らしい〜を見ました」で、舞台で演じられた演技を指す。空所に入るのはこの語だけ。"}, {"text": "寿命", "is_correct": false, "explanation": "物の使える期間を表す語で、見る対象にならない。「素晴らしい寿命を見ました」は意味が通らない。"}, {"text": "湿気", "is_correct": false, "explanation": "空気中の水分を表す語で、舞台を見る対象にならない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品の名前で、舞台の演技を見る文脈には入らない。"}], "explanations": {"パフォーマンス": "「素晴らしい〜を見ました」で、舞台で演じられた演技を指す。空所に入るのはこの語だけ。", "寿命": "物の使える期間を表す語で、見る対象にならない。「素晴らしい寿命を見ました」は意味が通らない。", "湿気": "空気中の水分を表す語で、舞台を見る対象にならない。", "砂糖": "食品の名前で、舞台の演技を見る文脈には入らない。"}, "sentence_index": 0, "correct_answer": "パフォーマンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しいポスターを作り、壁にパフォーマンスを貼った。", "explanation": "ここは〈ポスター〉の意味との混同。ポスターは貼るものだが、この語は演じることを指すので「貼る」とは合わない。"}, {"text": "彼は三年かけてパフォーマンスを書き上げた。", "explanation": "ここは〈脚本〉の意味との混同。脚本は書き上げるものだが、この語は演じることを指すので合わない。"}, {"text": "舞台の前で、パフォーマンスを被って写真を撮った。", "explanation": "ここは〈帽子〉の意味との混同。帽子は被るものだが、この語は演じることを指すので「被る」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53070, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パフォーマンス", "is_correct": true, "explanation": "「路上の〜は」で、道行く人に音楽を届ける演技を指す。空所に入るのはこの語だけ。"}, {"text": "標識", "is_correct": false, "explanation": "道路の案内を示す道具で、音楽を届けることはない。"}, {"text": "看板", "is_correct": false, "explanation": "店や案内を示すもので、音楽を届ける働きはない。"}, {"text": "信号", "is_correct": false, "explanation": "通行を指示するもので、音楽を届けることはない。"}], "explanations": {"パフォーマンス": "「路上の〜は」で、道行く人に音楽を届ける演技を指す。空所に入るのはこの語だけ。", "標識": "道路の案内を示す道具で、音楽を届けることはない。", "看板": "店や案内を示すもので、音楽を届ける働きはない。", "信号": "通行を指示するもので、音楽を届けることはない。"}, "sentence_index": 6, "correct_answer": "パフォーマンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "稽古の前にパフォーマンスを読んで、台詞を覚えた。", "explanation": "ここは〈台本〉の意味との混同。台本は読むものだが、この語は演じることを指すので「読む」とは合わない。"}, {"text": "パフォーマンスを当てると、舞台が明るく見えた。", "explanation": "ここは〈照明〉の意味との混同。照明は当てるものだが、この語は演技を指すので「当てる」とは合わない。"}, {"text": "終演後、パフォーマンスを下ろすと、客席から拍手がわいた。", "explanation": "ここは〈幕〉の意味との混同。幕は下ろすものだが、この語は演じることを指すので「下ろす」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53070, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公演では、子どもたちが元気なパフォーマンスに披露した。", "corrected_sentence": "公演では、子どもたちが元気なパフォーマンスを披露した。", "error_description": "「披露する」は目的語を「を」で示す。「に」では「披露した」の目的語にならず、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53070, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若手の劇団が舞台で、すばらしいパフォーマンスが見せた。", "corrected_sentence": "若手の劇団が舞台で、すばらしいパフォーマンスを見せた。", "error_description": "「見せる」は目的語を「を」で示す。「が」を付けると「見せた」の目的語にならず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53078, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『押す』の目的語を示す。ペンの部品を押す動作を表す。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、『押す』の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、押す対象を表すことはできない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、押す対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "『押す』の目的語を示す。ペンの部品を押す動作を表す。", "で": "手段や場所を示すが、『押す』の目的語にはならない。", "へ": "方向を示すが、押す対象を表すことはできない。", "と": "並列や相手を示すが、押す対象にはならない。"}, "error_tags": {"で": "手段", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53078, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『外れた』の主語を示す。おもちゃの中のスプリングが外れた、という文。"}, {"text": "に", "is_correct": false, "explanation": "場所を示すが、『外れた』の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示し、ここでは主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を示すが、「外れた」と直接結ぶと文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "『外れた』の主語を示す。おもちゃの中のスプリングが外れた、という文。", "に": "場所を示すが、『外れた』の主語にはならない。", "より": "比較を示し、ここでは主語にならない。", "と": "「と」は並列・共同を示すが、「外れた」と直接結ぶと文が成立しない。"}, "error_tags": {"に": "場所", "より": "比較", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53078, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "押すと縮み、離すと元に戻る性質を持った、コイル状の金属部品。", "primary_collocate": null, "pronunciation": "すぷりんぐ", "ipa": "sɯpɯɾiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "ベッドのスプリングが壊れて、寝るたびに音がきしむようになった。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "ベッドのスプリングが壊[こわ]れて、寝[ね]るたびに音[おと]がきしむようになった。", "sentence_source": "generated"}, {"text": "ペンのスプリングを押すと縮み、手を離すと元の長さに戻る。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "ペンのスプリングを押[お]すと縮[ちぢ]み、手[て]を離[はな]すと元[もと]の長[なが]さに戻[もど]る。", "sentence_source": "generated"}, {"text": "この椅子はスプリングが入っているので、座るとやわらかく沈む。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "この椅子[いす]はスプリングが入[はい]っているので、座[すわ]るとやわらかく沈[しず]む。", "sentence_source": "generated"}, {"text": "古い時計を分解したら、中から小さなスプリングが出てきた。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "古[ふる]い時計[とけい]を分解[ぶんかい]したら、中[なか]から小[ちい]さなスプリングが出[で]てきた。", "sentence_source": "generated"}, {"text": "自転車のサドルにはスプリングがついていて、道の揺れを和らげてくれる。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のサドルにはスプリングがついていて、道[みち]の揺[ゆ]れを和[やわ]らげてくれる。", "sentence_source": "generated"}, {"text": "スプリングが錆びてしまい、ドアがうまく閉まらなくなった。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "スプリングが錆[さ]びてしまい、ドアがうまく閉[し]まらなくなった。", "sentence_source": "generated"}, {"text": "工場では、強いスプリングを使って機械の部品を元の位置に戻している。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、強[つよ]いスプリングを使[つか]って機械[きかい]の部品[ぶひん]を元[もと]の位置[いち]に戻[もど]している。", "sentence_source": "generated"}, {"text": "おもちゃの中のスプリングが外れたので、お店で同じものを買ってきた。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "おもちゃの中[なか]のスプリングが外[はず]れたので、お店[みせ]で同[おな]じものを買[か]ってきた。", "sentence_source": "generated"}, {"text": "車のスプリングは、道のでこぼこから乗っている人を守る役目がある。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "車[くるま]のスプリングは、道[みち]のでこぼこから乗[の]っている人[ひと]を守[まも]る役目[やくめ]がある。", "sentence_source": "generated"}, {"text": "弟は、スプリングの力で飛び出すおもちゃを作って遊んでいた。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "弟[おとうと]は、スプリングの力[ちから]で飛[と]び出[だ]すおもちゃを作[つく]って遊[あそ]んでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スプリング", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "金属のバネ。ベッド・ペン・車などに入っていて、縮んでも元に戻る部品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53078, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スプリング", "is_correct": true, "explanation": "ベッド内部の金属のばねを指し、壊れて音がきしむ文脈に合う。"}, {"text": "枕", "is_correct": false, "explanation": "寝具だが、壊れて音がきしむ部品ではない。"}, {"text": "毛布", "is_correct": false, "explanation": "布製の寝具で、きしむ音の原因になる部品ではない。"}, {"text": "掛け布団", "is_correct": false, "explanation": "布団の一種で、ベッドの中の金属部品ではない。"}], "explanations": {"スプリング": "ベッド内部の金属のばねを指し、壊れて音がきしむ文脈に合う。", "枕": "寝具だが、壊れて音がきしむ部品ではない。", "毛布": "布製の寝具で、きしむ音の原因になる部品ではない。", "掛け布団": "布団の一種で、ベッドの中の金属部品ではない。"}, "sentence_index": 0, "correct_answer": "スプリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スプリングの季節に入ると、公園の桜がほころぶ。", "explanation": "ここは〈春〉の意味。金属のばねを指す文脈では使えない。"}, {"text": "スプリングがうまく噛み合わず、ペダルが空回りする。", "explanation": "ここは〈歯車〉の意味。スプリングは噛み合う部品ではないので使えない。"}, {"text": "スプリングを糸に通して、布の端を縫う。", "explanation": "ここは〈針〉の意味。スプリングは糸を通す道具ではないので、この文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53078, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スプリング", "is_correct": true, "explanation": "ばねの力で部品を元の位置に戻す部品で、『戻している』文脈に合う。"}, {"text": "油", "is_correct": false, "explanation": "潤滑に使う材料だが、部品を元の位置に戻す働きはない。"}, {"text": "布", "is_correct": false, "explanation": "拭くときに使う素材で、機械の部品を戻す働きはない。"}, {"text": "砂", "is_correct": false, "explanation": "機械の部品を戻す材料として使わず、文脈に合わない。"}], "explanations": {"スプリング": "ばねの力で部品を元の位置に戻す部品で、『戻している』文脈に合う。", "油": "潤滑に使う材料だが、部品を元の位置に戻す働きはない。", "布": "拭くときに使う素材で、機械の部品を戻す働きはない。", "砂": "機械の部品を戻す材料として使わず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "スプリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポンプでスプリングを入れると、タイヤがふくらむ。", "explanation": "ここは〈空気〉の意味。タイヤに入れるのは空気で、スプリングは金属のこまなので、入れる物には合わない。"}, {"text": "スプリングをひねると、水が出る。", "explanation": "ここは〈蛇口〉の意味。スプリングは水を出す部品ではないので使えない。"}, {"text": "スプリングが溶けて、飲み物が冷える。", "explanation": "ここは〈氷〉の意味。スプリングは溶けて冷やす材料ではないので、この文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53078, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペンのスプリングに縮むと、芯が引っ込む。", "corrected_sentence": "ペンのスプリングが縮むと、芯が引っ込む。", "error_description": "『縮む』は自動詞で主語は『が』。『に』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53078, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スプリングが錆びらないように、油を塗る。", "corrected_sentence": "スプリングが錆びないように、油を塗る。", "error_description": "『錆びる』は一段活用なので否定は『錆びない』。『錆びらない』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53103, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「訪れる」は行き先の場所を「〜を」で示すので、「島を訪れる」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「島に訪れる」とは言わない。「に」は到達点や存在を示す助詞で、この動詞の目的語には使えない。"}, {"text": "が", "is_correct": false, "explanation": "「島が訪れる」では島が主語になり、観光客が島へ行く文意と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「島と訪れる」は同行者を示す「と」になり、島を目的地とする文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「訪れる」は行き先の場所を「〜を」で示すので、「島を訪れる」が正しい。", "に": "「島に訪れる」とは言わない。「に」は到達点や存在を示す助詞で、この動詞の目的語には使えない。", "が": "「島が訪れる」では島が主語になり、観光客が島へ行く文意と合わない。", "と": "「島と訪れる」は同行者を示す「と」になり、島を目的地とする文として成り立たない。"}, "error_tags": {"に": "方向・到着点", "が": "主語", "と": "相手・同行"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53103, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人が訪れる」で、訪れる側の人を主語として示す。"}, {"text": "で", "is_correct": false, "explanation": "「人で訪れる」は手段や場所を表す「で」になり、人を主語にできない。"}, {"text": "へ", "is_correct": false, "explanation": "「人へ訪れる」は方向を表す「へ」になり、人は行き先にならない。"}, {"text": "を", "is_correct": false, "explanation": "「人を訪れる」は人を目的語にする用法で、「訪れる」は場所に使うので不自然。"}], "correct_answer": "が", "explanations": {"が": "「人が訪れる」で、訪れる側の人を主語として示す。", "で": "「人で訪れる」は手段や場所を表す「で」になり、人を主語にできない。", "へ": "「人へ訪れる」は方向を表す「へ」になり、人は行き先にならない。", "を": "「人を訪れる」は人を目的語にする用法で、「訪れる」は場所に使うので不自然。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "を": "目的語（場所以外）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53103, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所へ出かけて行くこと。", "primary_collocate": null, "pronunciation": "おとずれる", "ipa": "otozɯɾeɾɯ", "syllable_count": 5, "sentences": [{"text": "夏休みに、家族で京都を訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、家族[かぞく]で京都[きょうと]を訪[おとず]れた。", "sentence_source": "generated"}, {"text": "毎年、多くの観光客がこの島を訪れる。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "毎年[まいとし]、多[おお]くの観光客[かんこうきゃく]がこの島[しま]を訪[おとず]れる。", "sentence_source": "generated"}, {"text": "祖母の町を訪れるのは十年ぶりだ。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "祖母[そぼ]の町[まち]を訪[おとず]れるのは十年[じゅうねん]ぶりだ。", "sentence_source": "generated"}, {"text": "雨の日でも、美術館を訪れる人は多い。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]でも、美術館[びじゅつかん]を訪[おとず]れる人[ひと]は多[おお]い。", "sentence_source": "generated"}, {"text": "初めて訪れた国で、道に迷ってしまった。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "初[はじ]めて訪[おとず]れた国[くに]で、道[みち]に迷[まよ]ってしまった。", "sentence_source": "generated"}, {"text": "週末は友達と古いお寺を訪れる予定だ。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は友達[ともだち]と古[ふる]いお寺[てら]を訪[おとず]れる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "外国から訪れた学生に、町を案内した。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "外国[がいこく]から訪[おとず]れた学生[がくせい]に、町[まち]を案内[あんない]した。", "sentence_source": "generated"}, {"text": "この湖は、春になるとたくさんの人が訪れる。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "この湖[みずうみ]は、春[はる]になるとたくさんの人[ひと]が訪[おとず]れる。", "sentence_source": "generated"}, {"text": "出張で訪れた町の料理がとてもおいしかった。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "出張[しゅっちょう]で訪[おとず]れた町[まち]の料理[りょうり]がとてもおいしかった。", "sentence_source": "generated"}, {"text": "有名な滝を訪れたが、霧で何も見えなかった。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な滝[たき]を訪[おとず]れたが、霧[きり]で何[なに]も見[み]えなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "訪れる", "label": "終止形"}, {"form": "訪れた", "label": "過去形"}, {"form": "訪れない", "label": "否定形"}, {"form": "訪れて", "label": "て形"}, {"form": "訪れれば", "label": "仮定形"}], "register": "常体（中立）", "sense_fingerprint": "観光や用事である場所へ出かけて行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53103, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "過去の終止形で、「夏休みに家族で京都を訪れた」と文が言い切りの形で完結する。"}, {"text": "眠った", "is_correct": false, "explanation": "「眠る」は自動詞で「京都を」を目的語にとれないため、文が成り立たない。"}, {"text": "笑った", "is_correct": false, "explanation": "「笑う」も自動詞で「京都を」と続けられず、文意が通らない。"}, {"text": "泣いた", "is_correct": false, "explanation": "「泣く」は自動詞で「京都を」を取らないため、文が成り立たない。"}], "explanations": {"訪れた": "過去の終止形で、「夏休みに家族で京都を訪れた」と文が言い切りの形で完結する。", "眠った": "「眠る」は自動詞で「京都を」を目的語にとれないため、文が成り立たない。", "笑った": "「笑う」も自動詞で「京都を」と続けられず、文意が通らない。", "泣いた": "「泣く」は自動詞で「京都を」を取らないため、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "訪れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先週、新幹線を訪れた。", "explanation": "ここは〈乗る〉の意味。新幹線は場所ではなく乗り物なので、目的語に「訪れる」は使えない。"}, {"text": "春が、ようやく訪れた。", "explanation": "ここは〈到来する〉の意味。春が来る意味で、場所へ行く意味とは違うので合わない。"}, {"text": "貴重な体験を訪れた。", "explanation": "ここは〈体験する〉の意味。体験は場所ではないので、目的語に「訪れる」を使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53103, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "連体修飾の過去形で、「外国から訪れた学生」と名詞を修飾する。"}, {"text": "訪れて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「外国から訪れて学生に」と続かない。"}, {"text": "訪れよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、ここでは文が成り立たない。"}, {"text": "訪れれば", "is_correct": false, "explanation": "仮定形は「〜ば」で文を続ける形で、名詞を修飾できない。"}], "explanations": {"訪れた": "連体修飾の過去形で、「外国から訪れた学生」と名詞を修飾する。", "訪れて": "て形は名詞を修飾できず、「外国から訪れて学生に」と続かない。", "訪れよう": "意志形は名詞を修飾できず、ここでは文が成り立たない。", "訪れれば": "仮定形は「〜ば」で文を続ける形で、名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "訪れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大事な契約を訪れた。", "explanation": "ここは〈契約を結ぶ〉の意味。契約は場所ではないので、目的語に「訪れる」は使えない。"}, {"text": "週末は友達と買い物を訪れた。", "explanation": "ここは〈買い物に出かける〉の意味。買い物は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "新しい仕事を訪れた。", "explanation": "ここは〈仕事を引き受ける〉の意味。仕事は場所ではないので、目的語に「訪れる」を使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53103, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、家族で大阪に訪れた。", "corrected_sentence": "先週、家族で大阪を訪れた。", "error_description": "「訪れる」は行き先の場所を目的語にとるので「大阪を」が正しい。「大阪に」は到達点の「に」で、この動詞の目的語を示せていない。正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "訪れる", "is_correct": true, "explanation": "毎年の習慣を述べる文末の終止形で、文意に合う。"}, {"text": "訪れろ", "is_correct": false, "explanation": "命令形になり、事実を述べる文末に合わない。"}, {"text": "訪れない", "is_correct": false, "explanation": "否定形になり、観光客が来ないという意味に変わってしまう。"}, {"text": "訪れて", "is_correct": false, "explanation": "て形は文を終えられないため、文末に置けない。"}], "correct_form": "訪れる", "base_form": "訪れる", "form_label": "終止形", "sentence_index": 1, "explanations": {"訪れる": "毎年の習慣を述べる文末の終止形で、文意に合う。", "訪れろ": "命令形になり、事実を述べる文末に合わない。", "訪れない": "否定形になり、観光客が来ないという意味に変わってしまう。", "訪れて": "て形は文を終えられないため、文末に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53103, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨年、家族で奈良を訪れて。", "corrected_sentence": "昨年、家族で奈良を訪れた。", "error_description": "文末に「訪れて」（て形）が置かれており、文が終わっていない。過去の出来事を言い切る文末なので、過去形「訪れた」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "訪れる", "is_correct": true, "explanation": "春になると毎年起こる出来事を述べる文末の終止形で、文意に合う。"}, {"text": "訪れれば", "is_correct": false, "explanation": "仮定形は「〜ば」で続く形で、文を言い切れないため文末に置けない。"}, {"text": "訪れよう", "is_correct": false, "explanation": "意志形になり「〜しよう」の意味になるので、人が訪れるという事実を述べられない。"}, {"text": "訪れろ", "is_correct": false, "explanation": "命令形になり、事実を述べる文末に合わない。"}], "correct_form": "訪れる", "base_form": "訪れる", "form_label": "終止形", "sentence_index": 7, "explanations": {"訪れる": "春になると毎年起こる出来事を述べる文末の終止形で、文意に合う。", "訪れれば": "仮定形は「〜ば」で続く形で、文を言い切れないため文末に置けない。", "訪れよう": "意志形になり「〜しよう」の意味になるので、人が訪れるという事実を述べられない。", "訪れろ": "命令形になり、事実を述べる文末に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53104, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53104, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「チャンスが訪れた」で、チャンスを主語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "「チャンスへ訪れた」は方向を表す「へ」になり、チャンスは到達点にならない。"}, {"text": "と", "is_correct": false, "explanation": "「チャンスと訪れた」は同行を示す「と」になり、主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「チャンスより訪れた」は比較や起点を示す「より」になり、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「チャンスが訪れた」で、チャンスを主語として示す。", "へ": "「チャンスへ訪れた」は方向を表す「へ」になり、チャンスは到達点にならない。", "と": "「チャンスと訪れた」は同行を示す「と」になり、主語を示せない。", "より": "「チャンスより訪れた」は比較や起点を示す「より」になり、主語にならない。"}, "error_tags": {"へ": "方向", "と": "相手・同行", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53104, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "特定の場所へ行き会うこと。また、時や出来事が起こること。", "primary_collocate": null, "pronunciation": "おとずれる", "ipa": "otozɯɾeɾɯ", "syllable_count": 5, "sentences": [{"text": "休みを利用して、沖縄の海を訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "休[やす]みを利用[りよう]して、沖縄[おきなわ]の海[うみ]を訪[おとず]れた。", "sentence_source": "generated"}, {"text": "長い冬が終わり、この町にも春が訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "長[なが]い冬[ふゆ]が終[お]わり、この町[まち]にも春[はる]が訪[おとず]れた。", "sentence_source": "generated"}, {"text": "毎年、世界中から人々が古い城を訪れる。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "毎年[まいとし]、世界中[せかいじゅう]から人々[ひとびと]が古[ふる]い城[しろ]を訪[おとず]れる。", "sentence_source": "generated"}, {"text": "突然の別れが、二人に訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "突然[とつぜん]の別[わか]れが、二人[ふたり]に訪[おとず]れた。", "sentence_source": "generated"}, {"text": "結婚してから、彼女にようやく幸せが訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "結婚[けっこん]してから、彼女[かのじょ]にようやく幸[しあわ]せが訪[おとず]れた。", "sentence_source": "generated"}, {"text": "修学旅行で訪れた寺は、今も心に残っている。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "修学旅行[しゅうがくりょこう]で訪[おとず]れた寺[てら]は、今[いま]も心[こころ]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "研究者たちは、遠い島の遺跡を訪れて調査した。", "target_word": "訪れて", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]たちは、遠[とお]い島[しま]の遺跡[いせき]を訪[おとず]れて調査[ちょうさ]した。", "sentence_source": "generated"}, {"text": "努力を続けた彼に、ついにチャンスが訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "努力[どりょく]を続[つづ]けた彼[かれ]に、ついにチャンスが訪[おとず]れた。", "sentence_source": "generated"}, {"text": "朝の市場を訪れると、新鮮な魚が並んでいた。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "朝[あさ]の市場[いちば]を訪[おとず]れると、新鮮[しんせん]な魚[さかな]が並[なら]んでいた。", "sentence_source": "generated"}, {"text": "世界に平和が訪れることを、みんなが願っている。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "世界[せかい]に平和[へいわ]が訪[おとず]れることを、みんなが願[ねが]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "訪れる", "label": "終止形"}, {"form": "訪れた", "label": "過去形"}, {"form": "訪れない", "label": "否定形"}, {"form": "訪れて", "label": "て形"}, {"form": "訪れれば", "label": "仮定形"}], "register": "常体（中立）", "sense_fingerprint": "場所へ出かけて行く。また、時や出来事がやって来る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53104, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "過去の終止形で、「沖縄の海を訪れた」と行動を言い切る。"}, {"text": "眠った", "is_correct": false, "explanation": "自動詞「眠る」は「海を」を目的語にとれず、文が成り立たない。"}, {"text": "踊った", "is_correct": false, "explanation": "「踊る」も「海を」と続けられず、文意が通らない。"}, {"text": "泣いた", "is_correct": false, "explanation": "自動詞「泣く」は「海を」を取らないため、文が成り立たない。"}], "explanations": {"訪れた": "過去の終止形で、「沖縄の海を訪れた」と行動を言い切る。", "眠った": "自動詞「眠る」は「海を」を目的語にとれず、文が成り立たない。", "踊った": "「踊る」も「海を」と続けられず、文意が通らない。", "泣いた": "自動詞「泣く」は「海を」を取らないため、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "訪れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借りた本を訪れた。", "explanation": "ここは〈本を読む〉の意味。本は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "放課後、散歩を訪れた。", "explanation": "ここは〈散歩に出かける〉の意味。散歩は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "荷物が訪れた。", "explanation": "ここは〈荷物が届く〉の意味。品物が届くことには「訪れる」は使えないので、この語義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53104, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "訪れて", "is_correct": true, "explanation": "て形で、「遺跡を訪れて」から「調査した」へ動作を続けられる。"}, {"text": "訪れた", "is_correct": false, "explanation": "過去の終止形は「訪れた調査した」と続かず、文が成り立たない。"}, {"text": "訪れる", "is_correct": false, "explanation": "終止形は後ろの「調査した」と続けられず、文意が通らない。"}, {"text": "訪れない", "is_correct": false, "explanation": "否定形は「訪れない調査した」となり、意味が通らない。"}], "explanations": {"訪れて": "て形で、「遺跡を訪れて」から「調査した」へ動作を続けられる。", "訪れた": "過去の終止形は「訪れた調査した」と続かず、文が成り立たない。", "訪れる": "終止形は後ろの「調査した」と続けられず、文意が通らない。", "訪れない": "否定形は「訪れない調査した」となり、意味が通らない。"}, "sentence_index": 6, "correct_answer": "訪れて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この本の内容を訪れた。", "explanation": "ここは〈内容を理解する〉の意味。内容は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "夜になると、明かりを訪れた。", "explanation": "ここは〈明かりをつける〉の意味。明かりは場所ではないので、目的語に「訪れる」は使えない。"}, {"text": "朝、電車を訪れた。", "explanation": "ここは〈電車に乗る〉の意味。乗り物は場所ではないので、目的語に「訪れる」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53104, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先月、友達と箱根を訪れて。", "corrected_sentence": "先月、友達と箱根を訪れた。", "error_description": "文末に「訪れて」（て形）が置かれており、文が終わっていない。過去の出来事を言い切る文末なので、過去形「訪れた」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "冬が終わったあとに春が来たという既に起きた出来事を表す過去形で、文意に合う。"}, {"text": "訪れよう", "is_correct": false, "explanation": "意志形になり、「春が訪れよう」は文末として成り立たず、既に起きた出来事を表せない。"}, {"text": "訪れない", "is_correct": false, "explanation": "否定形になり、春が来なかったという意味に変わってしまう。"}, {"text": "訪れて", "is_correct": false, "explanation": "て形は文を終えられないため、文末に置けない。"}], "correct_form": "訪れた", "base_form": "訪れる", "form_label": "過去形", "sentence_index": 1, "explanations": {"訪れた": "冬が終わったあとに春が来たという既に起きた出来事を表す過去形で、文意に合う。", "訪れよう": "意志形になり、「春が訪れよう」は文末として成り立たず、既に起きた出来事を表せない。", "訪れない": "否定形になり、春が来なかったという意味に変わってしまう。", "訪れて": "て形は文を終えられないため、文末に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53104, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、祖父と沖縄へ訪れた。", "corrected_sentence": "先週、祖父と沖縄を訪れた。", "error_description": "「訪れる」は行き先の場所を「〜を」で示すので、方向を表す「へ」は誤り。正しくは「沖縄を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "過去形で、努力の末にチャンスが到来した出来事を言い切る。"}, {"text": "訪れれば", "is_correct": false, "explanation": "仮定形は文を言い切れず、文末に置けない。"}, {"text": "訪れよう", "is_correct": false, "explanation": "意志形になり「チャンスが訪れよう」と言えず、既に起きた出来事を表せない。"}, {"text": "訪れます", "is_correct": false, "explanation": "丁寧語になり、この常体の文と文体が合わない。"}], "correct_form": "訪れた", "base_form": "訪れる", "form_label": "過去形", "sentence_index": 7, "explanations": {"訪れた": "過去形で、努力の末にチャンスが到来した出来事を言い切る。", "訪れれば": "仮定形は文を言い切れず、文末に置けない。", "訪れよう": "意志形になり「チャンスが訪れよう」と言えず、既に起きた出来事を表せない。", "訪れます": "丁寧語になり、この常体の文と文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53105, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慌ただしい", "is_correct": true, "explanation": "落ち着かず慌てる様子を表し、慌てない「穏やか」と反対になる。"}, {"text": "静か", "is_correct": false, "explanation": "「穏やか」に近い意味で、反対ではない。"}, {"text": "優しい", "is_correct": false, "explanation": "「穏やか」に近い印象の語で、反対ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "「穏やか」の反対ではない。"}], "correct_answer": "慌ただしい", "explanations": {"慌ただしい": "落ち着かず慌てる様子を表し、慌てない「穏やか」と反対になる。", "静か": "「穏やか」に近い意味で、反対ではない。", "優しい": "「穏やか」に近い印象の語で、反対ではない。", "丁寧": "「穏やか」の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53105, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慌てた", "is_correct": true, "explanation": "地震で落ち着きを失う様子を表し、穏やかだったのと反対になる。"}, {"text": "静かだった", "is_correct": false, "explanation": "「穏やか」に近い意味で、反対ではない。"}, {"text": "優しかった", "is_correct": false, "explanation": "性格を表す語で、「穏やか」の反対ではない。"}, {"text": "元気だった", "is_correct": false, "explanation": "体調の様子を表し、「穏やか」の反対ではない。"}], "correct_answer": "慌てた", "explanations": {"慌てた": "地震で落ち着きを失う様子を表し、穏やかだったのと反対になる。", "静かだった": "「穏やか」に近い意味で、反対ではない。", "優しかった": "性格を表す語で、「穏やか」の反対ではない。", "元気だった": "体調の様子を表し、「穏やか」の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53105, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "こころがしずかで、あわてないことです。", "primary_collocate": null, "pronunciation": "おだやか", "ipa": "odajaka", "syllable_count": 4, "sentences": [{"text": "彼は穏やかな人です。", "target_word": "穏やかな", "complexity_tier": "T2", "furigana": "彼(かれ)は穏(おだ)やかな人(ひと)です。", "sentence_source": "generated"}, {"text": "父は穏やかです。", "target_word": "穏やかです", "complexity_tier": "T2", "furigana": "父(ちち)は穏(おだ)やかです。", "sentence_source": "generated"}, {"text": "穏やかに話します。", "target_word": "穏やかに", "complexity_tier": "T2", "furigana": "穏(おだ)やかに話(はな)します。", "sentence_source": "generated"}, {"text": "母はいつも穏やかです。", "target_word": "穏やかです", "complexity_tier": "T2", "furigana": "母(はは)はいつも穏(おだ)やかです。", "sentence_source": "generated"}, {"text": "穏やかな気持ちで寝ました。", "target_word": "穏やかな", "complexity_tier": "T2", "furigana": "穏(おだ)やかな気持(きも)ちで寝(ね)ました。", "sentence_source": "generated"}, {"text": "先生は穏やかに笑いました。", "target_word": "穏やかに", "complexity_tier": "T2", "furigana": "先生(せんせい)は穏(おだ)やかに笑(わら)いました。", "sentence_source": "generated"}, {"text": "私は穏やかになりました。", "target_word": "穏やかに", "complexity_tier": "T2", "furigana": "私(わたし)は穏(おだ)やかになりました。", "sentence_source": "generated"}, {"text": "穏やかな声で話しています。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "穏(おだ)やかな声(こえ)で話(はな)しています。", "sentence_source": "generated"}, {"text": "彼女は穏やかで、あわてません。", "target_word": "穏やかで", "complexity_tier": "T2", "furigana": "彼女(かのじょ)は穏(おだ)やかで、あわてません。", "sentence_source": "generated"}, {"text": "地震のときも、彼は穏やかだった。", "target_word": "穏やかだった", "complexity_tier": "T3", "furigana": "地震(じしん)のときも、彼(かれ)は穏(おだ)やかだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穏やかな", "label": "活用"}, {"form": "穏やかに", "label": "活用"}, {"form": "穏やかだ", "label": "活用"}, {"form": "穏やかさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 心が静かで慌てず落ち着いたさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53105, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「穏やかな人」で、心が静かで慌てない人柄を表す。"}, {"text": "新鮮な", "is_correct": false, "explanation": "形は合うが、人柄を表す語として意味が合わない。"}, {"text": "滑らかな", "is_correct": false, "explanation": "形は合うが、人柄を表す語として意味が合わない。"}, {"text": "鮮やかな", "is_correct": false, "explanation": "形は合うが、人を修飾する語として意味が合わない。"}], "explanations": {"穏やかな": "「穏やかな人」で、心が静かで慌てない人柄を表す。", "新鮮な": "形は合うが、人柄を表す語として意味が合わない。", "滑らかな": "形は合うが、人柄を表す語として意味が合わない。", "鮮やかな": "形は合うが、人を修飾する語として意味が合わない。"}, "sentence_index": 0, "correct_answer": "穏やかな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このかばんはいつも穏やかです。", "explanation": "「穏やか」は物のかばんの性質を表す語ではないので誤り。"}, {"text": "このテストはとても穏やかで、満点は無理です。", "explanation": "「穏やか」はテストの難しさを表す語ではないので誤り。"}, {"text": "この道はいつも穏やかで、とても長いです。", "explanation": "「穏やか」は道の長さを表す語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53105, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穏やかに", "is_correct": true, "explanation": "「穏やかになる」で、心が静かで落ち着いた状態への変化を表す。"}, {"text": "鮮やかに", "is_correct": false, "explanation": "形は合うが、人が主語だと意味が合わない。"}, {"text": "新鮮に", "is_correct": false, "explanation": "形は合うが、人の状態の変化として意味が合わない。"}, {"text": "滑らかに", "is_correct": false, "explanation": "形は合うが、人の状態の変化として意味が合わない。"}], "explanations": {"穏やかに": "「穏やかになる」で、心が静かで落ち着いた状態への変化を表す。", "鮮やかに": "形は合うが、人が主語だと意味が合わない。", "新鮮に": "形は合うが、人の状態の変化として意味が合わない。", "滑らかに": "形は合うが、人の状態の変化として意味が合わない。"}, "sentence_index": 6, "correct_answer": "穏やかに"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震のときも、この机は穏やかだった。", "explanation": "「穏やか」は机の性質を表す語ではないので誤り。"}, {"text": "地震のときも、彼は穏やかに大声で叫んだ。", "explanation": "大声で叫ぶのは慌てた様子で、「穏やか」と矛盾するので誤り。"}, {"text": "地震のとき、彼の部屋は穏やかで、本が全部落ちた。", "explanation": "本が全部落ちるほど揺れた様子と「穏やか」が矛盾するので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53105, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "穏やかな箱を机に置きました。", "corrected_sentence": "小さな箱を机に置きました。", "error_description": "「穏やか」は箱の性質を表す語ではないので不適切。「小さな」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "穏やかです", "is_correct": true, "explanation": "文末で「父は穏やかです」と述べる丁寧な述語の形。"}, {"text": "穏やかな", "is_correct": false, "explanation": "連体形なので、文末の述語としては使えない。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形なので、「父は」の述語として文が終わらない。"}, {"text": "穏やかで", "is_correct": false, "explanation": "中止形なので、ここで文が終わらず不完全になる。"}], "correct_form": "穏やかです", "base_form": "穏やか", "form_label": "終止形（丁寧）", "sentence_index": 1, "explanations": {"穏やかです": "文末で「父は穏やかです」と述べる丁寧な述語の形。", "穏やかな": "連体形なので、文末の述語としては使えない。", "穏やかに": "連用形なので、「父は」の述語として文が終わらない。", "穏やかで": "中止形なので、ここで文が終わらず不完全になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53105, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地震のとき、彼は穏やかに悲鳴を上げた。", "corrected_sentence": "地震のとき、彼は慌てて悲鳴を上げた。", "error_description": "悲鳴を上げるのは慌てた行動で、「穏やかに」と矛盾する。「慌てて」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「声」を修飾する連体形で、空所に合う。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形なので、名詞「声」を直接修飾できない。"}, {"text": "穏やかだ", "is_correct": false, "explanation": "終止形なので、名詞「声」の前では使えない。"}, {"text": "穏やかで", "is_correct": false, "explanation": "中止形なので、「声」を直接修飾できない。"}], "correct_form": "穏やかな", "base_form": "穏やか", "form_label": "連体形", "sentence_index": 7, "explanations": {"穏やかな": "「声」を修飾する連体形で、空所に合う。", "穏やかに": "連用形なので、名詞「声」を直接修飾できない。", "穏やかだ": "終止形なので、名詞「声」の前では使えない。", "穏やかで": "中止形なので、「声」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53106, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "荒々しい", "is_correct": true, "explanation": "態度が乱暴で激しいさまで、穏やかの反対。"}, {"text": "静か", "is_correct": false, "explanation": "穏やかに近い意味で、反対ではない。"}, {"text": "優しい", "is_correct": false, "explanation": "穏やかと近い意味で、反対ではない。"}, {"text": "立派", "is_correct": false, "explanation": "穏やかとは別の観点の語で、反対ではない。"}], "correct_answer": "荒々しい", "explanations": {"荒々しい": "態度が乱暴で激しいさまで、穏やかの反対。", "静か": "穏やかに近い意味で、反対ではない。", "優しい": "穏やかと近い意味で、反対ではない。", "立派": "穏やかとは別の観点の語で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53106, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "激しい", "is_correct": true, "explanation": "勢いが強く荒いさまで、穏やかの反対。"}, {"text": "安らか", "is_correct": false, "explanation": "穏やかに近い意味で、反対ではない。"}, {"text": "素直", "is_correct": false, "explanation": "穏やかとは別の観点の語で、反対ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "穏やかとは別の観点の語で、反対ではない。"}], "correct_answer": "激しい", "explanations": {"激しい": "勢いが強く荒いさまで、穏やかの反対。", "安らか": "穏やかに近い意味で、反対ではない。", "素直": "穏やかとは別の観点の語で、反対ではない。", "丁寧": "穏やかとは別の観点の語で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53106, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "気分や態度、状況などが落ち着いていて、荒々しくなく平穏なさま。", "primary_collocate": null, "pronunciation": "おだやか", "ipa": "odajaka", "syllable_count": 4, "sentences": [{"text": "嵐のあとの海は穏やかだった。", "target_word": "穏やかだった", "complexity_tier": "T3", "furigana": "嵐(あらし)のあとの海(うみ)は穏(おだ)やかだった。", "sentence_source": "generated"}, {"text": "穏やかな天気が数日続いている。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "穏(おだ)やかな天気(てんき)が数日(すうじつ)続(つづ)いている。", "sentence_source": "generated"}, {"text": "会議は穏やかな雰囲気で進んだ。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "会議(かいぎ)は穏(おだ)やかな雰囲気(ふんいき)で進(すす)んだ。", "sentence_source": "generated"}, {"text": "彼は穏やかな態度で相手に接した。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "彼(かれ)は穏(おだ)やかな態度(たいど)で相手(あいて)に接(せっ)した。", "sentence_source": "generated"}, {"text": "交渉は穏やかに終わった。", "target_word": "穏やかに", "complexity_tier": "T2", "furigana": "交渉(こうしょう)は穏(おだ)やかに終(お)わった。", "sentence_source": "generated"}, {"text": "波が穏やかなので、船は静かに進む。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "波(なみ)が穏(おだ)やかなので、船(ふね)は静(しず)かに進(すす)む。", "sentence_source": "generated"}, {"text": "荒れていた市場も、今は穏やかになった。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "荒(あ)れていた市場(しじょう)も、今(いま)は穏(おだ)やかになった。", "sentence_source": "generated"}, {"text": "新しい社長は穏やかで、社員の信頼が厚い。", "target_word": "穏やかで", "complexity_tier": "T3", "furigana": "新(あたら)しい社長(しゃちょう)は穏(おだ)やかで、社員(しゃいん)の信頼(しんらい)が厚(あつ)い。", "sentence_source": "generated"}, {"text": "両国は穏やかな関係を保っている。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "両国(りょうこく)は穏(おだ)やかな関係(かんけい)を保(たも)っている。", "sentence_source": "generated"}, {"text": "穏やかに見えても、心の中は不安だった。", "target_word": "穏やかに", "complexity_tier": "T4", "furigana": "穏(おだ)やかに見(み)えても、心(こころ)の中(なか)は不安(ふあん)だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穏やかな", "label": "活用"}, {"form": "穏やかに", "label": "活用"}, {"form": "穏やかだ", "label": "活用"}, {"form": "穏やかさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 態度や状況が荒れず平穏なさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53106, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穏やかだった", "is_correct": true, "explanation": "嵐のあとで海が荒れていない様子を表し、文意に合う。"}, {"text": "派手だった", "is_correct": false, "explanation": "形は合うが、嵐のあとの海の様子としては意味が合わない。"}, {"text": "正直だった", "is_correct": false, "explanation": "形は合うが、海に人の性格は使えず意味が合わない。"}, {"text": "勝手だった", "is_correct": false, "explanation": "形は合うが、海の状態として意味が合わない。"}], "explanations": {"穏やかだった": "嵐のあとで海が荒れていない様子を表し、文意に合う。", "派手だった": "形は合うが、嵐のあとの海の様子としては意味が合わない。", "正直だった": "形は合うが、海に人の性格は使えず意味が合わない。", "勝手だった": "形は合うが、海の状態として意味が合わない。"}, "sentence_index": 0, "correct_answer": "穏やかだった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "穏やかな声で、彼は大声で怒鳴りつけた。", "explanation": "「穏やかな声」と「怒鳴りつけた」が矛盾しており、穏やかの意味に反する。"}, {"text": "机の上に穏やかなコップが三つ並んでいる。", "explanation": "穏やかは物の形状には使えず、コップを修飾するのは誤り。"}, {"text": "穏やかな火事が町じゅうを焼き尽くした。", "explanation": "町を焼き尽くす火事は荒々しいもので、穏やかとは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53106, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穏やかに", "is_correct": true, "explanation": "荒れていた市場が落ち着いた状態になったという意味に合う。"}, {"text": "勝手に", "is_correct": false, "explanation": "形は合うが、市場が落ち着いたという意味にならない。"}, {"text": "余計に", "is_correct": false, "explanation": "形は合うが、荒れていたことの対比として意味が合わない。"}, {"text": "無駄に", "is_correct": false, "explanation": "形は合うが、文脈に意味が合わない。"}], "explanations": {"穏やかに": "荒れていた市場が落ち着いた状態になったという意味に合う。", "勝手に": "形は合うが、市場が落ち着いたという意味にならない。", "余計に": "形は合うが、荒れていたことの対比として意味が合わない。", "無駄に": "形は合うが、文脈に意味が合わない。"}, "sentence_index": 6, "correct_answer": "穏やかに"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "穏やかな試験が難しすぎて、全員が不合格だった。", "explanation": "穏やかは試験の難しさを表せず、用法が誤り。"}, {"text": "彼は穏やかに叫びながら暴れ回った。", "explanation": "叫んで暴れる様子は荒々しく、穏やかとは矛盾する。"}, {"text": "穏やかな電車で会社まで急いで向かった。", "explanation": "穏やかは電車の性質を表さず、急ぐ文脈とも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53106, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は風が穏やかの日だ。", "corrected_sentence": "今日は風が穏やかな日だ。", "error_description": "「穏やか」は名詞を修飾するとき「穏やかな」となり、「穏やかの」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "名詞「天気」を修飾する連体形で、空所に合う。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形で、名詞「天気」を直接修飾できない。"}, {"text": "穏やかだ", "is_correct": false, "explanation": "終止形で、名詞の前には置けない。"}, {"text": "穏やかさ", "is_correct": false, "explanation": "名詞形で、「天気」の前に置くと意味が通らない。"}], "correct_form": "穏やかな", "base_form": "穏やか", "form_label": "連体形", "sentence_index": 1, "explanations": {"穏やかな": "名詞「天気」を修飾する連体形で、空所に合う。", "穏やかに": "連用形で、名詞「天気」を直接修飾できない。", "穏やかだ": "終止形で、名詞の前には置けない。", "穏やかさ": "名詞形で、「天気」の前に置くと意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53106, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は穏やかに人だ。", "corrected_sentence": "彼女は穏やかな人だ。", "error_description": "名詞「人」を修飾するには「穏やかな」とすべきで、「穏やかに」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "穏やかで", "is_correct": true, "explanation": "「穏やかで、」と述語を中止形でつなぐ形で空所に合う。"}, {"text": "穏やかな", "is_correct": false, "explanation": "連体形で、後に名詞が必要なため読点の前では不自然。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形で、「社長は」の述語としてつながらない。"}, {"text": "穏やかさ", "is_correct": false, "explanation": "名詞形で、「社長は穏やかさ、」では文が成り立たない。"}], "correct_form": "穏やかで", "base_form": "穏やか", "form_label": "連用中止形(で)", "sentence_index": 7, "explanations": {"穏やかで": "「穏やかで、」と述語を中止形でつなぐ形で空所に合う。", "穏やかな": "連体形で、後に名詞が必要なため読点の前では不自然。", "穏やかに": "連用形で、「社長は」の述語としてつながらない。", "穏やかさ": "名詞形で、「社長は穏やかさ、」では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
