INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53109, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "おなかにできた赤ちゃんやたまごを、外に出すことです。", "primary_collocate": null, "pronunciation": "うむ", "ipa": "ɯmɯ", "syllable_count": 2, "sentences": [{"text": "母猫が五匹の子猫を産んだ。", "target_word": "産んだ", "complexity_tier": "T3", "furigana": "母猫[ははねこ]が五匹[ごひき]の子猫[こねこ]を産[う]んだ。", "sentence_source": "generated"}, {"text": "姉は先月、元気な男の子を産みました。", "target_word": "産みました", "complexity_tier": "T3", "furigana": "姉[あね]は先月[せんげつ]、元気[げんき]な男[おとこ]の子[こ]を産[う]みました。", "sentence_source": "generated"}, {"text": "ウミガメは夜の砂浜で卵を産む。", "target_word": "産む", "complexity_tier": "T3", "furigana": "ウミガメは夜[よる]の砂浜[すなはま]で卵[たまご]を産[う]む。", "sentence_source": "generated"}, {"text": "このにわとりは毎日卵を産むので、朝ごはんに困らない。", "target_word": "産む", "complexity_tier": "T3", "furigana": "このにわとりは毎日[まいにち]卵[たまご]を産[う]むので、朝[あさ]ごはんに困[こま]らない。", "sentence_source": "generated"}, {"text": "彼女は病院で女の子を産むことになっている。", "target_word": "産む", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は病院[びょういん]で女[おんな]の子[こ]を産[う]むことになっている。", "sentence_source": "generated"}, {"text": "親鳥が巣に卵を産み、静かに温めている。", "target_word": "産み", "complexity_tier": "T3", "furigana": "親鳥[おやどり]が巣[す]に卵[たまご]を産[う]み、静[しず]かに温[あたた]めている。", "sentence_source": "generated"}, {"text": "犬が子犬を産んだので、家族みんなで世話をした。", "target_word": "産んだ", "complexity_tier": "T3", "furigana": "犬[いぬ]が子犬[こいぬ]を産[う]んだので、家族[かぞく]みんなで世話[せわ]をした。", "sentence_source": "generated"}, {"text": "母は私を産んだとき、とても若かったそうだ。", "target_word": "産んだ", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]を産[う]んだとき、とても若[わか]かったそうだ。", "sentence_source": "generated"}, {"text": "鮭は川に戻って卵を産むと、その一生を終える。", "target_word": "産む", "complexity_tier": "T3", "furigana": "鮭[さけ]は川[かわ]に戻[もど]って卵[たまご]を産[う]むと、その一生[いっしょう]を終[お]える。", "sentence_source": "generated"}, {"text": "動物園のパンダが赤ちゃんを産み、ニュースになった。", "target_word": "産み", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]のパンダが赤[あか]ちゃんを産[う]み、ニュースになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "産む", "label": "辞書形"}, {"form": "産み", "label": "連用形"}, {"form": "産んだ", "label": "た形"}, {"form": "産まない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "子や卵を体の外に出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37ab8850-c41b-4109-8a15-341fe09879d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53109, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "産んだ", "is_correct": true, "explanation": "正解。「子猫を産んだ」は、母猫が子を生んだという意味で自然。"}, {"text": "泳いだ", "is_correct": false, "explanation": "「子猫を泳いだ」は成り立たない。「泳ぐ」は目的語を取らない動詞。"}, {"text": "曇った", "is_correct": false, "explanation": "「子猫を曇った」は意味をなさない。「曇る」は目的語を取らない。"}, {"text": "光った", "is_correct": false, "explanation": "「子猫を光った」は不自然。「光る」は目的語を取らない動詞。"}], "explanations": {"産んだ": "正解。「子猫を産んだ」は、母猫が子を生んだという意味で自然。", "泳いだ": "「子猫を泳いだ」は成り立たない。「泳ぐ」は目的語を取らない動詞。", "曇った": "「子猫を曇った」は意味をなさない。「曇る」は目的語を取らない。", "光った": "「子猫を光った」は不自然。「光る」は目的語を取らない動詞。"}, "sentence_index": 0, "correct_answer": "産んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭に苗を産んで、夏に野菜を収穫した。", "explanation": "ここは〈植える〉の意味。苗は植えるもので、産むのは子や卵など生き物の体外排出。"}, {"text": "母はパンを産んで、家族に配った。", "explanation": "ここは〈作る〉の意味。パンは作るもので、産むものではない。"}, {"text": "積み木を産んで、子どもと遊んだ。", "explanation": "ここは〈積む〉の意味。積み木は積むもので、産む対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53109, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "産んだ", "is_correct": true, "explanation": "正解。「子犬を産んだので」と、犬が子を生んだ原因を示す文で自然。"}, {"text": "転んだ", "is_correct": false, "explanation": "「子犬を転んだ」は成り立たない。「転ぶ」は目的語を取らない動詞。"}, {"text": "吠えた", "is_correct": false, "explanation": "「子犬を吠えた」は意味をなさない。「吠える」は目的語を取らない。"}, {"text": "震えた", "is_correct": false, "explanation": "「子犬を震えた」は不自然。「震える」は目的語を取らない動詞。"}], "explanations": {"産んだ": "正解。「子犬を産んだので」と、犬が子を生んだ原因を示す文で自然。", "転んだ": "「子犬を転んだ」は成り立たない。「転ぶ」は目的語を取らない動詞。", "吠えた": "「子犬を吠えた」は意味をなさない。「吠える」は目的語を取らない。", "震えた": "「子犬を震えた」は不自然。「震える」は目的語を取らない動詞。"}, "sentence_index": 6, "correct_answer": "産んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑に種を産んで、春に芽が出るのを待った。", "explanation": "ここは〈蒔く〉の意味。種は蒔くもので、産むのは生き物が子や卵を体外に出すこと。"}, {"text": "鍋でスープを産んで、家族で食べた。", "explanation": "ここは〈煮る〉の意味。スープは煮るもので、産むものではない。"}, {"text": "朝、床を産んでから、学校へ行った。", "explanation": "ここは〈掃く〉の意味。床は掃くもので、産むものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53109, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この猫は春に子猫を産また。", "corrected_sentence": "この猫は春に子猫を産んだ。", "error_description": "「産む」の過去形は「産んだ」。「産また」は活用を誤った形で誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "産みました", "is_correct": true, "explanation": "正解。「先月」の出来事を丁寧に過去で述べる、丁寧な過去形。"}, {"text": "産まない", "is_correct": false, "explanation": "否定形。「先月」の出来事を否定すると、文の意味が合わない。"}, {"text": "産め", "is_correct": false, "explanation": "命令形。過去の出来事を述べる文には合わない。"}, {"text": "産む", "is_correct": false, "explanation": "辞書形。「先月」の過去の出来事を言うには過去形が必要。"}], "correct_form": "産みました", "base_form": "産む", "form_label": "丁寧な過去形", "sentence_index": 1, "explanations": {"産みました": "正解。「先月」の出来事を丁寧に過去で述べる、丁寧な過去形。", "産まない": "否定形。「先月」の出来事を否定すると、文の意味が合わない。", "産め": "命令形。過去の出来事を述べる文には合わない。", "産む": "辞書形。「先月」の過去の出来事を言うには過去形が必要。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53109, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この亀は夏の夜に、砂浜で卵を産んた。", "corrected_sentence": "この亀は夏の夜に、砂浜で卵を産んだ。", "error_description": "「産んだ」は過去の「た形」で、濁音は「だ」。「産んた」は濁音を誤った形で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "産んだ", "is_correct": true, "explanation": "正解。「私を産んだとき」と、過去の出来事を普通の過去形で述べる。"}, {"text": "産めない", "is_correct": false, "explanation": "可能形の否定。産むことができないという意味になり、文の意味が合わない。"}, {"text": "産ませる", "is_correct": false, "explanation": "使役の現在形。誰かに産ませるという意味になり、文の意味が変わる。"}, {"text": "産もう", "is_correct": false, "explanation": "意志形。未来の意志を表すので、過去の出来事を述べる文には合わない。"}], "correct_form": "産んだ", "base_form": "産む", "form_label": "普通の過去形", "sentence_index": 7, "explanations": {"産んだ": "正解。「私を産んだとき」と、過去の出来事を普通の過去形で述べる。", "産めない": "可能形の否定。産むことができないという意味になり、文の意味が合わない。", "産ませる": "使役の現在形。誰かに産ませるという意味になり、文の意味が変わる。", "産もう": "意志形。未来の意志を表すので、過去の出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb49aaca-cf42-4021-ac08-6b2d965ceed8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53113, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「田園で」と場所を示し、「この田園では」の「では」の「で」として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「この田園が」と主語にすると、後ろの「は」と続かず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「この田園を」は目的語になり、「は」と続かず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「この田園の」と名詞をつなぐと、後ろの「は」と続かず不自然。"}], "correct_answer": "で", "explanations": {"で": "「田園で」と場所を示し、「この田園では」の「では」の「で」として正しい。", "が": "「この田園が」と主語にすると、後ろの「は」と続かず不自然。", "を": "「この田園を」は目的語になり、「は」と続かず文が成り立たない。", "の": "「この田園の」と名詞をつなぐと、後ろの「は」と続かず不自然。"}, "error_tags": {"が": "主語では文が続かない", "を": "目的語では文が成り立たない", "の": "名詞をつなぐ形では続かない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53113, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「田園に」と場所を示し、「田園にやわらかい光がさした」と自然に続く。"}, {"text": "と", "is_correct": false, "explanation": "「田園と」は並列を表し、「やわらかい光がさした」と文がつながらない。"}, {"text": "が", "is_correct": false, "explanation": "「田園が」と主語を重ねると、「光がさした」と主語が二つ並び文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「田園を」と目的語にすると「光がさした」と続かず、「さす」の対象としても成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「田園に」と場所を示し、「田園にやわらかい光がさした」と自然に続く。", "と": "「田園と」は並列を表し、「やわらかい光がさした」と文がつながらない。", "が": "「田園が」と主語を重ねると、「光がさした」と主語が二つ並び文が成り立たない。", "を": "「田園を」と目的語にすると「光がさした」と続かず、「さす」の対象としても成り立たない。"}, "error_tags": {"と": "並列では文が成り立たない", "が": "主語が二つ続いて成り立たない", "を": "目的語では文が成り立たない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53113, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "野菜や米を作る、のどかな広い土地のことです。", "primary_collocate": null, "pronunciation": "でんえん", "ipa": "deɴeɴ", "syllable_count": 2, "sentences": [{"text": "電車の窓から、のどかな田園が見えてきた。", "target_word": "田園", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の窓[まど]から、のどかな田園[でんえん]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "この田園では、春に米を作り、夏に野菜を育てている。", "target_word": "田園", "complexity_tier": "T3", "furigana": "この田園[でんえん]では、春[はる]に米[こめ]を作[つく]り、夏[なつ]に野菜[やさい]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "広い田園の中を、一本の道がまっすぐ続いている。", "target_word": "田園", "complexity_tier": "T3", "furigana": "広[ひろ]い田園[でんえん]の中[なか]を、一本[いっぽん]の道[みち]がまっすぐ続[つづ]いている。", "sentence_source": "generated"}, {"text": "祖父は、田園で米を作って五十年になる。", "target_word": "田園", "complexity_tier": "T3", "furigana": "祖父[そふ]は、田園[でんえん]で米[こめ]を作[つく]って五十年[ごじゅうねん]になる。", "sentence_source": "generated"}, {"text": "朝の田園は静かで、鳥の声しか聞こえない。", "target_word": "田園", "complexity_tier": "T3", "furigana": "朝[あさ]の田園[でんえん]は静[しず]かで、鳥[とり]の声[こえ]しか聞[き]こえない。", "sentence_source": "generated"}, {"text": "夏になると、田園は青い稲でいっぱいになる。", "target_word": "田園", "complexity_tier": "T3", "furigana": "夏[なつ]になると、田園[でんえん]は青[あお]い稲[いね]でいっぱいになる。", "sentence_source": "generated"}, {"text": "田園を歩いていると、土のにおいがしてきた。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]を歩[ある]いていると、土[つち]のにおいがしてきた。", "sentence_source": "generated"}, {"text": "雨がやんで、田園にやわらかい光がさした。", "target_word": "田園", "complexity_tier": "T3", "furigana": "雨[あめ]がやんで、田園[でんえん]にやわらかい光[ひかり]がさした。", "sentence_source": "generated"}, {"text": "都会から引っ越してきて、田園で野菜づくりを始めた。", "target_word": "田園", "complexity_tier": "T3", "furigana": "都会[とかい]から引[ひ]っ越[こ]してきて、田園[でんえん]で野菜[やさい]づくりを始[はじ]めた。", "sentence_source": "generated"}, {"text": "秋には、田園が金色の稲穂でおおわれる。", "target_word": "田園", "complexity_tier": "T3", "furigana": "秋[あき]には、田園[でんえん]が金色[きんいろ]の稲穂[いなほ]でおおわれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "田園", "label": "基本形"}], "register": "中立", "sense_fingerprint": "米や野菜を作る、のどかで広い農地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53113, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "田園", "is_correct": true, "explanation": "野菜や米を作る広い土地のことで、「のどかな田園が見えてきた」と風景として自然に続く。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除に使う道具で、「のどかな掃除機が見えてきた」とは風景として成り立たない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯に使う家電で、のどかな風景の中で見えてくるものとしては合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "においは嗅ぐもので、「見えてきた」とは言えない。"}], "explanations": {"田園": "野菜や米を作る広い土地のことで、「のどかな田園が見えてきた」と風景として自然に続く。", "掃除機": "掃除に使う道具で、「のどかな掃除機が見えてきた」とは風景として成り立たない。", "洗濯機": "洗濯に使う家電で、のどかな風景の中で見えてくるものとしては合わない。", "匂い": "においは嗅ぐもので、「見えてきた」とは言えない。"}, "sentence_index": 0, "correct_answer": "田園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "田園の商店街で、新しい靴を買った。", "explanation": "ここは〈商店街〉の意味。田園は田畑の広がる土地を指すので、店が並ぶ商店街とは結びつかない。"}, {"text": "田園の水族館で、大きな魚を見た。", "explanation": "ここは〈水族館〉の意味。田園は田畑の広がる土地を指すので、魚を展示する施設とは合わない。"}, {"text": "田園のビル街を電車が走る。", "explanation": "ここは〈都会〉の意味。田園は田畑が広がる土地で、ビルが並ぶ街とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53113, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "田園", "is_correct": true, "explanation": "田畑が広がる土地のことで、「田園を歩いていると」と場所を示して自然に続く。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面で、歩いていると言える場所ではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、「冷蔵庫を歩いていると」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部で、歩く場所としては合わない。"}], "explanations": {"田園": "田畑が広がる土地のことで、「田園を歩いていると」と場所を示して自然に続く。", "天井": "部屋の上の面で、歩いていると言える場所ではない。", "冷蔵庫": "食品を冷やす家電で、「冷蔵庫を歩いていると」は成り立たない。", "窓": "建物の開口部で、歩く場所としては合わない。"}, "sentence_index": 6, "correct_answer": "田園"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みに、田園の砂浜で泳いだ。", "explanation": "ここは〈砂浜〉の意味。田園は田畑の風景を指し、海辺の砂浜とは結びつかない。"}, {"text": "田園の山頂から、町の夜景を眺めた。", "explanation": "ここは〈山〉の意味。田園は田畑が広がる平らな土地を指すので、山頂のような高い場所には使わない。"}, {"text": "田園の煙突から、白い煙が出ている。", "explanation": "ここは〈工場〉の意味。煙突は工場の施設で、田畑の風景には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53113, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋の田園を、黄色い稲でいっぱいになる。", "corrected_sentence": "秋の田園は、黄色い稲でいっぱいになる。", "error_description": "「いっぱいになる」は自動詞なので「を」は取れない。主題を示す「は」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53113, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方の田園を、ゆっくり泳いだ。", "corrected_sentence": "夕方の田園を、ゆっくり歩いた。", "error_description": "「田園」を移動する動詞は「歩く」。「泳ぐ」は田園とは結びつかないので不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
