INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53114, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「守る」の対象（目的語）は「を」で示す。「田園を守る」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」を使うと田園が主語になり、「守るために」と続く文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すので、「田園に守る」では対象が示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「田園で守る」では対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「守る」の対象（目的語）は「を」で示す。「田園を守る」が正しい。", "が": "「が」を使うと田園が主語になり、「守るために」と続く文が成り立たない。", "に": "「に」は方向や相手を示すので、「田園に守る」では対象が示せない。", "で": "「で」は場所や手段を示すので、「田園で守る」では対象にならない。"}, "error_tags": {"が": "主語", "に": "方向", "で": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53114, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市の外れにある、農地や自然豊かな地域。田舎の景観や農業活動が行われる場所を指します。", "primary_collocate": null, "pronunciation": "でんえん", "ipa": "deɴeɴ", "syllable_count": 2, "sentences": [{"text": "この町は、駅から少し離れると田園が広がっている。", "target_word": "田園", "complexity_tier": "T3", "furigana": "この町[まち]は、駅[えき]から少[すこ]し離[はな]れると田園[でんえん]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "都心から電車で一時間のところに、田園の残る地域がある。", "target_word": "田園", "complexity_tier": "T3", "furigana": "都心[としん]から電車[でんしゃ]で一時間[いちじかん]のところに、田園[でんえん]の残[のこ]る地域[ちいき]がある。", "sentence_source": "generated"}, {"text": "新しい道路ができて、田園の景色が少しずつ変わってきた。", "target_word": "田園", "complexity_tier": "T3", "furigana": "新[あたら]しい道路[どうろ]ができて、田園[でんえん]の景色[けしき]が少[すこ]しずつ変[か]わってきた。", "sentence_source": "generated"}, {"text": "週末になると、田園で農業を体験する家族が多い。", "target_word": "田園", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]になると、田園[でんえん]で農業[のうぎょう]を体験[たいけん]する家族[かぞく]が多[おお]い。", "sentence_source": "generated"}, {"text": "市の外れの田園には、小さな畑と古い農家が並んでいる。", "target_word": "田園", "complexity_tier": "T3", "furigana": "市[し]の外[はず]れの田園[でんえん]には、小[ちい]さな畑[はたけ]と古[ふる]い農家[のうか]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "住宅が増えて、この辺りの田園は年々少なくなっている。", "target_word": "田園", "complexity_tier": "T3", "furigana": "住宅[じゅうたく]が増[ふ]えて、この辺[あた]りの田園[でんえん]は年々[ねんねん]少[すく]なくなっている。", "sentence_source": "generated"}, {"text": "田園で働く人たちは、朝早くから畑に出る。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]で働[はたら]く人[ひと]たちは、朝早[あさはや]くから畑[はたけ]に出[で]る。", "sentence_source": "generated"}, {"text": "私たちは田園を守るために、地元の農家を応援している。", "target_word": "田園", "complexity_tier": "T3", "furigana": "私[わたし]たちは田園[でんえん]を守[まも]るために、地元[じもと]の農家[のうか]を応援[おうえん]している。", "sentence_source": "generated"}, {"text": "街の中心から田園へ向かうバスは、一日に数本しかない。", "target_word": "田園", "complexity_tier": "T3", "furigana": "街[まち]の中心[ちゅうしん]から田園[でんえん]へ向[む]かうバスは、一日[いちにち]に数本[すうほん]しかない。", "sentence_source": "generated"}, {"text": "田園の景観を生かして、観光客を呼ぶ計画が進んでいる。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]の景観[けいかん]を生[い]かして、観光客[かんこうきゃく]を呼[よ]ぶ計画[けいかく]が進[すす]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "田園", "label": "基本形"}], "register": "中立", "sense_fingerprint": "都市のはずれにある、農業が行われる自然豊かな田舎の地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53114, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "田園", "is_correct": true, "explanation": "農地や自然豊かな地域を指す「田園」が、駅から離れた先に広がる景色として自然につながる。"}, {"text": "踏切", "is_correct": false, "explanation": "踏切は線路を横切る場所で、広がっている景色の主語にはならない。"}, {"text": "改札", "is_correct": false, "explanation": "改札は駅の出入口にある設備で、離れた所に広がるものとは言えない。"}, {"text": "駅舎", "is_correct": false, "explanation": "駅舎は駅の建物で、駅から離れた所に広がる景色とは合わない。"}], "explanations": {"田園": "農地や自然豊かな地域を指す「田園」が、駅から離れた先に広がる景色として自然につながる。", "踏切": "踏切は線路を横切る場所で、広がっている景色の主語にはならない。", "改札": "改札は駅の出入口にある設備で、離れた所に広がるものとは言えない。", "駅舎": "駅舎は駅の建物で、駅から離れた所に広がる景色とは合わない。"}, "sentence_index": 0, "correct_answer": "田園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家の田園には、池と石灯籠が置かれている。", "explanation": "ここは「庭園」の意味。池や石灯籠のある庭は庭園と言い、田園は都市の外れの農地や自然豊かな地域を指すので合わない。"}, {"text": "庭の隅に、家族で食べる野菜を植えるための田園を作った。", "explanation": "ここは「畑」の意味。家庭で野菜を育てる小さな区画は畑と言い、田園は広い農地や自然豊かな地域を指すので合わない。"}, {"text": "駅前の田園には、デパートや飲食店が並んでいる。", "explanation": "ここは「繁華街」の意味。店が集まる都市の中心部は繁華街と言い、田園は都市の外れの農地や自然地域を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53114, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "田園", "is_correct": true, "explanation": "田園は農業を行う場所なので、「田園で働く」と場所を示して自然につながる。"}, {"text": "夜間", "is_correct": false, "explanation": "「夜間で働く」は不自然で、朝早くから畑に出るという後半とも合わない。"}, {"text": "早朝", "is_correct": false, "explanation": "早朝は時間の語で、「で働く」の場所として使えない。"}, {"text": "深夜", "is_correct": false, "explanation": "深夜は時間の語で、「で働く」の場所として使えず、朝早くの話とも合わない。"}], "explanations": {"田園": "田園は農業を行う場所なので、「田園で働く」と場所を示して自然につながる。", "夜間": "「夜間で働く」は不自然で、朝早くから畑に出るという後半とも合わない。", "早朝": "早朝は時間の語で、「で働く」の場所として使えない。", "深夜": "深夜は時間の語で、「で働く」の場所として使えず、朝早くの話とも合わない。"}, "sentence_index": 6, "correct_answer": "田園"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田園の地下街で、週末に買い物をする人が多い。", "explanation": "ここは〈地下街〉の意味。地下の商業空間は都市の施設で、農地や自然豊かな地域とは結びつかない。"}, {"text": "田園の高層マンションに、多くの家族が住んでいる。", "explanation": "ここは〈都市部の住宅地〉の意味。高層マンションが並ぶ街は都市の住宅地で、農地や自然豊かな地域とは合わない。"}, {"text": "田園のオフィスビルで、会議が毎日開かれている。", "explanation": "ここは〈オフィス街〉の意味。オフィスビルが集まる場所は都市の業務地で、農地や自然豊かな地域とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53114, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バスを降りると、田園を広がる景色が見えた。", "corrected_sentence": "バスを降りると、田園が広がる景色が見えた。", "error_description": "誤りは「田園を」の「を」。「広がる」は目的語を取らず、広がるものは「が」で示す。「田園が広がる景色」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53114, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休日は、家族で田園を出かけた。", "corrected_sentence": "休日は、家族で田園へ出かけた。", "error_description": "誤りは「田園を」の「を」。「出かける」は行き先を「へ」で示す。「田園を」は誤りで、「田園へ出かけた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53127, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「うちに」の「に」。時間の区切りを表し、「眠っているうちに錆びついてしまった」と自然につながる。"}, {"text": "で", "is_correct": false, "explanation": "「うちで」は場所や手段を表すが、時間の「うち」には合わず不自然。"}, {"text": "を", "is_correct": false, "explanation": "〈錆びつく〉は目的語を取らない自動詞なので、「うちを」は文法上つながらない。"}, {"text": "と", "is_correct": false, "explanation": "「うちと」は並列を表すが、時間を示す節には入らない。"}], "correct_answer": "に", "explanations": {"に": "「うちに」の「に」。時間の区切りを表し、「眠っているうちに錆びついてしまった」と自然につながる。", "で": "「うちで」は場所や手段を表すが、時間の「うち」には合わず不自然。", "を": "〈錆びつく〉は目的語を取らない自動詞なので、「うちを」は文法上つながらない。", "と": "「うちと」は並列を表すが、時間を示す節には入らない。"}, "error_tags": {"で": "場所・手段", "を": "目的語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53127, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53127, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "金属が長いあいだ雨にぬれると、赤い色のさびが出て、もろくなります。", "primary_collocate": null, "pronunciation": "さびつく", "ipa": "sabitsɯkɯ", "syllable_count": 4, "sentences": [{"text": "雨の日も外に出しておいたので、バケツの底が錆びついた。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]も外[そと]に出[だ]しておいたので、バケツの底[そこ]が錆[さ]びついた。", "sentence_source": "generated"}, {"text": "祖父の自転車は、物置で十年眠っているうちに錆びついてしまった。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "祖父[そふ]の自転車[じてんしゃ]は、物置[ものおき]で十年[じゅうねん]眠[ねむ]っているうちに錆[さ]びついてしまった。", "sentence_source": "generated"}, {"text": "錆びついた鉄の階段は、足をのせるとぎしぎし鳴る。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "錆[さ]びついた鉄[てつ]の階段[かいだん]は、足[あし]をのせるとぎしぎし鳴[な]る。", "sentence_source": "generated"}, {"text": "海風に当たり続けた手すりが、赤茶色に錆びついている。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "海風[うみかぜ]に当[あ]たり続[つづ]けた手すりが、赤茶色[あかちゃいろ]に錆[さ]びついている。", "sentence_source": "generated"}, {"text": "使ったあとに油を塗れば、ハサミは錆びつきにくい。", "target_word": "錆びつき", "complexity_tier": "T3", "furigana": "使[つか]ったあとに油[あぶら]を塗[ぬ]れば、ハサミは錆[さ]びつきにくい。", "sentence_source": "generated"}, {"text": "錆びついたくぎは、少し力を入れるともろく折れた。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "錆[さ]びついたくぎは、少[すこ]し力[ちから]を入[い]れるともろく折[お]れた。", "sentence_source": "generated"}, {"text": "公園のブランコの鎖が錆びついたので、市が新しいものに替えた。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "公園[こうえん]のブランコの鎖[くさり]が錆[さ]びついたので、市[し]が新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "雨ざらしの看板は、いつの間にか錆びついて、文字が読めなくなった。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "雨[あめ]ざらしの看板[かんばん]は、いつの間[ま]にか錆[さ]びついて、文字[もじ]が読[よ]めなくなった。", "sentence_source": "generated"}, {"text": "この缶は錆びついて、ふたがまったく開かない。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "この缶[かん]は錆[さ]びついて、ふたがまったく開[あ]かない。", "sentence_source": "generated"}, {"text": "校庭の隅に、錆びついた鉄棒が一本だけ残っている。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "校庭[こうてい]の隅[すみ]に、錆[さ]びついた鉄棒[てつぼう]が一本[いっぽん]だけ残[のこ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "錆びつく", "label": "終止形"}, {"form": "錆びつかない", "label": "否定形"}, {"form": "錆びつきます", "label": "丁寧形"}, {"form": "錆びついて", "label": "て形"}, {"form": "錆びついた", "label": "た形"}], "register": "中立（普通体）", "sense_fingerprint": "金属が雨にぬれ続けて赤いさびが出て、もろくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53127, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "錆びつい", "is_correct": true, "explanation": "「バケツの底が錆びついた」の形。直後の「た」と合わさって過去の状態を表す。"}, {"text": "錆びつか", "is_correct": false, "explanation": "否定の語幹。「錆びつかた」となり、活用として成立しない。"}, {"text": "錆びつき", "is_correct": false, "explanation": "連用形。「錆びつきた」となり、た形として続かない。"}, {"text": "錆びつく", "is_correct": false, "explanation": "終止形。「錆びつくた」となり、「た」に直接続けられない。"}], "explanations": {"錆びつい": "「バケツの底が錆びついた」の形。直後の「た」と合わさって過去の状態を表す。", "錆びつか": "否定の語幹。「錆びつかた」となり、活用として成立しない。", "錆びつき": "連用形。「錆びつきた」となり、た形として続かない。", "錆びつく": "終止形。「錆びつくた」となり、「た」に直接続けられない。"}, "sentence_index": 0, "correct_answer": "錆びつい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の木の柵が、雨続きで錆びついてしまった。", "explanation": "ここは〈腐る〉の意味。木は錆びず腐って傷むものなので、錆びつくは金属の酸化にしか使わない。"}, {"text": "強い日差しに長くさらされて、テントの青い布地が錆びついてしまった。", "explanation": "ここは〈色あせる〉の意味。布は錆びないので、色が薄れる意味なら〈色あせる〉が自然。"}, {"text": "乾いた接着剤が錆びついて、封筒が開かなくなった。", "explanation": "ここは〈固まる〉の意味。接着剤は金属ではなく錆びないので、乾いて固くなる意味なら〈固まる〉が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53127, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "錆びつい", "is_correct": true, "explanation": "「錆びついたので」の形。直後の「た」と合わさって、錆びた理由を述べる。"}, {"text": "錆びついた", "is_correct": false, "explanation": "た形。「錆びついたたので」となり、「た」が重なって成り立たない。"}, {"text": "錆びついて", "is_correct": false, "explanation": "て形。「錆びついてたので」となり、た形として続かない。"}, {"text": "錆びつこう", "is_correct": false, "explanation": "意志形。「錆びつこうたので」となり、理由を表す文に合わない。"}], "explanations": {"錆びつい": "「錆びついたので」の形。直後の「た」と合わさって、錆びた理由を述べる。", "錆びついた": "た形。「錆びついたたので」となり、「た」が重なって成り立たない。", "錆びついて": "て形。「錆びついてたので」となり、た形として続かない。", "錆びつこう": "意志形。「錆びつこうたので」となり、理由を表す文に合わない。"}, "sentence_index": 6, "correct_answer": "錆びつい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の暑さで、ケーキのクリームが錆びついて崩れた。", "explanation": "ここは〈傷んで崩れる〉の意味。クリームは金属ではなく錆びないので、錆びつくは金属の酸化にしか使わない。"}, {"text": "溶鉱炉の中で、鉄くずが錆びついてどろどろに溶けた。", "explanation": "ここは〈溶ける〉の意味。熱で液体になる変化は〈溶ける〉で表し、錆びつくは酸化による劣化を指すので合わない。"}, {"text": "古いトラックの荷台が錆びついて、勢いよく燃えた。", "explanation": "ここは〈燃える〉の意味。火で燃えることは〈燃える〉で表し、錆びつくは金属の酸化を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53127, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父の物置の鋏は、雨で錆びつくてしまった。", "corrected_sentence": "祖父の物置の鋏は、雨で錆びついてしまった。", "error_description": "「錆びつくて」は誤り。正しくは「錆びついて」（く→いて）。五段動詞のて形は語幹に「いて」を付けて作る。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "錆びつい", "is_correct": true, "explanation": "て形・た形の語幹。直後の「てしまった」と続き、錆びて傷んだ結果を表す。"}, {"text": "錆びつかない", "is_correct": false, "explanation": "否定形。錆びていないという意味になり、錆びた結果を述べる文と逆になる。"}, {"text": "錆びつきます", "is_correct": false, "explanation": "丁寧形。普通体の「てしまった」と文体が合わない。"}, {"text": "錆びつけば", "is_correct": false, "explanation": "仮定形。仮定の意味になり、すでに起きた出来事の叙述に合わない。"}], "correct_form": "錆びつい", "base_form": "錆びつく", "form_label": "て形・た形（語幹）", "sentence_index": 1, "explanations": {"錆びつい": "て形・た形の語幹。直後の「てしまった」と続き、錆びて傷んだ結果を表す。", "錆びつかない": "否定形。錆びていないという意味になり、錆びた結果を述べる文と逆になる。", "錆びつきます": "丁寧形。普通体の「てしまった」と文体が合わない。", "錆びつけば": "仮定形。仮定の意味になり、すでに起きた出来事の叙述に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53127, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裏門の鉄柵は、雨を錆びついてぼろぼろになった。", "corrected_sentence": "裏門の鉄柵は、雨で錆びついてぼろぼろになった。", "error_description": "「雨を」は誤り。〈錆びつく〉は自動詞で目的語を取らず、原因は「雨で」と表す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "錆びつい", "is_correct": true, "explanation": "て形・た形の語幹。直後の「て」「た」と続き、錆びて文字が読めなくなった状態を表す。"}, {"text": "錆びつこう", "is_correct": false, "explanation": "意志形。意志の表現になり、事実を述べる文に合わない。"}, {"text": "錆びつけ", "is_correct": false, "explanation": "命令形。命令の意味になり、事実を述べる文に合わない。"}, {"text": "錆びついたり", "is_correct": false, "explanation": "たり形。例示の意味になり、ここの接続に合わない。"}], "correct_form": "錆びつい", "base_form": "錆びつく", "form_label": "て形・た形（語幹）", "sentence_index": 7, "explanations": {"錆びつい": "て形・た形の語幹。直後の「て」「た」と続き、錆びて文字が読めなくなった状態を表す。", "錆びつこう": "意志形。意志の表現になり、事実を述べる文に合わない。", "錆びつけ": "命令形。命令の意味になり、事実を述べる文に合わない。", "錆びついたり": "たり形。例示の意味になり、ここの接続に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53128, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「雨で」は原因を表す「で」。雨が原因で錆びついたという自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "〈錆びつく〉は自動詞で目的語を取らない。「雨を錆びつく」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「雨と」は並列や共同を表すので、ここで錆びつく原因を示すことにはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「雨へ錆びつく」は意味も文法も合わない。"}], "correct_answer": "で", "explanations": {"で": "「雨で」は原因を表す「で」。雨が原因で錆びついたという自然な文になる。", "を": "〈錆びつく〉は自動詞で目的語を取らない。「雨を錆びつく」は成り立たない。", "と": "「雨と」は並列や共同を表すので、ここで錆びつく原因を示すことにはならない。", "へ": "「へ」は方向を表す。「雨へ錆びつく」は意味も文法も合わない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
