INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53128, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "金属が空気や水分に触れて長い間置かれると、表面が酸化して赤茶色になり、弱くなること。", "primary_collocate": null, "pronunciation": "さびつく", "ipa": "sabitsɯkɯ", "syllable_count": 4, "sentences": [{"text": "私は遺産整理のために錆びついたドアノブに手をかけ、ゆっくりとそれを開けた。", "target_word": "錆びつい", "complexity_tier": "T4", "furigana": "私[わたし]は遺産整理[いさんせいり]のために錆[さ]びついたドアノブに手[て]をかけ、ゆっくりとそれを開[あ]けた。", "sentence_source": "mined"}, {"text": "庭に置きっぱなしの自転車が、雨で錆びついてしまった。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "庭[にわ]に置[お]きっぱなしの自転車[じてんしゃ]が、雨[あめ]で錆[さ]びついてしまった。", "sentence_source": "generated"}, {"text": "長年使われていない門の鍵は、錆びついて回らなかった。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "長年[ながねん]使[つか]われていない門[もん]の鍵[かぎ]は、錆[さ]びついて回[まわ]らなかった。", "sentence_source": "generated"}, {"text": "海の近くでは、鉄の柵が錆びつくのが早い。", "target_word": "錆びつく", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くでは、鉄[てつ]の柵[さく]が錆[さ]びつくのが早[はや]い。", "sentence_source": "generated"}, {"text": "倉庫の奥で錆びついた工具を見つけた。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "倉庫[そうこ]の奥[おく]で錆[さ]びついた工具[こうぐ]を見[み]つけた。", "sentence_source": "generated"}, {"text": "水気を拭いておかないと、包丁は一晩で錆びついてしまう。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "水気[みずけ]を拭[ふ]いておかないと、包丁[ほうちょう]は一晩[ひとばん]で錆[さ]びついてしまう。", "sentence_source": "generated"}, {"text": "長い間雨ざらしだったので、橋の鉄骨はすっかり錆びついている。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]雨[あめ]ざらしだったので、橋[はし]の鉄骨[てっこつ]はすっかり錆[さ]びついている。", "sentence_source": "generated"}, {"text": "ステンレスの鍋は、鉄の鍋と違ってなかなか錆びつかない。", "target_word": "錆びつか", "complexity_tier": "T3", "furigana": "ステンレスの鍋[なべ]は、鉄[てつ]の鍋[なべ]と違[ちが]ってなかなか錆[さ]びつかない。", "sentence_source": "generated"}, {"text": "古い線路が草に埋もれ、錆びついたレールだけが残っていた。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "古[ふる]い線路[せんろ]が草[くさ]に埋[う]もれ、錆[さ]びついたレールだけが残[のこ]っていた。", "sentence_source": "generated"}, {"text": "錆びついた蝶番は、油をさしても動かなかった。", "target_word": "錆びつい", "complexity_tier": "T3", "furigana": "錆[さ]びついた蝶番[ちょうつがい]は、油[あぶら]をさしても動[うご]かなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "錆びつく", "label": "終止形"}, {"form": "錆びつかない", "label": "否定形"}, {"form": "錆びつきます", "label": "丁寧形"}, {"form": "錆びついて", "label": "て形"}, {"form": "錆びついた", "label": "た形"}], "register": "中立（普通体）", "sense_fingerprint": "金属が長く放置されて表面が酸化し、赤茶色の錆で覆われて弱ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53128, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "錆びつい", "is_correct": true, "explanation": "「錆びついたドアノブ」の一部。直後の「た」と合わさって名詞を修飾する形になる。"}, {"text": "錆びつか", "is_correct": false, "explanation": "否定の語幹。「錆びつかたドアノブ」となり、活用として成立しない。"}, {"text": "錆びつき", "is_correct": false, "explanation": "連用形。「錆びつきたドアノブ」となり、た形として続かない。"}, {"text": "錆びつく", "is_correct": false, "explanation": "終止形。「錆びつくたドアノブ」となり、「た」に直接続けられない。"}], "explanations": {"錆びつい": "「錆びついたドアノブ」の一部。直後の「た」と合わさって名詞を修飾する形になる。", "錆びつか": "否定の語幹。「錆びつかたドアノブ」となり、活用として成立しない。", "錆びつき": "連用形。「錆びつきたドアノブ」となり、た形として続かない。", "錆びつく": "終止形。「錆びつくたドアノブ」となり、「た」に直接続けられない。"}, "sentence_index": 0, "correct_answer": "錆びつい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の木製のベンチが、長年の雨ざらしで錆びついてしまった。", "explanation": "ここは〈腐る〉の意味。木は錆びずに腐って傷むので、錆びつくは金属の酸化にしか使わない。"}, {"text": "直射日光に長くさらされて、ポスターの赤い色がすっかり錆びついた。", "explanation": "ここは〈色あせる〉の意味。色は金属の酸化で変わるものではないので、薄れる意味なら〈色あせる〉が自然。"}, {"text": "乾いたのりが錆びつき、紙が剥がれなくなった。", "explanation": "ここは〈固まる〉の意味。のりは金属ではなく錆びないので、乾いて固くなる意味なら〈固まる〉が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53128, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "錆びつい", "is_correct": true, "explanation": "「すっかり錆びついている」の形。直後の「ている」と合わさって状態を表す。"}, {"text": "錆びついた", "is_correct": false, "explanation": "た形。「錆びついたている」となり、「ている」に続かないので文が成り立たない。"}, {"text": "錆びついて", "is_correct": false, "explanation": "て形。「錆びついてている」となり、「ている」と直接続けられない。"}, {"text": "錆びつこう", "is_correct": false, "explanation": "意志形。「錆びつこうている」となり、状態を表す文に合わない。"}], "explanations": {"錆びつい": "「すっかり錆びついている」の形。直後の「ている」と合わさって状態を表す。", "錆びついた": "た形。「錆びついたている」となり、「ている」に続かないので文が成り立たない。", "錆びついて": "て形。「錆びついてている」となり、「ている」と直接続けられない。", "錆びつこう": "意志形。「錆びつこうている」となり、状態を表す文に合わない。"}, "sentence_index": 6, "correct_answer": "錆びつい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "真夏の車内に置いたチョコが錆びついて、形が崩れた。", "explanation": "ここは〈溶けて崩れる〉の意味。チョコは金属ではなく錆びないので、この意味なら〈溶ける〉を使う。"}, {"text": "溶鉱炉の中で、鉄くずが錆びついてどろどろに溶けた。", "explanation": "ここは〈溶ける〉の意味。熱で液体になる変化は〈溶ける〉で表し、錆びつくは酸化による劣化を指すので合わない。"}, {"text": "古いトラックの荷台が錆びついて、勢いよく燃えた。", "explanation": "ここは〈燃える〉の意味。火で燃えることは〈燃える〉で表し、錆びつくは金属の酸化を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53128, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "納屋に置いた鍬は、雨で錆びつくてしまった。", "corrected_sentence": "納屋に置いた鍬は、雨で錆びついてしまった。", "error_description": "「錆びつくて」は誤り。正しくは「錆びついて」（く→いて）。五段動詞のて形は語幹に「いて」を付けて作る。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "錆びつい", "is_correct": true, "explanation": "て形・た形の語幹。直後の「てしまった」と続き、錆びて傷んだ結果を表す。"}, {"text": "錆びつかない", "is_correct": false, "explanation": "否定形。錆びていないという意味になり、錆びた結果を述べる文と逆になる。"}, {"text": "錆びつきます", "is_correct": false, "explanation": "丁寧形。普通体の「てしまった」と文体が合わない。"}, {"text": "錆びつけば", "is_correct": false, "explanation": "仮定形。仮定の意味になり、すでに起きた出来事の叙述に合わない。"}], "correct_form": "錆びつい", "base_form": "錆びつく", "form_label": "て形・た形（語幹）", "sentence_index": 1, "explanations": {"錆びつい": "て形・た形の語幹。直後の「てしまった」と続き、錆びて傷んだ結果を表す。", "錆びつかない": "否定形。錆びていないという意味になり、錆びた結果を述べる文と逆になる。", "錆びつきます": "丁寧形。普通体の「てしまった」と文体が合わない。", "錆びつけば": "仮定形。仮定の意味になり、すでに起きた出来事の叙述に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53128, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "玄関先の鉄の門は、雨を錆びついてぼろぼろになった。", "corrected_sentence": "玄関先の鉄の門は、雨で錆びついてぼろぼろになった。", "error_description": "「雨を」は誤り。〈錆びつく〉は自動詞で、原因は「雨で」と表す。「を」は目的語に付く助詞なので成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "錆びつか", "is_correct": true, "explanation": "否定の語幹。直後の「ない」と続いて「錆びつかない」の否定の意味を作る。"}, {"text": "錆びつき", "is_correct": false, "explanation": "連用形。「錆びつきない」は成り立たず、否定の語幹にならない。"}, {"text": "錆びつけ", "is_correct": false, "explanation": "命令形の語幹。命令の意味になり、主語の状態を述べる文に合わない。"}, {"text": "錆びつこう", "is_correct": false, "explanation": "意志形。意志の表現になり、事実を述べる文と合わない。"}], "correct_form": "錆びつか", "base_form": "錆びつく", "form_label": "否定形（語幹）", "sentence_index": 7, "explanations": {"錆びつか": "否定の語幹。直後の「ない」と続いて「錆びつかない」の否定の意味を作る。", "錆びつき": "連用形。「錆びつきない」は成り立たず、否定の語幹にならない。", "錆びつけ": "命令形の語幹。命令の意味になり、主語の状態を述べる文に合わない。", "錆びつこう": "意志形。意志の表現になり、事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53133, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「日本酒を呑む」の目的語を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「日本酒に呑む」は不自然で、目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「日本酒で呑む」は手段の意味になり、文が合わない。"}, {"text": "が", "is_correct": false, "explanation": "「日本酒が呑む」は主語になり、呑むの目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「日本酒を呑む」の目的語を示す格助詞。", "に": "「日本酒に呑む」は不自然で、目的語にならない。", "で": "「日本酒で呑む」は手段の意味になり、文が合わない。", "が": "「日本酒が呑む」は主語になり、呑むの目的語にならない。"}, "error_tags": {"に": "方向・帰着", "で": "手段・場所", "が": "主格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53133, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「お酒を呑めません」の目的語を示す格助詞。"}, {"text": "の", "is_correct": false, "explanation": "「お酒の呑めません」は成立せず、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「お酒へ」は方向を示すことになり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、「お酒より呑めません」は文の意味が変わる。"}], "correct_answer": "を", "explanations": {"を": "「お酒を呑めません」の目的語を示す格助詞。", "の": "「お酒の呑めません」は成立せず、目的語にならない。", "へ": "「お酒へ」は方向を示すことになり、不自然。", "より": "比較の意味になり、「お酒より呑めません」は文の意味が変わる。"}, "error_tags": {"の": "所属・修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53133, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体を口からからだの中に入れることです。", "primary_collocate": null, "pronunciation": "のむ", "ipa": "nomɯ", "syllable_count": 2, "sentences": [{"text": "仕事のあとで、友だちと冷たいビールを呑んだ。", "target_word": "呑んだ", "complexity_tier": "T3", "furigana": "仕事[しごと]のあとで、友[とも]だちと冷[つめ]たいビールを呑[の]んだ。", "sentence_source": "generated"}, {"text": "父は毎晩、少しだけ日本酒を呑む。", "target_word": "呑む", "complexity_tier": "T3", "furigana": "父[ちち]は毎晩[まいばん]、少[すこ]しだけ日本酒[にほんしゅ]を呑[の]む。", "sentence_source": "generated"}, {"text": "喉が渇いたので、水を呑んで一息ついた。", "target_word": "呑んで", "complexity_tier": "T3", "furigana": "喉[のど]が渇[かわ]いたので、水[みず]を呑[の]んで一息[ひといき]ついた。", "sentence_source": "generated"}, {"text": "寒い夜は、温かいお茶を呑むと落ち着く。", "target_word": "呑む", "complexity_tier": "T3", "furigana": "寒[さむ]い夜[よる]は、温[あたた]かいお茶[ちゃ]を呑[の]むと落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "彼は酒を呑まないので、乾杯はジュースだった。", "target_word": "呑ま", "complexity_tier": "T3", "furigana": "彼[かれ]は酒[さけ]を呑[の]まないので、乾杯[かんぱい]はジュースだった。", "sentence_source": "generated"}, {"text": "昨日は夜遅くまで友人と酒を呑んで、朝起きられなかった。", "target_word": "呑んで", "complexity_tier": "T3", "furigana": "昨日[きのう]は夜遅[よるおそ]くまで友人[ゆうじん]と酒[さけ]を呑[の]んで、朝[あさ]起[お]きられなかった。", "sentence_source": "generated"}, {"text": "祖母は毎朝、牛乳をゆっくり呑んでいる。", "target_word": "呑んで", "complexity_tier": "T3", "furigana": "祖母[そぼ]は毎朝[まいあさ]、牛乳[ぎゅうにゅう]をゆっくり呑[の]んでいる。", "sentence_source": "generated"}, {"text": "運転があるので、今日はお酒を呑めません。", "target_word": "呑め", "complexity_tier": "T3", "furigana": "運転[うんてん]があるので、今日[きょう]はお酒[さけ]を呑[の]めません。", "sentence_source": "generated"}, {"text": "川の水をそのまま呑むのは危ない。", "target_word": "呑む", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]をそのまま呑[の]むのは危[あぶ]ない。", "sentence_source": "generated"}, {"text": "旅先の居酒屋で、地酒を呑んだ。", "target_word": "呑んだ", "complexity_tier": "T3", "furigana": "旅先[たびさき]の居酒屋[いざかや]で、地酒[じざけ]を呑[の]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "呑まない", "label": "否定形"}, {"form": "呑みます", "label": "丁寧形"}, {"form": "呑んだ", "label": "過去形"}, {"form": "呑んで", "label": "て形"}, {"form": "呑めば", "label": "仮定形"}, {"form": "呑もう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "お酒や水などの液体を口から体に入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53133, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呑んだ", "is_correct": true, "explanation": "過去の文を終える形。「冷たいビールを呑んだ」で文が成立する。"}, {"text": "呑み", "is_correct": false, "explanation": "連用形で、文を終えられない。"}, {"text": "呑ま", "is_correct": false, "explanation": "未然形で、「ビールを呑ま」では文が終わらない。"}, {"text": "呑ん", "is_correct": false, "explanation": "音便の語幹だけでは文が終わらず、「た」などが必要。"}], "explanations": {"呑んだ": "過去の文を終える形。「冷たいビールを呑んだ」で文が成立する。", "呑み": "連用形で、文を終えられない。", "呑ま": "未然形で、「ビールを呑ま」では文が終わらない。", "呑ん": "音便の語幹だけでは文が終わらず、「た」などが必要。"}, "sentence_index": 0, "correct_answer": "呑んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カラオケで好きな歌を呑んだ。", "explanation": "ここは〈歌う〉の意味。呑むは体の中に入れる動作で、声に出して歌うことは表さないので合わない。"}, {"text": "おやつにケーキをゆっくり呑んだ。", "explanation": "ここは〈食べる〉の意味。ケーキは固形物なので、液体を飲むこの見出し語では使わない。"}, {"text": "朝、ネクタイを呑んで締めた。", "explanation": "ここは〈締める〉の意味。呑むはものを体に入れる動作で、ネクタイを締める行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53133, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呑んで", "is_correct": true, "explanation": "「牛乳をゆっくり呑んでいる」の形。て形で「いる」に続く。"}, {"text": "呑む", "is_correct": false, "explanation": "終止形のため、「いる」の前に続かない。"}, {"text": "呑も", "is_correct": false, "explanation": "意志形の語幹で、「いる」に続かない。"}, {"text": "呑め", "is_correct": false, "explanation": "命令・可能の形で、進行の「いる」と続かず文脈に合わない。"}], "explanations": {"呑んで": "「牛乳をゆっくり呑んでいる」の形。て形で「いる」に続く。", "呑む": "終止形のため、「いる」の前に続かない。", "呑も": "意志形の語幹で、「いる」に続かない。", "呑め": "命令・可能の形で、進行の「いる」と続かず文脈に合わない。"}, "sentence_index": 6, "correct_answer": "呑んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ステーキをよく呑んで、ゆっくり食べた。", "explanation": "ここは〈噛む〉の意味。呑むは噛まずに飲み込むことで、よく噛む動作には使わない。"}, {"text": "雨で濡れた靴を、彼は呑んで乾かした。", "explanation": "ここは〈乾かす〉の意味。呑むは体に入れる動作で、濡れたものを乾かす行為には使わない。"}, {"text": "缶詰を呑んで開けた。", "explanation": "ここは〈開ける〉の意味。呑むは体に入れる動作で、缶を開ける行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53133, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼休みに、コーヒーで呑んだ。", "corrected_sentence": "昼休みに、コーヒーを呑んだ。", "error_description": "「コーヒーで呑んだ」の「で」が誤り。正しくは「コーヒーを呑んだ」。呑むは目的語に「を」を取り、「で」は手段や場所を表すため合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "呑む", "is_correct": true, "explanation": "基本形（辞書形）。文中の「日本酒を呑む」の形。"}, {"text": "呑まない", "is_correct": false, "explanation": "否定形で、基本形ではない。"}, {"text": "呑んで", "is_correct": false, "explanation": "て形で、文を終えられない。"}, {"text": "呑もう", "is_correct": false, "explanation": "意志形で、習慣を述べる文には合わない。"}], "correct_form": "呑む", "base_form": "呑む", "form_label": "基本形", "sentence_index": 1, "explanations": {"呑む": "基本形（辞書形）。文中の「日本酒を呑む」の形。", "呑まない": "否定形で、基本形ではない。", "呑んで": "て形で、文を終えられない。", "呑もう": "意志形で、習慣を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53133, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は毎朝、牛乳に呑んでいる。", "corrected_sentence": "祖母は毎朝、牛乳を呑んでいる。", "error_description": "「牛乳に呑んでいる」の「に」が誤り。正しくは「牛乳を呑んでいる」。呑むは目的語に「を」を取るため、「に」は合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "呑め", "is_correct": true, "explanation": "可能形の語幹。「呑めません」で「飲めない」の意味になり、文中の形。"}, {"text": "呑んで", "is_correct": false, "explanation": "て形で、否定の可能の文にはならない。"}, {"text": "呑めば", "is_correct": false, "explanation": "仮定形で、「呑めば」の条件の意味になり文と合わない。"}, {"text": "呑める", "is_correct": false, "explanation": "辞書形（可能）。「呑めるません」となり、「ません」に続かない。"}], "correct_form": "呑め", "base_form": "呑む", "form_label": "可能形", "sentence_index": 7, "explanations": {"呑め": "可能形の語幹。「呑めません」で「飲めない」の意味になり、文中の形。", "呑んで": "て形で、否定の可能の文にはならない。", "呑めば": "仮定形で、「呑めば」の条件の意味になり文と合わない。", "呑める": "辞書形（可能）。「呑めるません」となり、「ません」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53135, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「家を建てて」の「家」を目的語として示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「家に建てて」では家を場所として示すことになり、建てる対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「家が建てて」では家が主語になり、建てる主体（祖父）と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「家へ建てて」では方向を示すことになり、建てる対象の表現として不自然。"}], "correct_answer": "を", "explanations": {"を": "「家を建てて」の「家」を目的語として示す「を」。", "に": "「家に建てて」では家を場所として示すことになり、建てる対象を表せない。", "が": "「家が建てて」では家が主語になり、建てる主体（祖父）と合わない。", "へ": "「家へ建てて」では方向を示すことになり、建てる対象の表現として不自然。"}, "error_tags": {"に": "場所", "が": "主語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「建てる」の対義語で、建てたものを取り壊す意味。"}, {"text": "洗う", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、「建てる」と対義関係にはない。"}, {"text": "借りる", "is_correct": false, "explanation": "「借りる」は他人の物を一時的に使う動作で、「建てる」と対義関係にはない。"}, {"text": "読む", "is_correct": false, "explanation": "「読む」は文字を理解する動作で、「建てる」と対義関係にはない。"}], "correct_answer": "壊す", "explanations": {"壊す": "「建てる」の対義語で、建てたものを取り壊す意味。", "洗う": "「洗う」は汚れを落とす動作で、「建てる」と対義関係にはない。", "借りる": "「借りる」は他人の物を一時的に使う動作で、「建てる」と対義関係にはない。", "読む": "「読む」は文字を理解する動作で、「建てる」と対義関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53135, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「家を建てる」の目的語を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は名詞同士をつなぐもので、「家と建てる」では成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「家から建てる」では建てる対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「家より建てる」では比べる内容がなく文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「家を建てる」の目的語を示す「を」。", "と": "並列の「と」は名詞同士をつなぐもので、「家と建てる」では成り立たない。", "から": "「から」は起点を示すため、「家から建てる」では建てる対象を表せない。", "より": "「より」は比較を示すため、「家より建てる」では比べる内容がなく文が成り立たない。"}, "error_tags": {"と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「建てる」の対義語で、建てたものを壊す意味。"}, {"text": "書く", "is_correct": false, "explanation": "「書く」は文字を記す動作で、「建てる」と対義関係にはない。"}, {"text": "歩く", "is_correct": false, "explanation": "「歩く」は移動の動作で、「建てる」と対義関係にはない。"}, {"text": "届ける", "is_correct": false, "explanation": "「届ける」は物を相手に運ぶ動作で、「建てる」と対義関係にはない。"}], "correct_answer": "壊す", "explanations": {"壊す": "「建てる」の対義語で、建てたものを壊す意味。", "書く": "「書く」は文字を記す動作で、「建てる」と対義関係にはない。", "歩く": "「歩く」は移動の動作で、「建てる」と対義関係にはない。", "届ける": "「届ける」は物を相手に運ぶ動作で、「建てる」と対義関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53135, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いえやたてものをつくります。そこにすむことができます。", "primary_collocate": null, "pronunciation": "たてる", "ipa": "tateɾɯ", "syllable_count": 3, "sentences": [{"text": "来年、海の近くに家を建てるつもりです。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "来年[らいねん]、海[うみ]の近[ちか]くに家[いえ]を建[た]てるつもりです。", "sentence_source": "generated"}, {"text": "祖父は山の中に小さな家を建てて、一人で住んでいます。", "target_word": "建てて", "complexity_tier": "T3", "furigana": "祖父[そふ]は山[やま]の中[なか]に小[ちい]さな家[いえ]を建[た]てて、一人[ひとり]で住[す]んでいます。", "sentence_source": "generated"}, {"text": "土地を買ったので、これから家を建てたいと思っています。", "target_word": "建てたい", "complexity_tier": "T3", "furigana": "土地[とち]を買[か]ったので、これから家[いえ]を建[た]てたいと思[おも]っています。", "sentence_source": "generated"}, {"text": "父は二年前に庭の広い家を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "父[ちち]は二年前[にねんまえ]に庭[にわ]の広[ひろ]い家[いえ]を建[た]てた。", "sentence_source": "generated"}, {"text": "子どもが生まれたので、広い家を建てることにしました。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "子[こ]どもが生[う]まれたので、広[ひろ]い家[いえ]を建[た]てることにしました。", "sentence_source": "generated"}, {"text": "お金がなくて、まだ自分の家を建てられません。", "target_word": "建てられません", "complexity_tier": "T3", "furigana": "お金[かね]がなくて、まだ自分[じぶん]の家[いえ]を建[た]てられません。", "sentence_source": "generated"}, {"text": "地震に強い家を建てるために、丈夫な木を選びました。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "地震[じしん]に強[つよ]い家[いえ]を建[た]てるために、丈夫[じょうぶ]な木[き]を選[えら]びました。", "sentence_source": "generated"}, {"text": "川のそばに家を建てると、大雨のときに危ないです。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "川[かわ]のそばに家[いえ]を建[た]てると、大雨[おおあめ]のときに危[あぶ]ないです。", "sentence_source": "generated"}, {"text": "兄は結婚して、実家の隣に新しい家を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "兄[あに]は結婚[けっこん]して、実家[じっか]の隣[となり]に新[あたら]しい家[いえ]を建[た]てた。", "sentence_source": "generated"}, {"text": "大工さんが三か月かけて、私たちの家を建ててくれました。", "target_word": "建てて", "complexity_tier": "T3", "furigana": "大工[だいく]さんが三[さん]か月[げつ]かけて、私[わたし]たちの家[いえ]を建[た]ててくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "建てる", "label": "終止形"}, {"form": "建てた", "label": "過去形"}, {"form": "建てて", "label": "て形"}, {"form": "建てない", "label": "否定形"}, {"form": "建てれば", "label": "仮定形"}, {"form": "建てよう", "label": "意志形"}, {"form": "建てられる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "住むための家を作る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09538d83-9a44-4f80-ba28-79d49154d0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53135, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建てる", "is_correct": true, "explanation": "辞書形は「つもり」の前に置いて予定を表すので、「家を建てるつもり」は自然に成り立つ。"}, {"text": "建て", "is_correct": false, "explanation": "連用形だけでは「つもり」に続かず、文として成り立たない。"}, {"text": "建てよう", "is_correct": false, "explanation": "意志形は「つもり」の前に直接つながらないので、「建てようつもり」は不自然。"}, {"text": "建てれば", "is_correct": false, "explanation": "仮定形は「つもり」に続かず、「建てればつもり」は成立しない。"}], "explanations": {"建てる": "辞書形は「つもり」の前に置いて予定を表すので、「家を建てるつもり」は自然に成り立つ。", "建て": "連用形だけでは「つもり」に続かず、文として成り立たない。", "建てよう": "意志形は「つもり」の前に直接つながらないので、「建てようつもり」は不自然。", "建てれば": "仮定形は「つもり」に続かず、「建てればつもり」は成立しない。"}, "sentence_index": 0, "correct_answer": "建てる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は二年前に、庭の隅に旗を建てた。", "explanation": "ここは〈立てる〉の意味。旗など細長いものを立てる場合は「立てた」を使い、「建てた」は建築物を完成させる意味なので合わない。"}, {"text": "父は二年前に、家族の夕食を建てた。", "explanation": "ここは〈作る〉の意味（料理を作る）。料理には「作る」を使い、「建てる」は家などの建築物にしか使わないので合わない。"}, {"text": "父は二年前に、庭の大きな本棚を建てた。", "explanation": "ここは〈組み立てる〉の意味。本棚や家具は「組み立てる」で表し、「建てる」は建築物を完成させる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53135, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建てる", "is_correct": true, "explanation": "辞書形は「ために」の前に置いて目的を表すので、文が自然に成り立つ。"}, {"text": "建てろ", "is_correct": false, "explanation": "命令形は「ために」の前に続かず、文が成り立たない。"}, {"text": "建てます", "is_correct": false, "explanation": "丁寧形は文を言い切る形で、「ために」の前には置けない。"}, {"text": "建てなさい", "is_correct": false, "explanation": "丁寧な命令形は文を終わらせる形で、「ために」の前には来ない。"}], "explanations": {"建てる": "辞書形は「ために」の前に置いて目的を表すので、文が自然に成り立つ。", "建てろ": "命令形は「ために」の前に続かず、文が成り立たない。", "建てます": "丁寧形は文を言い切る形で、「ために」の前には置けない。", "建てなさい": "丁寧な命令形は文を終わらせる形で、「ために」の前には来ない。"}, "sentence_index": 6, "correct_answer": "建てる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は二年前に、小さな会社を建てた。", "explanation": "ここは〈立ち上げる〉の意味（事業や組織を始める）。会社は立ち上げるもので、「建てる」は建築物にしか使わないので合わない。"}, {"text": "父は二年前に、毎月の家計の予算を建てた。", "explanation": "ここは〈組む〉の意味（予算や計画を組む）。予算には「組む」を使い、「建てる」は建築物を作る意味なので合わない。"}, {"text": "父は二年前に、家族との信頼を建てた。", "explanation": "ここは〈築く〉の意味（信頼や関係を築く）。信頼は「築く」で表し、「建てる」は建築物を完成させる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53135, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、庭の奥に小さな小屋に建てたそうです。", "corrected_sentence": "祖母は、庭の奥に小さな小屋を建てたそうです。", "error_description": "誤りは「小屋に」の「に」。「建てる」は建てるもの（小屋）を「を」で示すので、正しくは「小屋を建てた」。「に」は場所を表すため目的語にはならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "建てて", "is_correct": true, "explanation": "て形で、後ろの「住んでいます」へつなぐ働きをするので、文の流れに合う。"}, {"text": "建てた", "is_correct": false, "explanation": "過去形は完了を表し、「て」で後ろへつなぐ働きにはならないので、この文の流れに合わない。"}, {"text": "建てない", "is_correct": false, "explanation": "否定形では家を建てないという意味になり、文の内容（建てて住んでいる）と合わない。"}, {"text": "建てられる", "is_correct": false, "explanation": "可能形は建てる能力を表すため、実際に建てて住んでいるという事実と合わない。"}], "correct_form": "建てて", "base_form": "建てる", "form_label": "て形", "sentence_index": 1, "explanations": {"建てて": "て形で、後ろの「住んでいます」へつなぐ働きをするので、文の流れに合う。", "建てた": "過去形は完了を表し、「て」で後ろへつなぐ働きにはならないので、この文の流れに合わない。", "建てない": "否定形では家を建てないという意味になり、文の内容（建てて住んでいる）と合わない。", "建てられる": "可能形は建てる能力を表すため、実際に建てて住んでいるという事実と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53135, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、駅の近くに新しい図書館を建つ予定です。", "corrected_sentence": "市は、駅の近くに新しい図書館を建てる予定です。", "error_description": "誤りは「建つ」。「建てる」は他動詞で目的語に「を」を取るので、正しくは「図書館を建てる」。「建つ」は自動詞で「が」を取るため、「図書館を建つ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "建てる", "is_correct": true, "explanation": "終止形で、「と」に続けて「建てると危ない」という条件文を作るので合う。"}, {"text": "建てて", "is_correct": false, "explanation": "て形は「と」に直接続いて条件を表せず、文として成り立たない。"}, {"text": "建てられません", "is_correct": false, "explanation": "可能の否定形で、建てることができないという意味になり、建てた場合に危ないという文脈と合わない。"}, {"text": "建てろ", "is_correct": false, "explanation": "命令形では家を建てろという命令になり、条件を述べる文として不自然。"}], "correct_form": "建てる", "base_form": "建てる", "form_label": "終止形", "sentence_index": 7, "explanations": {"建てる": "終止形で、「と」に続けて「建てると危ない」という条件文を作るので合う。", "建てて": "て形は「と」に直接続いて条件を表せず、文として成り立たない。", "建てられません": "可能の否定形で、建てることができないという意味になり、建てた場合に危ないという文脈と合わない。", "建てろ": "命令形では家を建てろという命令になり、条件を述べる文として不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53136, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「門を建てる」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「門に建てる」では場所を示すことになり、建てる対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「門が建てる」では門が主語になり、建てる主体と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「門へ建てる」では方向を示すが、建てる対象の表現として不自然。"}], "correct_answer": "を", "explanations": {"を": "「門を建てる」の目的語を示す「を」。", "に": "「門に建てる」では場所を示すことになり、建てる対象を表せない。", "が": "「門が建てる」では門が主語になり、建てる主体と合わない。", "へ": "「門へ建てる」では方向を示すが、建てる対象の表現として不自然。"}, "error_tags": {"に": "場所", "が": "主語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「建てる」の対義語で、建てたものを取り壊す意味。"}, {"text": "磨く", "is_correct": false, "explanation": "「磨く」は表面をきれいにする動作で、「建てる」と対義関係にはない。"}, {"text": "送る", "is_correct": false, "explanation": "「送る」は物を相手へ届ける動作で、「建てる」と対義関係にはない。"}, {"text": "借りる", "is_correct": false, "explanation": "「借りる」は他人の物を一時的に使う動作で、「建てる」と対義関係にはない。"}], "correct_answer": "壊す", "explanations": {"壊す": "「建てる」の対義語で、建てたものを取り壊す意味。", "磨く": "「磨く」は表面をきれいにする動作で、「建てる」と対義関係にはない。", "送る": "「送る」は物を相手へ届ける動作で、「建てる」と対義関係にはない。", "借りる": "「借りる」は他人の物を一時的に使う動作で、「建てる」と対義関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53136, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「茶室を建てた」の目的語を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は名詞同士をつなぐもので、「茶室と建てた」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「茶室から建てた」では建てる対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「茶室より建てた」では比べる内容がなく成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「茶室を建てた」の目的語を示す「を」。", "と": "並列の「と」は名詞同士をつなぐもので、「茶室と建てた」では文が成り立たない。", "から": "「から」は起点を示すため、「茶室から建てた」では建てる対象を表せない。", "より": "「より」は比較を示すため、「茶室より建てた」では比べる内容がなく成り立たない。"}, "error_tags": {"と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "「建てる」の対義語で、建てたものを壊す意味。"}, {"text": "書く", "is_correct": false, "explanation": "「書く」は文字を記す動作で、「建てる」と対義関係にはない。"}, {"text": "歩く", "is_correct": false, "explanation": "「歩く」は移動の動作で、「建てる」と対義関係にはない。"}, {"text": "届ける", "is_correct": false, "explanation": "「届ける」は物を相手に運ぶ動作で、「建てる」と対義関係にはない。"}], "correct_answer": "壊す", "explanations": {"壊す": "「建てる」の対義語で、建てたものを壊す意味。", "書く": "「書く」は文字を記す動作で、「建てる」と対義関係にはない。", "歩く": "「歩く」は移動の動作で、「建てる」と対義関係にはない。", "届ける": "「届ける」は物を相手に運ぶ動作で、「建てる」と対義関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53136, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "構造物や建築物を作り上げる。柱や壁などを組み立てて完成させる。", "primary_collocate": null, "pronunciation": "たてる", "ipa": "tateɾɯ", "syllable_count": 3, "sentences": [{"text": "大工たちは柱と壁を組み立てて、一週間で小屋を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "大工[だいく]たちは柱[はしら]と壁[かべ]を組[く]み立[た]てて、一週間[いっしゅうかん]で小屋[こや]を建[た]てた。", "sentence_source": "generated"}, {"text": "木の柱だけで、お寺の門を建てるのは大変な仕事だ。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "木[き]の柱[はしら]だけで、お寺[てら]の門[もん]を建[た]てるのは大変[たいへん]な仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "基礎ができたら、次は柱を組んで倉庫を建てます。", "target_word": "建てます", "complexity_tier": "T3", "furigana": "基礎[きそ]ができたら、次[つぎ]は柱[はしら]を組[く]んで倉庫[そうこ]を建[た]てます。", "sentence_source": "generated"}, {"text": "彼らは山小屋を建てるために、材木を運び上げた。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "彼[かれ]らは山小屋[やまごや]を建[た]てるために、材木[ざいもく]を運[はこ]び上[あ]げた。", "sentence_source": "generated"}, {"text": "壁も屋根もない状態から、三か月で体育館を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "壁[かべ]も屋根[やね]もない状態[じょうたい]から、三[さん]か月[げつ]で体育館[たいいくかん]を建[た]てた。", "sentence_source": "generated"}, {"text": "雪が多い地方では、屋根を強くして家を建てる必要がある。", "target_word": "建てる", "complexity_tier": "T3", "furigana": "雪[ゆき]が多[おお]い地方[ちほう]では、屋根[やね]を強[つよ]くして家[いえ]を建[た]てる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "設計図のとおりに建てれば、丈夫な建物になります。", "target_word": "建てれば", "complexity_tier": "T3", "furigana": "設計図[せっけいず]のとおりに建[た]てれば、丈夫[じょうぶ]な建物[たてもの]になります。", "sentence_source": "generated"}, {"text": "職人が一人で、庭に小さな茶室を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "職人[しょくにん]が一人[ひとり]で、庭[にわ]に小[ちい]さな茶室[ちゃしつ]を建[た]てた。", "sentence_source": "generated"}, {"text": "木材を切るところから始めて、自分で物置を建てました。", "target_word": "建てました", "complexity_tier": "T3", "furigana": "木材[もくざい]を切[き]るところから始[はじ]めて、自分[じぶん]で物置[ものおき]を建[た]てました。", "sentence_source": "generated"}, {"text": "工事の人たちは、柱を並べて壁を作り、ついに講堂を建てた。", "target_word": "建てた", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]たちは、柱[はしら]を並[なら]べて壁[かべ]を作[つく]り、ついに講堂[こうどう]を建[た]てた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "建てる", "label": "終止形"}, {"form": "建てた", "label": "過去形"}, {"form": "建てて", "label": "て形"}, {"form": "建てない", "label": "否定形"}, {"form": "建てれば", "label": "仮定形"}, {"form": "建てよう", "label": "意志形"}, {"form": "建てられる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "柱や壁を組み立てて建築物を完成させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09538d83-9a44-4f80-ba28-79d49154d0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53136, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建てた", "is_correct": true, "explanation": "過去形で文を言い切り、「一週間で小屋を建てた。」として完成の出来事を表すので合う。"}, {"text": "建て", "is_correct": false, "explanation": "連用形だけでは文を言い切れず、「小屋を建て。」では文が成り立たない。"}, {"text": "建てて", "is_correct": false, "explanation": "て形では文を言い切れず、「小屋を建てて。」で終わるこの文は成り立たない。"}, {"text": "建てれば", "is_correct": false, "explanation": "仮定形は「ば」の後に結果が続く形で、ここでは文が終わらず成り立たない。"}], "explanations": {"建てた": "過去形で文を言い切り、「一週間で小屋を建てた。」として完成の出来事を表すので合う。", "建て": "連用形だけでは文を言い切れず、「小屋を建て。」では文が成り立たない。", "建てて": "て形では文を言い切れず、「小屋を建てて。」で終わるこの文は成り立たない。", "建てれば": "仮定形は「ば」の後に結果が続く形で、ここでは文が終わらず成り立たない。"}, "sentence_index": 0, "correct_answer": "建てた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼らは会議で、新しい方針を建てた。", "explanation": "ここは〈立てる〉の意味（方針を立てる）。方針には「立てる」を使い、「建てる」は建築物を完成させる意味なので合わない。"}, {"text": "彼らは村の祭りで、美しい人形を建てた。", "explanation": "ここは〈作る〉の意味（人形を作る）。工芸品には「作る」を使い、「建てる」は建築物にしか使わないので合わない。"}, {"text": "彼らは十年かけて、地域の信頼を建てた。", "explanation": "ここは〈築く〉の意味（信頼を築く）。信頼は「築く」で表し、「建てる」は建築物を完成させる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53136, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建てれば", "is_correct": true, "explanation": "仮定形で「建てれば、〜なります」の条件を表し、設計図どおりに建てた場合の結果として合う。"}, {"text": "建てよう", "is_correct": false, "explanation": "意志形は「建てよう、」と続く形で、条件を表す文脈には入らない。"}, {"text": "建てろ", "is_correct": false, "explanation": "命令形は文を言い切る形で、「建てろ、丈夫な建物になります」は成り立たない。"}, {"text": "建てさせ", "is_correct": false, "explanation": "使役の語幹では文が完結せず、「建てさせ、」は条件文として成り立たない。"}], "explanations": {"建てれば": "仮定形で「建てれば、〜なります」の条件を表し、設計図どおりに建てた場合の結果として合う。", "建てよう": "意志形は「建てよう、」と続く形で、条件を表す文脈には入らない。", "建てろ": "命令形は文を言い切る形で、「建てろ、丈夫な建物になります」は成り立たない。", "建てさせ": "使役の語幹では文が完結せず、「建てさせ、」は条件文として成り立たない。"}, "sentence_index": 6, "correct_answer": "建てれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼らは創業を機に、小さな会社を建てた。", "explanation": "ここは〈立ち上げる〉の意味（事業を始める）。会社は立ち上げるもので、「建てる」は建築物にしか使わないので合わない。"}, {"text": "彼らは毎月の家計の予算を建てた。", "explanation": "ここは〈組む〉の意味（予算を組む）。予算には「組む」を使い、「建てる」は建築物を作る意味なので合わない。"}, {"text": "彼らは来年の新しい目標を建てた。", "explanation": "ここは〈掲げる〉の意味（目標を掲げる）。目標には「掲げる」を使い、「建てる」は建築物を完成させる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53136, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は庭の奥に、小さな書斎に建てた。", "corrected_sentence": "父は庭の奥に、小さな書斎を建てた。", "error_description": "誤りは「書斎に」の「に」。「建てる」は建てるもの（書斎）を「を」で示すので、正しくは「書斎を建てた」。「に」は場所を表すため目的語にはならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "建てる", "is_correct": true, "explanation": "辞書形で、「建てるのは大変な仕事だ」と名詞句として文の述語につながるので合う。"}, {"text": "建てて", "is_correct": false, "explanation": "て形は「〜のは」に直接続かず、文として成り立たない。"}, {"text": "建てない", "is_correct": false, "explanation": "否定形では門を建てないことが大変だという意味になり、文の内容と合わない。"}, {"text": "建てろ", "is_correct": false, "explanation": "命令形は「〜のは」に続かず、文が成り立たない。"}], "correct_form": "建てる", "base_form": "建てる", "form_label": "終止形", "sentence_index": 1, "explanations": {"建てる": "辞書形で、「建てるのは大変な仕事だ」と名詞句として文の述語につながるので合う。", "建てて": "て形は「〜のは」に直接続かず、文として成り立たない。", "建てない": "否定形では門を建てないことが大変だという意味になり、文の内容と合わない。", "建てろ": "命令形は「〜のは」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53136, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村は、丘の上に新しい集会所を建つ予定です。", "corrected_sentence": "村は、丘の上に新しい集会所を建てる予定です。", "error_description": "誤りは「建つ」。「建てる」は他動詞で目的語に「を」を取るので、正しくは「集会所を建てる」。「建つ」は自動詞なので「集会所を建つ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "建てた", "is_correct": true, "explanation": "過去形で、職人が茶室を建てたという完了した出来事を表し、文の内容に合う。"}, {"text": "建てて", "is_correct": false, "explanation": "て形では文を言い切れず、「庭に小さな茶室を建てて。」では文が成り立たない。"}, {"text": "建てたい", "is_correct": false, "explanation": "願望形では建てたいという気持ちの意味になり、実際に建てたという事実と合わない。"}, {"text": "建てられません", "is_correct": false, "explanation": "可能の否定形で建てることができなかったという意味になり、建てた事実と合わない。"}], "correct_form": "建てた", "base_form": "建てる", "form_label": "過去形", "sentence_index": 7, "explanations": {"建てた": "過去形で、職人が茶室を建てたという完了した出来事を表し、文の内容に合う。", "建てて": "て形では文を言い切れず、「庭に小さな茶室を建てて。」では文が成り立たない。", "建てたい": "願望形では建てたいという気持ちの意味になり、実際に建てたという事実と合わない。", "建てられません": "可能の否定形で建てることができなかったという意味になり、建てた事実と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d0b759-a473-4657-9e50-c739151f8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53137, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在を示す「〜がある」の主語になり、物置きが存在する文として成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「物置きをある」は対象にならず、存在の文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「物置きからある」は成り立たず、存在を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「物置きとある」は並列の関係になり、存在を表す文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "存在を示す「〜がある」の主語になり、物置きが存在する文として成り立つ。", "を": "「物置きをある」は対象にならず、存在の文が成り立たない。", "から": "「物置きからある」は成り立たず、存在を表せない。", "と": "「物置きとある」は並列の関係になり、存在を表す文が成り立たない。"}, "error_tags": {"を": "直接目的語", "から": "起点", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53137, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "状態を述べる主語の「が」で、「物置きが暗い」が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「物置きに暗い」は成り立たず、位置を示す語が文に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、状態の主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「物置きの暗いので」は名詞修飾になり、「暗いので」の主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "状態を述べる主語の「が」で、「物置きが暗い」が成り立つ。", "に": "「物置きに暗い」は成り立たず、位置を示す語が文に合わない。", "から": "起点を示す「から」で、状態の主語にならない。", "の": "「物置きの暗いので」は名詞修飾になり、「暗いので」の主語として成り立たない。"}, "error_tags": {"に": "位置", "から": "起点", "の": "名詞修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53137, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いろいろなものをしまうためのへや。", "primary_collocate": null, "pronunciation": "ものおき", "ipa": "mo̞no̞o̞kʲi", "syllable_count": 4, "sentences": [{"text": "冬になる前に、ストーブを物置きから出した。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "冬[ふゆ]になる前[まえ]に、ストーブを物置[ものお]きから出[だ]した。", "sentence_source": "generated"}, {"text": "この家には、掃除の道具を入れる小さな物置きがある。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "この家[いえ]には、掃除[そうじ]の道具[どうぐ]を入[い]れる小[ちい]さな物置[ものお]きがある。", "sentence_source": "generated"}, {"text": "物置きは古い物でいっぱいで、人が入れない。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "物置[ものお]きは古[ふる]い物[もの]でいっぱいで、人[ひと]が入[はい]れない。", "sentence_source": "generated"}, {"text": "兄は物置きから自転車の空気入れを持ってきた。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "兄[あに]は物置[ものお]きから自転車[じてんしゃ]の空気入[くうきい]れを持[も]ってきた。", "sentence_source": "generated"}, {"text": "夏に使う扇風機は、秋になると物置きにしまう。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "夏[なつ]に使[つか]う扇風機[せんぷうき]は、秋[あき]になると物置[ものお]きにしまう。", "sentence_source": "generated"}, {"text": "物置きの戸を開けると、ほこりのにおいがした。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "物置[ものお]きの戸[と]を開[あ]けると、ほこりのにおいがした。", "sentence_source": "generated"}, {"text": "母は物置きを片付けて、広い場所を作った。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "母[はは]は物置[ものお]きを片付[かたづ]けて、広[ひろ]い場所[ばしょ]を作[つく]った。", "sentence_source": "generated"}, {"text": "物置きが暗いので、電気をつけてから入った。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "物置[ものお]きが暗[くら]いので、電気[でんき]をつけてから入[はい]った。", "sentence_source": "generated"}, {"text": "使わない食器は、台所の隣の物置きに置いている。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "使[つか]わない食器[しょっき]は、台所[だいどころ]の隣[となり]の物置[ものお]きに置[お]いている。", "sentence_source": "generated"}, {"text": "祖父の物置きには、昔の道具がたくさん残っている。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "祖父[そふ]の物置[ものお]きには、昔[むかし]の道具[どうぐ]がたくさん残[のこ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物置き", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "いろいろな物を入れておく小さなへや", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53137, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物置き", "is_correct": true, "explanation": "物を入れておく部屋を指し、ストーブを取り出す場所として文に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "錠を開ける道具で、ストーブを取り出す場所にはならない。"}, {"text": "軍手", "is_correct": false, "explanation": "作業用の手袋で、物を出し入れする場所とは言えない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "口を磨く道具で、ストーブを取り出す場所ではない。"}], "explanations": {"物置き": "物を入れておく部屋を指し、ストーブを取り出す場所として文に合う。", "鍵": "錠を開ける道具で、ストーブを取り出す場所にはならない。", "軍手": "作業用の手袋で、物を出し入れする場所とは言えない。", "歯ブラシ": "口を磨く道具で、ストーブを取り出す場所ではない。"}, "sentence_index": 0, "correct_answer": "物置き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は毎朝、物置きでお風呂に入ってから出かける。", "explanation": "ここは〈浴室〉の意味。物置きは物をしまう部屋で、入浴する場所としては使わないので合わない。"}, {"text": "祖父は毎晩、物置きに車を入れて鍵をかける。", "explanation": "ここは〈車庫〉の意味。物置きは物を入れる部屋で、車を止める場所として使うのは不自然。"}, {"text": "台所の物置きの引き出しから、箸を取り出した。", "explanation": "ここは〈物入れ〉の意味。物置きは部屋のことで、引き出しという家具の部分を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53137, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物置き", "is_correct": true, "explanation": "物を入れて片付けられる部屋を指し、広い場所を作る対象として文に合う。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の現象で、片付ける対象にはならないので文が成り立たない。"}, {"text": "虹", "is_correct": false, "explanation": "空に現れる現象で、片付けて広い場所を作る対象ではない。"}, {"text": "雷", "is_correct": false, "explanation": "自然現象で、片付けて広い場所を作ることとは結びつかない。"}], "explanations": {"物置き": "物を入れて片付けられる部屋を指し、広い場所を作る対象として文に合う。", "夕焼け": "空の現象で、片付ける対象にはならないので文が成り立たない。", "虹": "空に現れる現象で、片付けて広い場所を作る対象ではない。", "雷": "自然現象で、片付けて広い場所を作ることとは結びつかない。"}, "sentence_index": 6, "correct_answer": "物置き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その小説の物置きは、結末が意外で面白かった。", "explanation": "ここは〈物語（ストーリー）〉の意味。物置きは部屋のことで、作品の筋や結末には使わないので合わない。"}, {"text": "兄は物置きで毎朝、朝食を作る。", "explanation": "ここは〈台所〉の意味。物置きは物をしまう部屋で、料理をする場所としては使わないので合わない。"}, {"text": "お客さんは物置きで靴を脱いでから、居間へ上がった。", "explanation": "ここは〈玄関〉の意味。物置きは出入りの場所ではなく、靴を脱ぐ所としては使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53137, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いおもちゃは、物置きからしまった。", "corrected_sentence": "古いおもちゃは、物置きにしまった。", "error_description": "「しまう」の場所は「に」で示す。「から」は起点を表すため、しまう先としては誤り。正しくは「物置きに」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53137, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の服は、秋になると物置きがしまう。", "corrected_sentence": "夏の服は、秋になると物置きにしまう。", "error_description": "「しまう」の場所は「に」で示す。「物置きが」だと主語になり、しまう先として成り立たない。正しくは「物置きに」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53138, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "しまう先（収納場所）を示す「に」で、物置きが収納先になる。"}, {"text": "が", "is_correct": false, "explanation": "「物置きが」は主語になり、「しまってある」の対象として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「物置きを」は対象を示すが、しまわれているのは物で、物置きではない。"}, {"text": "と", "is_correct": false, "explanation": "「物置きと」は並列や相手を示し、収納場所の関係を作れない。"}], "correct_answer": "に", "explanations": {"に": "しまう先（収納場所）を示す「に」で、物置きが収納先になる。", "が": "「物置きが」は主語になり、「しまってある」の対象として成り立たない。", "を": "「物置きを」は対象を示すが、しまわれているのは物で、物置きではない。", "と": "「物置きと」は並列や相手を示し、収納場所の関係を作れない。"}, "error_tags": {"が": "主語（動作の主体）", "を": "直接目的語（しまう物）", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53138, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "遊びが行われる場所を示す「で」で、物置きが遊んだ場所になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向（移動先）を示す「へ」で、遊ぶ場所を指すには合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、遊んだ場所としては成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」で、場所の関係としては文が通らない。"}], "correct_answer": "で", "explanations": {"で": "遊びが行われる場所を示す「で」で、物置きが遊んだ場所になる。", "へ": "方向（移動先）を示す「へ」で、遊ぶ場所を指すには合わない。", "から": "起点を示す「から」で、遊んだ場所としては成り立たない。", "より": "比較を示す「より」で、場所の関係としては文が通らない。"}, "error_tags": {"へ": "方向（移動先）", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53138, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家の中で、使わないものや備品を保管しておくための部屋。", "primary_collocate": null, "pronunciation": "ものおき", "ipa": "mo̞no̞o̞kʲi", "syllable_count": 4, "sentences": [{"text": "単なる物置きではなく、創造性を刺激する空間にしたいと考えたのだ。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "単[たん]なる物置[ものお]きではなく、創造性[そうぞうせい]を刺激[しげき]する空間[くうかん]にしたいと考[かんが]えたのだ。", "sentence_source": "mined"}, {"text": "使わなくなったストーブは、階段の下の物置きにしまってある。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "使[つか]わなくなったストーブは、階段[かいだん]の下[した]の物置[ものお]きにしまってある。", "sentence_source": "generated"}, {"text": "大掃除の日に、父は物置きから古いアルバムを見つけ出した。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "大掃除[おおそうじ]の日[ひ]に、父[ちち]は物置[ものお]きから古[ふる]いアルバムを見[み]つけ出[だ]した。", "sentence_source": "generated"}, {"text": "物置きが散らかっていて、工具がどこにあるか分からなかった。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "物置[ものお]きが散[ち]らかっていて、工具[こうぐ]がどこにあるか分[わ]からなかった。", "sentence_source": "generated"}, {"text": "来客用の布団は、二階の物置きに入れておくことにした。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "来客用[らいきゃくよう]の布団[ふとん]は、二階[にかい]の物置[ものお]きに入[い]れておくことにした。", "sentence_source": "generated"}, {"text": "物置きの奥は暗かったので、懐中電灯を持って入った。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "物置[ものお]きの奥[おく]は暗[くら]かったので、懐中電灯[かいちゅうでんとう]を持[も]って入[はい]った。", "sentence_source": "generated"}, {"text": "引っ越しの前に、物置きの中身を全部整理しなければならない。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの前[まえ]に、物置[ものお]きの中身[なかみ]を全部[ぜんぶ]整理[せいり]しなければならない。", "sentence_source": "generated"}, {"text": "子どものころ、雨の日は物置きで隠れんぼをして遊んだ。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "子[こ]どものころ、雨[あめ]の日[ひ]は物置[ものお]きで隠[かく]れんぼをして遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "物置きを書斎に変えたので、家族が本を読む場所が増えた。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "物置[ものお]きを書斎[しょさい]に変[か]えたので、家族[かぞく]が本[ほん]を読[よ]む場所[ばしょ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "季節外れの服は、押し入れではなく物置きに保管している。", "target_word": "物置き", "complexity_tier": "T3", "furigana": "季節外[きせつはず]れの服[ふく]は、押[お]し入[い]れではなく物置[ものお]きに保管[ほかん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物置き", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家の中にある、使わない物をしまっておく収納用の部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53138, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物置き", "is_correct": true, "explanation": "不用品をしまう部屋を指し、「空間にしたい」対象として文に合う。"}, {"text": "洗濯ばさみ", "is_correct": false, "explanation": "小さな道具で、「単なる〜ではなく、創造性を刺激する空間」の対象にはならない。"}, {"text": "懐中電灯", "is_correct": false, "explanation": "持ち歩く照明器具で、創造性を刺激する空間とは結びつかない。"}, {"text": "電子レンジ", "is_correct": false, "explanation": "調理家電で、空間として作り変える対象ではないので文が成り立たない。"}], "explanations": {"物置き": "不用品をしまう部屋を指し、「空間にしたい」対象として文に合う。", "洗濯ばさみ": "小さな道具で、「単なる〜ではなく、創造性を刺激する空間」の対象にはならない。", "懐中電灯": "持ち歩く照明器具で、創造性を刺激する空間とは結びつかない。", "電子レンジ": "調理家電で、空間として作り変える対象ではないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "物置き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家族は物置きでお茶を飲みながら、テレビを見た。", "explanation": "ここは〈居間〉の意味。物置きは物をしまう部屋で、くつろいでお茶を飲む場所としては使わないので合わない。"}, {"text": "物置きの引き出しを開けて、ハンカチを探した。", "explanation": "ここは〈物入れ〉の意味。物置きは部屋のことで、引き出しという家具の部分を指さないので合わない。"}, {"text": "父は毎朝、物置きから車を出して会社へ向かった。", "explanation": "ここは〈車庫〉の意味。物置きは物をしまう部屋で、車を止める場所としては使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53138, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物置き", "is_correct": true, "explanation": "中身を整理する対象になる収納用の部屋を指し、文に合う。"}, {"text": "階段", "is_correct": false, "explanation": "通路で、中身を入れて整理する場所ではないので文が成り立たない。"}, {"text": "扇風機", "is_correct": false, "explanation": "家電で、中身を入れる場所ではないため「中身を整理」と合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の現象で、中身を整理する対象にはならないので文が成り立たない。"}], "explanations": {"物置き": "中身を整理する対象になる収納用の部屋を指し、文に合う。", "階段": "通路で、中身を入れて整理する場所ではないので文が成り立たない。", "扇風機": "家電で、中身を入れる場所ではないため「中身を整理」と合わない。", "夕焼け": "空の現象で、中身を整理する対象にはならないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "物置き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その映画の物置きは、最後まで意外で面白かった。", "explanation": "ここは〈物語（ストーリー）〉の意味。物置きは部屋のことで、話の展開には使わないので合わない。"}, {"text": "母は物置きで毎晩、夕飯を作っている。", "explanation": "ここは〈台所〉の意味。物置きは物をしまう部屋で、料理をする場所としては使わないので合わない。"}, {"text": "客は物置きで靴を脱いで、上がった。", "explanation": "ここは〈玄関〉の意味。物置きは出入りの場所ではなく、靴を脱ぐ所としては使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53138, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は古い手紙を物置きを保管している。", "corrected_sentence": "祖母は古い手紙を物置きに保管している。", "error_description": "「保管する」の置き場所は「に」で示す。「物置きを」と誤ると、対象を示す「を」を使ったことになる。正しくは「物置きに」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53138, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いストーブは、物置きが保管してある。", "corrected_sentence": "古いストーブは、物置きに保管してある。", "error_description": "保管する場所を示すのは「に」。「物置きが」だと主語になり、「保管してある」の場所として成り立たない。正しくは「物置きに」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53155, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ヴォールトには」の「に」は、石の跡が残っている場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「ヴォールトが」の形では、場所を示す文の流れに合わず、「は」と続けても不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「ヴォールトを」は対象を示すが、跡が残るという自動詞の文には合わない。"}, {"text": "も", "is_correct": false, "explanation": "「ヴォールトも」の形では、直後の「は」と重なり不自然で文が通らない。"}], "correct_answer": "に", "explanations": {"に": "「ヴォールトには」の「に」は、石の跡が残っている場所を示す。", "が": "「ヴォールトが」の形では、場所を示す文の流れに合わず、「は」と続けても不自然になる。", "を": "「ヴォールトを」は対象を示すが、跡が残るという自動詞の文には合わない。", "も": "「ヴォールトも」の形では、直後の「は」と重なり不自然で文が通らない。"}, "error_tags": {"が": "主語の取り違え", "を": "対象の取り違え", "も": "「は」との重複"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53155, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ヴォールトの下を」の「の」は、ヴォールトと下の位置関係をつなぐ。"}, {"text": "に", "is_correct": false, "explanation": "「ヴォールトに下を」では位置関係が結べず、不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「ヴォールトで下を」は手段や場所を示すが、位置関係をつなぐ語にはならない。"}, {"text": "が", "is_correct": false, "explanation": "「ヴォールトが下を」では主語になり、通り抜ける場所を示す文の流れに合わない。"}], "correct_answer": "の", "explanations": {"の": "「ヴォールトの下を」の「の」は、ヴォールトと下の位置関係をつなぐ。", "に": "「ヴォールトに下を」では位置関係が結べず、不自然になる。", "で": "「ヴォールトで下を」は手段や場所を示すが、位置関係をつなぐ語にはならない。", "が": "「ヴォールトが下を」では主語になり、通り抜ける場所を示す文の流れに合わない。"}, "error_tags": {"に": "対象・相手の取り違え", "で": "手段・場所の取り違え", "が": "主語の取り違え"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53155, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "屋根や天井がアーチのかたちになっているところです。石やコンクリートでできています。建物の上の部分を支えています。", "primary_collocate": null, "pronunciation": "ゔぉーると", "ipa": "voːɾɯto", "syllable_count": 4, "sentences": [{"text": "教会に入ると、高いヴォールトが頭の上に広がっていた。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "教会[きょうかい]に入[はい]ると、高[たか]いヴォールトが頭[あたま]の上[うえ]に広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "古い地下室のヴォールトには、石を組んだ跡がはっきり残っている。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "古[ふる]い地下室[ちかしつ]のヴォールトには、石[いし]を組[く]んだ跡[あと]がはっきり残[のこ]っている。", "sentence_source": "generated"}, {"text": "このヴォールトには、小さな星の絵がたくさん描かれている。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "このヴォールトには、小[ちい]さな星[ほし]の絵[え]がたくさん描[か]かれている。", "sentence_source": "generated"}, {"text": "この図書館は、石でできたヴォールトの下に静かな読書室がある。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "この図書館[としょかん]は、石[いし]でできたヴォールトの下[した]に静[しず]かな読書室[どくしょしつ]がある。", "sentence_source": "generated"}, {"text": "雨がひどかったので、私たちは駅のヴォールトの下で雨宿りをした。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "雨[あめ]がひどかったので、私[わたし]たちは駅[えき]のヴォールトの下[した]で雨宿[あまやど]りをした。", "sentence_source": "generated"}, {"text": "ヴォールトの内側は丸くなっているので、小さな声もよく響く。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "ヴォールトの内側[うちがわ]は丸[まる]くなっているので、小[ちい]さな声[こえ]もよく響[ひび]く。", "sentence_source": "generated"}, {"text": "修道院のヴォールトは、何百年も前の石でできている。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "修道院[しゅうどういん]のヴォールトは、何百年[なんびゃくねん]も前[まえ]の石[いし]でできている。", "sentence_source": "generated"}, {"text": "コンクリートのヴォールトの下を、電車がゆっくり通っていった。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "コンクリートのヴォールトの下[した]を、電車[でんしゃ]がゆっくり通[とお]っていった。", "sentence_source": "generated"}, {"text": "見上げると、ヴォールトの中央に大きな窓があり、光が差していた。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "見上[みあ]げると、ヴォールトの中央[ちゅうおう]に大[おお]きな窓[まど]があり、光[ひかり]が差[さ]していた。", "sentence_source": "generated"}, {"text": "父は古い教会のヴォールトの形がきれいだと言って、写真を何枚も撮った。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "父[ちち]は古[ふる]い教会[きょうかい]のヴォールトの形[かたち]がきれいだと言[い]って、写真[しゃしん]を何枚[なんまい]も撮[と]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ヴォールト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "建物の中の、アーチ形になっている天井・屋根の部分そのもの(石やコンクリート製で見上げたり下に立ったりする場所)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53155, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ヴォールト", "is_correct": true, "explanation": "「高いヴォールトが頭の上に広がる」は、教会の天井の形として自然に合う。"}, {"text": "祭壇", "is_correct": false, "explanation": "「祭壇」は礼拝の台で、頭の上に広がる形の主語にはならない。"}, {"text": "聖書", "is_correct": false, "explanation": "「聖書」は本で、高さや広がりを持つ構造の主語には合わない。"}, {"text": "長椅子", "is_correct": false, "explanation": "「長椅子」は座る家具で、頭の上に広がる構造の主語としては合わない。"}], "explanations": {"ヴォールト": "「高いヴォールトが頭の上に広がる」は、教会の天井の形として自然に合う。", "祭壇": "「祭壇」は礼拝の台で、頭の上に広がる形の主語にはならない。", "聖書": "「聖書」は本で、高さや広がりを持つ構造の主語には合わない。", "長椅子": "「長椅子」は座る家具で、頭の上に広がる構造の主語としては合わない。"}, "sentence_index": 0, "correct_answer": "ヴォールト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖にヴォールトを浮かべて、釣りを楽しんだ。", "explanation": "ここは〈ボート〉（水に浮かぶ小さな船）の意味。ヴォールトはアーチ状の天井・屋根の構造で、水上で使う乗り物は指さない。"}, {"text": "板張りのヴォールトの上で、体育の授業が行われている。", "explanation": "ここは〈床〉の意味。ヴォールトはアーチ状の天井・屋根を指し、授業をする床面には使わない。"}, {"text": "このヴォールトは、壁に沿って真っすぐ立っている。", "explanation": "ここは〈壁〉の意味。ヴォールトはアーチ状の天井・屋根の部分で、垂直に立つ壁には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53155, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ヴォールト", "is_correct": true, "explanation": "「修道院のヴォールトは」の主語として、石でできた建築部分の説明に合う。"}, {"text": "オルガン", "is_correct": false, "explanation": "「オルガン」は楽器で、石でできているという説明には合わない。"}, {"text": "鐘", "is_correct": false, "explanation": "「鐘」は金属製が多く、石でできているという説明には合わない。"}, {"text": "聖歌", "is_correct": false, "explanation": "「聖歌」は歌で、材料の説明の主語として成り立たない。"}], "explanations": {"ヴォールト": "「修道院のヴォールトは」の主語として、石でできた建築部分の説明に合う。", "オルガン": "「オルガン」は楽器で、石でできているという説明には合わない。", "鐘": "「鐘」は金属製が多く、石でできているという説明には合わない。", "聖歌": "「聖歌」は歌で、材料の説明の主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "ヴォールト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "倉庫の扉に、ヴォールトをかけて閉めた。", "explanation": "ここは〈錠〉（扉を閉ざす装置）の意味。ヴォールトはアーチ状の天井・屋根の構造で、扉を閉ざす装置は指さない。"}, {"text": "コンサートの最後で、会場のヴォールトが一気に上がった。", "explanation": "ここは〈ボルテージ〉（熱気の度合い）の意味。ヴォールトは建築の天井・屋根を指し、熱気の度合いは表さない。"}, {"text": "このヴォールトのふたを開けて、ごみを捨てた。", "explanation": "ここは〈ごみ箱〉（ふたのついた容器）の意味。ヴォールトはアーチ状の天井・屋根の構造で、ごみを入れる容器は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53155, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教会の入口は、アーチ状のヴォールトが覆われている。", "corrected_sentence": "教会の入口は、アーチ状のヴォールトに覆われている。", "error_description": "「覆われている」は受け身で、覆う側のヴォールトは「に」で示す。「が」は誤りで、正しくは「ヴォールトに覆われている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53155, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "石造りのヴォールトを下で、子どもたちが遊んでいる。", "corrected_sentence": "石造りのヴォールトの下で、子どもたちが遊んでいる。", "error_description": "「下で」は場所を表すため、ヴォールトと「下」は「の」でつなぐ。「を」は誤りで、正しくは「ヴォールトの下で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53156, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ヴォールトを使うと」の「を」は使う対象を示し、他動詞の目的語として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「ヴォールトが使うと」では、ヴォールトが使う主体になり不自然で、文の意味が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「ヴォールトと使うと」は並列の形になり、使う対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「ヴォールトから使うと」は起点を表し、使う対象としては合わない。"}], "correct_answer": "を", "explanations": {"を": "「ヴォールトを使うと」の「を」は使う対象を示し、他動詞の目的語として正しい。", "が": "「ヴォールトが使うと」では、ヴォールトが使う主体になり不自然で、文の意味が成り立たない。", "と": "「ヴォールトと使うと」は並列の形になり、使う対象を示せない。", "から": "「ヴォールトから使うと」は起点を表し、使う対象としては合わない。"}, "error_tags": {"が": "主語の取り違え", "と": "並列・共同", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53156, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53156, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の天井や屋根を、アーチ状に造った構造のことです。重量を支えて広い空間を作るときに使われます。", "primary_collocate": null, "pronunciation": "ゔぉーると", "ipa": "voːɾɯto", "syllable_count": 4, "sentences": [{"text": "ヴォールトは天井の重さを壁へ分けて伝える、昔からの建築の仕組みだ。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "ヴォールトは天井[てんじょう]の重[おも]さを壁[かべ]へ分[わ]けて伝[つた]える、昔[むかし]からの建築[けんちく]の仕組[しく]みだ。", "sentence_source": "generated"}, {"text": "ヴォールトを使うと、柱の少ない広い空間を作ることができる。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "ヴォールトを使[つか]うと、柱[はしら]の少[すく]ない広[ひろ]い空間[くうかん]を作[つく]ることができる。", "sentence_source": "generated"}, {"text": "ローマ時代の建築家は、石を積んでヴォールトを造り、重い屋根を支えた。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "ローマ時代[じだい]の建築家[けんちくか]は、石[いし]を積[つ]んでヴォールトを造[つく]り、重[おも]い屋根[やね]を支[ささ]えた。", "sentence_source": "generated"}, {"text": "ヴォールトの重さは、壁や柱に伝わって地面へ流れていく。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "ヴォールトの重[おも]さは、壁[かべ]や柱[はしら]に伝[つた]わって地面[じめん]へ流[なが]れていく。", "sentence_source": "generated"}, {"text": "この駅は、ヴォールトの構造のおかげで、中に柱が一本もない。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "この駅[えき]は、ヴォールトの構造[こうぞう]のおかげで、中[なか]に柱[はしら]が一本[いっぽん]もない。", "sentence_source": "generated"}, {"text": "ゴシック建築では、尖ったアーチを使ったヴォールトが高い天井を可能にした。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "ゴシック建築[けんちく]では、尖[とが]ったアーチを使[つか]ったヴォールトが高[たか]い天井[てんじょう]を可能[かのう]にした。", "sentence_source": "generated"}, {"text": "ヴォールトは外側へ広がろうとする力が強いため、厚い壁で支える必要がある。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "ヴォールトは外側[そとがわ]へ広[ひろ]がろうとする力[ちから]が強[つよ]いため、厚[あつ]い壁[かべ]で支[ささ]える必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "半円形のアーチを長く伸ばした形のヴォールトは、トンネルに似ている。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "半円形[はんえんけい]のアーチを長[なが]く伸[の]ばした形[かたち]のヴォールトは、トンネルに似[に]ている。", "sentence_source": "generated"}, {"text": "修復の専門家は、ひびが入ったヴォールトを慎重に調べた。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "修復[しゅうふく]の専門家[せんもんか]は、ひびが入[はい]ったヴォールトを慎重[しんちょう]に調[しら]べた。", "sentence_source": "generated"}, {"text": "現代の建築でも、コンクリートのヴォールトは大きな体育館に使われている。", "target_word": "ヴォールト", "complexity_tier": "T3", "furigana": "現代[げんだい]の建築[けんちく]でも、コンクリートのヴォールトは大[おお]きな体育館[たいいくかん]に使[つか]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ヴォールト", "label": "基本形"}], "register": "technical", "sense_fingerprint": "建築の構造としてのヴォールト(アーチ状の天井・屋根を造る工法。重さを支え広い空間を作る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53156, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ヴォールト", "is_correct": true, "explanation": "「ヴォールトは天井の重さを壁へ分けて伝える」は、アーチ状の天井構造の名称として自然に入る。"}, {"text": "ファサード", "is_correct": false, "explanation": "「ファサード」は建物の正面を指す語で、天井の重量を分散させる構造名には合わない。"}, {"text": "バルコニー", "is_correct": false, "explanation": "「バルコニー」は張り出した台のことで、天井の重量を分散させる構造名にはならない。"}, {"text": "ペディメント", "is_correct": false, "explanation": "「ペディメント」は建物正面の三角形の装飾部分で、天井の重さを伝える仕組みの名称には合わない。"}], "explanations": {"ヴォールト": "「ヴォールトは天井の重さを壁へ分けて伝える」は、アーチ状の天井構造の名称として自然に入る。", "ファサード": "「ファサード」は建物の正面を指す語で、天井の重量を分散させる構造名には合わない。", "バルコニー": "「バルコニー」は張り出した台のことで、天井の重量を分散させる構造名にはならない。", "ペディメント": "「ペディメント」は建物正面の三角形の装飾部分で、天井の重さを伝える仕組みの名称には合わない。"}, "sentence_index": 0, "correct_answer": "ヴォールト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁の板を、ヴォールトでしっかり留めた。", "explanation": "ここは〈ボルト〉（ねじで締める留め具）の意味。ヴォールトはアーチ状の天井・屋根の構造で、板を締めて留める部品は指さない。"}, {"text": "このバンドはヴォールトが美しく、歌声に人気がある。", "explanation": "ここは〈ヴォーカル〉（歌い手）の意味。ヴォールトは建築の天井や屋根の構造で、歌声には使わない。"}, {"text": "この部屋のヴォールトは平らで、天井が低い。", "explanation": "ここは〈天井〉の意味。ヴォールトはアーチ状の構造を指すので、平らな天井には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53156, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ヴォールト", "is_correct": true, "explanation": "「___は外側へ広がろうとする力が強い」の主語として、アーチ構造の性質を説明するので自然に入る。"}, {"text": "ガラス", "is_correct": false, "explanation": "「ガラス」は割れやすい素材で、外側へ広がる力を受ける構造の説明には合わない。"}, {"text": "絨毯", "is_correct": false, "explanation": "「絨毯」は床に敷く布で、構造の力の性質を説明する主語として合わない。"}, {"text": "照明", "is_correct": false, "explanation": "「照明」は明かりを出す器具で、建物の構造が持つ力を説明する文には合わない。"}], "explanations": {"ヴォールト": "「___は外側へ広がろうとする力が強い」の主語として、アーチ構造の性質を説明するので自然に入る。", "ガラス": "「ガラス」は割れやすい素材で、外側へ広がる力を受ける構造の説明には合わない。", "絨毯": "「絨毯」は床に敷く布で、構造の力の性質を説明する主語として合わない。", "照明": "「照明」は明かりを出す器具で、建物の構造が持つ力を説明する文には合わない。"}, "sentence_index": 6, "correct_answer": "ヴォールト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝室の窓に、ヴォールトをかけて光をさえぎった。", "explanation": "ここは〈カーテン〉（布を掛けて光をさえぎるもの）の意味。ヴォールトはアーチ状の天井・屋根の構造で、窓に掛ける布は表さない。"}, {"text": "会場のヴォールトが上がって、観客が盛り上がった。", "explanation": "ここは〈ボルテージ〉（熱気の度合い）の意味。ヴォールトは建築の構造で、熱気の度合いは表さない。"}, {"text": "体育館のヴォールトで、バスケットボールを弾ませた。", "explanation": "ここは〈床〉の意味。ヴォールトは天井や屋根の構造を指し、ボールを弾ませる面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53156, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "石造りのヴォールトが補強するため、足場が組まれた。", "corrected_sentence": "石造りのヴォールトを補強するため、足場が組まれた。", "error_description": "「補強する」は他動詞なので、補強される対象は「を」で示す。「が」は誤りで、正しくは「ヴォールトを補強する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53156, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ローマの石工が、ヴォールトに造って屋根を支えた。", "corrected_sentence": "ローマの石工が、ヴォールトを造って屋根を支えた。", "error_description": "「造る」は他動詞で、作る対象は「を」で示す。「に」は誤りで、正しくは「ヴォールトを造って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53161, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「水が満ちあふれていた」で、満ちる主語を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「水を満ちあふれていた」は目的語の形になり、主語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「水と満ちあふれていた」は並列の形になり、主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「水へ満ちあふれていた」は方向の形で、主語を示す文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「水が満ちあふれていた」で、満ちる主語を示す「が」が正しい。", "を": "「水を満ちあふれていた」は目的語の形になり、主語として成り立たない。", "と": "「水と満ちあふれていた」は並列の形になり、主語を示せない。", "へ": "「水へ満ちあふれていた」は方向の形で、主語を示す文に合わない。"}, "error_tags": {"を": "目的語", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53161, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「朝日に満ちあふれた」で、満ちる対象を示す「に」が正しい。"}, {"text": "で", "is_correct": false, "explanation": "「朝日で満ちあふれた」は手段の形になり、満ちる主体の朝日を示せないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「朝日から満ちあふれた」は起点の形で、満ちる対象を示す文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「朝日より満ちあふれた」は比較の形になり、満ちる対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「朝日に満ちあふれた」で、満ちる対象を示す「に」が正しい。", "で": "「朝日で満ちあふれた」は手段の形になり、満ちる主体の朝日を示せないので合わない。", "から": "「朝日から満ちあふれた」は起点の形で、満ちる対象を示す文に合わない。", "より": "「朝日より満ちあふれた」は比較の形になり、満ちる対象を示せない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53161, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "中がいっぱいになって、あふれ出ることをいいます。水や光がたくさんあるときに使います。", "primary_collocate": null, "pronunciation": "みちあふれる", "ipa": "mit͡ɕiaɸɯɾeɾɯ", "syllable_count": 6, "sentences": [{"text": "朝の光が部屋いっぱいに満ちあふれている。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "朝[あさ]の光[ひかり]が部屋[へや]いっぱいに満[み]ちあふれている。", "sentence_source": "generated"}, {"text": "大雨のあと、池には水が満ちあふれていた。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のあと、池[いけ]には水[みず]が満[み]ちあふれていた。", "sentence_source": "generated"}, {"text": "窓を開けると、部屋に光が満ちあふれました。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、部屋[へや]に光[ひかり]が満[み]ちあふれました。", "sentence_source": "generated"}, {"text": "雪どけの季節になると、川は水に満ちあふれる。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "雪[ゆき]どけの季節[きせつ]になると、川[かわ]は水[みず]に満[み]ちあふれる。", "sentence_source": "generated"}, {"text": "森の中は、木々の間から差す光に満ちあふれていた。", "target_word": "満ちあふれ", "complexity_tier": "T4", "furigana": "森[もり]の中[なか]は、木々[きぎ]の間[あいだ]から差[さ]す光[ひかり]に満[み]ちあふれていた。", "sentence_source": "generated"}, {"text": "夏の海は、まぶしい光に満ちあふれている。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "夏[なつ]の海[うみ]は、まぶしい光[ひかり]に満[み]ちあふれている。", "sentence_source": "generated"}, {"text": "ダムは雨水に満ちあふれ、放水が始まった。", "target_word": "満ちあふれ", "complexity_tier": "T4", "furigana": "ダムは雨水[あまみず]に満[み]ちあふれ、放水[ほうすい]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "朝日に満ちあふれた台所で、母がお茶をいれた。", "target_word": "満ちあふれ", "complexity_tier": "T4", "furigana": "朝日[あさひ]に満[み]ちあふれた台所[だいどころ]で、母[はは]がお茶[ちゃ]をいれた。", "sentence_source": "generated"}, {"text": "夕方、空も海もオレンジ色の光に満ちあふれた。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]、空[そら]も海[うみ]もオレンジ色[いろ]の光[ひかり]に満[み]ちあふれた。", "sentence_source": "generated"}, {"text": "満月の夜、庭は白い光に満ちあふれていた。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "満月[まんげつ]の夜[よる]、庭[にわ]は白[しろ]い光[ひかり]に満[み]ちあふれていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "満ちあふれる", "label": "辞書形"}, {"form": "満ちあふれ", "label": "連用形"}, {"form": "満ちあふれた", "label": "過去形"}, {"form": "満ちあふれて", "label": "て形"}, {"form": "満ちあふれない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "水や光がたくさんあって、場所いっぱいになりあふれ出る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53161, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "満ちあふれ", "is_correct": true, "explanation": "「朝の光が部屋いっぱいに満ちあふれている」で、光が部屋を満たす意味に合う。"}, {"text": "凍え", "is_correct": false, "explanation": "「部屋いっぱいに凍えている」は意味が通らず、光の文脈に合わない。"}, {"text": "壊れ", "is_correct": false, "explanation": "「部屋いっぱいに壊れている」は光の状態を表せず、文が成立しない。"}, {"text": "遠ざかり", "is_correct": false, "explanation": "「部屋いっぱいに遠ざかっている」は、光が部屋を満たす文と合わない。"}], "explanations": {"満ちあふれ": "「朝の光が部屋いっぱいに満ちあふれている」で、光が部屋を満たす意味に合う。", "凍え": "「部屋いっぱいに凍えている」は意味が通らず、光の文脈に合わない。", "壊れ": "「部屋いっぱいに壊れている」は光の状態を表せず、文が成立しない。", "遠ざかり": "「部屋いっぱいに遠ざかっている」は、光が部屋を満たす文と合わない。"}, "sentence_index": 0, "correct_answer": "満ちあふれ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、潮が満ちあふれて港に入ってきた。", "explanation": "ここは〈満ちる〉の意味。潮が満ちるのは水位が上がることで、あふれ出るとは言わないので合わない。"}, {"text": "食べすぎて、お腹が満ちあふれた。", "explanation": "ここは〈満腹〉の意味。お腹がいっぱいになるさまで、中身があふれ出る状態には使わないので合わない。"}, {"text": "日照りで池の水が満ちあふれた。", "explanation": "ここは〈減る〉の意味。水が減る場面では、いっぱいになってはみ出す満ちあふれるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53161, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "満ちあふれ", "is_correct": true, "explanation": "「ダムは雨水に満ちあふれ、放水が始まった」で、雨水がダムをいっぱいにする意味に合う。"}, {"text": "迷い", "is_correct": false, "explanation": "「ダムは雨水に迷い」は意味が通らず、ダムの状態を表せない。"}, {"text": "転がり", "is_correct": false, "explanation": "「ダムは雨水に転がり」は文脈に合わず、ダムの状態を表せない。"}, {"text": "叫び", "is_correct": false, "explanation": "「ダムは雨水に叫び」は主語と動詞が合わず、文が成り立たない。"}], "explanations": {"満ちあふれ": "「ダムは雨水に満ちあふれ、放水が始まった」で、雨水がダムをいっぱいにする意味に合う。", "迷い": "「ダムは雨水に迷い」は意味が通らず、ダムの状態を表せない。", "転がり": "「ダムは雨水に転がり」は文脈に合わず、ダムの状態を表せない。", "叫び": "「ダムは雨水に叫び」は主語と動詞が合わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "満ちあふれ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電気を消すと、部屋が光に満ちあふれた。", "explanation": "ここは〈消える〉の意味。光が消えて暗くなる場面で、光があふれるとは言えないので合わない。"}, {"text": "日照りで池が干上がり、水が満ちあふれた。", "explanation": "ここは〈減る〉の意味。水が少なくなる場面では、いっぱいになってはみ出す満ちあふれるは合わない。"}, {"text": "夜明けの空が暗くなって、光が満ちあふれた。", "explanation": "ここは〈弱まる〉の意味。光が弱まっていく場面では、あふれ出る満ちあふれるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53161, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部屋に光を満ちあふれていた。", "corrected_sentence": "部屋に光が満ちあふれていた。", "error_description": "「満ちあふれる」の主語は光なので、「を」は誤りで「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "満ちあふれ", "is_correct": true, "explanation": "「〜ていた」の直前には連用形が入るので、この形が正しい。"}, {"text": "満ちあふれる", "is_correct": false, "explanation": "辞書形は「ていた」に続かないので、ここでは合わない。"}, {"text": "満ちあふれない", "is_correct": false, "explanation": "否定形は、池に水があふれていたという肯定の文意と合わない。"}, {"text": "満ちあふれた", "is_correct": false, "explanation": "過去形は「ていた」に続かないので、この文の形としては合わない。"}], "correct_form": "満ちあふれ", "base_form": "満ちあふれる", "form_label": "連用形", "sentence_index": 1, "explanations": {"満ちあふれ": "「〜ていた」の直前には連用形が入るので、この形が正しい。", "満ちあふれる": "辞書形は「ていた」に続かないので、ここでは合わない。", "満ちあふれない": "否定形は、池に水があふれていたという肯定の文意と合わない。", "満ちあふれた": "過去形は「ていた」に続かないので、この文の形としては合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53161, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭は白い光に満ちあふれたていた。", "corrected_sentence": "庭は白い光に満ちあふれていた。", "error_description": "「満ちあふれた」に続く「て」の形が誤り。「ていた」の一形で、余分な「た」が入っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "満ちあふれ", "is_correct": true, "explanation": "「朝日に満ちあふれた台所」の「た」の前には連用形の「満ちあふれ」が入る。"}, {"text": "満ちあふれろ", "is_correct": false, "explanation": "命令形は「た」に続かないので、ここでは合わない。"}, {"text": "満ちあふれれば", "is_correct": false, "explanation": "仮定形は「た」に続かないので、この文の形としては合わない。"}, {"text": "満ちあふれず", "is_correct": false, "explanation": "否定の連用形「ず」は過去の「た」に続かないので、ここでは合わない。"}], "correct_form": "満ちあふれ", "base_form": "満ちあふれる", "form_label": "連用形", "sentence_index": 7, "explanations": {"満ちあふれ": "「朝日に満ちあふれた台所」の「た」の前には連用形の「満ちあふれ」が入る。", "満ちあふれろ": "命令形は「た」に続かないので、ここでは合わない。", "満ちあふれれば": "仮定形は「た」に続かないので、この文の形としては合わない。", "満ちあふれず": "否定の連用形「ず」は過去の「た」に続かないので、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53162, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「声に満ちあふれる」の形で、満ちる対象を示す「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「声を満ちあふれる」は目的語の形になり、満ちあふれるの形と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「声と満ちあふれていた」は並列の形になり、満ちる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「声へ満ちあふれる」は方向の形で、満ちる状態を表す文に合わない。"}], "correct_answer": "に", "explanations": {"に": "「声に満ちあふれる」の形で、満ちる対象を示す「に」が正しい。", "を": "「声を満ちあふれる」は目的語の形になり、満ちあふれるの形と合わない。", "と": "「声と満ちあふれていた」は並列の形になり、満ちる対象を示せない。", "へ": "「声へ満ちあふれる」は方向の形で、満ちる状態を表す文に合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53162, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「自信に満ちあふれた」で、満ちる対象を示す「に」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「自信と満ちあふれた」は並列の形になり、満ちる対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「自信より満ちあふれた」は比較の形になり、満ちる対象を示す文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「自信を満ちあふれた顔」は目的語の形になり、満ちあふれるは目的語を取らないので不自然になる。"}], "correct_answer": "に", "explanations": {"に": "「自信に満ちあふれた」で、満ちる対象を示す「に」が正しい。", "と": "「自信と満ちあふれた」は並列の形になり、満ちる対象を示せない。", "より": "「自信より満ちあふれた」は比較の形になり、満ちる対象を示す文として成り立たない。", "を": "「自信を満ちあふれた顔」は目的語の形になり、満ちあふれるは目的語を取らないので不自然になる。"}, "error_tags": {"と": "相手", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53162, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "空間や器などが、液体や光、感情などでいっぱいになり、外にはみ出すほどになること。また、その状態にあること。", "primary_collocate": null, "pronunciation": "みちあふれる", "ipa": "mit͡ɕiaɸɯɾeɾɯ", "syllable_count": 6, "sentences": [{"text": "これらにより、壁を薄くして大きな窓を設けることが可能となり、内部は光に満ちあふれました。", "target_word": "満ちあふれ", "complexity_tier": "T4", "furigana": "これらにより、壁[かべ]を薄[うす]くして大[おお]きな窓[まど]を設[もう]けることが可能[かのう]となり、内部[ないぶ]は光[ひかり]に満[み]ちあふれました。", "sentence_source": "mined"}, {"text": "優勝が決まると、会場は喜びの声に満ちあふれていた。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]が決[き]まると、会場[かいじょう]は喜[よろこ]びの声[こえ]に満[み]ちあふれていた。", "sentence_source": "generated"}, {"text": "春の公園は、花の香りに満ちあふれている。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "春[はる]の公園[こうえん]は、花[はな]の香[かお]りに満[み]ちあふれている。", "sentence_source": "generated"}, {"text": "大雨で、田んぼには水が満ちあふれていた。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で、田[た]んぼには水[みず]が満[み]ちあふれていた。", "sentence_source": "generated"}, {"text": "彼女の手紙は、家族への感謝の気持ちに満ちあふれていた。", "target_word": "満ちあふれ", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の手紙[てがみ]は、家族[かぞく]への感謝[かんしゃ]の気持[きも]ちに満[み]ちあふれていた。", "sentence_source": "generated"}, {"text": "新しい学校は、元気な子どもたちの笑顔に満ちあふれている。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "新[あたら]しい学校[がっこう]は、元気[げんき]な子[こ]どもたちの笑顔[えがお]に満[み]ちあふれている。", "sentence_source": "generated"}, {"text": "古い教会の中は、やさしい音楽に満ちあふれていました。", "target_word": "満ちあふれ", "complexity_tier": "T3", "furigana": "古[ふる]い教会[きょうかい]の中[なか]は、やさしい音楽[おんがく]に満[み]ちあふれていました。", "sentence_source": "generated"}, {"text": "彼は自信に満ちあふれた顔で、舞台に立った。", "target_word": "満ちあふれ", "complexity_tier": "T4", "furigana": "彼[かれ]は自信[じしん]に満[み]ちあふれた顔[かお]で、舞台[ぶたい]に立[た]った。", "sentence_source": "generated"}, {"text": "祭りの日、町は人々の熱気に満ちあふれる。", "target_word": "満ちあふれ", "complexity_tier": "T4", "furigana": "祭[まつ]りの日[ひ]、町[まち]は人々[ひとびと]の熱気[ねっき]に満[み]ちあふれる。", "sentence_source": "generated"}, {"text": "大雨が続いて、川の水が堤防を越えるほどに満ちあふれた。", "target_word": "満ちあふれた", "complexity_tier": "T3", "furigana": "大雨[おおあめ]が続[つづ]いて、川[かわ]の水[みず]が堤防[ていぼう]を越[こ]えるほどに満[み]ちあふれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "満ちあふれる", "label": "辞書形"}, {"form": "満ちあふれ", "label": "連用形"}, {"form": "満ちあふれた", "label": "過去形"}, {"form": "満ちあふれて", "label": "て形"}, {"form": "満ちあふれない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "場所や人が光・音・感情などでいっぱいになり、はみ出るほどの状態になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53162, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "満ちあふれ", "is_correct": true, "explanation": "「内部は光に満ちあふれました」で、光があふれるほど満ちる意味に合う。"}, {"text": "壊れ", "is_correct": false, "explanation": "「光に壊れました」は意味が通らず、光が何かを壊すという文にもならない。"}, {"text": "遠ざかり", "is_correct": false, "explanation": "「光に遠ざかりました」は主語と動詞が合わず、文が成立しない。"}, {"text": "凍え", "is_correct": false, "explanation": "「光に凍えました」は意味が通らず、光の文脈に合わない。"}], "explanations": {"満ちあふれ": "「内部は光に満ちあふれました」で、光があふれるほど満ちる意味に合う。", "壊れ": "「光に壊れました」は意味が通らず、光が何かを壊すという文にもならない。", "遠ざかり": "「光に遠ざかりました」は主語と動詞が合わず、文が成立しない。", "凍え": "「光に凍えました」は意味が通らず、光の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "満ちあふれ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜空に月が満ちあふれて、街がさえざえと見えた。", "explanation": "ここは〈満ちる〉の意味。満月になって欠けがなくなることを指し、はみ出すとは言わないので合わない。"}, {"text": "たくさん食べて、お腹が満ちあふれた。", "explanation": "ここは〈満腹〉の意味。お腹がいっぱいになることを言い、中身があふれ出る状態には使わないので合わない。"}, {"text": "秋、田んぼの稲が満ちあふれた。", "explanation": "ここは〈実る〉の意味。稲は実るもので、あふれ出るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53162, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "満ちあふれ", "is_correct": true, "explanation": "「やさしい音楽に満ちあふれていました」で、音楽が教会いっぱいに広がる意味に合う。"}, {"text": "迷い", "is_correct": false, "explanation": "「音楽に迷っていました」は意味が通らず、音楽を対象とする文にならない。"}, {"text": "転がり", "is_correct": false, "explanation": "「音楽に転がっていました」は文脈に合わず、音楽の状態を表せない。"}, {"text": "叫び", "is_correct": false, "explanation": "「音楽に叫んでいました」は主語と動詞が合わず、文が成り立たない。"}], "explanations": {"満ちあふれ": "「やさしい音楽に満ちあふれていました」で、音楽が教会いっぱいに広がる意味に合う。", "迷い": "「音楽に迷っていました」は意味が通らず、音楽を対象とする文にならない。", "転がり": "「音楽に転がっていました」は文脈に合わず、音楽の状態を表せない。", "叫び": "「音楽に叫んでいました」は主語と動詞が合わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "満ちあふれ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客が帰って、会場の席が満ちあふれた。", "explanation": "ここは〈空く〉の意味。席が空いてゆく場面で、いっぱいになるさまを表す満ちあふれるは合わない。"}, {"text": "日照りで田んぼが乾いて、水が満ちあふれた。", "explanation": "ここは〈減る〉の意味。水が少なくなっていく場面では、いっぱいになってはみ出す満ちあふれるは合わない。"}, {"text": "任期が満ちあふれた。", "explanation": "ここは〈満了〉の意味。期限がちょうど来ることを言い、あふれ出るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53162, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭は花の香りを満ちあふれていた。", "corrected_sentence": "庭は花の香りに満ちあふれていた。", "error_description": "「満ちあふれる」は「〜に満ちあふれる」の形をとるので、「を」は誤りで「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "満ちあふれ", "is_correct": true, "explanation": "「〜ていた」の直前には連用形が入るので、この形が正しい。"}, {"text": "満ちあふれる", "is_correct": false, "explanation": "辞書形は「ていた」に続かないので、ここでは合わない。"}, {"text": "満ちあふれない", "is_correct": false, "explanation": "否定形は、会場が満ちていたという肯定の文意と合わない。"}, {"text": "満ちあふれた", "is_correct": false, "explanation": "過去形は「ていた」に続かないので、この文の形としては合わない。"}], "correct_form": "満ちあふれ", "base_form": "満ちあふれる", "form_label": "連用形", "sentence_index": 1, "explanations": {"満ちあふれ": "「〜ていた」の直前には連用形が入るので、この形が正しい。", "満ちあふれる": "辞書形は「ていた」に続かないので、ここでは合わない。", "満ちあふれない": "否定形は、会場が満ちていたという肯定の文意と合わない。", "満ちあふれた": "過去形は「ていた」に続かないので、この文の形としては合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53162, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの夜、町は人々の熱気に満ちあふれいた。", "corrected_sentence": "祭りの夜、町は人々の熱気に満ちあふれていた。", "error_description": "過去の継続を表す「ていた」の「て」が抜けている。満ちあふれる形の活用が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "満ちあふれ", "is_correct": true, "explanation": "「自信に満ちあふれた顔」の「た」の前には連用形の「満ちあふれ」が入る。"}, {"text": "満ちあふれろ", "is_correct": false, "explanation": "命令形は「た」に続かないので、ここでは合わない。"}, {"text": "満ちあふれれば", "is_correct": false, "explanation": "仮定形は「た」に続かないので、この文の形としては合わない。"}, {"text": "満ちあふれず", "is_correct": false, "explanation": "否定の連用形「ず」は過去の「た」に続かないので、ここでは合わない。"}], "correct_form": "満ちあふれ", "base_form": "満ちあふれる", "form_label": "連用形", "sentence_index": 7, "explanations": {"満ちあふれ": "「自信に満ちあふれた顔」の「た」の前には連用形の「満ちあふれ」が入る。", "満ちあふれろ": "命令形は「た」に続かないので、ここでは合わない。", "満ちあふれれば": "仮定形は「た」に続かないので、この文の形としては合わない。", "満ちあふれず": "否定の連用形「ず」は過去の「た」に続かないので、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53165, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「活かす」の目的語（気持ち）を「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「気持ちが活かして」は主語になり、使う人と動詞の関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「気持ちに活かして」は目的語の役割を果たさず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示す。「気持ちで活かして」は目的語の役割を果たさず不自然。"}], "correct_answer": "を", "explanations": {"を": "「活かす」の目的語（気持ち）を「を」で示す。", "が": "「気持ちが活かして」は主語になり、使う人と動詞の関係が成り立たない。", "に": "「気持ちに活かして」は目的語の役割を果たさず、不自然。", "で": "「で」は手段を示す。「気持ちで活かして」は目的語の役割を果たさず不自然。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53165, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「活かす」の目的語（立地）を「を」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「駅に近い立地へ活かした店」では方向の意味になり、目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「駅に近い立地から活かした店」では出どころの意味になり、目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。比べる相手がなく、「駅に近い立地より活かした店」は文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「活かす」の目的語（立地）を「を」で示す。", "へ": "「へ」は方向を示す。「駅に近い立地へ活かした店」では方向の意味になり、目的語にならない。", "から": "「から」は起点を示す。「駅に近い立地から活かした店」では出どころの意味になり、目的語にならない。", "より": "「より」は比較を示す。比べる相手がなく、「駅に近い立地より活かした店」は文脈に合わない。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53165, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "よいところをじょうずに使うことです。", "primary_collocate": null, "pronunciation": "いかす", "ipa": "ikasɯ", "syllable_count": 3, "sentences": [{"text": "背が高いことを活かして、バスケットボールで活躍しています。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "せがたかいことをいかして、バスケットボールでかつやくしています。", "sentence_source": "generated"}, {"text": "料理が好きな気持ちを活かして、店を開きました。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "りょうりがすきなきもちをいかして、みせをひらきました。", "sentence_source": "generated"}, {"text": "先生は生徒の個性を活かす授業をしています。", "target_word": "活かす", "complexity_tier": "T3", "furigana": "せんせいはせいとのこせいをいかすじゅぎょうをしています。", "sentence_source": "generated"}, {"text": "古い着物を活かして、かわいいかばんを作った。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "ふるいきものをいかして、かわいいかばんをつくった。", "sentence_source": "generated"}, {"text": "経験を活かせば、きっと新しい仕事もうまくいきます。", "target_word": "活かせば", "complexity_tier": "T3", "furigana": "けいけんをいかせば、きっとあたらしいしごともうまくいきます。", "sentence_source": "generated"}, {"text": "自分の得意なことを活かして、友達を手伝いました。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "じぶんのとくいなことをいかして、ともだちをてつだいました。", "sentence_source": "generated"}, {"text": "彼女は声のよさを活かして、歌手になった。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "かのじょはこえのよさをいかして、かしゅになった。", "sentence_source": "generated"}, {"text": "駅に近い立地を活かした店は、いつも客が多いです。", "target_word": "活かした", "complexity_tier": "T3", "furigana": "えきにちかいりっちをいかしたみせは、いつもきゃくがおおいです。", "sentence_source": "generated"}, {"text": "勉強したことを活かす機会がなかなかありません。", "target_word": "活かす", "complexity_tier": "T3", "furigana": "べんきょうしたことをいかすきかいがなかなかありません。", "sentence_source": "generated"}, {"text": "昔の技を活かして、新しい道具が作られました。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "むかしのわざをいかして、あたらしいどうぐがつくられました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活かす", "label": "終止形"}, {"form": "活かし", "label": "連用形"}, {"form": "活かした", "label": "過去形"}, {"form": "活かして", "label": "て形"}, {"form": "活かさない", "label": "否定形"}, {"form": "活かせば", "label": "仮定形"}, {"form": "活かせる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "自分や物のよいところをじょうずに使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53165, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で「背が高いことを使って、バスケットボールで活躍している」と続き、文が通る。"}, {"text": "活かした", "is_correct": false, "explanation": "連体形は名詞を修飾するが、「活かした、バスケットボールで」と文が切れて不自然。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は文を終えるため、「活かせ、バスケットボールで」と文が通らない。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身形は助詞が「が」になるため、「ことを活かされ」は助詞と合わない。"}], "explanations": {"活かして": "て形で「背が高いことを使って、バスケットボールで活躍している」と続き、文が通る。", "活かした": "連体形は名詞を修飾するが、「活かした、バスケットボールで」と文が切れて不自然。", "活かせ": "命令形は文を終えるため、「活かせ、バスケットボールで」と文が通らない。", "活かされ": "受身形は助詞が「が」になるため、「ことを活かされ」は助詞と合わない。"}, "sentence_index": 0, "correct_answer": "活かして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "親は息子を習い事に活かせた。", "explanation": "ここは〈行かせる〉の意味。同じ読みの別語で、活かすは良い点を使う語なので、人を行かせる意味では使わない。"}, {"text": "捕まえた蛙を活かして、庭に放した。", "explanation": "ここは〈生かす〉（命を保つ）の意味。よい点を使う意味ではない。"}, {"text": "枯れた苗を活かして、もう一度畑に植えた。", "explanation": "ここは〈生き返らせる〉の意味。よい点を使う意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53165, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で「声のよさを使って、歌手になった」と続き、文が通る。"}, {"text": "活かす", "is_correct": false, "explanation": "終止形で文を言い切るため、「、歌手になった」へつながらず、文が続かない。"}, {"text": "活かせる", "is_correct": false, "explanation": "可能形の終止形で文を言い切るため、後ろの「歌手になった」へ続けられない。"}, {"text": "活かさない", "is_correct": false, "explanation": "否定形で文を言い切るため、「、歌手になった」へつながらず、文が続かない。"}], "explanations": {"活かして": "て形で「声のよさを使って、歌手になった」と続き、文が通る。", "活かす": "終止形で文を言い切るため、「、歌手になった」へつながらず、文が続かない。", "活かせる": "可能形の終止形で文を言い切るため、後ろの「歌手になった」へ続けられない。", "活かさない": "否定形で文を言い切るため、「、歌手になった」へつながらず、文が続かない。"}, "sentence_index": 6, "correct_answer": "活かして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "捕まえた虫を活かして、窓から逃がした。", "explanation": "ここは〈生かす〉（命を保つ）の意味。よい点を使う意味ではない。"}, {"text": "枯れた花を活かして、もう一度咲かせた。", "explanation": "ここは〈生き返らせる〉の意味。よい点を使う意味ではない。"}, {"text": "川で拾った亀を活かして、池に戻した。", "explanation": "ここは〈生かす〉（命を保つ）の意味。よい点を使う意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53165, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の教えに活かして、畑を続けています。", "corrected_sentence": "祖母の教えを活かして、畑を続けています。", "error_description": "「活かす」は使うもの（教え）を「を」で示す。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で後ろの「店を開きました」へつながり、気持ちを使って店を開いた意味になる。"}, {"text": "活かした", "is_correct": false, "explanation": "連体形は名詞を修飾するが、「気持ちを活かした、店を開きました」は文が切れて不自然。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は相手に命じる形で、説明の文には合わない。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身形は助詞が「が」になるため、「気持ちを活かされ」は不自然。"}], "correct_form": "活かして", "base_form": "活かす", "form_label": "て形", "sentence_index": 1, "explanations": {"活かして": "て形で後ろの「店を開きました」へつながり、気持ちを使って店を開いた意味になる。", "活かした": "連体形は名詞を修飾するが、「気持ちを活かした、店を開きました」は文が切れて不自然。", "活かせ": "命令形は相手に命じる形で、説明の文には合わない。", "活かされ": "受身形は助詞が「が」になるため、「気持ちを活かされ」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53165, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父の経験を活かしで、店を継ぎました。", "corrected_sentence": "父の経験を活かして、店を継ぎました。", "error_description": "正しくは「活かして」（て形）。「活かしで」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "活かした", "is_correct": true, "explanation": "連体形で後ろの「店」を修飾し、立地を使った店という意味になる。"}, {"text": "活かし", "is_correct": false, "explanation": "連用形は名詞に直接つながらず、「活かし店」は不自然。"}, {"text": "活かせば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「活かせば店は」と文が成り立たない。"}, {"text": "活かさ", "is_correct": false, "explanation": "未然形は単独で名詞を修飾できず、「活かさ店」は不自然。"}], "correct_form": "活かした", "base_form": "活かす", "form_label": "過去形", "sentence_index": 7, "explanations": {"活かした": "連体形で後ろの「店」を修飾し、立地を使った店という意味になる。", "活かし": "連用形は名詞に直接つながらず、「活かし店」は不自然。", "活かせば": "仮定形は名詞を修飾できず、「活かせば店は」と文が成り立たない。", "活かさ": "未然形は単独で名詞を修飾できず、「活かさ店」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53166, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「活かす」の目的語（風合い）を「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。風合いが活かすという意味になり、主語と動詞の関係が逆になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」では使う対象を表せず、「風合いに活かして」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示す。「風合いで活かして」は目的語の役割を果たさず不自然。"}], "correct_answer": "を", "explanations": {"を": "「活かす」の目的語（風合い）を「を」で示す。", "が": "「が」は主語を示す。風合いが活かすという意味になり、主語と動詞の関係が逆になる。", "に": "「に」では使う対象を表せず、「風合いに活かして」は不自然。", "で": "「で」は手段を示す。「風合いで活かして」は目的語の役割を果たさず不自然。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53166, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「活かす」の目的語（庭の形）を「を」で示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を示す。「庭の形と活かした家」は活かす対象とつながらず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「庭の形より活かした家」では比べる相手が成り立たず、目的語の役割も果たさない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「庭の形から活かした家」では活かす対象の関係が成り立たず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「活かす」の目的語（庭の形）を「を」で示す。", "と": "「と」は並列・共同を示す。「庭の形と活かした家」は活かす対象とつながらず不自然。", "より": "「より」は比較を示す。「庭の形より活かした家」では比べる相手が成り立たず、目的語の役割も果たさない。", "から": "「から」は起点を示す。「庭の形から活かした家」では活かす対象の関係が成り立たず、不自然。"}, "error_tags": {"を": "対象", "と": "並列", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53166, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "持っている良い面や特徴を生かして、有効に利用すること。", "primary_collocate": null, "pronunciation": "いかす", "ipa": "ikasɯ", "syllable_count": 3, "sentences": [{"text": "コンクリートの打ちっぱなしという素材感を活かした設計は、入居者のコミュニティ形成に多大な社会的影響を与えました。", "target_word": "活かした", "complexity_tier": "T4", "furigana": "コンクリートのうちっぱなしというそざいかんをいかしたせっけいは、にゅうきょしゃのコミュニティけいせいにただいなしゃかいてきえいきょうをあたえました。", "sentence_source": "mined"}, {"text": "古い木材の風合いを活かして、カフェの内装を作りました。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "ふるいもくざいのふうあいをいかして、カフェのないそうをつくりました。", "sentence_source": "generated"}, {"text": "彼は語学力を活かせる仕事を探しています。", "target_word": "活かせる", "complexity_tier": "T3", "furigana": "かれはごがくりょくをいかせるしごとをさがしています。", "sentence_source": "generated"}, {"text": "この土地の広さを活かし、大きな公園を造る計画です。", "target_word": "活かし", "complexity_tier": "T3", "furigana": "このとちのひろさをいかし、おおきなこうえんをつくるけいかくです。", "sentence_source": "generated"}, {"text": "失敗した経験を次の試合に活かしたいです。", "target_word": "活かし", "complexity_tier": "T3", "furigana": "しっぱいしたけいけんをつぎのしあいにいかしたいです。", "sentence_source": "generated"}, {"text": "素材の味を活かすために、味付けはできるだけ薄くします。", "target_word": "活かす", "complexity_tier": "T3", "furigana": "そざいのあじをいかすために、あじつけはできるだけうすくします。", "sentence_source": "generated"}, {"text": "留学で学んだことを活かして、通訳の仕事に就きました。", "target_word": "活かして", "complexity_tier": "T3", "furigana": "りゅうがくでまなんだことをいかして、つうやくのしごとにつきました。", "sentence_source": "generated"}, {"text": "小さな庭の形を活かした家が人気です。", "target_word": "活かした", "complexity_tier": "T3", "furigana": "ちいさなにわのかたちをいかしたいえがにんきです。", "sentence_source": "generated"}, {"text": "せっかくの長所を活かさないのはもったいない。", "target_word": "活かさ", "complexity_tier": "T3", "furigana": "せっかくのちょうしょをいかさないのはもったいない。", "sentence_source": "generated"}, {"text": "自然の光を活かした明るい部屋で、毎日気持ちよく過ごしています。", "target_word": "活かした", "complexity_tier": "T3", "furigana": "しぜんのひかりをいかしたあかるいへやで、まいにちきもちよくすごしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活かす", "label": "終止形"}, {"form": "活かし", "label": "連用形"}, {"form": "活かした", "label": "過去形"}, {"form": "活かして", "label": "て形"}, {"form": "活かさない", "label": "否定形"}, {"form": "活かせる", "label": "可能形"}, {"form": "活かされる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "素材・特徴などの良い面を生かして有効に利用する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53166, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活かした", "is_correct": true, "explanation": "過去形の連体形で、後ろの「設計」を修飾する。素材感を使った設計という意味になり、文が通る。"}, {"text": "活かして", "is_correct": false, "explanation": "て形は名詞を修飾できない。「活かして設計は」となり、文が続かない。"}, {"text": "活かし", "is_correct": false, "explanation": "連用形は名詞に直接つながらない。「活かし設計」は不自然。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は文を終えるため、後ろの「設計は」とつながらない。"}], "explanations": {"活かした": "過去形の連体形で、後ろの「設計」を修飾する。素材感を使った設計という意味になり、文が通る。", "活かして": "て形は名詞を修飾できない。「活かして設計は」となり、文が続かない。", "活かし": "連用形は名詞に直接つながらない。「活かし設計」は不自然。", "活かせ": "命令形は文を終えるため、後ろの「設計は」とつながらない。"}, "sentence_index": 0, "correct_answer": "活かした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "親は娘を留学に活かせた。", "explanation": "ここは〈行かせる〉の意味。同じ読みの別語で、活かすは良い点を使う語なので、人を行かせる意味では使わない。"}, {"text": "雨で汚れた壁を活かして、落書きを隠した。", "explanation": "ここは〈隠す〉の意味。活かすは良い点を使う語で、落書きを隠す意味では使わない。"}, {"text": "古いラジオを活かして、ばらばらに壊した。", "explanation": "ここは〈壊す〉の意味。活かすは良い点を使う語で、壊す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53166, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で「学んだことを使って、通訳の仕事に就いた」と続き、文が通る。"}, {"text": "活かした", "is_correct": false, "explanation": "連体形は名詞を修飾するが、「活かした、通訳の仕事に」と文が切れて不自然。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は文を終えるため、続く部分とつながらない。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身形は助詞が「が」になるため、「ことを活かされ」は助詞と合わない。"}], "explanations": {"活かして": "て形で「学んだことを使って、通訳の仕事に就いた」と続き、文が通る。", "活かした": "連体形は名詞を修飾するが、「活かした、通訳の仕事に」と文が切れて不自然。", "活かせ": "命令形は文を終えるため、続く部分とつながらない。", "活かされ": "受身形は助詞が「が」になるため、「ことを活かされ」は助詞と合わない。"}, "sentence_index": 6, "correct_answer": "活かして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "使えなくなった鍋を活かして、ごみに出した。", "explanation": "ここは〈捨てる〉の意味。活かすは良い点を使う語で、使えなくなったものを捨てる意味では使わない。"}, {"text": "火鉢の炭を活かして、すぐに消した。", "explanation": "ここは〈消す〉の意味。活かすは良い点を使う語で、火を消す意味では使わない。"}, {"text": "照明を活かして、部屋の雰囲気を損なった。", "explanation": "ここは〈損なう〉の意味。活かすは良い点を生かす語で、雰囲気を損なう意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53166, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昔の蔵の梁の風合いに活かして、店を改装しました。", "corrected_sentence": "昔の蔵の梁の風合いを活かして、店を改装しました。", "error_description": "「活かす」は使うもの（風合い）を「を」で示す。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 5]}, "level_4": {"options": [{"text": "活かして", "is_correct": true, "explanation": "て形で後ろの「作りました」へつながり、風合いを使って内装を作った意味になる。"}, {"text": "活かさない", "is_correct": false, "explanation": "否定形だと「風合いを使わずに」の意味になり、「内装を作りました」と矛盾する。"}, {"text": "活かせ", "is_correct": false, "explanation": "命令形は相手に命じる形で、事実を述べる文には合わない。"}, {"text": "活かされて", "is_correct": false, "explanation": "受身形は助詞が「が」になる。「風合いを活かされて」は不自然。"}], "correct_form": "活かして", "base_form": "活かす", "form_label": "て形", "sentence_index": 1, "explanations": {"活かして": "て形で後ろの「作りました」へつながり、風合いを使って内装を作った意味になる。", "活かさない": "否定形だと「風合いを使わずに」の意味になり、「内装を作りました」と矛盾する。", "活かせ": "命令形は相手に命じる形で、事実を述べる文には合わない。", "活かされて": "受身形は助詞が「が」になる。「風合いを活かされて」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53166, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父の大工の技を活かしで、古い蔵を修理しました。", "corrected_sentence": "祖父の大工の技を活かして、古い蔵を修理しました。", "error_description": "正しくは「活かして」（て形）。「活かしで」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "活かした", "is_correct": true, "explanation": "連体形で後ろの「家」を修飾し、庭の形を使った家という意味になる。"}, {"text": "活かして", "is_correct": false, "explanation": "て形は名詞を修飾できず、「活かして家が人気」は文が続かない。"}, {"text": "活かし", "is_correct": false, "explanation": "連用形は名詞に直接つながらず、「活かし家」は不自然。"}, {"text": "活かされ", "is_correct": false, "explanation": "受身の連用形は名詞に直接続かず、「小さな庭の形を活かされ家」は成り立たない（受身にすると助詞が「が」になる）。"}], "correct_form": "活かした", "base_form": "活かす", "form_label": "過去形", "sentence_index": 7, "explanations": {"活かした": "連体形で後ろの「家」を修飾し、庭の形を使った家という意味になる。", "活かして": "て形は名詞を修飾できず、「活かして家が人気」は文が続かない。", "活かし": "連用形は名詞に直接つながらず、「活かし家」は不自然。", "活かされ": "受身の連用形は名詞に直接続かず、「小さな庭の形を活かされ家」は成り立たない（受身にすると助詞が「が」になる）。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53167, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は場所を示し、「コミュニティで」で出会いの場を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すが、ここで「コミュニティを」とすると後ろの文と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。ここは出会いの場を表す文なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐが、後ろに名詞が続かず文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「で」は場所を示し、「コミュニティで」で出会いの場を表す。", "を": "「を」は対象を示すが、ここで「コミュニティを」とすると後ろの文と結びつかない。", "へ": "「へ」は移動の方向を示す。ここは出会いの場を表す文なので合わない。", "の": "「の」は名詞どうしをつなぐが、後ろに名詞が続かず文が成り立たない。"}, "error_tags": {"を": "対象", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53167, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53167, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで集まって仲よくするグループのことです。", "primary_collocate": null, "pronunciation": "こみゅにてぃ", "ipa": "komjɯniti", "syllable_count": 4, "sentences": [{"text": "この町には、外国人も参加できるコミュニティがある。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "この町[まち]には、外国人[がいこくじん]も参加[さんか]できるコミュニティがある。", "sentence_source": "generated"}, {"text": "私は趣味のコミュニティで、新しい友達ができた。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "私[わたし]は趣味[しゅみ]のコミュニティで、新[あたら]しい友達[ともだち]ができた。", "sentence_source": "generated"}, {"text": "コミュニティのみんなで、公園のごみを拾った。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "コミュニティのみんなで、公園[こうえん]のごみを拾[ひろ]った。", "sentence_source": "generated"}, {"text": "ネット上のコミュニティで、料理の作り方を教え合っている。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "ネット上[じょう]のコミュニティで、料理[りょうり]の作[つく]り方[かた]を教[おし]え合[あ]っている。", "sentence_source": "generated"}, {"text": "引っ越してきたばかりで、地域のコミュニティに入れてもらった。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してきたばかりで、地域[ちいき]のコミュニティに入[い]れてもらった。", "sentence_source": "generated"}, {"text": "コミュニティの仲間と、毎月一回食事会を開く。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "コミュニティの仲間[なかま]と、毎月[まいつき]一回[いっかい]食事会[しょくじかい]を開[ひら]く。", "sentence_source": "generated"}, {"text": "学校のコミュニティは、先生も生徒も仲がいい。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "学校[がっこう]のコミュニティは、先生[せんせい]も生徒[せいと]も仲[なか]がいい。", "sentence_source": "generated"}, {"text": "このコミュニティは、犬が好きな人たちが集まっている。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "このコミュニティは、犬[いぬ]が好[す]きな人[ひと]たちが集[あつ]まっている。", "sentence_source": "generated"}, {"text": "コミュニティの中で、お互いに助け合うことが大切だ。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "コミュニティの中[なか]で、お互[たが]いに助[たす]け合[あ]うことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼は音楽のコミュニティを作って、仲間を集めた。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "彼[かれ]は音楽[おんがく]のコミュニティを作[つく]って、仲間[なかま]を集[あつ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニティ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が集まって仲よく交流するグループ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53167, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コミュニティ", "is_correct": true, "explanation": "「参加できる」とあり、人が加わる集まりを指すので正解。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は感覚の一種で、人が参加する対象にはならない。"}, {"text": "湿気", "is_correct": false, "explanation": "湿気は空気の状態を指し、参加できる集まりにはならない。"}, {"text": "好み", "is_correct": false, "explanation": "好みは個人の嗜好を指し、参加できる集まりを表さない。"}], "explanations": {"コミュニティ": "「参加できる」とあり、人が加わる集まりを指すので正解。", "眠気": "眠気は感覚の一種で、人が参加する対象にはならない。", "湿気": "湿気は空気の状態を指し、参加できる集まりにはならない。", "好み": "好みは個人の嗜好を指し、参加できる集まりを表さない。"}, "sentence_index": 0, "correct_answer": "コミュニティ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は夕食に、コミュニティを切って焼いた。", "explanation": "ここは〈食材〉の意味。コミュニティは仲間の集まりなので、切って焼く食べ物ではない。"}, {"text": "週末は、コミュニティを飲みながら本を読む。", "explanation": "ここは〈飲み物〉の意味。コミュニティは仲間の集まりなので、飲めるものではない。"}, {"text": "この店は、コミュニティの値段が安くて、学生に人気がある。", "explanation": "ここは〈料金〉の意味。コミュニティは人の集まりなので、値段は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53167, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コミュニティ", "is_correct": true, "explanation": "学校に関わる人々の集まりを指し、先生や生徒の仲を述べる文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を指し、先生や生徒の仲を主語にはできない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は部品で、先生と生徒の仲の話題には当てはまらない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は寝るための道具で、仲のいい先生と生徒を指さない。"}], "explanations": {"コミュニティ": "学校に関わる人々の集まりを指し、先生や生徒の仲を述べる文に合う。", "天気": "天気は空模様を指し、先生や生徒の仲を主語にはできない。", "電池": "電池は部品で、先生と生徒の仲の話題には当てはまらない。", "寝具": "寝具は寝るための道具で、仲のいい先生と生徒を指さない。"}, "sentence_index": 6, "correct_answer": "コミュニティ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町は、コミュニティが便利で、どこへでも行ける。", "explanation": "ここは〈交通〉の意味。コミュニティは人の集まりを指し、移動の便利さは表せない。"}, {"text": "この地域は、コミュニティの状態が悪くて、ネットがつながらない。", "explanation": "ここは〈通信〉の意味。コミュニティは仲間の集まりなので、電波や回線の状態は表せない。"}, {"text": "この店のコミュニティは、どれもおいしい。", "explanation": "ここは〈メニュー〉の意味。コミュニティは人の集まりなので、料理の種類は指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53167, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は、地域のコミュニティを参加して、ボランティアをしている。", "corrected_sentence": "週末は、地域のコミュニティに参加して、ボランティアをしている。", "error_description": "「参加する」は「に」を取る。「コミュニティを」の「を」が誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53167, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校長先生は、学校のコミュニティを建てた。", "corrected_sentence": "校長先生は、学校のコミュニティを作った。", "error_description": "「コミュニティ」は「作る」と組む。「建てる」は建物を対象にする動詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53177, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53177, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "引用を示す。「治すと」で、「約束した」の内容を導く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すので、「約束した」の内容を導く位置には使えない。"}, {"text": "に", "is_correct": false, "explanation": "相手を示すので、「治すに約束した」は内容を導けず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すので、「治すで約束した」は成り立たない。"}], "correct_answer": "と", "explanations": {"と": "引用を示す。「治すと」で、「約束した」の内容を導く。", "を": "目的語を示すので、「約束した」の内容を導く位置には使えない。", "に": "相手を示すので、「治すに約束した」は内容を導けず不自然。", "で": "手段や場所を示すので、「治すで約束した」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53177, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "病気やけがをなくして、よくすることです。", "primary_collocate": null, "pronunciation": "なおす", "ipa": "naosɯ", "syllable_count": 3, "sentences": [{"text": "先生は、この病気は手術で治せると言った。", "target_word": "治せる", "complexity_tier": "T3", "furigana": "先生[せんせい]は、この病気[びょうき]は手術[しゅじゅつ]で治[なお]せると言[い]った。", "sentence_source": "generated"}, {"text": "毎日リハビリをして、肩の痛みを治した。", "target_word": "治した", "complexity_tier": "T3", "furigana": "毎日[まいにち]リハビリをして、肩[かた]の痛[いた]みを治[なお]した。", "sentence_source": "generated"}, {"text": "病気を治したくて、遠い町の病院まで通った。", "target_word": "治したくて", "complexity_tier": "T3", "furigana": "病気[びょうき]を治[なお]したくて、遠[とお]い町[まち]の病院[びょういん]まで通[かよ]った。", "sentence_source": "generated"}, {"text": "風邪は薬よりも、よく休んで治すのが一番だ。", "target_word": "治す", "complexity_tier": "T3", "furigana": "風邪[かぜ]は薬[くすり]よりも、よく休[やす]んで治[なお]すのが一番[いちばん]だ。", "sentence_source": "generated"}, {"text": "彼はけがを治すため、半年間運動を休んだ。", "target_word": "治す", "complexity_tier": "T3", "furigana": "彼[かれ]はけがを治[なお]すため、半年間[はんとしかん]運動[うんどう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "虫刺されを早く治すには、かかないことだ。", "target_word": "治す", "complexity_tier": "T3", "furigana": "虫刺[むしさ]されを早[はや]く治[なお]すには、かかないことだ。", "sentence_source": "generated"}, {"text": "祖母の腰痛は、あの温泉で治したそうだ。", "target_word": "治した", "complexity_tier": "T3", "furigana": "祖母[そぼ]の腰痛[ようつう]は、あの温泉[おんせん]で治[なお]したそうだ。", "sentence_source": "generated"}, {"text": "医者は、時間をかければ必ず治すと約束した。", "target_word": "治す", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、時間[じかん]をかければ必[かなら]ず治[なお]すと約束[やくそく]した。", "sentence_source": "generated"}, {"text": "傷を治す薬を、薬局で買ってきた。", "target_word": "治す", "complexity_tier": "T3", "furigana": "傷[きず]を治[なお]す薬[くすり]を、薬局[やっきょく]で買[か]ってきた。", "sentence_source": "generated"}, {"text": "病気を治さないまま働くと、もっと悪くなる。", "target_word": "治さない", "complexity_tier": "T3", "furigana": "病気[びょうき]を治[なお]さないまま働[はたら]くと、もっと悪[わる]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "治した", "label": "過去形"}, {"form": "治して", "label": "て形"}, {"form": "治さない", "label": "否定形"}, {"form": "治せる", "label": "可能形"}, {"form": "治せば", "label": "仮定形"}], "register": "標準・常体", "sense_fingerprint": "病気やけがの悪いところをなくして、よい状態にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53177, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治せる", "is_correct": true, "explanation": "可能形で「手術で治すことができる」の意味になり、「と言った」の内容として自然。"}, {"text": "治し", "is_correct": false, "explanation": "連用形のままでは「と言った」につながらず、文が成り立たない。"}, {"text": "治さ", "is_correct": false, "explanation": "未然形のままでは文として成り立たない。"}, {"text": "治って", "is_correct": false, "explanation": "「て形」は「と言った」の前に直接続けられず、文が不自然になる。"}], "explanations": {"治せる": "可能形で「手術で治すことができる」の意味になり、「と言った」の内容として自然。", "治し": "連用形のままでは「と言った」につながらず、文が成り立たない。", "治さ": "未然形のままでは文として成り立たない。", "治って": "「て形」は「と言った」の前に直接続けられず、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "治せる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大学で経済学を治して、卒業した。", "explanation": "ここは〈修める〉の意味。治すは病気やけがをなおす意味で使い、学問を習得する意味では使わない。"}, {"text": "散らかった部屋を治して、掃除を終えた。", "explanation": "ここは〈片付ける〉の意味。治すは病気やけがに使うので、部屋の整頓には合わない。"}, {"text": "争っていた二国を治して、和平を結んだ。", "explanation": "ここは〈収める〉の意味。治すは病気やけがに使い、争いを収める意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53177, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治した", "is_correct": true, "explanation": "過去形で「治したそうだ」と伝聞の形に続き、文として自然。"}, {"text": "治して", "is_correct": false, "explanation": "「て形」は「そうだ」に直接続けられず、伝聞の文が成り立たない。"}, {"text": "治そう", "is_correct": false, "explanation": "意志形は「そうだ」に続かず、伝聞の文として成り立たない。"}, {"text": "治れ", "is_correct": false, "explanation": "命令形は「そうだ」に続かず、伝聞の文として成り立たない。"}], "explanations": {"治した": "過去形で「治したそうだ」と伝聞の形に続き、文として自然。", "治して": "「て形」は「そうだ」に直接続けられず、伝聞の文が成り立たない。", "治そう": "意志形は「そうだ」に続かず、伝聞の文として成り立たない。", "治れ": "命令形は「そうだ」に続かず、伝聞の文として成り立たない。"}, "sentence_index": 6, "correct_answer": "治した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい王は、混乱した国をうまく治した。", "explanation": "ここは〈治める〉の意味。治すは病気やけがに使い、国の統治には使わない。"}, {"text": "大学で法律を治して、卒業した。", "explanation": "ここは〈修める〉の意味。治すは病気やけがに使い、学問を習得する意味では使わない。"}, {"text": "騒がしい場を治して、みんなを落ち着かせた。", "explanation": "ここは〈鎮める〉の意味。治すは病気やけがに使い、場の騒ぎを静める意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53177, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "傷が治したから、もう大丈夫だ。", "corrected_sentence": "傷を治したから、もう大丈夫だ。", "error_description": "「治した」は他動詞なので目的語に「を」を取る。「傷が」の「が」は誤りで、正しくは「傷を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "治した", "is_correct": true, "explanation": "過去形で、リハビリの後に痛みが治ったという完了の出来事を表す。"}, {"text": "治して", "is_correct": false, "explanation": "「て形」は前後をつなぐ形で、文末の完了を表さないので文が完結しない。"}, {"text": "治す", "is_correct": false, "explanation": "辞書形は現在や未来を表し、既に終わった出来事の文に合わない。"}, {"text": "治せない", "is_correct": false, "explanation": "否定の可能形で「治せなかった」の意味になり、文の内容と逆になる。"}], "correct_form": "治した", "base_form": "治す", "form_label": "過去形", "sentence_index": 1, "explanations": {"治した": "過去形で、リハビリの後に痛みが治ったという完了の出来事を表す。", "治して": "「て形」は前後をつなぐ形で、文末の完了を表さないので文が完結しない。", "治す": "辞書形は現在や未来を表し、既に終わった出来事の文に合わない。", "治せない": "否定の可能形で「治せなかった」の意味になり、文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53177, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "腰痛を治さずで、今日も仕事を続けた。", "corrected_sentence": "腰痛を治さずに、今日も仕事を続けた。", "error_description": "「治さず」の後には「に」が続く。「で」は誤りで、正しくは「治さずに」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "治す", "is_correct": true, "explanation": "辞書形で「治すと約束した」と引用の文に続く形。"}, {"text": "治した", "is_correct": false, "explanation": "過去形は「治したと約束した」となり、未来の治療を述べる文に合わない。"}, {"text": "治さない", "is_correct": false, "explanation": "否定形は「治さないと約束した」の意味になり、文の内容と逆になる。"}, {"text": "治せば", "is_correct": false, "explanation": "仮定形は「治せば〜」と条件を表し、「約束した」に直接続かない。"}], "correct_form": "治す", "base_form": "治す", "form_label": "辞書形", "sentence_index": 7, "explanations": {"治す": "辞書形で「治すと約束した」と引用の文に続く形。", "治した": "過去形は「治したと約束した」となり、未来の治療を述べる文に合わない。", "治さない": "否定形は「治さないと約束した」の意味になり、文の内容と逆になる。", "治せば": "仮定形は「治せば〜」と条件を表し、「約束した」に直接続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53178, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「寝坊する癖を治す」と「癖」が治す対象になる。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すので、「癖に治す」では対象関係が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すので、「癖で治す」は対象を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、「癖へ治す」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「寝坊する癖を治す」と「癖」が治す対象になる。", "に": "相手や場所を示すので、「癖に治す」では対象関係が成り立たない。", "で": "手段を示すので、「癖で治す」は対象を示せず不自然。", "へ": "方向を示すので、「癖へ治す」は成り立たない。"}, "error_tags": {"に": "相手・場所", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53178, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「足の傷を治す」と「傷」が治す対象になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、治すは他動詞なので「傷が治す」では目的語の関係が成り立たず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を示すので、「傷と治すまで」では治す対象の関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すので、「傷より治すまで」は比べる対象がなく、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「足の傷を治す」と「傷」が治す対象になる。", "が": "主語を示すが、治すは他動詞なので「傷が治す」では目的語の関係が成り立たず、文が成り立たない。", "と": "並列や引用を示すので、「傷と治すまで」では治す対象の関係が成り立たない。", "より": "比較を示すので、「傷より治すまで」は比べる対象がなく、文が成り立たない。"}, "error_tags": {"が": "主語", "と": "並列・引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53178, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "病気やけがなどをなくして、健康な状態にもどす。また、物事の悪い状態を正しく直すこと。", "primary_collocate": null, "pronunciation": "なおす", "ipa": "naosɯ", "syllable_count": 3, "sentences": [{"text": "爪をかむ悪い癖を、なかなか治せない。", "target_word": "治せない", "complexity_tier": "T3", "furigana": "爪[つめ]をかむ悪[わる]い癖[くせ]を、なかなか治[なお]せない。", "sentence_source": "generated"}, {"text": "寝坊する癖を治すために、早く寝ることにした。", "target_word": "治す", "complexity_tier": "T3", "furigana": "寝坊[ねぼう]する癖[くせ]を治[なお]すために、早[はや]く寝[ね]ることにした。", "sentence_source": "generated"}, {"text": "彼は大けがを治して、再び山に登った。", "target_word": "治して", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]けがを治[なお]して、再[ふたた]び山[やま]に登[のぼ]った。", "sentence_source": "generated"}, {"text": "好き嫌いが多い偏食を治したいなら、少しずつ食べよう。", "target_word": "治したい", "complexity_tier": "T3", "furigana": "好[す]き嫌[きら]いが多[おお]い偏食[へんしょく]を治[なお]したいなら、少[すこ]しずつ食[た]べよう。", "sentence_source": "generated"}, {"text": "母は子どもの喘息を治そうと、空気のきれいな町へ引っ越した。", "target_word": "治そう", "complexity_tier": "T3", "furigana": "母[はは]は子[こ]どもの喘息[ぜんそく]を治[なお]そうと、空気[くうき]のきれいな町[まち]へ引[ひ]っ越[こ]した。", "sentence_source": "generated"}, {"text": "風邪を治してから、旅行の計画を立てよう。", "target_word": "治して", "complexity_tier": "T3", "furigana": "風邪[かぜ]を治[なお]してから、旅行[りょこう]の計画[けいかく]を立[た]てよう。", "sentence_source": "generated"}, {"text": "やけどを治せば、またピアノが弾けるようになる。", "target_word": "治せば", "complexity_tier": "T3", "furigana": "やけどを治[なお]せば、またピアノが弾[ひ]けるようになる。", "sentence_source": "generated"}, {"text": "医者から、足の傷を治すまで走るなと言われた。", "target_word": "治す", "complexity_tier": "T3", "furigana": "医者[いしゃ]から、足[あし]の傷[きず]を治[なお]すまで走[はし]るなと言[い]われた。", "sentence_source": "generated"}, {"text": "悪い癖を治すには、まず自分で気づくことが大切だ。", "target_word": "治す", "complexity_tier": "T3", "furigana": "悪[わる]い癖[くせ]を治[なお]すには、まず自分[じぶん]で気[き]づくことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "長年の腰痛を治して、彼は趣味の釣りを再開した。", "target_word": "治して", "complexity_tier": "T3", "furigana": "長年[ながねん]の腰痛[ようつう]を治[なお]して、彼[かれ]は趣味[しゅみ]の釣[つ]りを再開[さいかい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "治した", "label": "過去形"}, {"form": "治して", "label": "て形"}, {"form": "治さない", "label": "否定形"}, {"form": "治せる", "label": "可能形"}, {"form": "治せば", "label": "仮定形"}], "register": "標準・常体", "sense_fingerprint": "病気やけがをなくす。悪い癖や好き嫌いなど悪い状態をなくして正しくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53178, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治せない", "is_correct": true, "explanation": "否定の可能形で「なかなか治すことができない」の意味になり、文の内容に合う。"}, {"text": "治し", "is_correct": false, "explanation": "連用形のままでは文末が成り立たず、文として完結しない。"}, {"text": "治さ", "is_correct": false, "explanation": "未然形のままでは文として成り立たない。"}, {"text": "治って", "is_correct": false, "explanation": "「て形」は文末に続けられず、「癖を治って」は主語と合わない。"}], "explanations": {"治せない": "否定の可能形で「なかなか治すことができない」の意味になり、文の内容に合う。", "治し": "連用形のままでは文末が成り立たず、文として完結しない。", "治さ": "未然形のままでは文として成り立たない。", "治って": "「て形」は文末に続けられず、「癖を治って」は主語と合わない。"}, "sentence_index": 0, "correct_answer": "治せない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "王は混乱した国をよく治して、人々を安心させた。", "explanation": "ここは〈治める〉の意味。治すは病気やけがや悪い状態を正す意味で使い、国の統治には使わない。"}, {"text": "大学で経済学を治して、卒業した。", "explanation": "ここは〈修める〉の意味。治すは学問を習得する意味では使わない。"}, {"text": "紙の束を治して、ホチキスで留めた。", "explanation": "ここは〈束ねる〉の意味。治すは悪い状態を正す意味で使い、紙をまとめる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53178, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治せば", "is_correct": true, "explanation": "仮定形で「治せば、〜ピアノが弾ける」と条件を表し、文の流れに合う。"}, {"text": "治す", "is_correct": false, "explanation": "辞書形は「治すば」となり、仮定の形として成り立たない。"}, {"text": "治し", "is_correct": false, "explanation": "連用形は仮定の「ば」に続かず、文が成り立たない。"}, {"text": "治る", "is_correct": false, "explanation": "自動詞なので「やけどを治る」となり、「やけどを」の形は取れない。"}], "explanations": {"治せば": "仮定形で「治せば、〜ピアノが弾ける」と条件を表し、文の流れに合う。", "治す": "辞書形は「治すば」となり、仮定の形として成り立たない。", "治し": "連用形は仮定の「ば」に続かず、文が成り立たない。", "治る": "自動詞なので「やけどを治る」となり、「やけどを」の形は取れない。"}, "sentence_index": 6, "correct_answer": "治せば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土を治して、種をまいた。", "explanation": "ここは〈耕す〉の意味。治すは病気やけがや悪い状態を正す意味で使い、畑の土を耕す意味では使わない。"}, {"text": "領地をよく治して、民を豊かにした。", "explanation": "ここは〈治める〉の意味。治すは病気やけがや悪い状態を正す意味で使い、領地を統治する意味では使わない。"}, {"text": "ケーキの生地を治して、丁寧に焼いた。", "explanation": "ここは〈練る〉の意味。治すは病気やけがや悪い状態を正す意味で使い、材料をこねる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53178, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遅刻する癖が治すために、早く寝ることにした。", "corrected_sentence": "遅刻する癖を治すために、早く寝ることにした。", "error_description": "「治す」の目的語には「を」が必要。「癖が」の「が」は誤りで、正しくは「癖を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "治す", "is_correct": true, "explanation": "辞書形で「治すために」と目的を表す形に続き、文の流れに合う。"}, {"text": "治した", "is_correct": false, "explanation": "過去形は「治したために」となり、目的を表す「ために」に続かない。"}, {"text": "治さない", "is_correct": false, "explanation": "否定形は「治さないために」となり、目的の意味が文と逆になる。"}, {"text": "治せる", "is_correct": false, "explanation": "可能形は「治せるために」となり、目的を表す形として不自然。"}], "correct_form": "治す", "base_form": "治す", "form_label": "辞書形", "sentence_index": 1, "explanations": {"治す": "辞書形で「治すために」と目的を表す形に続き、文の流れに合う。", "治した": "過去形は「治したために」となり、目的を表す「ために」に続かない。", "治さない": "否定形は「治さないために」となり、目的の意味が文と逆になる。", "治せる": "可能形は「治せるために」となり、目的を表す形として不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53178, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "指のやけどを治すば、また楽器が弾けるようになる。", "corrected_sentence": "指のやけどを治せば、また楽器が弾けるようになる。", "error_description": "仮定形は「治せば」。「治すば」は仮定の形として誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "治す", "is_correct": true, "explanation": "辞書形で「治すまで走るな」と期間を表す形に続き、文の流れに合う。"}, {"text": "治した", "is_correct": false, "explanation": "過去形は「治したまで」となり、「まで」の前に続かず不自然。"}, {"text": "治せない", "is_correct": false, "explanation": "否定の可能形は「治せないまで」となり、「まで」の前に続かない。"}, {"text": "治される", "is_correct": false, "explanation": "受身形は「治されるまで」となり、傷を治す主体が変わって文の意味が合わない。"}], "correct_form": "治す", "base_form": "治す", "form_label": "辞書形", "sentence_index": 7, "explanations": {"治す": "辞書形で「治すまで走るな」と期間を表す形に続き、文の流れに合う。", "治した": "過去形は「治したまで」となり、「まで」の前に続かず不自然。", "治せない": "否定の可能形は「治せないまで」となり、「まで」の前に続かない。", "治される": "受身形は「治されるまで」となり、傷を治す主体が変わって文の意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53179, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "条件の「～と」で、引くと皿が動くという結果につながる"}, {"text": "に", "is_correct": false, "explanation": "「に」は行き先や対象を表すが、「引くに」では条件の文として続かない"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」は「引くで」と続けると文が成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「引くへ」と続けると文の流れが合わない"}], "correct_answer": "と", "explanations": {"と": "条件の「～と」で、引くと皿が動くという結果につながる", "に": "「に」は行き先や対象を表すが、「引くに」では条件の文として続かない", "で": "手段や場所の「で」は「引くで」と続けると文が成り立たない", "へ": "方向の「へ」は「引くへ」と続けると文の流れが合わない"}, "error_tags": {"に": "対象・位置", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "押す", "is_correct": true, "explanation": "手前に引く動きと逆向きの動作で、辞書でも対義語として並ぶ"}, {"text": "投げる", "is_correct": false, "explanation": "遠くへ放る動作で、引くの対義語ではない"}, {"text": "掴む", "is_correct": false, "explanation": "握って保つ動作で、引くとは対義語の関係にない"}, {"text": "包む", "is_correct": false, "explanation": "くるむ動作で、引くの対義語ではない"}], "correct_answer": "押す", "explanations": {"押す": "手前に引く動きと逆向きの動作で、辞書でも対義語として並ぶ", "投げる": "遠くへ放る動作で、引くの対義語ではない", "掴む": "握って保つ動作で、引くとは対義語の関係にない", "包む": "くるむ動作で、引くの対義語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53179, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "条件の「～と」で、引くと赤ちゃんが目を覚ますという結果につながる"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」は「引くで」と続けると文が成り立たない"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞につなぐ語で、「引くの、赤ちゃん」では文がつながらない"}, {"text": "を", "is_correct": false, "explanation": "対象の「を」は「毛布を」の後に来るので、引くの直後では合わない"}], "correct_answer": "と", "explanations": {"と": "条件の「～と」で、引くと赤ちゃんが目を覚ますという結果につながる", "で": "手段の「で」は「引くで」と続けると文が成り立たない", "の": "「の」は名詞につなぐ語で、「引くの、赤ちゃん」では文がつながらない", "を": "対象の「を」は「毛布を」の後に来るので、引くの直後では合わない"}, "error_tags": {"で": "手段・場所", "の": "修飾", "を": "対象"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "押す", "is_correct": true, "explanation": "手前に引く動きと逆向きの動作で、辞書でも対義語として並ぶ"}, {"text": "叩く", "is_correct": false, "explanation": "打ちつける動作で、引くの対義語ではない"}, {"text": "撫でる", "is_correct": false, "explanation": "やさしくさする動作で、引くの対義語ではない"}, {"text": "結ぶ", "is_correct": false, "explanation": "ひもなどをつなぐ動作で、引くの対義語ではない"}], "correct_answer": "押す", "explanations": {"押す": "手前に引く動きと逆向きの動作で、辞書でも対義語として並ぶ", "叩く": "打ちつける動作で、引くの対義語ではない", "撫でる": "やさしくさする動作で、引くの対義語ではない", "結ぶ": "ひもなどをつなぐ動作で、引くの対義語ではない"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53179, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを手の方に動かすことです。", "primary_collocate": null, "pronunciation": "ひく", "ipa": "çikɯ", "syllable_count": 2, "sentences": [{"text": "引き出しを引くと、ペンが一本転がり出ました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しを引[ひ]くと、ペンが一本[いっぽん]転[ころ]がり出[で]ました。", "sentence_source": "generated"}, {"text": "テーブルクロスを引くと、皿が少し動きました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "テーブルクロスを引[ひ]くと、皿[さら]が少[すこ]し動[うご]きました。", "sentence_source": "generated"}, {"text": "お盆を自分の方に引くと、食べやすくなります。", "target_word": "引く", "complexity_tier": "T3", "furigana": "お盆[ぼん]を自分[じぶん]の方[ほう]に引[ひ]くと、食[た]べやすくなります。", "sentence_source": "generated"}, {"text": "棚の箱を引くと、奥から古い写真が出てきました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "棚[たな]の箱[はこ]を引[ひ]くと、奥[おく]から古[ふる]い写真[しゃしん]が出[で]てきました。", "sentence_source": "generated"}, {"text": "レバーを引く前に、周りに人がいないか見ます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "レバーを引[ひ]く前[まえ]に、周[まわ]りに人[ひと]がいないか見[み]ます。", "sentence_source": "generated"}, {"text": "電気のひもを引くと、部屋の明かりがつきます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "電気[でんき]のひもを引[ひ]くと、部屋[へや]の明[あ]かりがつきます。", "sentence_source": "generated"}, {"text": "窓のそばの椅子を引くと、床に音が響きました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "窓[まど]のそばの椅子[いす]を引[ひ]くと、床[ゆか]に音[おと]が響[ひび]きました。", "sentence_source": "generated"}, {"text": "毛布を引くと、赤ちゃんが目を覚ましました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "毛布[もうふ]を引[ひ]くと、赤[あか]ちゃんが目[め]を覚[さ]ましました。", "sentence_source": "generated"}, {"text": "重い台車を引く力が足りず、坂の途中で止まりました。", "target_word": "引く", "complexity_tier": "T4", "furigana": "重[おも]い台車[だいしゃ]を引[ひ]く力[ちから]が足[た]りず、坂[さか]の途中[とちゅう]で止[と]まりました。", "sentence_source": "generated"}, {"text": "古いふすまを引くと、隣の部屋が見えました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "古[ふる]いふすまを引[ひ]くと、隣[となり]の部屋[へや]が見[み]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引く", "label": "終止形"}, {"form": "引かない", "label": "否定形"}, {"form": "引きます", "label": "丁寧形"}, {"form": "引いた", "label": "過去形"}, {"form": "引いて", "label": "て形"}, {"form": "引けば", "label": "仮定形"}, {"form": "引こう", "label": "意向形"}, {"form": "引かれる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "物を手のある方へ寄せるように動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53179, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "引き出しを手前に動かして開けるという意味で、ここに合う"}, {"text": "眺める", "is_correct": false, "explanation": "じっと見る意味。引き出しを眺めても、ペンが転がり出る流れにならない"}, {"text": "磨く", "is_correct": false, "explanation": "こすって光らせる意味。引き出しを磨いてペンが転がり出るのは不自然"}, {"text": "数える", "is_correct": false, "explanation": "数を数える意味。引き出しを数えてもペンが転がり出る結果にならない"}], "explanations": {"引く": "引き出しを手前に動かして開けるという意味で、ここに合う", "眺める": "じっと見る意味。引き出しを眺めても、ペンが転がり出る流れにならない", "磨く": "こすって光らせる意味。引き出しを磨いてペンが転がり出るのは不自然", "数える": "数を数える意味。引き出しを数えてもペンが転がり出る結果にならない"}, "sentence_index": 0, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "十から三を引くと、七になります。", "explanation": "ここは〈差し引く〉（数を減らす計算）の意味。手前へ動かす意味では合わない"}, {"text": "ボタンを引くと、明かりがつきます。", "explanation": "「引く」には〈押す〉の意味はなく、ボタンを手前に引く操作としては合わない"}, {"text": "テーブルを引くと、きれいになりました。", "explanation": "「引く」には〈拭く〉の意味はなく、テーブルを手前へ動かしてもきれいにはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53179, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "椅子を手前に動かす意味で、床に音が響く流れに合う"}, {"text": "乾かす", "is_correct": false, "explanation": "濡れたものを乾かす意味。椅子を乾かしても床に音が響く流れにならない"}, {"text": "読む", "is_correct": false, "explanation": "文字を読む意味。椅子は読む対象にならないので合わない"}, {"text": "祝う", "is_correct": false, "explanation": "喜んで祝う意味。椅子を祝っても床に音が響く流れにならない"}], "explanations": {"引く": "椅子を手前に動かす意味で、床に音が響く流れに合う", "乾かす": "濡れたものを乾かす意味。椅子を乾かしても床に音が響く流れにならない", "読む": "文字を読む意味。椅子は読む対象にならないので合わない", "祝う": "喜んで祝う意味。椅子を祝っても床に音が響く流れにならない"}, "sentence_index": 6, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "くじを引いたら、一等が当たりました。", "explanation": "ここは〈くじを引く〉（抽選する）の意味。手前へ動かす意味では合わない"}, {"text": "紙くずを引くと、ゴミ箱に入りました。", "explanation": "「引く」には〈投げる〉の意味はなく、紙くずを手前に引いてもゴミ箱に入る流れにならない"}, {"text": "プレゼントを引くと、きれいに仕上がりました。", "explanation": "「引く」には〈包む〉の意味はなく、プレゼントを手前に引いても仕上がりにはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53179, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い戸が引くと、冷たい風が入ってきました。", "corrected_sentence": "重い戸を引くと、冷たい風が入ってきました。", "error_description": "助詞の誤り。引く対象は「を」で示すので、「が」にすると文が成り立たない", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引く", "is_correct": true, "explanation": "終止形。「～と」の前に置く辞書形で、ここに合う"}, {"text": "引いて", "is_correct": false, "explanation": "て形。「～と」の前には続かず、文の形が成り立たない"}, {"text": "引けば", "is_correct": false, "explanation": "仮定形。「～ば」で続く条件の形で、「～と」の文には入らない"}, {"text": "引け", "is_correct": false, "explanation": "命令形。「～と」の前には続かず、命令の文になるので合わない"}], "correct_form": "引く", "base_form": "引く", "form_label": "終止形", "sentence_index": 1, "explanations": {"引く": "終止形。「～と」の前に置く辞書形で、ここに合う", "引いて": "て形。「～と」の前には続かず、文の形が成り立たない", "引けば": "仮定形。「～ば」で続く条件の形で、「～と」の文には入らない", "引け": "命令形。「～と」の前には続かず、命令の文になるので合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53179, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い障子を引いと、庭の緑が見えました。", "corrected_sentence": "古い障子を引くと、庭の緑が見えました。", "error_description": "活用の誤り。条件の「～と」は辞書形「引く」に続けるので、「引い」は成り立たない", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引く", "is_correct": true, "explanation": "終止形。「～と」の前に置く辞書形で、ここに合う"}, {"text": "引き", "is_correct": false, "explanation": "連用形で、条件の「と」の前には続かず文が成り立たない。"}, {"text": "引かれる", "is_correct": false, "explanation": "受身形。毛布が誰かに引かれる意味になり、赤ちゃんが目を覚ます流れと合わない"}, {"text": "引いたり", "is_correct": false, "explanation": "並列の形で、条件の「と」に続けると文が成り立たない。"}], "correct_form": "引く", "base_form": "引く", "form_label": "終止形", "sentence_index": 7, "explanations": {"引く": "終止形。「～と」の前に置く辞書形で、ここに合う", "引き": "連用形で、条件の「と」の前には続かず文が成り立たない。", "引かれる": "受身形。毛布が誰かに引かれる意味になり、赤ちゃんが目を覚ます流れと合わない", "引いたり": "並列の形で、条件の「と」に続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53180, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "条件の「～と」で、引くと船が岸へ近づくという結果につながる"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」は「引くで」と続けると文が成り立たない"}, {"text": "に", "is_correct": false, "explanation": "「に」は「引くに」と続けると、条件の文として成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「引くへ」と続けると文の流れが合わない"}], "correct_answer": "と", "explanations": {"と": "条件の「～と」で、引くと船が岸へ近づくという結果につながる", "で": "手段や場所の「で」は「引くで」と続けると文が成り立たない", "に": "「に」は「引くに」と続けると、条件の文として成り立たない", "へ": "方向の「へ」は「引くへ」と続けると文の流れが合わない"}, "error_tags": {"で": "手段・場所", "に": "対象・位置", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "押す", "is_correct": true, "explanation": "近づける動きと逆向きに押す動作で、辞書でも対義語として並ぶ"}, {"text": "撫でる", "is_correct": false, "explanation": "やさしくさする動作で、引くの対義語ではない"}, {"text": "結ぶ", "is_correct": false, "explanation": "ひもなどをつなぐ動作で、引くの対義語ではない"}, {"text": "洗う", "is_correct": false, "explanation": "汚れを落とす動作で、引くの対義語ではない"}], "correct_answer": "押す", "explanations": {"押す": "近づける動きと逆向きに押す動作で、辞書でも対義語として並ぶ", "撫でる": "やさしくさする動作で、引くの対義語ではない", "結ぶ": "ひもなどをつなぐ動作で、引くの対義語ではない", "洗う": "汚れを落とす動作で、引くの対義語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53180, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段の「で」で、腰のベルトを使って引くという意味になり、ここに合う"}, {"text": "に", "is_correct": false, "explanation": "「に」は「腰のベルトに引く練習」と続かず、文が成り立たない"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象がなく、引くの前では文が成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「腰のベルトへ引く練習」と続かず、文が成り立たない"}], "correct_answer": "で", "explanations": {"で": "手段の「で」で、腰のベルトを使って引くという意味になり、ここに合う", "に": "「に」は「腰のベルトに引く練習」と続かず、文が成り立たない", "より": "比較の「より」は比べる対象がなく、引くの前では文が成り立たない", "へ": "方向の「へ」は「腰のベルトへ引く練習」と続かず、文が成り立たない"}, "error_tags": {"に": "対象・位置", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "押す", "is_correct": true, "explanation": "近づける動きと逆向きに押す動作で、辞書でも対義語として並ぶ"}, {"text": "投げる", "is_correct": false, "explanation": "遠くへ放る動作で、引くの対義語ではない"}, {"text": "掴む", "is_correct": false, "explanation": "握って保つ動作で、引くとは対義語の関係にない"}, {"text": "包む", "is_correct": false, "explanation": "くるむ動作で、引くの対義語ではない"}], "correct_answer": "押す", "explanations": {"押す": "近づける動きと逆向きに押す動作で、辞書でも対義語として並ぶ", "投げる": "遠くへ放る動作で、引くの対義語ではない", "掴む": "握って保つ動作で、引くとは対義語の関係にない", "包む": "くるむ動作で、引くの対義語ではない"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53180, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手や体の方向に力を加えて、物や体を近づけること。", "primary_collocate": null, "pronunciation": "ひく", "ipa": "çikɯ", "syllable_count": 2, "sentences": [{"text": "犬のリードを引くと、犬が立ち止まって私を見ました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "犬[いぬ]のリードを引[ひ]くと、犬[いぬ]が立[た]ち止[ど]まって私[わたし]を見[み]ました。", "sentence_source": "generated"}, {"text": "ロープを引くと、小さな船が岸にゆっくり近づきます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "ロープを引[ひ]くと、小[ちい]さな船[ふね]が岸[きし]にゆっくり近[ちか]づきます。", "sentence_source": "generated"}, {"text": "友人が私の肩を引くので、振り返りました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "友人[ゆうじん]が私[わたし]の肩[かた]を引[ひ]くので、振[ふ]り返[かえ]りました。", "sentence_source": "generated"}, {"text": "危ない車から子供の体を引く母の姿が見えました。", "target_word": "引く", "complexity_tier": "T4", "furigana": "危[あぶ]ない車[くるま]から子供[こども]の体[からだ]を引[ひ]く母[はは]の姿[すがた]が見[み]えました。", "sentence_source": "generated"}, {"text": "網を体の方へ引くと、足元に魚が集まりました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "網[あみ]を体[からだ]の方[ほう]へ引[ひ]くと、足元[あしもと]に魚[さかな]が集[あつ]まりました。", "sentence_source": "generated"}, {"text": "鎖を引くと、重い門が少しずつこちらへ開きます。", "target_word": "引く", "complexity_tier": "T4", "furigana": "鎖[くさり]を引[ひ]くと、重[おも]い門[もん]が少[すこ]しずつこちらへ開[ひら]きます。", "sentence_source": "generated"}, {"text": "本の背を指で引くと、棚から本が出てきます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "本[ほん]の背[せ]を指[ゆび]で引[ひ]くと、棚[たな]から本[ほん]が出[で]てきます。", "sentence_source": "generated"}, {"text": "友人は重いそりを腰のベルトで引く練習をしています。", "target_word": "引く", "complexity_tier": "T3", "furigana": "友人[ゆうじん]は重[おも]いそりを腰[こし]のベルトで引[ひ]く練習[れんしゅう]をしています。", "sentence_source": "generated"}, {"text": "綱を引くと、相手の体がこちらに近づきました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "綱[つな]を引[ひ]くと、相手[あいて]の体[からだ]がこちらに近[ちか]づきました。", "sentence_source": "generated"}, {"text": "腕を引く力が強くて、つい転びそうになりました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "腕[うで]を引[ひ]く力[ちから]が強[つよ]くて、つい転[ころ]びそうになりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引く", "label": "終止形"}, {"form": "引かない", "label": "否定形"}, {"form": "引きます", "label": "丁寧形"}, {"form": "引いた", "label": "過去形"}, {"form": "引いて", "label": "て形"}, {"form": "引けば", "label": "仮定形"}, {"form": "引こう", "label": "意向形"}, {"form": "引かれる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "手や体の方向へ力を加えて、物や人を自分に近づける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53180, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "リードを手前へ引いて犬を近づける意味で、犬が立ち止まる流れに合う"}, {"text": "眺める", "is_correct": false, "explanation": "じっと見る意味。リードを眺めても犬が立ち止まる結果にならない"}, {"text": "飲む", "is_correct": false, "explanation": "口に入れる意味。リードは飲めないので合わない"}, {"text": "数える", "is_correct": false, "explanation": "数を数える意味。リードを数えても犬が止まる流れにならない"}], "explanations": {"引く": "リードを手前へ引いて犬を近づける意味で、犬が立ち止まる流れに合う", "眺める": "じっと見る意味。リードを眺めても犬が立ち止まる結果にならない", "飲む": "口に入れる意味。リードは飲めないので合わない", "数える": "数を数える意味。リードを数えても犬が止まる流れにならない"}, "sentence_index": 0, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "資金の問題で、彼はこの事業から手を引くことにした。", "explanation": "ここは〈手を引く〉（関わるのをやめる）の意味。体を近づける意味では合わない"}, {"text": "ボールを引くと、ゴールに入りました。", "explanation": "「引く」には〈蹴る〉の意味はなく、ボールを手前へ引いてゴールに入る流れにはならない"}, {"text": "壁を引くと、隣の部屋から声がしました。", "explanation": "「引く」には〈叩く〉の意味はなく、壁を手前へ近づける流れにはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53180, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "指で手前に引き出す意味で、棚から本が出てくる流れに合う"}, {"text": "歌う", "is_correct": false, "explanation": "声を出して歌う意味。本の背を歌う動作は合わない"}, {"text": "祝う", "is_correct": false, "explanation": "喜んで祝う意味で、棚から本が出る流れにならない"}, {"text": "噛む", "is_correct": false, "explanation": "歯で砕く意味。本の背を噛んでも本が出てくる流れにはならない"}], "explanations": {"引く": "指で手前に引き出す意味で、棚から本が出てくる流れに合う", "歌う": "声を出して歌う意味。本の背を歌う動作は合わない", "祝う": "喜んで祝う意味で、棚から本が出る流れにならない", "噛む": "歯で砕く意味。本の背を噛んでも本が出てくる流れにはならない"}, "sentence_index": 6, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はピアノを引いて、家族を楽しませた。", "explanation": "ここは〈弾く〉（楽器を演奏する）の意味。体を近づける意味では合わない"}, {"text": "石を引くと、水面に大きな輪ができました。", "explanation": "「引く」には〈投げる〉の意味はなく、石を手前へ引いても水面に輪ができる流れにはならない"}, {"text": "床を白く引くと、部屋が明るくなりました。", "explanation": "「引く」には〈塗る〉の意味はなく、床を手前へ動かしても白く明るくはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53180, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "釣り糸に引くと、大きな魚が暴れ出しました。", "corrected_sentence": "釣り糸を引くと、大きな魚が暴れ出しました。", "error_description": "助詞の誤り。引く対象は「を」で示すので、「に」にすると引く動作の対象が成り立たない", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引く", "is_correct": true, "explanation": "終止形。「～と」の前に置く辞書形で、ここに合う"}, {"text": "引いて", "is_correct": false, "explanation": "て形。「～と」の前には続かず、文の形が成り立たない"}, {"text": "引けば", "is_correct": false, "explanation": "仮定形。「～ば」で続く条件の形で、「～と」の文には入らない"}, {"text": "引け", "is_correct": false, "explanation": "命令形。「～と」の前には続かず、命令の文になるので合わない"}], "correct_form": "引く", "base_form": "引く", "form_label": "終止形", "sentence_index": 1, "explanations": {"引く": "終止形。「～と」の前に置く辞書形で、ここに合う", "引いて": "て形。「～と」の前には続かず、文の形が成り立たない", "引けば": "仮定形。「～ば」で続く条件の形で、「～と」の文には入らない", "引け": "命令形。「～と」の前には続かず、命令の文になるので合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53180, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "腕を引かと、子供がこちらへ戻ってきました。", "corrected_sentence": "腕を引くと、子供がこちらへ戻ってきました。", "error_description": "活用の誤り。条件の「～と」は辞書形「引くと」に続けるので、「引かと」は成り立たない", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引く", "is_correct": true, "explanation": "連体形。後ろの「練習」を修飾する辞書形で、ここに合う"}, {"text": "引きます", "is_correct": false, "explanation": "丁寧形。名詞「練習」を直接修飾できず、空所に入らない"}, {"text": "引きません", "is_correct": false, "explanation": "丁寧否定形。名詞「練習」を直接修飾できず、空所に入らない"}, {"text": "引かせて", "is_correct": false, "explanation": "使役のて形。「練習」の前には続かず、文が成り立たない"}], "correct_form": "引く", "base_form": "引く", "form_label": "連体形", "sentence_index": 7, "explanations": {"引く": "連体形。後ろの「練習」を修飾する辞書形で、ここに合う", "引きます": "丁寧形。名詞「練習」を直接修飾できず、空所に入らない", "引きません": "丁寧否定形。名詞「練習」を直接修飾できず、空所に入らない", "引かせて": "使役のて形。「練習」の前には続かず、文が成り立たない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53181, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "対義語。動くものの速さの反対を表し、「速いボール」の対になる。"}, {"text": "重い", "is_correct": false, "explanation": "対義語は「軽い」で、速さの反対ではない。"}, {"text": "硬い", "is_correct": false, "explanation": "対義語は「柔らかい」で、速さとは関係ない。"}, {"text": "高い", "is_correct": false, "explanation": "対義語は「低い」で、速さの話には合わない。"}], "correct_answer": "遅い", "explanations": {"遅い": "対義語。動くものの速さの反対を表し、「速いボール」の対になる。", "重い": "対義語は「軽い」で、速さの反対ではない。", "硬い": "対義語は「柔らかい」で、速さとは関係ない。", "高い": "対義語は「低い」で、速さの話には合わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53181, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "対義語。「速く走る」の反対で、速さの対になる語。"}, {"text": "軽い", "is_correct": false, "explanation": "対義語は「重い」で、速さの反対ではない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "対義語は「硬い」で、速さとは関係ない。"}, {"text": "低い", "is_correct": false, "explanation": "対義語は「高い」で、速さの話には合わない。"}], "correct_answer": "遅い", "explanations": {"遅い": "対義語。「速く走る」の反対で、速さの対になる語。", "軽い": "対義語は「重い」で、速さの反対ではない。", "柔らかい": "対義語は「硬い」で、速さとは関係ない。", "低い": "対義語は「高い」で、速さの話には合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53181, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "ものやひとが、はやくうごくこと。", "primary_collocate": null, "pronunciation": "はやい", "ipa": "hajai", "syllable_count": 3, "sentences": [{"text": "猫は動きが速くて、手でつかまえられなかった。", "target_word": "速く", "complexity_tier": "T3", "furigana": "猫[ねこ]は動[うご]きが速[はや]くて、手[て]でつかまえられなかった。", "sentence_source": "generated"}, {"text": "台風が近づくと、雲の動きが速くなる。", "target_word": "速く", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づくと、雲[くも]の動[うご]きが速[はや]くなる。", "sentence_source": "generated"}, {"text": "あの選手は足が速く、百メートルを十秒で走る。", "target_word": "速く", "complexity_tier": "T3", "furigana": "あの選手[せんしゅ]は足[あし]が速[はや]く、百[ひゃく]メートルを十秒[じゅうびょう]で走[はし]る。", "sentence_source": "generated"}, {"text": "速いボールが飛んできて、私は思わず目を閉じた。", "target_word": "速い", "complexity_tier": "T3", "furigana": "速[はや]いボールが飛[と]んできて、私[わたし]は思[おも]わず目[め]を閉[と]じた。", "sentence_source": "generated"}, {"text": "川の水は冬でも流れが速く、橋の下で白く光っていた。", "target_word": "速く", "complexity_tier": "T4", "furigana": "川[かわ]の水[みず]は冬[ふゆ]でも流[なが]れが速[はや]く、橋[はし]の下[した]で白[しろ]く光[ひか]っていた。", "sentence_source": "generated"}, {"text": "電車が速いせいで、窓の外の景色がぼやけて見えた。", "target_word": "速い", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が速[はや]いせいで、窓[まど]の外[そと]の景色[けしき]がぼやけて見[み]えた。", "sentence_source": "generated"}, {"text": "兄は自転車で坂を下るのが速く、私は追いつけない。", "target_word": "速く", "complexity_tier": "T3", "furigana": "兄[あに]は自転車[じてんしゃ]で坂[さか]を下[くだ]るのが速[はや]く、私[わたし]は追[お]いつけない。", "sentence_source": "generated"}, {"text": "ツバメは飛ぶのが速いから、カメラでは追いにくい。", "target_word": "速い", "complexity_tier": "T3", "furigana": "ツバメは飛[と]ぶのが速[はや]いから、カメラでは追[お]いにくい。", "sentence_source": "generated"}, {"text": "水泳選手は泳ぎが速く、ほとんど水しぶきを立てない。", "target_word": "速く", "complexity_tier": "T3", "furigana": "水泳選手[すいえいせんしゅ]は泳[およ]ぎが速[はや]く、ほとんど水[みず]しぶきを立[た]てない。", "sentence_source": "generated"}, {"text": "馬は速く走るために、長い足と強い筋肉を持っている。", "target_word": "速く", "complexity_tier": "T3", "furigana": "馬[うま]は速[はや]く走[はし]るために、長[なが]い足[あし]と強[つよ]い筋肉[きんにく]を持[も]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "速い", "label": "終止形"}, {"form": "速く", "label": "連用形"}, {"form": "速かった", "label": "過去形"}, {"form": "速くない", "label": "否定形"}, {"form": "速ければ", "label": "仮定形"}, {"form": "速くて", "label": "て形"}], "register": "neutral", "sense_fingerprint": "物や人・動物の動きの速さが大きい（動くものの速さ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53181, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。「動きが速くて」の形で「て」に続くので、空所に入る。"}, {"text": "速い", "is_correct": false, "explanation": "終止形。「動きが速いて」と「て」に続かないので、空所に入らない。"}, {"text": "速かった", "is_correct": false, "explanation": "過去形。「速かったて」とは続かず、「速くて」の形が必要。"}, {"text": "速ければ", "is_correct": false, "explanation": "仮定形。「速ければて」と続かず、文の形に合わない。"}], "explanations": {"速く": "連用形。「動きが速くて」の形で「て」に続くので、空所に入る。", "速い": "終止形。「動きが速いて」と「て」に続かないので、空所に入らない。", "速かった": "過去形。「速かったて」とは続かず、「速くて」の形が必要。", "速ければ": "仮定形。「速ければて」と続かず、文の形に合わない。"}, "sentence_index": 0, "correct_answer": "速く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この坂は速いので、自転車では登りにくい。", "explanation": "速いは動きや進みの速さを表し、坂の傾きは「急な坂」と言う。ここは速さの意味にならない"}, {"text": "この枝は速いので、強い風でも折れない。", "explanation": "枝の太さは「太い」で表し、「速い」は速度を表すので合わない"}, {"text": "毎朝、速い時間に目が覚めて、散歩に行く。", "explanation": "時間の早さは「早い時間」と言い、「速い」は動きや進みの速さなので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53181, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。「下るのが速く、私は追いつけない」と理由の流れに合う。"}, {"text": "遅く", "is_correct": false, "explanation": "反対の意味。遅く下るなら「私は追いつけない」の理由にならず、文の流れが合わない。"}, {"text": "速さ", "is_correct": false, "explanation": "名詞。「下るのが速さ、」と続かないので、空所に入らない。"}, {"text": "速め", "is_correct": false, "explanation": "「速めの」の形で使う語。「下るのが速め、」とは続かない。"}], "explanations": {"速く": "連用形。「下るのが速く、私は追いつけない」と理由の流れに合う。", "遅く": "反対の意味。遅く下るなら「私は追いつけない」の理由にならず、文の流れが合わない。", "速さ": "名詞。「下るのが速さ、」と続かないので、空所に入らない。", "速め": "「速めの」の形で使う語。「下るのが速め、」とは続かない。"}, "sentence_index": 6, "correct_answer": "速く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この包丁は切れ味が速いので、野菜がすぐ切れる。", "explanation": "切れ味の鋭さは「鋭い」で表し、「速い」は動きや進みの速さなので合わない"}, {"text": "彼は力が速いので、重い荷物も楽に運べる。", "explanation": "力の強さは「強い」で表し、「速い」は速度の意味なので合わない"}, {"text": "毎晩、速い声で名前を呼ばれて、目が覚めた。", "explanation": "声の大きさは「大きい」で表し、「速い」は速度の意味なので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53181, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "そのランナーは足が速いて、誰にも追いつけなかった。", "corrected_sentence": "そのランナーは足が速くて、誰にも追いつけなかった。", "error_description": "形容詞「速い」を「て」に続けるときは連用形の「速くて」になる。「速いて」は誤りで、正しくは「速くて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。「速くなる」で状態の変化を表し、文の形に合う。"}, {"text": "速い", "is_correct": false, "explanation": "終止形。「速いなる」とは続かず、変化を表す「なる」の前には連用形が必要。"}, {"text": "速かった", "is_correct": false, "explanation": "過去形。変化を述べる現在の文には過去形は合わない。"}, {"text": "速くない", "is_correct": false, "explanation": "否定形。「速くないなる」となり、変化を表す「なる」の前には入らない"}], "correct_form": "速く", "base_form": "速い", "form_label": "連用形", "sentence_index": 1, "explanations": {"速く": "連用形。「速くなる」で状態の変化を表し、文の形に合う。", "速い": "終止形。「速いなる」とは続かず、変化を表す「なる」の前には連用形が必要。", "速かった": "過去形。変化を述べる現在の文には過去形は合わない。", "速くない": "否定形。「速くないなる」となり、変化を表す「なる」の前には入らない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53181, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は泳ぐのを速く、みんなを引き離した。", "corrected_sentence": "彼は泳ぐのが速く、みんなを引き離した。", "error_description": "誤りは「泳ぐのを」。「速い」の主語は「泳ぐのが」で「が」を使うので、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "速い", "is_correct": true, "explanation": "終止形。理由を表す「から」の前には普通形（終止形）が来る。"}, {"text": "速く", "is_correct": false, "explanation": "連用形。「速くから」とは続かず、理由の「から」の前に置けない。"}, {"text": "速ければ", "is_correct": false, "explanation": "仮定形。「速ければから」と続かず、理由の文の形に合わない。"}, {"text": "速くて", "is_correct": false, "explanation": "て形。「速くてから」と続かない。"}], "correct_form": "速い", "base_form": "速い", "form_label": "終止形", "sentence_index": 7, "explanations": {"速い": "終止形。理由を表す「から」の前には普通形（終止形）が来る。", "速く": "連用形。「速くから」とは続かず、理由の「から」の前に置けない。", "速ければ": "仮定形。「速ければから」と続かず、理由の文の形に合わない。", "速くて": "て形。「速くてから」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53182, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "対義語。手際や処理の速さの反対を表し、速いの対になる。"}, {"text": "重い", "is_correct": false, "explanation": "対義語は「軽い」で、速さの反対ではない。"}, {"text": "硬い", "is_correct": false, "explanation": "対義語は「柔らかい」で、速さとは関係ない。"}, {"text": "高い", "is_correct": false, "explanation": "対義語は「低い」で、速さの話には合わない。"}], "correct_answer": "遅い", "explanations": {"遅い": "対義語。手際や処理の速さの反対を表し、速いの対になる。", "重い": "対義語は「軽い」で、速さの反対ではない。", "硬い": "対義語は「柔らかい」で、速さとは関係ない。", "高い": "対義語は「低い」で、速さの話には合わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53182, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅い", "is_correct": true, "explanation": "対義語。手際や変化の速さの反対を表し、速いの対になる。"}, {"text": "軽い", "is_correct": false, "explanation": "対義語は「重い」で、速さの反対ではない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "対義語は「硬い」で、速さとは関係ない。"}, {"text": "低い", "is_correct": false, "explanation": "対義語は「高い」で、速さの話には合わない。"}], "correct_answer": "遅い", "explanations": {"遅い": "対義語。手際や変化の速さの反対を表し、速いの対になる。", "軽い": "対義語は「重い」で、速さの反対ではない。", "柔らかい": "対義語は「硬い」で、速さとは関係ない。", "低い": "対義語は「高い」で、速さの話には合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53182, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物事を行うのに時間がかからず、移動や動作のスピードが大きいこと。", "primary_collocate": null, "pronunciation": "はやい", "ipa": "hajai", "syllable_count": 3, "sentences": [{"text": "新しい機械は処理が速く、作業時間が半分になった。", "target_word": "速く", "complexity_tier": "T4", "furigana": "新[あたら]しい機械[きかい]は処理[しょり]が速[はや]く、作業時間[さぎょうじかん]が半分[はんぶん]になった。", "sentence_source": "generated"}, {"text": "特急は各駅停車より速いが、料金も高くなる。", "target_word": "速い", "complexity_tier": "T4", "furigana": "特急[とっきゅう]は各駅停車[かくえきていしゃ]より速[はや]いが、料金[りょうきん]も高[たか]くなる。", "sentence_source": "generated"}, {"text": "彼女は読むのが速いので、一晩で長い小説を読み終える。", "target_word": "速い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は読[よ]むのが速[はや]いので、一晩[ひとばん]で長[なが]い小説[しょうせつ]を読[よ]み終[お]える。", "sentence_source": "generated"}, {"text": "熟練した職人は手の動きが速く、見ていても細かい動作が追えない。", "target_word": "速く", "complexity_tier": "T4", "furigana": "熟練[じゅくれん]した職人[しょくにん]は手[て]の動[うご]きが速[はや]く、見[み]ていても細[こま]かい動作[どうさ]が追[お]えない。", "sentence_source": "generated"}, {"text": "速いテンポの曲に合わせて、みんなが踊り出した。", "target_word": "速い", "complexity_tier": "T3", "furigana": "速[はや]いテンポの曲[きょく]に合[あ]わせて、みんなが踊[おど]り出[だ]した。", "sentence_source": "generated"}, {"text": "運送会社は配達が速いことを売りにしている。", "target_word": "速い", "complexity_tier": "T4", "furigana": "運送会社[うんそうがいしゃ]は配達[はいたつ]が速[はや]いことを売[う]りにしている。", "sentence_source": "generated"}, {"text": "彼の説明は話し方が速く、メモが間に合わなかった。", "target_word": "速く", "complexity_tier": "T3", "furigana": "彼[かれ]の説明[せつめい]は話[はな]し方[かた]が速[はや]く、メモが間[ま]に合[あ]わなかった。", "sentence_source": "generated"}, {"text": "流れの速い川では、橋を架ける工事が難しい。", "target_word": "速い", "complexity_tier": "T4", "furigana": "流[なが]れの速[はや]い川[かわ]では、橋[はし]を架[か]ける工事[こうじ]が難[むずか]しい。", "sentence_source": "generated"}, {"text": "この竹は伸びるのが速く、一週間で背丈が倍になった。", "target_word": "速く", "complexity_tier": "T3", "furigana": "この竹[たけ]は伸[の]びるのが速[はや]く、一週間[いっしゅうかん]で背丈[せたけ]が倍[ばい]になった。", "sentence_source": "generated"}, {"text": "世の中の変化が速い時代には、学び続けることが大切だ。", "target_word": "速い", "complexity_tier": "T4", "furigana": "世[よ]の中[なか]の変化[へんか]が速[はや]い時代[じだい]には、学[まな]び続[つづ]けることが大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "速い", "label": "終止形"}, {"form": "速く", "label": "連用形"}, {"form": "速かった", "label": "過去形"}, {"form": "速くない", "label": "否定形"}, {"form": "速ければ", "label": "仮定形"}, {"form": "速くて", "label": "て形"}], "register": "neutral", "sense_fingerprint": "作業・動作・変化の進み方のスピードが大きい（手際や処理の速さ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53182, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。「処理が速く、作業時間が半分になった」と原因を表し、文の形に合う。"}, {"text": "強く", "is_correct": false, "explanation": "「処理が強く」は処理の速さを表さず、作業時間の短縮とつながらない。"}, {"text": "大きく", "is_correct": false, "explanation": "「処理が大きく」は処理の速さを表さず、文の内容に合わない。"}, {"text": "速さ", "is_correct": false, "explanation": "名詞。「処理が速さ、」と文が続かないので、空所に入らない。"}], "explanations": {"速く": "連用形。「処理が速く、作業時間が半分になった」と原因を表し、文の形に合う。", "強く": "「処理が強く」は処理の速さを表さず、作業時間の短縮とつながらない。", "大きく": "「処理が大きく」は処理の速さを表さず、文の内容に合わない。", "速さ": "名詞。「処理が速さ、」と文が続かないので、空所に入らない。"}, "sentence_index": 0, "correct_answer": "速く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この坂道は速いので、自転車を降りて押した。", "explanation": "速いは作業や動作の速さを表し、坂の傾きは「急な坂」と言う。ここは速さの意味にならない"}, {"text": "問題に速い段階で気づいたので、対応が間に合った。", "explanation": "「早い段階」と言い、「速い」は進み方のスピードを表すので段階には使わない"}, {"text": "このスープは速いので、すぐには飲めなかった。", "explanation": "温度の高さは「熱い」で表し、「速い」は速さを表すので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53182, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速く", "is_correct": true, "explanation": "連用形。「話し方が速く、メモが間に合わなかった」と原因を表し、文の形に合う。"}, {"text": "遅く", "is_correct": false, "explanation": "反対の意味。話し方が遅ければメモは間に合うはずで、文の流れに合わない。"}, {"text": "速め", "is_correct": false, "explanation": "「速めの」の形で使う語。「話し方が速め、」とは続かない。"}, {"text": "遅め", "is_correct": false, "explanation": "「遅めの」の形で使う語。「話し方が遅め、」とは続かない。"}], "explanations": {"速く": "連用形。「話し方が速く、メモが間に合わなかった」と原因を表し、文の形に合う。", "遅く": "反対の意味。話し方が遅ければメモは間に合うはずで、文の流れに合わない。", "速め": "「速めの」の形で使う語。「話し方が速め、」とは続かない。", "遅め": "「遅めの」の形で使う語。「話し方が遅め、」とは続かない。"}, "sentence_index": 6, "correct_answer": "速く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この石は速いので、ハンマーで割れなかった。", "explanation": "石の硬さは「硬い」で表し、「速い」は速度の意味なので合わない"}, {"text": "この鞄は速いので、毎日持ち歩ける。", "explanation": "重さは「軽い」で表し、「速い」は速度なので合わない"}, {"text": "この店は値段が速いが、品質は確かだ。", "explanation": "値段の高さは「高い」で表し、「速い」は速度なので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53182, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この新しいソフトは読み込みが速いて、待ち時間がほとんどない。", "corrected_sentence": "この新しいソフトは読み込みが速くて、待ち時間がほとんどない。", "error_description": "形容詞「速い」を「て」に続けるときは連用形の「速くて」になる。「速いて」は誤りで、正しくは「速くて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "速い", "is_correct": true, "explanation": "終止形。「速いが」と逆接の「が」の前には普通形（終止形）が来る。"}, {"text": "速く", "is_correct": false, "explanation": "連用形。「速くが」とは続かず、逆接の文の形に合わない。"}, {"text": "速くて", "is_correct": false, "explanation": "て形。「速くてが」と続かず、「が」の前に入らない"}, {"text": "速ければ", "is_correct": false, "explanation": "仮定形。「速ければが」と続かず、「が」の前に入らない"}], "correct_form": "速い", "base_form": "速い", "form_label": "終止形", "sentence_index": 1, "explanations": {"速い": "終止形。「速いが」と逆接の「が」の前には普通形（終止形）が来る。", "速く": "連用形。「速くが」とは続かず、逆接の文の形に合わない。", "速くて": "て形。「速くてが」と続かず、「が」の前に入らない", "速ければ": "仮定形。「速ければが」と続かず、「が」の前に入らない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53182, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験の採点が速さので、結果が早く届く。", "corrected_sentence": "試験の採点が速いので、結果が早く届く。", "error_description": "形容詞「速い」は理由の「ので」に続けると「速いので」になる。名詞「速さ」は「速さので」と続けられず、誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "速い", "is_correct": true, "explanation": "連体形。名詞「流れ」を修飾する形で、「流れの速い川」と続く。"}, {"text": "速いです", "is_correct": false, "explanation": "丁寧形。名詞「川」を直接修飾できず、空所に入らない"}, {"text": "速さ", "is_correct": false, "explanation": "名詞。「速さの川」と「の」を挟まないと「川」を修飾できず、空所に入らない"}, {"text": "速そう", "is_correct": false, "explanation": "様態の形。「速そうな」と「な」が必要で、「速そう川」とは続かない"}], "correct_form": "速い", "base_form": "速い", "form_label": "連体形", "sentence_index": 7, "explanations": {"速い": "連体形。名詞「流れ」を修飾する形で、「流れの速い川」と続く。", "速いです": "丁寧形。名詞「川」を直接修飾できず、空所に入らない", "速さ": "名詞。「速さの川」と「の」を挟まないと「川」を修飾できず、空所に入らない", "速そう": "様態の形。「速そうな」と「な」が必要で、「速そう川」とは続かない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
