INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53183, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "ぎゅっときつく、あわてずじょうずにやることです。", "primary_collocate": null, "pronunciation": "しっかり", "ipa": "ɕikkaɾi", "syllable_count": 4, "sentences": [{"text": "転ばないように、手すりをしっかりつかんだ。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "転[ころ]ばないように、手[て]すりをしっかりつかんだ。", "sentence_source": "generated"}, {"text": "子どもの手をしっかりにぎって、道をわたった。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "子[こ]どもの手[て]をしっかりにぎって、道[みち]をわたった。", "sentence_source": "generated"}, {"text": "ひもをしっかりむすばないと、荷物が落ちてしまう。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "ひもをしっかりむすばないと、荷物[にもつ]が落[お]ちてしまう。", "sentence_source": "generated"}, {"text": "急がないで、しっかりやれば、きっとうまくいく。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "急[いそ]がないで、しっかりやれば、きっとうまくいく。", "sentence_source": "generated"}, {"text": "ねじをしっかりしめたので、もうゆるまない。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "ねじをしっかりしめたので、もうゆるまない。", "sentence_source": "generated"}, {"text": "彼女は赤ちゃんをしっかりだいて、やさしくゆらした。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は赤[あか]ちゃんをしっかりだいて、やさしくゆらした。", "sentence_source": "generated"}, {"text": "ふたをしっかりしめないと、中身がこぼれる。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "ふたをしっかりしめないと、中身[なかみ]がこぼれる。", "sentence_source": "generated"}, {"text": "あわてず、しっかり狙って矢を放った。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "あわてず、しっかり狙[ねら]って矢[や]を放[はな]った。", "sentence_source": "generated"}, {"text": "母は荷物をしっかりかかえて、電車に乗った。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "母[はは]は荷物[にもつ]をしっかりかかえて、電車[でんしゃ]に乗[の]った。", "sentence_source": "generated"}, {"text": "落ち着いて、しっかり息をすってから、歌いはじめた。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "落[お]ち着[つ]いて、しっかり息[いき]をすってから、歌[うた]いはじめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "しっかり", "label": "基本形"}, {"form": "しっかりと", "label": "強調形"}, {"form": "しっかりする", "label": "サ変動詞"}, {"form": "しっかりして", "label": "テ形"}], "register": "中立・口語（常体）", "sense_fingerprint": "ぎゅっときつく、落ち着いて確実にするようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53183, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "しっかり", "is_correct": true, "explanation": "「手すりをしっかりつかんだ」で、きつく確実に握る様子を表す。文に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "〈深く眠るさま〉の意味で、握る動作には使えない。"}, {"text": "ぽかぽか", "is_correct": false, "explanation": "〈温かいさま〉の意味で、握る強さは表せない。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "〈軽くやわらかいさま〉の意味で、しっかり握る文脈と合わない。"}], "explanations": {"しっかり": "「手すりをしっかりつかんだ」で、きつく確実に握る様子を表す。文に合う。", "ぐっすり": "〈深く眠るさま〉の意味で、握る動作には使えない。", "ぽかぽか": "〈温かいさま〉の意味で、握る強さは表せない。", "ふわふわ": "〈軽くやわらかいさま〉の意味で、しっかり握る文脈と合わない。"}, "sentence_index": 0, "correct_answer": "しっかり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は寝坊して、しっかり遅刻した。", "explanation": "ここは〈落ち着いて確実に〉の意味。遅刻の程度を強める語としては使わないので、この文では成り立たない。"}, {"text": "彼女は地図を見ながら、しっかり道を間違えた。", "explanation": "ここは〈落ち着いて確実に〉の意味。道を間違えるという誤りは「しっかり」では表せず、誤りの強さを示す語ではない。"}, {"text": "祖父は耳がしっかり遠くて、大声でもよく聞こえない。", "explanation": "ここは〈確実に〉の意味。耳が遠いという状態を強める用法ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53183, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "しっかり", "is_correct": true, "explanation": "「ふたをしっかりしめないと」で、きつく確実に閉める様子を表す。文に合う。"}, {"text": "のんびり", "is_correct": false, "explanation": "〈ゆったり構えるさま〉の意味で、きつく閉める動作には合わない。"}, {"text": "さっぱり", "is_correct": false, "explanation": "〈すっきりしたさま〉の意味で、閉める動作の副詞としては不自然。"}, {"text": "ゆったり", "is_correct": false, "explanation": "〈ゆるやかでゆとりがあるさま〉の意味で、きつく閉める文脈と矛盾する。"}], "explanations": {"しっかり": "「ふたをしっかりしめないと」で、きつく確実に閉める様子を表す。文に合う。", "のんびり": "〈ゆったり構えるさま〉の意味で、きつく閉める動作には合わない。", "さっぱり": "〈すっきりしたさま〉の意味で、閉める動作の副詞としては不自然。", "ゆったり": "〈ゆるやかでゆとりがあるさま〉の意味で、きつく閉める文脈と矛盾する。"}, "sentence_index": 6, "correct_answer": "しっかり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は焦るほど、しっかり慌てて答案を書いた。", "explanation": "ここは〈落ち着いて〉の意味。慌てる状態を「しっかり」で強めることはできず、慌てて書く様子とは噛み合わない。"}, {"text": "子どもは宿題を、しっかり途中で投げ出した。", "explanation": "ここは〈きちんと確実に〉の意味。途中で投げ出す行為を「しっかり」で修飾すると、意味が矛盾する。"}, {"text": "彼女は怒ると、しっかり黙って部屋を出ていった。", "explanation": "ここは〈落ち着いて確実に〉の意味。黙るという様子を「しっかり」で強める用法はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53183, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "急な坂では、手すりをしっかりつかまって歩こう。", "corrected_sentence": "急な坂では、手すりをしっかりつかんで歩こう。", "error_description": "「手すりをつかむ」が正しい。「つかまる」は「手すりにつかまる」と使い、「を」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53183, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ねじを最後までしっかりしめないば、あとは安心だ。", "corrected_sentence": "ねじを最後までしっかりしめれば、あとは安心だ。", "error_description": "仮定形「しめれば」が正しい。「しめないば」は活用が誤っており、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
