INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53184, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "物事を安定して行うさま。また、注意深く十分に行うさま。", "primary_collocate": null, "pronunciation": "しっかり", "ipa": "ɕikkaɾi", "syllable_count": 4, "sentences": [{"text": "試験の前に、しっかり復習しておきなさい。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、しっかり復習[ふくしゅう]しておきなさい。", "sentence_source": "generated"}, {"text": "朝ごはんをしっかり食べて、元気に出かけた。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんをしっかり食[た]べて、元気[げんき]に出[で]かけた。", "sentence_source": "generated"}, {"text": "病気を治すために、しっかり休んでください。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "病気[びょうき]を治[なお]すために、しっかり休[やす]んでください。", "sentence_source": "generated"}, {"text": "先生の話をしっかり聞かないと、宿題がわからなくなる。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]をしっかり聞[き]かないと、宿題[しゅくだい]がわからなくなる。", "sentence_source": "generated"}, {"text": "しっかり準備したおかげで、発表は成功した。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "しっかり準備[じゅんび]したおかげで、発表[はっぴょう]は成功[せいこう]した。", "sentence_source": "generated"}, {"text": "事故を防ぐため、出発前にしっかり確認する。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "事故[じこ]を防[ふせ]ぐため、出発[しゅっぱつ]前[まえ]にしっかり確認[かくにん]する。", "sentence_source": "generated"}, {"text": "毎日しっかり歯をみがく習慣をつけている。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "毎日[まいにち]しっかり歯[は]をみがく習慣[しゅうかん]をつけている。", "sentence_source": "generated"}, {"text": "契約書は、サインする前にしっかり読むべきだ。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]は、サインする前[まえ]にしっかり読[よ]むべきだ。", "sentence_source": "generated"}, {"text": "彼は仕事をしっかりこなして、上司に信頼されている。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]をしっかりこなして、上司[じょうし]に信頼[しんらい]されている。", "sentence_source": "generated"}, {"text": "しっかり睡眠をとると、次の日の集中力が上がる。", "target_word": "しっかり", "complexity_tier": "T3", "furigana": "しっかり睡眠[すいみん]をとると、次[つぎ]の日[ひ]の集中力[しゅうちゅうりょく]が上[あ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "しっかり", "label": "基本形"}, {"form": "しっかりと", "label": "強調形"}, {"form": "しっかりする", "label": "サ変動詞"}, {"form": "しっかりして", "label": "テ形"}], "register": "中立・口語（常体）", "sense_fingerprint": "手を抜かず、注意深く十分に物事を行うようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53184, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "しっかり", "is_correct": true, "explanation": "「安定して、念入りに」の意味で、復習の仕方として正しい。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "「ぐっすり」は熟睡する様子を表す。復習の仕方としては意味が合わない。"}, {"text": "ふらふら", "is_correct": false, "explanation": "「ふらふら」は足元が定まらない様子を表す。復習の仕方には合わない。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "「ぴかぴか」は光って輝く様子を表す。復習とは結びつかない。"}], "explanations": {"しっかり": "「安定して、念入りに」の意味で、復習の仕方として正しい。", "ぐっすり": "「ぐっすり」は熟睡する様子を表す。復習の仕方としては意味が合わない。", "ふらふら": "「ふらふら」は足元が定まらない様子を表す。復習の仕方には合わない。", "ぴかぴか": "「ぴかぴか」は光って輝く様子を表す。復習とは結びつかない。"}, "sentence_index": 0, "correct_answer": "しっかり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は、しっかり五時に終わった。", "explanation": "ここは〈ぴったり〉（時刻がきっちり合う）の意味。しっかりは安定や念入りさを表すので、時刻の正確さは示せない。"}, {"text": "空は、しっかり暗くなった。", "explanation": "ここは〈すっかり〉（完全にそうなる）の意味。しっかりは安定や念入りさを表すので、状態が完全に変わったことは表せない。"}, {"text": "焼きたてのパンが、しっかり柔らかい。", "explanation": "ここは〈ふんわり〉（軽く柔らかい様子）の意味。しっかりは堅く安定した様子を表すので、柔らかさを示す表現には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53184, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "しっかり", "is_correct": true, "explanation": "歯を念入りにみがく習慣という意味で、文に合う。"}, {"text": "ごろごろ", "is_correct": false, "explanation": "「ごろごろ」は横になって過ごす様子を表す。歯をみがく動作とは合わない。"}, {"text": "うきうき", "is_correct": false, "explanation": "「うきうき」は心が弾む様子を表す。動作の仕方を表せない。"}, {"text": "ぺらぺら", "is_correct": false, "explanation": "「ぺらぺら」は話し方が流暢な様子を表す。歯をみがく場面では使えない。"}], "explanations": {"しっかり": "歯を念入りにみがく習慣という意味で、文に合う。", "ごろごろ": "「ごろごろ」は横になって過ごす様子を表す。歯をみがく動作とは合わない。", "うきうき": "「うきうき」は心が弾む様子を表す。動作の仕方を表せない。", "ぺらぺら": "「ぺらぺら」は話し方が流暢な様子を表す。歯をみがく場面では使えない。"}, "sentence_index": 6, "correct_answer": "しっかり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "胸が、しっかり高鳴った。", "explanation": "ここは〈どきどき〉（心臓が速く打つ様子）の意味。しっかりは落ち着いて安定した様子を表すので、動揺で鼓動が速まる状態には合わない。"}, {"text": "椅子が、しっかりがたつく。", "explanation": "ここは〈ぐらぐら〉（揺れて不安定な様子）の意味。しっかりは安定していることを表すので、ぐらついて不安定な状態には合わない。"}, {"text": "魚がしっかりはねた。", "explanation": "ここは〈ぴちぴち〉（勢いよく跳ねる様子）の意味。しっかりは安定した状態を表すので、勢いのある動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53184, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降るので、傘をしっかりに持って出かけた。", "corrected_sentence": "雨が降るので、傘をしっかり持って出かけた。", "error_description": "副詞「しっかり」の直後に「に」は付けない。正しくは「傘をしっかり持って」で、「しっかりに」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53184, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "保管箱のふたを、しっかりで閉めてください。", "corrected_sentence": "保管箱のふたを、しっかり閉めてください。", "error_description": "副詞「しっかり」には「で」を付けず、そのまま動詞の前に置く。正しくは「ふたを、しっかり閉めて」で、「しっかりで」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53205, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「参拝客が訪れる」で、訪れる側の参拝客を主語として示す。"}, {"text": "に", "is_correct": false, "explanation": "「客に訪れる」とは言わない。「に」は到達点を示す助詞で、この動詞の主語には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「客で訪れる」は手段や場所を表す「で」になり、主語を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「客を訪れる」は人を目的語にする不自然な用法で、この動詞には合わない。"}], "correct_answer": "が", "explanations": {"が": "「参拝客が訪れる」で、訪れる側の参拝客を主語として示す。", "に": "「客に訪れる」とは言わない。「に」は到達点を示す助詞で、この動詞の主語には合わない。", "で": "「客で訪れる」は手段や場所を表す「で」になり、主語を示せない。", "を": "「客を訪れる」は人を目的語にする不自然な用法で、この動詞には合わない。"}, "error_tags": {"に": "方向・到着点", "で": "場所・手段", "を": "目的語（場所以外）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53205, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53205, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所へ行き会うこと。", "primary_collocate": null, "pronunciation": "おとずれる", "ipa": "otozɯɾeɾɯ", "syllable_count": 5, "sentences": [{"text": "先月、仕事で北海道を訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "先月[せんげつ]、仕事[しごと]で北海道[ほっかいどう]を訪[おとず]れた。", "sentence_source": "generated"}, {"text": "この神社は、お正月に多くの参拝客が訪れる。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "この神社[じんじゃ]は、お正月[しょうがつ]に多[おお]くの参拝客[さんぱいきゃく]が訪[おとず]れる。", "sentence_source": "generated"}, {"text": "一度は訪れたい場所が、世界にはたくさんある。", "target_word": "訪れたい", "complexity_tier": "T3", "furigana": "一度[いちど]は訪[おとず]れたい場所[ばしょ]が、世界[せかい]にはたくさんある。", "sentence_source": "generated"}, {"text": "彼は旅行でパリを訪れ、美術館をめぐった。", "target_word": "訪れ", "complexity_tier": "T3", "furigana": "彼[かれ]は旅行[りょこう]でパリを訪[おとず]れ、美術館[びじゅつかん]をめぐった。", "sentence_source": "generated"}, {"text": "桜の季節は、公園を訪れる人で道がこんでいる。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "桜[さくら]の季節[きせつ]は、公園[こうえん]を訪[おとず]れる人[ひと]で道[みち]がこんでいる。", "sentence_source": "generated"}, {"text": "小さな村を訪れたとき、親切な人に水をもらった。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "小[ちい]さな村[むら]を訪[おとず]れたとき、親切[しんせつ]な人[ひと]に水[みず]をもらった。", "sentence_source": "generated"}, {"text": "市長は災害のあった町を訪れ、住民の話を聞いた。", "target_word": "訪れ", "complexity_tier": "T3", "furigana": "市長[しちょう]は災害[さいがい]のあった町[まち]を訪[おとず]れ、住民[じゅうみん]の話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "初めて訪れる駅では、いつも案内図を見る。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "初[はじ]めて訪[おとず]れる駅[えき]では、いつも案内図[あんないず]を見[み]る。", "sentence_source": "generated"}, {"text": "私たちは博物館を訪れて、昔の道具を見学した。", "target_word": "訪れて", "complexity_tier": "T3", "furigana": "私[わたし]たちは博物館[はくぶつかん]を訪[おとず]れて、昔[むかし]の道具[どうぐ]を見学[けんがく]した。", "sentence_source": "generated"}, {"text": "山奥の温泉を訪れるために、朝早く出発した。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "山奥[やまおく]の温泉[おんせん]を訪[おとず]れるために、朝早[あさはや]く出発[しゅっぱつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "訪れる", "label": "終止形"}, {"form": "訪れた", "label": "過去形"}, {"form": "訪れない", "label": "否定形"}, {"form": "訪れて", "label": "て形"}, {"form": "訪れれば", "label": "仮定形"}], "register": "常体（中立）", "sense_fingerprint": "観光や用事である場所へ出かけて行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53205, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "過去の終止形で、「先月、仕事で北海道を訪れた」と文を言い切れる。"}, {"text": "眠った", "is_correct": false, "explanation": "自動詞「眠る」は「北海道を」を目的語にとれず、文が成り立たない。"}, {"text": "笑った", "is_correct": false, "explanation": "自動詞「笑う」は「北海道を」と続けられず、文意が通らない。"}, {"text": "泣いた", "is_correct": false, "explanation": "自動詞「泣く」は「北海道を」を取らないため、文が成り立たない。"}], "explanations": {"訪れた": "過去の終止形で、「先月、仕事で北海道を訪れた」と文を言い切れる。", "眠った": "自動詞「眠る」は「北海道を」を目的語にとれず、文が成り立たない。", "笑った": "自動詞「笑う」は「北海道を」と続けられず、文意が通らない。", "泣いた": "自動詞「泣く」は「北海道を」を取らないため、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "訪れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、新しい通知を訪れた。", "explanation": "ここは〈通知を受け取る〉の意味。通知は場所ではないので、目的語に「訪れる」は使えない。"}, {"text": "週末、借りた本を訪れた。", "explanation": "ここは〈本を読む〉の意味。本は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "注文の品が訪れた。", "explanation": "ここは〈品物が届く〉の意味。品物が届くことには「訪れる」は使えないので、この語義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53205, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "訪れ", "is_correct": true, "explanation": "連用形で、「町を訪れ、住民の話を聞いた」と後ろに動作を続けられる。"}, {"text": "食べ", "is_correct": false, "explanation": "「食べる」は「町を」を目的語にとれず、「町を食べ」は意味が通らず文意に合わない。"}, {"text": "踊り", "is_correct": false, "explanation": "「踊る」は場所を目的語にできず、「町を踊り」は文意が通らない。"}, {"text": "転び", "is_correct": false, "explanation": "自動詞「転ぶ」は「町を」と続けられず、文が成り立たない。"}], "explanations": {"訪れ": "連用形で、「町を訪れ、住民の話を聞いた」と後ろに動作を続けられる。", "食べ": "「食べる」は「町を」を目的語にとれず、「町を食べ」は意味が通らず文意に合わない。", "踊り": "「踊る」は場所を目的語にできず、「町を踊り」は文意が通らない。", "転び": "自動詞「転ぶ」は「町を」と続けられず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "訪れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "難しい課題を訪れた。", "explanation": "ここは〈課題に取り組む〉の意味。課題は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "午後、急に締め切りを訪れた。", "explanation": "ここは〈締め切りを守る〉の意味。締め切りは場所ではないので、目的語に「訪れる」は使えない。"}, {"text": "川の水が訪れた。", "explanation": "ここは〈水が流れる〉の意味。水が場所へ行くわけではないので、この語義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53205, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先月、仕事で神戸を訪れる。", "corrected_sentence": "先月、仕事で神戸を訪れた。", "error_description": "「先月」という過去を表す語があるのに、動詞が非過去の「訪れる」になっている。正しくは過去形「訪れた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "訪れる", "is_correct": true, "explanation": "お正月ごとに起こる出来事を述べる文末の終止形で、文意に合う。"}, {"text": "訪れよう", "is_correct": false, "explanation": "意志形になり、「参拝客が訪れよう」は文末として成り立たず、習慣を述べる文に合わない。"}, {"text": "訪れない", "is_correct": false, "explanation": "否定形になり、参拝客が来ないという意味に変わってしまう。"}, {"text": "訪れて", "is_correct": false, "explanation": "て形は文を終えられないため、文末に置けない。"}], "correct_form": "訪れる", "base_form": "訪れる", "form_label": "終止形", "sentence_index": 1, "explanations": {"訪れる": "お正月ごとに起こる出来事を述べる文末の終止形で、文意に合う。", "訪れよう": "意志形になり、「参拝客が訪れよう」は文末として成り立たず、習慣を述べる文に合わない。", "訪れない": "否定形になり、参拝客が来ないという意味に変わってしまう。", "訪れて": "て形は文を終えられないため、文末に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53205, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、友人と京都へ訪れた。", "corrected_sentence": "昨日、友人と京都を訪れた。", "error_description": "「訪れる」は行き先の場所を「〜を」で示すので、方向を表す「へ」は誤り。正しくは「京都を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "訪れる", "is_correct": true, "explanation": "直後の「駅」を修飾する連体形で、「初めて訪れる駅」という意味になる。"}, {"text": "訪れれば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「訪れれば駅」は成り立たない。"}, {"text": "訪れよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、ここでは文が成り立たない。"}, {"text": "訪れます", "is_correct": false, "explanation": "丁寧語は名詞の前に置けず、常体の文の中では使えない。"}], "correct_form": "訪れる", "base_form": "訪れる", "form_label": "連体形", "sentence_index": 7, "explanations": {"訪れる": "直後の「駅」を修飾する連体形で、「初めて訪れる駅」という意味になる。", "訪れれば": "仮定形は名詞を修飾できず、「訪れれば駅」は成り立たない。", "訪れよう": "意志形は名詞を修飾できず、ここでは文が成り立たない。", "訪れます": "丁寧語は名詞の前に置けず、常体の文の中では使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
