INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53206, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所へ行き会うこと。また、時間や季節などがやって来ること。", "primary_collocate": null, "pronunciation": "おとずれる", "ipa": "otozɯɾeɾɯ", "syllable_count": 5, "sentences": [{"text": "友達に会うため、大阪を訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "友達[ともだち]に会[あ]うため、大阪[おおさか]を訪[おとず]れた。", "sentence_source": "generated"}, {"text": "雪が溶けると、山にも春が訪れる。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "雪[ゆき]が溶[と]けると、山[やま]にも春[はる]が訪[おとず]れる。", "sentence_source": "generated"}, {"text": "この動物園は、休日に多くの家族連れが訪れる。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "この動物園[どうぶつえん]は、休日[きゅうじつ]に多[おお]くの家族連[かぞくづ]れが訪[おとず]れる。", "sentence_source": "generated"}, {"text": "夜が明けて、静かな朝が訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]けて、静[しず]かな朝[あさ]が訪[おとず]れた。", "sentence_source": "generated"}, {"text": "初めて訪れた旅館は、窓から海が見えた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "初[はじ]めて訪[おとず]れた旅館[りょかん]は、窓[まど]から海[うみ]が見[み]えた。", "sentence_source": "generated"}, {"text": "北の国にも、短い夏が訪れる。", "target_word": "訪れる", "complexity_tier": "T3", "furigana": "北[きた]の国[くに]にも、短[みじか]い夏[なつ]が訪[おとず]れる。", "sentence_source": "generated"}, {"text": "校長先生が、卒業生の働く工場を訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "校長先生[こうちょうせんせい]が、卒業生[そつぎょうせい]の働[はたら]く工場[こうじょう]を訪[おとず]れた。", "sentence_source": "generated"}, {"text": "暑い夏が過ぎ、涼しい秋が訪れた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "暑[あつ]い夏[なつ]が過[す]ぎ、涼[すず]しい秋[あき]が訪[おとず]れた。", "sentence_source": "generated"}, {"text": "彼は子どものころに訪れた村を、今も覚えている。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "彼[かれ]は子[こ]どものころに訪[おとず]れた村[むら]を、今[いま]も覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "展覧会を訪れた客は、作品の前で長く足を止めた。", "target_word": "訪れた", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]を訪[おとず]れた客[きゃく]は、作品[さくひん]の前[まえ]で長[なが]く足[あし]を止[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "訪れる", "label": "終止形"}, {"form": "訪れた", "label": "過去形"}, {"form": "訪れない", "label": "否定形"}, {"form": "訪れて", "label": "て形"}, {"form": "訪れれば", "label": "仮定形"}], "register": "常体（中立）", "sense_fingerprint": "場所へ出かけて行く。また、時間や季節がやって来る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53206, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "過去の終止形で、「大阪を訪れた」と行動を言い切る。"}, {"text": "食べた", "is_correct": false, "explanation": "「食べる」は食物を目的語にする語で、「大阪を食べた」は意味が通らない。"}, {"text": "笑った", "is_correct": false, "explanation": "自動詞「笑う」は「大阪を」を目的語にとれず、文が成り立たない。"}, {"text": "泣いた", "is_correct": false, "explanation": "自動詞「泣く」は「大阪を」を取らないため、文が成り立たない。"}], "explanations": {"訪れた": "過去の終止形で、「大阪を訪れた」と行動を言い切る。", "食べた": "「食べる」は食物を目的語にする語で、「大阪を食べた」は意味が通らない。", "笑った": "自動詞「笑う」は「大阪を」を目的語にとれず、文が成り立たない。", "泣いた": "自動詞「泣く」は「大阪を」を取らないため、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "訪れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末、借りた本を訪れた。", "explanation": "ここは〈本を読む〉の意味。本は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "週末は、料理を訪れた。", "explanation": "ここは〈料理を作る〉の意味。料理は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "手紙が訪れた。", "explanation": "ここは〈手紙が届く〉の意味。手紙が届くことには「訪れる」は使えないので、この語義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53206, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "過去の終止形で、「工場を訪れた」と行動を言い切る。"}, {"text": "眠った", "is_correct": false, "explanation": "自動詞「眠る」は「工場を」を目的語にとれず、文が成り立たない。"}, {"text": "踊った", "is_correct": false, "explanation": "自動詞「踊る」は「工場を」と続けられず、文意が通らない。"}, {"text": "寝転んだ", "is_correct": false, "explanation": "自動詞「寝転ぶ」も「工場を」を取れず、文が成り立たない。"}], "explanations": {"訪れた": "過去の終止形で、「工場を訪れた」と行動を言い切る。", "眠った": "自動詞「眠る」は「工場を」を目的語にとれず、文が成り立たない。", "踊った": "自動詞「踊る」は「工場を」と続けられず、文意が通らない。", "寝転んだ": "自動詞「寝転ぶ」も「工場を」を取れず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "訪れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "荷物を訪れた。", "explanation": "ここは〈荷物を運ぶ〉の意味。荷物は場所ではないので、目的語に「訪れる」を使うのは誤り。"}, {"text": "遠くで声が訪れた。", "explanation": "ここは〈声が聞こえる〉の意味。声は場所へ行くものではないので、この語義の「訪れる」は合わない。"}, {"text": "写真を訪れた。", "explanation": "ここは〈写真を撮る〉の意味。写真は場所ではないので、目的語に「訪れる」を使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53206, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、友人と大阪と訪れた。", "corrected_sentence": "昨日、友人と大阪を訪れた。", "error_description": "「訪れる」の行き先を示す助詞が誤っている。「大阪」の後に来るべき「を」が「と」になっている。正しくは「大阪を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "訪れる", "is_correct": true, "explanation": "雪が溶けるたびに春が来るという当然の成り行きを述べる終止形で、文意に合う。"}, {"text": "訪れよう", "is_correct": false, "explanation": "意志形になり、「山に春が訪れよう」は文末として成り立たず、習慣的な出来事を述べられない。"}, {"text": "訪れない", "is_correct": false, "explanation": "否定形になり、春が来ないという意味に変わってしまう。"}, {"text": "訪れて", "is_correct": false, "explanation": "て形は文を終えられないため、文末に置けない。"}], "correct_form": "訪れる", "base_form": "訪れる", "form_label": "終止形", "sentence_index": 1, "explanations": {"訪れる": "雪が溶けるたびに春が来るという当然の成り行きを述べる終止形で、文意に合う。", "訪れよう": "意志形になり、「山に春が訪れよう」は文末として成り立たず、習慣的な出来事を述べられない。", "訪れない": "否定形になり、春が来ないという意味に変わってしまう。", "訪れて": "て形は文を終えられないため、文末に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53206, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨年、家族と倉敷を訪れて。", "corrected_sentence": "昨年、家族と倉敷を訪れた。", "error_description": "文末に「訪れて」（て形）が置かれており、文が終わっていない。過去の出来事を言い切る文末なので、過去形「訪れた」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "訪れた", "is_correct": true, "explanation": "過去形で、涼しい秋が来たという既に起きた出来事を言い切る。"}, {"text": "訪れれば", "is_correct": false, "explanation": "仮定形は文を言い切れず、文末に置けない。"}, {"text": "訪れよう", "is_correct": false, "explanation": "意志形になり「秋が訪れよう」の意味になるため、既に起きた出来事を表せない。"}, {"text": "訪れます", "is_correct": false, "explanation": "丁寧語になり、この常体の文と文体が合わない。"}], "correct_form": "訪れた", "base_form": "訪れる", "form_label": "過去形", "sentence_index": 7, "explanations": {"訪れた": "過去形で、涼しい秋が来たという既に起きた出来事を言い切る。", "訪れれば": "仮定形は文を言い切れず、文末に置けない。", "訪れよう": "意志形になり「秋が訪れよう」の意味になるため、既に起きた出来事を表せない。", "訪れます": "丁寧語になり、この常体の文と文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53207, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乱暴", "is_correct": true, "explanation": "荒々しくて人を傷つけそうな様子を表し、穏やかで優しい犬と反対になる。"}, {"text": "優しい", "is_correct": false, "explanation": "「穏やか」に近い意味で、反対ではない。"}, {"text": "静か", "is_correct": false, "explanation": "「穏やか」に近い意味で、反対ではない。"}, {"text": "賢い", "is_correct": false, "explanation": "知能を表す語で、「穏やか」の反対ではない。"}], "correct_answer": "乱暴", "explanations": {"乱暴": "荒々しくて人を傷つけそうな様子を表し、穏やかで優しい犬と反対になる。", "優しい": "「穏やか」に近い意味で、反対ではない。", "静か": "「穏やか」に近い意味で、反対ではない。", "賢い": "知能を表す語で、「穏やか」の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53207, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "荒く", "is_correct": true, "explanation": "気持ちが荒れる様子を表し、気持ちが穏やかになるのと反対になる。"}, {"text": "静かに", "is_correct": false, "explanation": "「穏やかに」に近い意味で、反対ではない。"}, {"text": "優しく", "is_correct": false, "explanation": "「穏やかに」に近い印象で、反対ではない。"}, {"text": "軽く", "is_correct": false, "explanation": "重さや程度を表す語で、「穏やかに」の反対ではない。"}], "correct_answer": "荒く", "explanations": {"荒く": "気持ちが荒れる様子を表し、気持ちが穏やかになるのと反対になる。", "静かに": "「穏やかに」に近い意味で、反対ではない。", "優しく": "「穏やかに」に近い印象で、反対ではない。", "軽く": "重さや程度を表す語で、「穏やかに」の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53207, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "きもちがしずかです。あわてません。やさしいかんじです。", "primary_collocate": null, "pronunciation": "おだやか", "ipa": "odajaka", "syllable_count": 4, "sentences": [{"text": "穏やかな先生が好きです。", "target_word": "穏やかな", "complexity_tier": "T2", "furigana": "穏(おだ)やかな先生(せんせい)が好(す)きです。", "sentence_source": "generated"}, {"text": "犬は穏やかな顔で寝ています。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "犬(いぬ)は穏(おだ)やかな顔(かお)で寝(ね)ています。", "sentence_source": "generated"}, {"text": "姉は穏やかに話してくれます。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "姉(あね)は穏(おだ)やかに話(はな)してくれます。", "sentence_source": "generated"}, {"text": "この犬は穏やかで、人が好きです。", "target_word": "穏やかで", "complexity_tier": "T2", "furigana": "この犬(いぬ)は穏(おだ)やかで、人(ひと)が好(す)きです。", "sentence_source": "generated"}, {"text": "穏やかな音楽を聞きました。", "target_word": "穏やかな", "complexity_tier": "T2", "furigana": "穏(おだ)やかな音楽(おんがく)を聞(き)きました。", "sentence_source": "generated"}, {"text": "母の声は穏やかでやさしい。", "target_word": "穏やかで", "complexity_tier": "T2", "furigana": "母(はは)の声(こえ)は穏(おだ)やかでやさしい。", "sentence_source": "generated"}, {"text": "祖母はいつも穏やかに笑う。", "target_word": "穏やかに", "complexity_tier": "T2", "furigana": "祖母(そぼ)はいつも穏(おだ)やかに笑(わら)う。", "sentence_source": "generated"}, {"text": "彼は穏やかな人だ。", "target_word": "穏やかな", "complexity_tier": "T1", "furigana": "彼(かれ)は穏(おだ)やかな人(ひと)だ。", "sentence_source": "generated"}, {"text": "今日の私は穏やかです。", "target_word": "穏やかです", "complexity_tier": "T2", "furigana": "今日(きょう)の私(わたし)は穏(おだ)やかです。", "sentence_source": "generated"}, {"text": "お茶を飲んで、気持ちが穏やかになった。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "お茶(ちゃ)を飲(の)んで、気持(きも)ちが穏(おだ)やかになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穏やかな", "label": "活用"}, {"form": "穏やかに", "label": "活用"}, {"form": "穏やかだ", "label": "活用"}, {"form": "穏やかさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 気持ちが静かで慌てず優しい感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53207, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「穏やかな先生」で、気持ちが静かで優しい感じの先生を表す。"}, {"text": "新鮮な", "is_correct": false, "explanation": "形は合うが、先生の人柄を表す語として意味が合わない。"}, {"text": "滑らかな", "is_correct": false, "explanation": "形は合うが、先生の人柄を表す語として意味が合わない。"}, {"text": "鮮やかな", "is_correct": false, "explanation": "形は合うが、先生を修飾する語として意味が合わない。"}], "explanations": {"穏やかな": "「穏やかな先生」で、気持ちが静かで優しい感じの先生を表す。", "新鮮な": "形は合うが、先生の人柄を表す語として意味が合わない。", "滑らかな": "形は合うが、先生の人柄を表す語として意味が合わない。", "鮮やかな": "形は合うが、先生を修飾する語として意味が合わない。"}, "sentence_index": 0, "correct_answer": "穏やかな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このペンは穏やかで、とても長いです。", "explanation": "「穏やか」はペンの長さを表す語ではないので誤り。"}, {"text": "この机は穏やかで、人が好きです。", "explanation": "机には気持ちがないので、「穏やか」や「人が好き」の主語として誤り。"}, {"text": "この箱は穏やかで、とても重いです。", "explanation": "「穏やか」は箱の重さを表す語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53207, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穏やかに", "is_correct": true, "explanation": "「穏やかに笑う」で、静かで優しい笑い方を表す。"}, {"text": "鮮やかに", "is_correct": false, "explanation": "形は合うが、笑い方として意味が合わない。"}, {"text": "滑らかに", "is_correct": false, "explanation": "形は合うが、笑い方として意味が合わない。"}, {"text": "新鮮に", "is_correct": false, "explanation": "形は合うが、笑い方として意味が合わない。"}], "explanations": {"穏やかに": "「穏やかに笑う」で、静かで優しい笑い方を表す。", "鮮やかに": "形は合うが、笑い方として意味が合わない。", "滑らかに": "形は合うが、笑い方として意味が合わない。", "新鮮に": "形は合うが、笑い方として意味が合わない。"}, "sentence_index": 6, "correct_answer": "穏やかに"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お茶を飲んで、テーブルが穏やかになった。", "explanation": "「穏やか」は気持ちのある人や様子に使い、テーブルには使えないので誤り。"}, {"text": "お茶を飲んで、靴が穏やかになった。", "explanation": "「穏やか」は靴の状態を表す語ではないので誤り。"}, {"text": "お茶を飲んで、気持ちが穏やかに怒った。", "explanation": "怒ることは穏やかな気持ちと矛盾するので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53207, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "穏やかな犬が人にかみついて暴れた。", "corrected_sentence": "乱暴な犬が人にかみついて暴れた。", "error_description": "人にかみついて暴れる犬は穏やかではないので、「穏やかな」は不適切。「乱暴な」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「顔」を修飾する連体形で、空所に合う。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形なので、名詞「顔」を直接修飾できない。"}, {"text": "穏やかだ", "is_correct": false, "explanation": "終止形なので、名詞「顔」の前では使えない。"}, {"text": "穏やかで", "is_correct": false, "explanation": "中止形なので、「顔」を直接修飾できない。"}], "correct_form": "穏やかな", "base_form": "穏やか", "form_label": "連体形", "sentence_index": 1, "explanations": {"穏やかな": "「顔」を修飾する連体形で、空所に合う。", "穏やかに": "連用形なので、名詞「顔」を直接修飾できない。", "穏やかだ": "終止形なので、名詞「顔」の前では使えない。", "穏やかで": "中止形なので、「顔」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53207, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は穏やかに怒鳴った。", "corrected_sentence": "祖母は穏やかに笑った。", "error_description": "怒鳴ることは穏やかな行動ではないので、「穏やかに」と合わない。「笑った」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "「人」を修飾する連体形で、空所に合う。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形なので、名詞「人」を直接修飾できない。"}, {"text": "穏やかだ", "is_correct": false, "explanation": "終止形なので、名詞「人」の前では使えない。"}, {"text": "穏やかで", "is_correct": false, "explanation": "中止形なので、名詞「人」を直接修飾できない。"}], "correct_form": "穏やかな", "base_form": "穏やか", "form_label": "連体形", "sentence_index": 7, "explanations": {"穏やかな": "「人」を修飾する連体形で、空所に合う。", "穏やかに": "連用形なので、名詞「人」を直接修飾できない。", "穏やかだ": "終止形なので、名詞「人」の前では使えない。", "穏やかで": "中止形なので、名詞「人」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53208, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "荒っぽい", "is_correct": true, "explanation": "態度が乱暴なさまで、穏やかの反対。"}, {"text": "静か", "is_correct": false, "explanation": "穏やかに近い意味で、反対ではない。"}, {"text": "優しい", "is_correct": false, "explanation": "穏やかと近い意味で、反対ではない。"}, {"text": "真面目", "is_correct": false, "explanation": "穏やかとは別の観点の語で、反対ではない。"}], "correct_answer": "荒っぽい", "explanations": {"荒っぽい": "態度が乱暴なさまで、穏やかの反対。", "静か": "穏やかに近い意味で、反対ではない。", "優しい": "穏やかと近い意味で、反対ではない。", "真面目": "穏やかとは別の観点の語で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53208, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乱暴", "is_correct": true, "explanation": "態度や行いが荒々しいさまで、穏やかの反対。"}, {"text": "安らか", "is_correct": false, "explanation": "穏やかに近い意味で、反対ではない。"}, {"text": "素直", "is_correct": false, "explanation": "穏やかとは別の観点の語で、反対ではない。"}, {"text": "慎重", "is_correct": false, "explanation": "穏やかとは別の観点の語で、反対ではない。"}], "correct_answer": "乱暴", "explanations": {"乱暴": "態度や行いが荒々しいさまで、穏やかの反対。", "安らか": "穏やかに近い意味で、反対ではない。", "素直": "穏やかとは別の観点の語で、反対ではない。", "慎重": "穏やかとは別の観点の語で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53208, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "気分や態度が落ち着いていて、荒々しくない様子。", "primary_collocate": null, "pronunciation": "おだやか", "ipa": "odajaka", "syllable_count": 4, "sentences": [{"text": "彼女は穏やかな口調で断った。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は穏(おだ)やかな口調(くちょう)で断(ことわ)った。", "sentence_source": "generated"}, {"text": "祖父は穏やかな人柄で知られている。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "祖父(そふ)は穏(おだ)やかな人柄(ひとがら)で知(し)られている。", "sentence_source": "generated"}, {"text": "犬は穏やかに眠っている。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "犬(いぬ)は穏(おだ)やかに眠(ねむ)っている。", "sentence_source": "generated"}, {"text": "彼の態度は終始穏やかだった。", "target_word": "穏やかだった", "complexity_tier": "T3", "furigana": "彼(かれ)の態度(たいど)は終始(しゅうし)穏(おだ)やかだった。", "sentence_source": "generated"}, {"text": "怒鳴らずに、穏やかに説明してください。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "怒鳴(どな)らずに、穏(おだ)やかに説明(せつめい)してください。", "sentence_source": "generated"}, {"text": "穏やかで落ち着いた雰囲気の店です。", "target_word": "穏やかで", "complexity_tier": "T3", "furigana": "穏(おだ)やかで落(お)ち着(つ)いた雰囲気(ふんいき)の店(みせ)です。", "sentence_source": "generated"}, {"text": "先生の穏やかな目を見て、安心した。", "target_word": "穏やかな", "complexity_tier": "T3", "furigana": "先生(せんせい)の穏(おだ)やかな目(め)を見(み)て、安心(あんしん)した。", "sentence_source": "generated"}, {"text": "機嫌が直って、父は穏やかになった。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "機嫌(きげん)が直(なお)って、父(ちち)は穏(おだ)やかになった。", "sentence_source": "generated"}, {"text": "怒られても、彼は穏やかなままだった。", "target_word": "穏やかな", "complexity_tier": "T4", "furigana": "怒(おこ)られても、彼(かれ)は穏(おだ)やかなままだった。", "sentence_source": "generated"}, {"text": "彼のように穏やかに生きたい。", "target_word": "穏やかに", "complexity_tier": "T3", "furigana": "彼(かれ)のように穏(おだ)やかに生(い)きたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穏やかな", "label": "活用"}, {"form": "穏やかに", "label": "活用"}, {"form": "穏やかだ", "label": "活用"}, {"form": "穏やかさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 気分や態度が落ち着き荒くない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aa904c4-3d5b-42f2-9b5c-440c33b00587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53208, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "落ち着いて荒くない口調という意味で文意に合う。"}, {"text": "派手な", "is_correct": false, "explanation": "形は合うが、口調を派手と言うのは断る場面に意味が合わない。"}, {"text": "巨大な", "is_correct": false, "explanation": "形は合うが、口調の形容として意味が合わない。"}, {"text": "新鮮な", "is_correct": false, "explanation": "形は合うが、口調と断る場面に意味が合わない。"}], "explanations": {"穏やかな": "落ち着いて荒くない口調という意味で文意に合う。", "派手な": "形は合うが、口調を派手と言うのは断る場面に意味が合わない。", "巨大な": "形は合うが、口調の形容として意味が合わない。", "新鮮な": "形は合うが、口調と断る場面に意味が合わない。"}, "sentence_index": 0, "correct_answer": "穏やかな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "穏やかな石を積んで壁を作った。", "explanation": "穏やかは石のような物の性質には使えず、用法が誤り。"}, {"text": "彼は穏やかに怒鳴って部屋を飛び出した。", "explanation": "怒鳴る行為は荒々しく、穏やかと矛盾する。"}, {"text": "穏やかなナイフで野菜を切った。", "explanation": "穏やかは道具の切れ味などを表せず、用法が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53208, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "先生の落ち着いた目を見て安心したという意味に合う。"}, {"text": "派手な", "is_correct": false, "explanation": "形は合うが、安心した理由として意味が合わない。"}, {"text": "盛大な", "is_correct": false, "explanation": "形は合うが、目の形容として意味が合わない。"}, {"text": "複雑な", "is_correct": false, "explanation": "形は合うが、安心したという流れに意味が合わない。"}], "explanations": {"穏やかな": "先生の落ち着いた目を見て安心したという意味に合う。", "派手な": "形は合うが、安心した理由として意味が合わない。", "盛大な": "形は合うが、目の形容として意味が合わない。", "複雑な": "形は合うが、安心したという流れに意味が合わない。"}, "sentence_index": 6, "correct_answer": "穏やかな"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の試験は穏やかに難しかった。", "explanation": "穏やかは難しさの程度を表せず、用法が誤り。"}, {"text": "彼は穏やかに叫びながら暴れた。", "explanation": "叫んで暴れる行為は荒々しく、穏やかと矛盾する。"}, {"text": "穏やかな電車で会社まで急いだ。", "explanation": "穏やかは電車の性質を表さず、急ぐ文脈とも合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53208, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は穏やかの人だ。", "corrected_sentence": "祖母は穏やかな人だ。", "error_description": "名詞「人」を修飾するときは「穏やかな」で、「穏やかの」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "穏やかな", "is_correct": true, "explanation": "名詞「人柄」を修飾する連体形で空所に合う。"}, {"text": "穏やかに", "is_correct": false, "explanation": "連用形で、名詞「人柄」を修飾できない。"}, {"text": "穏やかだ", "is_correct": false, "explanation": "終止形で、名詞の前には置けない。"}, {"text": "穏やかさ", "is_correct": false, "explanation": "名詞形で、「穏やかさ人柄」では意味が通らない。"}], "correct_form": "穏やかな", "base_form": "穏やか", "form_label": "連体形", "sentence_index": 1, "explanations": {"穏やかな": "名詞「人柄」を修飾する連体形で空所に合う。", "穏やかに": "連用形で、名詞「人柄」を修飾できない。", "穏やかだ": "終止形で、名詞の前には置けない。", "穏やかさ": "名詞形で、「穏やかさ人柄」では意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53208, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は穏やかな笑った。", "corrected_sentence": "弟は穏やかに笑った。", "error_description": "動詞「笑った」を修飾するには「穏やかに」が必要で、「穏やかな」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "穏やかに", "is_correct": true, "explanation": "「なった」に続く変化を表す連用形で空所に合う。"}, {"text": "穏やかな", "is_correct": false, "explanation": "連体形で、「なった」にはつながらない。"}, {"text": "穏やかで", "is_correct": false, "explanation": "中止形で、「なった」とは続かない。"}, {"text": "穏やかさ", "is_correct": false, "explanation": "名詞形で、「穏やかさなった」は文法的に誤り。"}], "correct_form": "穏やかに", "base_form": "穏やか", "form_label": "連用形(に)", "sentence_index": 7, "explanations": {"穏やかに": "「なった」に続く変化を表す連用形で空所に合う。", "穏やかな": "連体形で、「なった」にはつながらない。", "穏やかで": "中止形で、「なった」とは続かない。", "穏やかさ": "名詞形で、「穏やかさなった」は文法的に誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e869aaf1-0ead-422d-a313-3f138ef975cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
