INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53209, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「田園の空気」と名詞をつなぎ、「空気」を修飾する形として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「田園を空気は」と目的語にすると、「おいしい」と続かず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「田園へ空気は」と場所の意味で続かず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「田園が空気は」と主語を重ねると、文の構造が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「田園の空気」と名詞をつなぎ、「空気」を修飾する形として正しい。", "を": "「田園を空気は」と目的語にすると、「おいしい」と続かず文が成り立たない。", "へ": "「へ」は方向を示すので、「田園へ空気は」と場所の意味で続かず不自然。", "が": "「田園が空気は」と主語を重ねると、文の構造が成り立たない。"}, "error_tags": {"を": "目的語では文が成り立たない", "へ": "方向では「おいしい」の主語として続かない", "が": "二つの主語が続かない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53209, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "野菜や米を作る田畑が広がる、空が広くて緑の多い場所です。", "primary_collocate": null, "pronunciation": "でんえん", "ipa": "deɴeɴ", "syllable_count": 2, "sentences": [{"text": "田園には、広い空があります。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]には、広[ひろ]い空[そら]があります。", "sentence_source": "generated"}, {"text": "田園で、おじいさんが野菜を作っています。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]で、おじいさんが野菜[やさい]を作[つく]っています。", "sentence_source": "generated"}, {"text": "わたしは夏休みに、田園へ行きました。", "target_word": "田園", "complexity_tier": "T3", "furigana": "わたしは夏休[なつやす]みに、田園[でんえん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "田園の道を、犬と歩きました。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]の道[みち]を、犬[いぬ]と歩[ある]きました。", "sentence_source": "generated"}, {"text": "田園では、米を育てています。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]では、米[こめ]を育[そだ]てています。", "sentence_source": "generated"}, {"text": "田園に、きれいな花がさいていました。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]に、きれいな花[はな]がさいていました。", "sentence_source": "generated"}, {"text": "おばあさんの家の前には、田園が広がっています。", "target_word": "田園", "complexity_tier": "T3", "furigana": "おばあさんの家[いえ]の前[まえ]には、田園[でんえん]が広[ひろ]がっています。", "sentence_source": "generated"}, {"text": "田園の空気はおいしいと思います。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]の空気[くうき]はおいしいと思[おも]います。", "sentence_source": "generated"}, {"text": "雨の日の田園は、とても静かでした。", "target_word": "田園", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]の田園[でんえん]は、とても静[しず]かでした。", "sentence_source": "generated"}, {"text": "田園で、子どもたちが虫をとって遊んでいます。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]で、子[こ]どもたちが虫[むし]をとって遊[あそ]んでいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "田園", "label": "基本形"}], "register": "中立", "sense_fingerprint": "野菜や米を育てる、空が広く緑が多い場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53209, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "田園", "is_correct": true, "explanation": "田畑が広がる場所のことで、「田園には、広い空がある」と自然に続く。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、「冷蔵庫には、広い空がある」とは成り立たない。"}, {"text": "本棚", "is_correct": false, "explanation": "本を置く家具で、広い空があるという文の主語としては合わない。"}, {"text": "靴箱", "is_correct": false, "explanation": "靴をしまう棚で、広い空があるという文の場所としては合わない。"}], "explanations": {"田園": "田畑が広がる場所のことで、「田園には、広い空がある」と自然に続く。", "冷蔵庫": "食品を冷やす家電で、「冷蔵庫には、広い空がある」とは成り立たない。", "本棚": "本を置く家具で、広い空があるという文の主語としては合わない。", "靴箱": "靴をしまう棚で、広い空があるという文の場所としては合わない。"}, "sentence_index": 0, "correct_answer": "田園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "田園の高層ビルの前で、犬と歩きました。", "explanation": "ここは〈都市〉の意味。田園は田畑や緑の広がる土地で、高層ビルが並ぶ場所とは結びつかない。"}, {"text": "田園の海岸で、貝がらを拾いました。", "explanation": "ここは〈海岸〉の意味。田園は内陸の田畑を指すので、海辺の場所とは合わない。"}, {"text": "田園の空港から、飛行機が飛び立ちました。", "explanation": "ここは〈空港〉の意味。田園は田畑の風景で、飛行機が発着する施設の語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53209, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "田園", "is_correct": true, "explanation": "田畑が広がる土地のことで、「田園が広がっています」と自然に続く。"}, {"text": "電車", "is_correct": false, "explanation": "鉄道の車両で、「電車が広がっています」とは言えない。"}, {"text": "電話", "is_correct": false, "explanation": "通話をする機器で、広がるという表現とは合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書く道具で、広がっているという状態を表す主語には合わない。"}], "explanations": {"田園": "田畑が広がる土地のことで、「田園が広がっています」と自然に続く。", "電車": "鉄道の車両で、「電車が広がっています」とは言えない。", "電話": "通話をする機器で、広がるという表現とは合わない。", "鉛筆": "書く道具で、広がっているという状態を表す主語には合わない。"}, "sentence_index": 6, "correct_answer": "田園"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田園の病院で、薬をもらいました。", "explanation": "ここは〈病院〉の意味。田園は田畑の風景を指し、薬をもらう施設とは結びつかない。"}, {"text": "田園の体育館で、バスケットをしました。", "explanation": "ここは〈体育館〉の意味。田園は屋外の田畑の風景で、屋内の施設には使わない。"}, {"text": "田園の繁華街で、買い物をしました。", "explanation": "ここは〈繁華街〉の意味。田園は人の少ない農地や風景で、にぎやかな商業地区とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53209, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨上がりの田園を、虹がかかっていた。", "corrected_sentence": "雨上がりの田園に、虹がかかっていた。", "error_description": "「虹がかかる」の場所は「に」で示す。「田園を」の「を」は、かかるという自動詞には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53209, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休日には、田園を散髪する人が多い。", "corrected_sentence": "休日には、田園を散歩する人が多い。", "error_description": "「田園」を歩き回る動詞は「散歩する」。「散髪する」は田園とは結びつかないので不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53210, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "移り住む先（到着点）を「に」で示す。「田園に移り住んだ」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は通過点や起点を示すので、住み着く先には合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」を使うと田園が主語になり、移り住むのが作家である文の流れと合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、住み着く先には合わない。"}], "correct_answer": "に", "explanations": {"に": "移り住む先（到着点）を「に」で示す。「田園に移り住んだ」が正しい。", "を": "「を」は通過点や起点を示すので、住み着く先には合わない。", "が": "「が」を使うと田園が主語になり、移り住むのが作家である文の流れと合わない。", "で": "「で」は場所や手段を示すので、住み着く先には合わない。"}, "error_tags": {"を": "起点", "が": "主語", "で": "場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53210, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「働く」が行われる場所を「で」で示す。「田園で働く」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「働く」は目的語を取らない動詞なので、「を」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」を使うと田園が働く主体になり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点や存在の場所を示すので、「田園に働く」では文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「働く」が行われる場所を「で」で示す。「田園で働く」が正しい。", "を": "「働く」は目的語を取らない動詞なので、「を」は合わない。", "が": "「が」を使うと田園が働く主体になり、意味が通らない。", "に": "「に」は到着点や存在の場所を示すので、「田園に働く」では文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "存在"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53210, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "農地や庭園などが広がっている、都市以外の静かな地方の土地。", "primary_collocate": null, "pronunciation": "でんえん", "ipa": "deɴeɴ", "syllable_count": 2, "sentences": [{"text": "退職したら、静かな田園で暮らしたいと考えている。", "target_word": "田園", "complexity_tier": "T3", "furigana": "退職[たいしょく]したら、静[しず]かな田園[でんえん]で暮[く]らしたいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "その作家は、都会をはなれて田園に移り住んだ。", "target_word": "田園", "complexity_tier": "T3", "furigana": "その作家[さっか]は、都会[とかい]をはなれて田園[でんえん]に移[うつ]り住[す]んだ。", "sentence_source": "generated"}, {"text": "田園には、畑のほかに、手入れされた庭も多い。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]には、畑[はたけ]のほかに、手入[ていれ]れされた庭[にわ]も多[おお]い。", "sentence_source": "generated"}, {"text": "田園の夜は暗くて、空の星がよく見える。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]の夜[よる]は暗[くら]くて、空[そら]の星[ほし]がよく見[み]える。", "sentence_source": "generated"}, {"text": "都会のさわがしさにつかれて、週末は田園へ出かけた。", "target_word": "田園", "complexity_tier": "T3", "furigana": "都会[とかい]のさわがしさにつかれて、週末[しゅうまつ]は田園[でんえん]へ出[で]かけた。", "sentence_source": "generated"}, {"text": "彼女は田園の小さな家で、花を育てながら暮らしている。", "target_word": "田園", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は田園[でんえん]の小[ちい]さな家[いえ]で、花[はな]を育[そだ]てながら暮[く]らしている。", "sentence_source": "generated"}, {"text": "田園では、時間がゆっくり流れているように感じる。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]では、時間[じかん]がゆっくり流[なが]れているように感[かん]じる。", "sentence_source": "generated"}, {"text": "この絵には、田園で働く人々のおだやかな姿が描かれている。", "target_word": "田園", "complexity_tier": "T3", "furigana": "この絵[え]には、田園[でんえん]で働[はたら]く人々[ひとびと]のおだやかな姿[すがた]が描[えが]かれている。", "sentence_source": "generated"}, {"text": "田園の人たちは、あいさつを大切にしている。", "target_word": "田園", "complexity_tier": "T3", "furigana": "田園[でんえん]の人[ひと]たちは、あいさつを大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "都会と比べて、田園は生活に必要な店が少ない。", "target_word": "田園", "complexity_tier": "T3", "furigana": "都会[とかい]と比[くら]べて、田園[でんえん]は生活[せいかつ]に必要[ひつよう]な店[みせ]が少[すく]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "田園", "label": "基本形"}], "register": "中立", "sense_fingerprint": "都会とは違う、畑や庭が広がる静かな地方の暮らしの場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53210, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "田園", "is_correct": true, "explanation": "静かな地方の暮らしの場を指す「田園」が、「で暮らしたい」と自然につながる。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は寝るための部屋で、「静かな寝室で暮らす」は意味が通らない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は授業のための場所で、暮らす場所としては不自然。"}, {"text": "図書館", "is_correct": false, "explanation": "図書館は本を読む施設で、暮らす場所としては合わない。"}], "explanations": {"田園": "静かな地方の暮らしの場を指す「田園」が、「で暮らしたい」と自然につながる。", "寝室": "寝室は寝るための部屋で、「静かな寝室で暮らす」は意味が通らない。", "教室": "教室は授業のための場所で、暮らす場所としては不自然。", "図書館": "図書館は本を読む施設で、暮らす場所としては合わない。"}, "sentence_index": 0, "correct_answer": "田園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市の中心にある田園には、高層ビルが林立し、役所も置かれている。", "explanation": "ここは「中心市街地」の意味。ビルと役所が並ぶ都市の中心部は中心市街地と言い、静かな地方の土地を指す田園とは合わない。"}, {"text": "夜の田園はネオンが明るく、人通りが絶えない。", "explanation": "ここは「繁華街」の意味。ネオンと人通りでにぎわう場所は繁華街と言い、静かな地方の土地を指す田園とは合わない。"}, {"text": "この田園には滑走路が二本あり、毎日多くの便が飛び立つ。", "explanation": "ここは「空港」の意味。滑走路と便をもつ施設は空港と言い、農地や庭が広がる静かな地方の土地を指す田園とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53210, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "田園", "is_correct": true, "explanation": "時間がゆっくり流れる静かな地方の土地を指す「田園」が、文の場所として自然につながる。"}, {"text": "証券取引所", "is_correct": false, "explanation": "取引が激しく動く場所で、時間がゆっくり流れるという文と矛盾する。"}, {"text": "工事現場", "is_correct": false, "explanation": "工事現場は忙しく動く場所で、時間がゆっくり流れるという文と合わない。"}, {"text": "繁忙期", "is_correct": false, "explanation": "繁忙期は忙しい時期を指すので、時間がゆっくり流れるという文と矛盾する。"}], "explanations": {"田園": "時間がゆっくり流れる静かな地方の土地を指す「田園」が、文の場所として自然につながる。", "証券取引所": "取引が激しく動く場所で、時間がゆっくり流れるという文と矛盾する。", "工事現場": "工事現場は忙しく動く場所で、時間がゆっくり流れるという文と合わない。", "繁忙期": "繁忙期は忙しい時期を指すので、時間がゆっくり流れるという文と矛盾する。"}, "sentence_index": 6, "correct_answer": "田園"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田園の大学の校舎で、新学期の講義が始まる。", "explanation": "ここは〈大学〉の意味。大学の校舎は教育施設で、静かな地方の土地を指す田園とは結びつかない。"}, {"text": "お盆には、田園へ里帰りする人が多い。", "explanation": "ここは「田舎」の意味。実家のある故郷を指す田舎へは里帰りできるが、田園は農地や庭が広がる土地を指すので、帰る先としては合わない。"}, {"text": "この田園には大型船が着き、荷物が次々と運ばれる。", "explanation": "ここは「港」の意味。船が着いて荷物を積み降ろす場所は港と言い、田園は農地や庭が広がる地方の土地を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53210, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "静かな田園を暮らしたいと、毎年夏に思う。", "corrected_sentence": "静かな田園で暮らしたいと、毎年夏に思う。", "error_description": "誤りは「田園を」の「を」。「暮らす」は場所を「で」で示す。「を」は目的語に付くので、「田園で暮らしたい」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53210, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の外には田園な景色が広がっている。", "corrected_sentence": "窓の外には田園の景色が広がっている。", "error_description": "誤りは「田園な」の「な」。「田園」は名詞なので、後ろの名詞を修飾するには「の」を使う。「田園な」は形容動詞の形で誤り（「田園的な」は別の語）。「田園の景色」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53215, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53215, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「手すりが」の「が」。錆びついた主語（手すり）を示し、「手すりが錆びついて危ない」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "〈錆びつく〉は自動詞なので、「手すりを錆びついて」は目的語として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「手すりと」は並列や相手を表し、錆びつく主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、手すりが錆びつく状態には合わない。"}], "correct_answer": "が", "explanations": {"が": "「手すりが」の「が」。錆びついた主語（手すり）を示し、「手すりが錆びついて危ない」と自然につながる。", "を": "〈錆びつく〉は自動詞なので、「手すりを錆びついて」は目的語として不自然。", "と": "「手すりと」は並列や相手を表し、錆びつく主語にはならない。", "へ": "「へ」は方向を表すので、手すりが錆びつく状態には合わない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53215, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "鉄などがさびて、こわれてしまうことです。", "primary_collocate": null, "pronunciation": "さびつく", "ipa": "sabit͡sɯkɯ", "syllable_count": 4, "sentences": [{"text": "雨の中に放置した自転車のチェーンが錆びついて、動かなくなった。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "雨[あめ]の中[なか]に放置[ほうち]した自転車[じてんしゃ]のチェーンが錆[さ]びついて、動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "長いあいだ使わなかった門の鍵は、すっかり錆びついていた。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "長[なが]いあいだ使[つか]わなかった門[もん]の鍵[かぎ]は、すっかり錆[さ]びついていた。", "sentence_source": "generated"}, {"text": "海の近くでは、鉄の柵が早く錆びついてしまう。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くでは、鉄[てつ]の柵[さく]が早[はや]く錆[さ]びついてしまう。", "sentence_source": "generated"}, {"text": "倉庫の奥で、錆びついたはさみが見つかった。", "target_word": "錆びついた", "complexity_tier": "T3", "furigana": "倉庫[そうこ]の奥[おく]で、錆[さ]びついたはさみが見[み]つかった。", "sentence_source": "generated"}, {"text": "錆びついた蝶番のせいで、扉がなかなか開かなかった。", "target_word": "錆びついた", "complexity_tier": "T3", "furigana": "錆[さ]びついた蝶番[ちょうつがい]のせいで、扉[とびら]がなかなか開[あ]かなかった。", "sentence_source": "generated"}, {"text": "水をかけたまま片付けたので、釘が錆びついてしまった。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "水[みず]をかけたまま片付[かたづ]けたので、釘[くぎ]が錆[さ]びついてしまった。", "sentence_source": "generated"}, {"text": "祖父の工具箱には、錆びついたやすりが何本も入っていた。", "target_word": "錆びついた", "complexity_tier": "T3", "furigana": "祖父[そふ]の工具箱[こうぐばこ]には、錆[さ]びついたやすりが何本[なんぼん]も入[はい]っていた。", "sentence_source": "generated"}, {"text": "この古い鉄橋は、手すりが錆びついて危ない。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "この古[ふる]い鉄橋[てっきょう]は、手[て]すりが錆[さ]びついて危[あぶ]ない。", "sentence_source": "generated"}, {"text": "錆びつく前に、油を塗って道具をしまっておこう。", "target_word": "錆びつく", "complexity_tier": "T3", "furigana": "錆[さ]びつく前[まえ]に、油[あぶら]を塗[ぬ]って道具[どうぐ]をしまっておこう。", "sentence_source": "generated"}, {"text": "公園の鉄棒が錆びついて、手が茶色くなった。", "target_word": "錆びついて", "complexity_tier": "T3", "furigana": "公園[こうえん]の鉄棒[てつぼう]が錆[さ]びついて、手[て]が茶色[ちゃいろ]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "錆びつかない", "label": "否定形"}, {"form": "錆びつきます", "label": "丁寧形"}, {"form": "錆びついた", "label": "過去形"}, {"form": "錆びついて", "label": "て形"}, {"form": "錆びつけば", "label": "仮定形"}, {"form": "錆びつこう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "鉄などがさびて使えなくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53215, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "錆びついて", "is_correct": true, "explanation": "「錆びついて、動かなくなった」の形。て形で、錆びた結果として動かなくなったことにつながる。"}, {"text": "錆びつか", "is_correct": false, "explanation": "否定の語幹。「錆びつかて」となり、て形として成立しない。"}, {"text": "錆びつき", "is_correct": false, "explanation": "連用形。「錆びつきて」となり、て形として成立しない。"}, {"text": "錆びつく", "is_correct": false, "explanation": "終止形。「錆びつくて」となり、て形として成立しない。"}], "explanations": {"錆びついて": "「錆びついて、動かなくなった」の形。て形で、錆びた結果として動かなくなったことにつながる。", "錆びつか": "否定の語幹。「錆びつかて」となり、て形として成立しない。", "錆びつき": "連用形。「錆びつきて」となり、て形として成立しない。", "錆びつく": "終止形。「錆びつくて」となり、て形として成立しない。"}, "sentence_index": 0, "correct_answer": "錆びついて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湿気で木の床板が錆びついて、ぎしぎし鳴るようになった。", "explanation": "ここは〈腐る〉の意味。木の床板は錆びず腐って傷むので、錆びつくは金属の酸化にしか使わない。"}, {"text": "夜の冷え込みで、池の水面が錆びついてしまった。", "explanation": "ここは〈凍りつく〉の意味。寒さで水が凍ることは〈凍りつく〉で表し、錆びつくは金属の酸化を指すので合わない。"}, {"text": "放置した糊が錆びついて、封筒が開かなくなった。", "explanation": "ここは〈固まる〉の意味。糊は金属ではなく錆びないので、乾いて固くなる意味なら〈固まる〉が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53215, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "錆びついた", "is_correct": true, "explanation": "た形。直後の「やすり」を修飾し、錆びた状態のやすりを表す。"}, {"text": "錆びつけ", "is_correct": false, "explanation": "命令形の語幹。「錆びつけやすり」となり、名詞を修飾する形として成立しない。"}, {"text": "錆びつこう", "is_correct": false, "explanation": "意志形。「錆びつこうやすり」となり、名詞修飾として成立しない。"}, {"text": "錆びついて", "is_correct": false, "explanation": "て形。「錆びついてやすり」となり、名詞を修飾する形として成立しない。"}], "explanations": {"錆びついた": "た形。直後の「やすり」を修飾し、錆びた状態のやすりを表す。", "錆びつけ": "命令形の語幹。「錆びつけやすり」となり、名詞を修飾する形として成立しない。", "錆びつこう": "意志形。「錆びつこうやすり」となり、名詞修飾として成立しない。", "錆びついて": "て形。「錆びついてやすり」となり、名詞を修飾する形として成立しない。"}, "sentence_index": 6, "correct_answer": "錆びついた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の日差しで、洗濯物が錆びついて、からりと乾いた。", "explanation": "ここは〈乾く〉の意味。洗濯物は金属ではなく錆びないので、錆びつくは使わない。"}, {"text": "真っ赤に熱した鉄板が錆びついて、どろりと溶けた。", "explanation": "ここは〈溶ける〉の意味。熱で液体になる変化は〈溶ける〉で表し、錆びつくは酸化による劣化を指すので合わない。"}, {"text": "古い木箱の金具が錆びついて、火に投げ入れるとよく燃えた。", "explanation": "ここは〈燃える〉の意味。火で燃えることは〈燃える〉で表し、錆びつくは金属の酸化を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53215, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父の工具箱のやすりは、雨で錆びつくて使えない。", "corrected_sentence": "祖父の工具箱のやすりは、雨で錆びついて使えない。", "error_description": "「錆びつくて」は誤り。正しくは「錆びついて」（く→いて）。五段動詞のて形は語幹に「いて」を付けて作る。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "錆びついて", "is_correct": true, "explanation": "て形。「すっかり錆びついていた」と続き、錆びた状態を表す。"}, {"text": "錆びつかない", "is_correct": false, "explanation": "否定形。錆びていないという意味になり、門の鍵が錆びた状態と逆になる。"}, {"text": "錆びつきます", "is_correct": false, "explanation": "丁寧形。普通体の「いていた」と文体が合わない。"}, {"text": "錆びつけば", "is_correct": false, "explanation": "仮定形。仮定の意味になり、すでに錆びた状態の叙述に合わない。"}], "correct_form": "錆びついて", "base_form": "錆びつく", "form_label": "て形", "sentence_index": 1, "explanations": {"錆びついて": "て形。「すっかり錆びついていた」と続き、錆びた状態を表す。", "錆びつかない": "否定形。錆びていないという意味になり、門の鍵が錆びた状態と逆になる。", "錆びつきます": "丁寧形。普通体の「いていた」と文体が合わない。", "錆びつけば": "仮定形。仮定の意味になり、すでに錆びた状態の叙述に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53215, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園の隅の鉄棒は、雨を錆びついて手が茶色くなった。", "corrected_sentence": "公園の隅の鉄棒は、雨で錆びついて手が茶色くなった。", "error_description": "「雨を」は誤り。〈錆びつく〉は自動詞で目的語を取らず、原因は「雨で」と表す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "錆びついて", "is_correct": true, "explanation": "て形。直後の「危ない」へ続き、錆びて危険な状態を説明する形になる。"}, {"text": "錆びついた", "is_correct": false, "explanation": "た形。「錆びついた危ない」となり、て形の接続として成立しない。"}, {"text": "錆びつけ", "is_correct": false, "explanation": "命令形。「錆びつけ危ない」となり、状態を述べる文に合わない。"}, {"text": "錆びつこう", "is_correct": false, "explanation": "意志形。「錆びつこう危ない」となり、状態の叙述に合わない。"}], "correct_form": "錆びついて", "base_form": "錆びつく", "form_label": "て形", "sentence_index": 7, "explanations": {"錆びついて": "て形。直後の「危ない」へ続き、錆びて危険な状態を説明する形になる。", "錆びついた": "た形。「錆びついた危ない」となり、て形の接続として成立しない。", "錆びつけ": "命令形。「錆びつけ危ない」となり、状態を述べる文に合わない。", "錆びつこう": "意志形。「錆びつこう危ない」となり、状態の叙述に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53216, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「金属の板が」の「が」。錆びる主語（金属の板）を示し、「板が錆びついてきた」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "〈錆びつく〉は自動詞で目的語を取らないので、「板を錆びついてきた」は誤り。"}, {"text": "と", "is_correct": false, "explanation": "「板と」は並列や相手を表し、錆びつく主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、金属の板が錆びる主語の役割には合わない。"}], "correct_answer": "が", "explanations": {"が": "「金属の板が」の「が」。錆びる主語（金属の板）を示し、「板が錆びついてきた」と自然につながる。", "を": "〈錆びつく〉は自動詞で目的語を取らないので、「板を錆びついてきた」は誤り。", "と": "「板と」は並列や相手を表し、錆びつく主語にはならない。", "へ": "「へ」は方向を表すので、金属の板が錆びる主語の役割には合わない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
